["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        return Merfin:L('Mobs active - East |cffffff80(1/4)|r')\n    end\n    \n    local id = aura_env.roleplayID\n    if id == 1 then\n        return Merfin:L('Mobs active - East |cffffff80(1/4)|r')\n    elseif id == 2 then\n        return Merfin:L('Mobs active - West |cffffff80(2/4)|r')\n    elseif id == 3 then\n        return Merfin:L('Mobs active - North |cffffff80(3/4)|r')\n    elseif id == 4 then\n        return Merfin:L('Mobs active - South |cffffff80(4/4)|r')\n    elseif id == 5 then\n        return EJ_GetEncounterInfo(687)\n    end\nend",
