},
["init"] = {
["do_custom_load"] = false,
["custom"] = "local encounterID = 'Trash'\nlocal ID          = 'SmokeBomb'\n\nlocal name, icon = C_Spell.GetSpellName(116595), C_Spell.GetSpellTexture(116595)\n\nlocal options = {\n    warningText = '%icon @cffff8b17%name@r %icon'\n}\n\naura_env.SendWarning = function()\n    local data = {\n        ID   = ID,\n        name = name,\n        icon = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID, GUID = GUID })\nend\n\naura_env.StartCD = function(duration, unitGUID)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        GUID           = unitGUID,\n        noCount        = true\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.guids = {}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(e, ...)\n    if e == 'UNIT_THREAT_LIST_UPDATE' then\n        local nameplateID = ...\n        local unitGUID = UnitGUID(nameplateID)\n        local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n        \n        if npcID == 60381 and aura_env.guids[unitGUID] then\n            local inCombat = UnitAffectingCombat(nameplateID)\n            if inCombat then\n                aura_env.StartCD(25, unitGUID)\n            else\n                aura_env.StopCD(unitGUID)\n            end\n        end\n        \n    elseif e == 'NAME_PLATE_UNIT_ADDED' then\n        local nameplateID = ...\n        local unitGUID = UnitGUID(nameplateID)\n        local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n        \n        if npcID == 60381 then\n            local inCombat = UnitAffectingCombat(nameplateID)\n            \n            if not inCombat then\n                aura_env.guids[unitGUID] = true\n            else\n                aura_env.guids[unitGUID] = nil\n            end\n        end\n    end\nend",
