{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n    cooldownId = {\n        display = 'Cooldown ID',\n        type = 'string',\n    },\n    noCount = {\n        display = 'Missing Counter',\n        type = 'bool'\n    },\n    hasSrcName = {\n        display = 'Has Source Name',\n        type = 'bool',\n    },\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        states:Update(i, {\n                progressType   = 'timed',\n                autoHide       = false,\n                duration       = 15,\n                expirationTime = 15 + GetTime(),\n                name           = C_Spell.GetSpellName(122774),\n                nextCount      = math.random(1, 10),\n        })\n    end\n    \n    if e == 'MERFIN_CD_HIDE' then\n        local encounterID, cooldown = ...\n        \n        if cooldown.ID ~= 'Crush' then return end\n        states:Remove('')\n        \n    elseif e == 'MERFIN_CD_SHOW_WIDGET' then\n        local encounterID, cooldown = ...\n        if cooldown.ID ~= 'Crush' then return end\n        local newState = {\n            progressType   = 'timed',\n            duration       = cooldown.duration,\n            expirationTime = cooldown.expirationTime,\n            autoHide       = cooldown.autoHide,\n            icon           = cooldown.icon,\n            name           = cooldown.name,\n            nextCount      = (cooldown.count or 0) + 1,\n        }\n        \n        states:Update('', newState)\n    end\nend",
["spellIds"] = {
},
["events"] = "MERFIN_CD_SHOW_WIDGET, MERFIN_CD_HIDE",
["check"] = "event",
