["custom"] = "-- Author: 露露緹婭@Bilibili\nlocal e = aura_env\nlocal region = WeakAuras.GetRegion(e.id)\n\nif not _G[e.id..\"Button\"] then\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\")\n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"LeftButtonDown\", \"RightButtonUp\", \"RightButtonDown\", \"MiddleButtonUp\", \"MiddleButtonDown\")\n    e.btn:SetAttribute(\"type1\", \"macro\")\n    e.btn:SetAttribute(\"type2\", \"macro\")\n    e.btn:SetAttribute(\"type3\", \"macro\")\n    e.btn:SetAllPoints(region)\nend\n\nlocal btn = _G[e.id..\"Button\"]\nbtn:SetAttribute(\"macrotext1\", \"/use item:6948\")\nbtn:SetAttribute(\"macrotext2\", \"/use item:6948\")\nbtn:SetAttribute(\"macrotext3\", \"/use item:6948\")\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_BOTTOM\") \n        GameTooltip:SetText(\"|cffffffff露露的快捷按钮|r\\n\"..\"|cffffffff左键：|cff00ffff炉石|r\")\nend)\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()",
