["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    if event == 'MERFIN_WARNING' then\n        if not aura_env.order then return end\n        if aura_env.lineCount == 0 then return end\n        \n        local _, warning = ...\n        \n        if warning.ID == 'CrossedOver' then\n            aura_env.lastCrossedOver = aura_env.lastCrossedOver or 0\n            local now = GetTime()\n            \n            -- Anti-spam\n            if now - aura_env.lastCrossedOver > 10 then\n                aura_env.lastCrossedOver = now\n                local count = warning.count\n                local nextStep = (count % aura_env.lineCount) + 1\n                aura_env.RefreshActualOrder(nextStep)\n                states:Update('', { step = nextStep })\n            end\n            \n        elseif warning.ID == 'VoodooDoll' and states[''] then\n            -- Update the order after Voodoo Doll debuffs applied\n            local nextStep = states[''].step\n            aura_env.RefreshActualOrder(nextStep)\n            states:Update('', { step = nextStep })\n        end\n        \n    elseif event == 'GROUP_SWAPS_RL' then\n        local order, backup, lineCount = ...\n        aura_env.order, aura_env.backup, aura_env.lineCount = order, backup, lineCount\n        \n        if not aura_env.order then return end\n        if aura_env.lineCount == 0 then return end\n        \n        if not aura_env.firstCallback then\n            local count = 0\n            local nextStep = (count % aura_env.lineCount) + 1\n            aura_env.RefreshActualOrder(nextStep)\n            states:Update('', { step = nextStep })\n        end\n        \n    elseif event == 'ENCOUNTER_START' then\n        aura_env.firstCallback = false\n        aura_env.lastCrossedOver = 0\n        \n    elseif event == 'OPTIONS' then\n        states:Update('', { step = 1 })\n    end\nend",
