["customText"] = "function()\n    \n    if WeakAuras.IsOptionsOpen() then\n        local nextStep = aura_env.state.step\n        local order = { WeakAuras.me, 'Scarpa', 'Devil', 'Kyn', 'Merfin' }\n        local nextPlayers = aura_env.BuildStringLine(order)\n        return nextPlayers\n    end\n    \n    local nextStep = aura_env.state.step\n    local nextPlayers = aura_env.BuildStringLine(aura_env.actualOrder)\n    return nextPlayers\n    \nend",
["exrtLastSync"] = 1751209613,
["useAdjustededMin"] = false,
["regionType"] = "icon",
["preferToUpdate"] = true,
["anchorFrameType"] = "SELECTFRAME",
["alpha"] = 1,
["config"] = {
},
["anchorFrameParent"] = false,
["useCooldownModRate"] = true,
["cooldownTextDisabled"] = true,
["zoom"] = 0.3,
["semver"] = "1.2.2",
["tocversion"] = 50500,
["id"] = "[Widget] Gara'jal Groups Icon",
["url"] = "https://space.bilibili.com/455259",
["frameStrata"] = 1,
["width"] = 70,
["progressSource"] = {
-1,
"",
},
["uid"] = "GlCEsBP2oop",
["inverse"] = false,
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local debuffCondition = {\n    [122151] = true, -- Voodoo Doll\n    [117723] = true, -- Frail Soul\n}\n\nlocal ClassColorName = function(name)\n    local _, class = UnitClass(name)\n    local color = RAID_CLASS_COLORS[class]\n    if color then\n        return string.format(\"|cFF%02X%02X%02X%s|r\", color.r * 255, color.g * 255, color.b * 255, name)\n    else\n        return name\n    end\nend\n\nlocal IsHealer = function(name)\n    return name and UnitGroupRolesAssigned(name) == \"HEALER\"\nend\n\naura_env.BuildStringLine = function(line)\n    local result = \"\"\n    for i, name in ipairs(line) do\n        local coloredName = ClassColorName(name)\n        \n        if IsHealer(name) then\n            coloredName = \"|A:groupfinder-icon-role-large-heal:16:16:0:0|a\" .. coloredName\n        end\n        \n        if name == WeakAuras.me then\n            coloredName = \">> \" .. coloredName .. \" <<\"\n        end\n        \n        result = result .. coloredName\n        if i < #line then\n            result = result .. \"\\n\"\n        end\n    end\n    return result\nend\n\naura_env.IsUnitEligible = function(unitName)\n    if UnitIsDeadOrGhost(unitName) then\n        return false\n    end\n    \n    for spellID in pairs(debuffCondition) do\n        local debuff = WA_GetUnitDebuff(unitName, spellID)\n        if debuff then\n            return false\n        end\n    end\n    \n    return true\nend\n\naura_env.RefreshActualOrder = function(nextStep)\n    aura_env.actualOrder = {}\n    local requiresBackup = {}\n    local usedBackup = {}\n    \n    for _, unitName in ipairs(aura_env.order[nextStep]) do\n        if aura_env.IsUnitEligible(unitName) then\n            table.insert(aura_env.actualOrder, unitName)\n        else\n            table.insert(requiresBackup, unitName)\n        end\n    end\n    \n    for _, replacedUnit in ipairs(requiresBackup) do\n        local backupFound = false\n        \n        if IsHealer(replacedUnit) then\n            for _, candidate in ipairs(aura_env.backup) do\n                if aura_env.IsUnitEligible(candidate) and IsHealer(candidate) and not usedBackup[candidate] then\n                    table.insert(aura_env.actualOrder, candidate)\n                    usedBackup[candidate] = true\n                    backupFound = true\n                    break\n                end\n            end\n        end\n        \n        if not backupFound then\n            for _, candidate in ipairs(aura_env.backup) do\n                if aura_env.IsUnitEligible(candidate) and not usedBackup[candidate] then\n                    table.insert(aura_env.actualOrder, candidate)\n                    usedBackup[candidate] = true\n                    break\n                end\n            end\n        end\n    end\nend",
["do_custom"] = true,
},
