["subeventPrefix"] = "SPELL",
["custom"] = "function(e, schedEvent, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 120001 then\n                local count = aura_env.ManageCounter('increase', 'Detonate')\n                aura_env.Warning('Detonate', count)\n                aura_env.StartCD('Detonate', 45.5)\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if USSspellID == 119990 then\n            local count = aura_env.ManageCounter('increase', 'SummonSappling')\n            aura_env.Warning('SummonSappling', count)\n            aura_env.StartCD('SummonSappling', 45)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('SummonSappling', 10)\n        aura_env.StartCD('Detonate', 30.2)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
