["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'DrawPower'\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r @cffffff40+%damage%@r %icon\",\n}\n\nlocal name, icon = C_Spell.GetSpellName(119387), C_Spell.GetSpellTexture(119387)\n\naura_env.SendWarning = function(amount)\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        damage = amount * 10,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID,_,_,_, amount = ...\n        \n        if spellID == 119387 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning(amount or 1)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
