["Challenge Mode Timer"] = {
["sparkWidth"] = 10,
["iconSource"] = -1,
["xOffset"] = -45,
["adjustedMax"] = "",
["yOffset"] = 140,
["anchorPoint"] = "RIGHT",
["sparkRotation"] = 0,
["url"] = "https://wago.io/progress_mv/77",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.personalBest = CHALLENGES_RECORD_TIME\naura_env.realmBest = CHALLENGE_MODE_REALM_BEST\n\nif WatchFrame then\n    WatchFrame:SetScript(\"OnEvent\", nil)\n    WatchFrame:Hide()\nend\n\naura_env.FormatTime = function(seconds)\n    local m = math.floor(seconds / 60)\n    local s = seconds % 60\n    return string.format(\"%02d:%02d\", m, s)\nend\n\naura_env.GetPersonalBestTime = function()\n    local activeCMMapID = C_ChallengeMode.GetActiveChallengeMapID()\n    local _, bestTimeMS = GetChallengeModeMapPlayerStats(activeCMMapID)\n    if bestTimeMS then\n        local bestTimeSec = bestTimeMS / 1000\n        return bestTimeSec, aura_env.FormatTime(bestTimeSec)\n    end\n    return nil, nil\nend\n\naura_env.GetRealmBestTime = function(instanceMapID)\n    local _, realmBestMS = C_ChallengeMode.GetChallengeBestTime(instanceMapID)\n    if realmBestMS then\n        local realmTimeSec = realmBestMS / 1000\n        return realmTimeSec, aura_env.FormatTime(realmTimeSec)\n    end\n    return nil, nil\nend\n\naura_env.GetCurrentMedalData = function(mapTimers, elapsedTime)\n    local totalInstanceTime = mapTimers[1]\n    \n    local medalType, medalName, icon, duration, expirationTime\n    \n    if elapsedTime < mapTimers[3] then\n        -- Gold\n        medalType = 1\n        medalName = CHALLENGE_MODE_MEDAL3\n        icon = CHALLENGE_MEDAL_TEXTURES[medalType]\n        duration = mapTimers[3]\n        expirationTime = GetTime() + (mapTimers[3] - elapsedTime)\n    elseif elapsedTime < mapTimers[2] then\n        -- Silver\n        medalType = 2\n        medalName = CHALLENGE_MODE_MEDAL2\n        icon = CHALLENGE_MEDAL_TEXTURES[medalType]\n        duration = mapTimers[2]\n        expirationTime = GetTime() + (mapTimers[2] - elapsedTime)\n    elseif elapsedTime < totalInstanceTime then\n        -- Bronze\n        medalType = 3\n        medalName = CHALLENGE_MODE_MEDAL1\n        icon = CHALLENGE_MEDAL_TEXTURES[medalType]\n        duration = totalInstanceTime\n        expirationTime = GetTime() + (totalInstanceTime - elapsedTime)\n    else\n        -- Expired\n        medalType = 4\n        medalName = \"Expired\"\n        icon = \"\"\n        duration = totalInstanceTime\n        expirationTime = GetTime()\n    end\n    \n    return {\n        medalType         = medalType,\n        medalName         = medalName,\n        totalTime         = duration,\n        medalElapsed      = elapsedTime,\n        expirationTime    = expirationTime,\n        remainingTime     = duration - elapsedTime,\n        icon              = icon,\n        formattedTime     = aura_env.FormatTime(elapsedTime),\n        formattedTotal    = aura_env.FormatTime(duration)\n    }\nend\n\naura_env.GenerateDummyState = function(states)\n    local dummyElapsed   = 400  -- 6:40 elapsed\n    local dummyTotal     = 1320 -- Silver duration (22:00)\n    local dummyRemaining = dummyTotal - dummyElapsed\n    local dummyExpiration = GetTime() + dummyRemaining\n    \n    states:Update('', {\n            progressType              = 'timed',\n            duration                  = dummyTotal,\n            expirationTime            = dummyExpiration,\n            \n            currentTime               = dummyElapsed,\n            medalElapsedTime          = dummyElapsed,\n            totalTime                 = dummyTotal,\n            formattedTime             = aura_env.FormatTime(dummyElapsed),\n            formattedElapsedTime      = aura_env.FormatTime(dummyElapsed),\n            formattedTotalTime        = aura_env.FormatTime(dummyTotal),\n            \n            icon                      = CHALLENGE_MEDAL_TEXTURES[2], -- Silver icon\n            formattedIcon             = Merfin.GetIconCropped(CHALLENGE_MEDAL_TEXTURES[2], 16),\n            \n            medal                     = 2,\n            medalName                 = CHALLENGE_MODE_MEDAL2,\n            \n            personalBestTime          = 800,\n            formattedPersonalBestTime = aura_env.FormatTime(800),\n            isPersonalBestFailed      = false,\n            \n            realmBestTime             = 750,\n            formattedRealmBestTime    = aura_env.FormatTime(750),\n            isRealmBestFailed         = false,\n    })\nend",
["do_custom"] = true,
},
},
