["customTextUpdate"] = "update",
["automaticWidth"] = "Auto",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["events"] = "CHALLENGE_MODE_START, CHALLENGE_MODE_COMPLETED, WORLD_STATE_TIMER_START, MERFIN_CM_UPDATE_TIME, PLAYER_ENTERING_WORLD, ZONE_CHANGED_INDOORS",
["custom"] = "function(states, event)\n    \n    if not C_AddOns.IsAddOnLoaded(\"Blizzard_ChallengesUI\") then\n        C_AddOns.LoadAddOn(\"Blizzard_ChallengesUI\")\n    end\n    \n    if event == \"OPTIONS\" and select(3, GetInstanceInfo()) ~= 8 then\n        aura_env.GenerateDummyState(states)\n        return true\n    end\n    \n    if not C_ChallengeMode.IsChallengeModeActive() then\n        if aura_env.ticker then\n            aura_env.ticker:Cancel()\n            aura_env.ticker = nil\n        end\n        states:Remove('')\n        return true\n    end\n    \n    if event == \"MERFIN_CM_UPDATE_TIME\" then\n        local _, elapsedTime = GetWorldElapsedTime(1)\n        if not elapsedTime then return end\n        \n        local instanceMapID = select(8, GetInstanceInfo())\n        if not instanceMapID then return end\n        \n        local mapTimers = C_ChallengeMode.GetChallengeModeMapTimes(instanceMapID)\n        if not mapTimers then return end\n        \n        local personalBest, formattedPersonalBest = aura_env.GetPersonalBestTime()\n        local realmBest, formattedRealmBest       = aura_env.GetRealmBestTime(instanceMapID)\n        local medalData                           = aura_env.GetCurrentMedalData(mapTimers, elapsedTime)\n        \n        states:Update('', {\n                progressType              = 'timed',\n                duration                  = medalData.totalTime,\n                expirationTime            = medalData.expirationTime,\n                \n                currentTime               = elapsedTime,\n                medalElapsedTime          = medalData.medalElapsed,\n                totalTime                 = medalData.totalTime,\n                formattedTime             = medalData.formattedTime,\n                formattedElapsedTime      = aura_env.FormatTime(elapsedTime),\n                formattedTotalTime        = medalData.formattedTotal,\n                \n                icon                      = medalData.icon,\n                formattedIcon             = medalData.icon and Merfin.GetIconCropped(medalData.icon, 16),\n                \n                medal                     = medalData.medalType,\n                medalName                 = medalData.medalName,\n                \n                personalBestTime          = personalBest,\n                formattedPersonalBestTime = formattedPersonalBest,\n                isPersonalBestFailed      = personalBest and elapsedTime > personalBest,\n                \n                realmBestTime             = realmBest,\n                formattedRealmBestTime    = formattedRealmBest,\n                isRealmBestFailed         = realmBest and elapsedTime > realmBest,\n        })\n        return true\n    end\n    \n    if not aura_env.ticker then\n        aura_env.ticker = C_Timer.NewTicker(1, function()\n                WeakAuras.ScanEvents(\"MERFIN_CM_UPDATE_TIME\")\n        end)\n    end\n    \n    WeakAuras.ScanEvents(\"MERFIN_CM_UPDATE_TIME\")\n    return true\nend",
