["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 113764 then\n                local count = aura_env.ManageCounter('increase', 'FirestormKick')\n                aura_env.Warning('FirestormKick', count)\n                aura_env.StartCD('FirestormKick', 25)\n            elseif spellID == 114807 then\n                local count = aura_env.ManageCounter('increase', 'BlazingFists')\n                aura_env.Warning('BlazingFists', count)\n                aura_env.StartCD('BlazingFists', 30)\n                aura_env.TTS('Frontal')\n            end\n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 114465 then\n                if destGUID == WeakAuras.myGUID and aura_env.Antispam(spellID, 2) then\n                    aura_env.Warning('ScorchedEarthGTFO')\n                end\n            elseif spellID == 113766 then\n                if destGUID == WeakAuras.myGUID and aura_env.Antispam(spellID, 2) then\n                    aura_env.Warning('FirestormKickGTFO')\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('FirestormKick', 10)\n        aura_env.StartCD('BlazingFists', 20.5)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
