["unit"] = "player",
["custom"] = "function(states, event, ...)\n    if event == 'OPTIONS' then\n        states:Update('', { stacks = 2 })\n        \n    elseif event == 'MERFIN_WARNING' then\n        local _, warning = ...\n        if warning.ID == 'Overload' then\n            if states[''] then\n                states[''].stacks  = states[''].stacks - 1\n                states[''].changed = true\n                return true\n            end\n        end\n        \n    elseif event == 'FLOOR_FALLING' then\n        states:Update('', { stacks = 6 })\n        \n    elseif event == 'ELEGON_PHASE' then\n        local phaseN = ...\n        \n        if (phaseN == 1 or phaseN == 2) and states[''] then\n            states:Remove('')\n        end\n    end\nend",
