["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1463'\nlocal ID          = 'FuriousSwipe'\n\nlocal name, icon = C_Spell.GetSpellName(122735), C_Spell.GetSpellTexture(122735)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r %icon\",\n    ttsLine = Merfin:L('Frontal'),\n    prewarnTTStext = Merfin:L('Frontal Soon'),\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 122735 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(8)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(8)\n    end\nend",
