["init"] = {
["custom"] = "local encounterID = '1463'\nlocal ID          = 'UnderBoss'\n\nlocal options = {\n    ['UnderBoss'] = {\n        warningText = \"@cffffff80%name@r » %destName\",\n    },\n    ['UnderBossMe'] = {\n        warningText = \"@cffff4040\" .. Merfin:L('Move Out'):upper() .. \"@r\",\n    }\n}\n\naura_env.SendWarning = function(ID, destName)\n    local warning = {\n        ID       = ID,\n        name     = 'Under Boss',\n        noCount  = true,\n        destName = WA_ClassColorName(destName),\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, warning, options[ID])\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = { Under = \"under him\" },\n    ['zhCN'] = { Under = \"在它下方\" },\n    ['deDE'] = { Under = \"Unter ihm\" },\n    ['frFR'] = { Under = \"sous lui\" },\n    ['ruRU'] = { Under = \"под ним\" },\n    ['koKR'] = { Under = \"있는 것을 감지하고\" },\n    ['zhTW'] = { Under = \"在他下面\" },\n    ['esES'] = { Under = \"Debajo de él\" },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        local msg,_,_,_, destName = ...\n        \n        if msg:find(\"spell:122774\") and aura_env.IsEmote(msg, 'Under') then\n            aura_env.count = aura_env.count + 1\n            local ID = destName == WeakAuras.me and 'UnderBossMe' or 'UnderBoss'\n            aura_env.SendWarning(ID, destName)\n            \n            GMRT.F.Note_Timer('CRUSH_UNDER_' .. aura_env.count)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
