["custom"] = "\n    ",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, scheduledEvent, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 106851 then\n                local count = aura_env.ManageCounter('increase', 'BlackoutBrew')\n                aura_env.Warning('BlackoutBrew', count)\n                aura_env.StartCD('BlackoutBrew', 10.5)\n                --aura_env.TTS(spellName)\n            elseif spellID == 106563 then\n                local count = aura_env.ManageCounter('increase', 'BubbleShield')\n                aura_env.Warning('BubbleShield', count)\n                aura_env.StartCD('BubbleShield', 42)\n                aura_env.TTS(spellName)\n            elseif spellID == 115003 then\n                local count = aura_env.ManageCounter('increase', 'Carbonation')\n                aura_env.Warning('Carbonation', count)\n                aura_env.StartCD('Carbonation', 64)\n                aura_env.TTS(spellName)\n            elseif spellID == 106546 then\n                --local count = aura_env.ManageCounter('increase', 'Bloat')\n                --aura_env.Warning('Bloat', count)\n                aura_env.StartCD('Bloat', 14.5)\n                --aura_env.TTS(spellName)\n            elseif spellID == 116155 then\n                if not aura_env.mobCollector[sourceGUID] then\n                    aura_env.mobCollector[sourceGUID] = true\n                    local count = aura_env.ManageCounter('increase', 'NextAdd')\n                    if count < 5 then\n                        aura_env.StartCD('NextAdd', 18)\n                    end\n                end\n            end\n        elseif subEvent == 'SPELL_HEAL' then\n            if spellID == 114451 then\n                if not aura_env.mobCollector[sourceGUID] then\n                    aura_env.mobCollector[sourceGUID] = true\n                    local count = aura_env.ManageCounter('increase', 'NextAdd')\n                    if count < 5 then\n                        aura_env.StartCD('NextAdd', 18)\n                    end\n                end\n                if aura_env.IsGUID(destGUID, 'YAN_ZHU') \n                and aura_env.Antispam('InterceptBeam', 2) then\n                    aura_env.Warning('InterceptBeam')\n                end\n            end\n        end\n        \n    elseif e == 'WA_MERFIN_DUNGEON_SCHEDULED' then\n        if scheduledEvent == 'ENCOUNTER_START_DELAYED' then\n            \n            print('Boss Exists: ', UnitExists('boss1'))\n            \n            if WA_GetUnitAura('boss1', 114929) then -- Bloating Brew\n                aura_env.StartCD('Bloat', 7)\n            elseif WA_GetUnitAura('boss1', 114930) then -- Blackout Brew\n                aura_env.StartCD('BlackoutBrew', 6.6)\n            end\n            \n            if WA_GetUnitAura('boss1', 114931) then -- Bubbling Brew\n                aura_env.StartCD('BubbleShield', 22.1)\n            elseif WA_GetUnitAura('boss1', 114932) then -- Yeasty Brew\n                aura_env.StartCD('NextAdd', 21.8, true)\n            end\n            \n            if WA_GetUnitAura('boss1', 114933) then -- Sudsy Brew\n                aura_env.StartCD('WallOfSuds', 29.8, true)\n            elseif WA_GetUnitAura('boss1', 114934) then -- Fizzy Brew\n                aura_env.StartCD('Carbonation', 45.8)\n            end\n            \n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.ScheduleEvent('ENCOUNTER_START_DELAYED', 0.1)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
