["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 117837 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(20.5)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'MENG' then return end\n        \n        if activated then \n            aura_env.StartCD(20.5-delay)\n        else\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
