["parent"] = "[Widget] Cooldowns",
["customText"] = "function()\n    return Merfin:L('Player Explosion')\nend",
["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n    cooldownId = {\n        display = 'Cooldown ID',\n        type = 'string',\n    },\n    noCount = {\n        display = 'Missing Counter',\n        type = 'bool'\n    },\n    hasSrcName = {\n        display = 'Has Source Name',\n        type = 'bool',\n    },\n    isPlayer = {\n        display = 'Is Source Me',\n        type = 'bool',\n    },\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        for i = 1, 2 do\n            local duration = math.random(3, 10)\n            local newState = {\n                progressType   = 'timed',\n                autoHide       = false,\n                duration       = duration,\n                expirationTime = duration + GetTime(),\n                name           = 'Amber Explosion',\n                nextCount      = math.random(1, 10),\n            }\n            \n            states:Update(i, newState)\n        end\n    end\n    \n    if e == 'MERFIN_CD_HIDE' then\n        local encounterID, cooldown = ...\n        \n        if not (cooldown.ID == 'AmberExplosion' or cooldown.ID == 'AmberExplosionM') then return end\n        local stateName = encounterID .. cooldown.ID .. (cooldown.GUID or '')\n        states:Remove(stateName)\n        \n    elseif e == 'MERFIN_CD_SHOW_WIDGET' then\n        local encounterID, cooldown = ...\n        \n        if not (cooldown.ID == 'AmberExplosion' or cooldown.ID == 'AmberExplosionM') then return end\n        if cooldown.sourceGUID and cooldown.sourceGUID ~= WeakAuras.myGUID then return end\n        \n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        \n        local newState = {\n            progressType   = 'timed',\n            duration       = cooldown.duration,\n            expirationTime = cooldown.expirationTime,\n            autoHide       = cooldown.autoHide,\n            icon           = cooldown.icon,\n            name           = cooldown.name,\n            nextCount      = (cooldown.count or 0) + 1,\n            noCount        = cooldown.noCount,\n            cooldownId     = cooldown.ID,\n            sourceName     = cooldown.sourceName,\n            hasSrcName     = cooldown.sourceName ~= nil,\n            isPlayer       = cooldown.isPlayer\n        }\n        \n        states:Update(stateName, newState)\n    end\nend",
