["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_AUR_APPLIED' then\n            if spellID == 27607 then\n                aura_env.Warning('PW:S')\n                aura_env.TTS('Purge')\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 113134 then\n                local count = aura_env.ManageCounter('increase', 'MassResurrection')\n                aura_env.Warning('MassResurrection', count)\n                aura_env.StartCD('MassResurrection', 21)\n            elseif spellID == 12039 then\n                local count = aura_env.ManageCounter('increase', 'Heal')\n                aura_env.Warning('Heal', count)\n            elseif spellID == 130857 then\n                local count = aura_env.ManageCounter('increase', 'MindControl')\n                aura_env.Warning('MindControl', count)\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 9256 then\n                aura_env.phase = 3\n                aura_env.Warning('DeepSleep')\n                aura_env.StartCD('MassResurrection', 18)\n                if aura_env.IsChallenge then\n                    aura_env.StartCD('MindControl', 19)\n                end\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'DURAND') then\n                if aura_env.phase ~= 3 then\n                    phase = 2\n                    aura_env.StartCD('MassResurrection', 13)\n                    if aura_env.IsChallenge then\n                        aura_env.StartCD('MindControl', 14)\n                    end\n                    aura_env.StopCD('FlashOfSteel')\n                    aura_env.StopCD('DashingStrike')\n                end\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if USSspellID == 115627 and aura_env.Antispam(USSspellID, 2) then\n            local count = aura_env.ManageCounter('increase', 'FlashOfSteel')\n            aura_env.Warning('FlashOfSteel', count)\n            aura_env.StartCD('FlashOfSteel', 26)\n        elseif USSspellID == 115676 and aura_env.Antispam(USSspellID, 2) then\n            local count = aura_env.ManageCounter('increase', 'DashingStrike')\n            aura_env.Warning('DashingStrike', count)\n            aura_env.StartCD('DashingStrike', 26)\n        end\n        \n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('FlashOfSteel', 9)\n        aura_env.StartCD('DashingStrike', 24)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
