["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'DreadSpray'\n\nlocal name, icon = C_Spell.GetSpellName(120047), C_Spell.GetSpellTexture(120047)\n\nlocal options = {\n    warningText = '%icon @cffff8b17%name@r %icon',\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n    prewarnCountVA = 2,\n}\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID, GUID = GUID})\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            GUID = GUID\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.bowManSeq = {\n    [61038] = {4, 8, 8, 4, 3, 7, 7, 3, 2, 6, 6, 2, 1, 5, 5, 1}, -- Yang Guoshi\n    [61042] = {1, 4, 5, 6, 3, 6, 7, 8, 5, 8, 1, 2, 7, 2, 3, 4}, -- Cheng Kang\n    [61046] = {5, 6, 8, 1, 7, 8, 2, 3, 1, 2, 4, 5, 3, 4, 6, 7} -- Jinlun Kun\n}",
["do_custom"] = true,
},
