["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' and aura_env.onPlatform then\n        local _, subEvent,_, sourceGUID,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 120047 and aura_env.guardianID then -- Dread Spray\n                if aura_env.guardianID == Merfin.GetNPCIDFromGUID(sourceGUID) then\n                    aura_env.SendWarning()\n                    aura_env.StartCD(20.5, sourceGUID)\n                end\n            end\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            -- Mob Engages. Here we track the very first CD of Dread Spray\n            if spellID == 119862 and not aura_env.platformGUIDs[sourceGUID] then -- Shot\n                aura_env.platformGUIDs[sourceGUID] = true\n                aura_env.guardianID = Merfin.GetNPCIDFromGUID(sourceGUID)\n                aura_env.StartCD(10.5, sourceGUID)\n                WeakAuras.ScanEvents('DREAD_SPRAY', false, aura_env.guardianID, 0)\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 120047 then\n                aura_env.sprayCounter = 0\n                WeakAuras.ScanEvents('DREAD_SPRAY', true, aura_env.guardianID, aura_env.sprayCounter)\n                \n            elseif spellID == 119983 then\n                aura_env.sprayCounter = aura_env.sprayCounter + 1\n                WeakAuras.ScanEvents('DREAD_SPRAY', true, aura_env.guardianID, aura_env.sprayCounter)\n                \n                -- Reset after 16th shot\n                if aura_env.sprayCounter == 16 then\n                    C_Timer.After(0.5, function()\n                            if aura_env.guardianID then\n                                WeakAuras.ScanEvents('DREAD_SPRAY', false, aura_env.guardianID, 0)\n                            end\n                    end)\n                end\n            end\n        end\n        \n    elseif e == 'ENTER_PLATFORM' then\n        aura_env.onPlatform = true\n        \n    elseif e == 'LEAVE_PLATFORM' then\n        aura_env.onPlatform = false\n        aura_env.platformGUIDs = {}\n        aura_env.guardianID = nil\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        \n        if aura_env.platformGUIDs[destGUID] then\n            aura_env.StopCD(destGUID)\n        end\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase2 = true\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.onPlatform = false\n        aura_env.sprayCounter = 0\n        aura_env.platformGUIDs = {}\n        aura_env.guardianID = nil\n    end\nend",
