["[督军佐诺兹] 方向决定器后端"] = {
["outline"] = "OUTLINE",
["wagoID"] = "r2q5DNxZh",
["parent"] = "[小工具] [督军佐诺兹] 干扰之影协调器",
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "-- Table to store players with the debuff\nlocal playersWithDebuff = {}\nlocal schedulePending = false\n\n-- Function to assign positions and trigger events\nlocal function assignPlayers()\n    -- Sort players alphabetically by name\n    table.sort(playersWithDebuff, function(a, b)\n            return a.name < b.name\n    end)\n    \n    -- Assign positions and send events immediately for the first two players\n    for index, playerData in ipairs(playersWithDebuff) do\n        if playerData.name == WeakAuras.me then\n            -- Determine position based on the player's index\n            if index % 2 == 0 then\n                playerData.position = \"RIGHT\"\n                WeakAuras.ScanEvents(\"PLAYER_POSITION_ASSIGNED\", \"RIGHT\")\n            else\n                playerData.position = \"LEFT\"\n                WeakAuras.ScanEvents(\"PLAYER_POSITION_ASSIGNED\", \"LEFT\")\n            end\n            \n        end\n    end\n    \n    -- Clear pending state\n    schedulePending = false\nend\n\n-- Event handler function\n-- Triggered on SPELL_AURA_APPLIED and SPELL_AURA_REMOVED\naura_env.OnTrigger = function(event, timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, _,_, dispelSpellId)\n    -- Reset state at the start of the encounter\n    if event == 'ENCOUNTER_START' then\n        playersWithDebuff = {}\n    end\n    \n    \n    if subEvent == \"SPELL_AURA_APPLIED\" and spellId == 103434 then\n        \n        if not aura_env.last or GetTime() - aura_env.last > 5 then\n            playersWithDebuff = {}\n            aura_env.last = GetTime()\n        end\n        \n        -- Add the player to the debuff list\n        table.insert(playersWithDebuff, { name = destName, guid = destGUID })\n        \n        -- Schedule position assignment if not already scheduled\n        if not schedulePending then\n            schedulePending = true\n            C_Timer.After(0.5, assignPlayers)\n        end\n    end\n    \n    --[[if (subEvent == \"SPELL_AURA_REMOVED\" and spellId == 103434) \n    or (subEvent == 'SPELL_DISPEL' and dispelSpellId == 103434) then\n        for index, playerData in ipairs(playersWithDebuff) do\n            if playerData.name == destName then\n                -- Check if there's a next player in the list\n                local nextPlayer = playersWithDebuff[index + 2]\n                if nextPlayer and nextPlayer.name == WeakAuras.me then\n                    WeakAuras.ScanEvents(\"PLAYER_POSITION_ASSIGNED\", nextPlayer.position)\n                end\n                \n                break\n            end\n        end\n    end]]--\nend",
["do_custom"] = true,
},
},
