["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 118988 or spellID == 129262 then\n                local count = aura_env.ManageCounter('increase', 'RecklessInspiration')\n                aura_env.Warning('RecklessInspiration', amount)\n            elseif spellID == 118958 then\n                local count = aura_env.ManageCounter('increase', 'IronProtector')\n                aura_env.Warning('IronProtector', amount)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 129262 then\n                local count = aura_env.ManageCounter('increase', 'RecklessInspiration')\n                aura_env.Warning('RecklessInspiration', amount)\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 118903 then\n                aura_env.StartCD('Hex', true)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
