["subeventPrefix"] = "SPELL",
["custom"] = "function(e, schedEvent, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 131521 then\n                local count = aura_env.ManageCounter('increase', 'RingOfMalice')\n                aura_env.Warning('RingOfMalice', count)\n                aura_env.StartCD('RingOfMalice', 40)\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 115002 and aura_env.Antispam(spellID, 5) then\n                local count = aura_env.ManageCounter('increase', 'SummonGrippingHatred')\n                aura_env.Warning('SummonGrippingHatred', count)\n                aura_env.StartCD('SummonGrippingHatred', 43.7)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 107356 then\n                local count = aura_env.ManageCounter('increase', 'RisingHate')\n                aura_env.Warning('RisingHate', count)\n                aura_env.StartCD('RisingHate', 15.7)\n                aura_env.TTS('Interrupt')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('RingOfMalice', 10.8)\n        aura_env.StartCD('SummonGrippingHatred', 15.6)\n        aura_env.StartCD('RisingHate', 19.2)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
