["custom"] = "local encounterID = '1395'\nlocal ID          = 'JasperChains'\n\nlocal name, icon = C_Spell.GetSpellName(130395), C_Spell.GetSpellTexture(130395)\n\nlocal options = {\n    warningText = '%icon @cffffff80%name@r » %destName (%count) %icon',\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local names = {}\n    for _, name in ipairs(aura_env.targets) do\n        table.insert(names, WA_ClassColorName(name))\n    end\n    \n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = table.concat(names, ', '),\n        name     = name,\n        icon     = icon,\n        localization = localization,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispams[ID] or cur - aura_env.antispams[ID] > before then\n        aura_env.antispams[ID] = cur\n        return false\n    end\n    return true\nend\n\naura_env.ScheduleEvent = function(ID, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[ID] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[ID])\n    end\n    \n    aura_env.schedulers[ID] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'MERFIN_SCHEDULED',\n        ID\n    )\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local  _, subEvent,_, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID = ...\n        \n        if spellID ~= 130395 then return end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if not aura_env.IsSpam(3) then\n                aura_env.targets = {}\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(12)\n                \n                C_Timer.After(0.3, function()\n                        WeakAuras.ScanEvents('CHAINS_TARGETS', mate) \n                end)\n            end\n            \n            table.insert(aura_env.targets, destName) \n            \n            if destGUID == WeakAuras.myGUID then\n                aura_env.rangeTicker = C_Timer.NewTimer(1.1, function()\n                        WeakAuras.ScanEvents('CHAINS_RANGE_MIN', mate) \n                end)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if destGUID == WeakAuras.myGUID then\n                \n                WeakAuras.ScanEvents('CHAINS_RANGE_MAX')\n                \n                if aura_env.rangeTicker then\n                    aura_env.rangeTicker:Cancel()\n                end\n                \n                aura_env.rangeTicker = C_Timer.NewTimer(1.1, function()\n                        WeakAuras.ScanEvents('CHAINS_RANGE_MIN', mate) \n                end)\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if destGUID == WeakAuras.myGUID and aura_env.rangeTicker then\n                aura_env.rangeTicker:Cancel()\n            end\n        end\n        \n    elseif e == 'CHAINS_TARGETS' then\n        aura_env.SendWarning()\n        WeakAuras.ScanEvents('CHAINS_PAIR', aura_env.targets)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.antispams = {}\n        aura_env.targets = {}\n        aura_env.count = 0\n        \n        if WeakAuras.InstanceType() == 'twentyfive' \n        and WeakAuras.InstanceDifficulty() ~= 'lfr' then\n            aura_env.StartCD(12)\n        end\n        \n    elseif e == 'ENCOUNTER_ENGAGE' then -- Custom Event for 10 Man\n        local npcID = ...\n        if npcID == 59915 then\n            aura_env.StartCD(12 - 1)\n        end\n    end\nend",
