["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'Overload'\n\nlocal name, icon = C_Spell.GetSpellName(117204), C_Spell.GetSpellTexture(117204)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r @cffff4040+%damage%@r (%count) %icon\",\n}\n\naura_env.SendWarning = function(amount)\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon,\n        damage = amount * 20\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
