["do_sound"] = true,
},
["init"] = {
["custom"] = "-- 动作代码（初始化）\naura_env.GetOozeColorized = function(ooze)\n    \n    local colors = {\n        ['BLUE'] = '|cff4040ff蓝色|r',\n        ['PURPLE'] = '|cffff00ff紫色|r',\n        ['BLACK'] = '|cff4f4f4f黑色|r',\n        ['RED'] = '|cffff4040红色|r',\n        ['GREEN'] = '|cff00bf00绿色|r',\n        ['YELLOW'] = '|cffffff00黄色|r',\n    }\n    \n    return colors[ooze]\nend\n\naura_env.GetOozeName = function(ooze)\n    local names = {\n        ['BLUE'] = '蓝色',\n        ['PURPLE'] = '紫色',\n        ['BLACK'] = '黑色',\n        ['RED'] = '红色',\n        ['GREEN'] = '绿色',\n        ['YELLOW'] = '黄色',\n    }\n    return names[ooze] or ooze\nend\n\naura_env.summons = {\n    [1227589] = 'BLUE',\n    [1227598] = 'BLACK',\n    [1227595] = 'RED',\n    [1227450] = 'PURPLE',\n    [1227599] = 'GREEN',\n    [1227594] = 'YELLOW',\n}\n\naura_env.priority = {\n    ['BLACK'] = 1,\n    ['BLUE'] = 2,\n    ['RED'] = 3,\n    ['PURPLE'] = 4,\n    ['GREEN'] = 5,\n    ['YELLOW'] = 6,\n}\n\naura_env.GetTopPriority = function(list)\n    local topColor, topPriority = nil, math.huge\n    for _, color in ipairs(list) do\n        local priority = aura_env.priority[color]\n        if priority and priority < topPriority then\n            topColor, topPriority = color, priority\n        end\n    end\n    return topColor\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    priority = {\n        display = 'Color',\n        type = 'string',\n    }\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "-- 触发器代码\nfunction(a, e, ...)\n    \n    if e == 'OPTIONS' then\n        local topPriority = aura_env.GetOozeColorized('BLUE')\n        a[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            duration = 5,\n            expirationTime = 5 + GetTime(),\n            autoHide = true,\n            priority = topPriority,\n        }\n        \n        return true\n        \n    elseif e == 'ENCOUNTER_END' then\n        if aura_env.timer then\n            WeakAuras.timer:CancelTimer(aura_env.timer)\n        end\n        \n        if a[''] then\n            a[''].show = false\n            a[''].changed = true\n            return true\n        end\n        \n    elseif e == 'WA_MERFIN_OOZES_PRIO' then\n        local topPriority = aura_env.GetTopPriority(aura_env.summoned)\n        if not topPriority then\n            return\n        end\n        WeakAuras.ScanEvents('WA_MERFIN_OOZE_PRIORITY', topPriority)\n        a[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            duration = 5,\n            expirationTime = 5 + GetTime(),\n            autoHide = true,\n            priority = aura_env.GetOozeColorized(topPriority),\n        }\n        \n        -- 使用中文颜色名称进行语音提示\n        if topPriority then\n            C_VoiceChat.SpeakText(1, '集火 ' .. aura_env.GetOozeName(topPriority), Enum.VoiceTtsDestination.LocalPlayback, 1, 100)\n        end\n        \n        return true\n        \n    elseif e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        local _,_,_,_,_,_,_,_,_,_,_, spellId = ...\n        \n        local ooze = aura_env.summons[spellId]\n        if not ooze then\n            return\n        end\n        \n        local curTime = GetTime()\n        if not aura_env.throttle or curTime - aura_env.throttle > 5 then\n            aura_env.throttle = curTime\n            aura_env.summoned = {}\n            \n            if aura_env.timer then\n                WeakAuras.timer:CancelTimer(aura_env.timer)\n            end\n            \n            aura_env.timer = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, 0.1, 'WA_MERFIN_OOZES_PRIO')\n        end\n        \n        table.insert(aura_env.summoned, ooze)\n    end\nend",
