["subeventPrefix"] = "SPELL",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        local destName = WA_ClassColorName(WeakAuras.me)\n        \n        local newState = {\n            progressType   = 'timed',\n            duration       = 3,\n            expirationTime = 3 + GetTime(),\n            autoHide       = true,\n            displayText    = Merfin:L('BIG BANG INC.'),\n            icon           = 237538,\n            nextCount      = 2\n        }\n        \n        states:Update('', newState)\n    end\n    \n    if e == 'MERFIN_CD_STOP' or e == 'MERFIN_READY_HIDE' then\n        local encounterID, cooldown = ...\n        local stateName = encounterID .. cooldown.ID .. (cooldown.GUID or '')\n        states:Remove(stateName)\n        \n    elseif e == 'MERFIN_CD_READY' then\n        local encounterID, cooldown, readyText = ...\n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        \n        states:Update(stateName, {\n                displayText = readyText,\n                icon        = cooldown.icon,\n                nextCount   = cooldown.count and (cooldown.count + 1),\n                encounterID = tonumber(encounterID),\n        })\n        \n    elseif e == 'ENCOUNTER_END' then\n        local encounterID = ...\n        for stateName, state in pairs(states) do\n            if state.encounterID == encounterID then\n                states:Remove(stateName)\n            end\n        end\n    end\nend",
