["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.stformat = string.format\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    full = {\n        display = 'Is Full',\n        type = 'bool'\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    if event == 'OVERLOAD_DEF_ORDER' then\n        local order = ...\n        \n        if not order or #order == 0 then \n            aura_env.powerBreakpoint = nil\n            aura_env.cdSpellID = nil\n            return \n        end\n        \n        local indexToSpellID = {\n            [1] = 62618,  -- Power Word: Barrier\n            [2] = 98008,  -- Spirit Link Totem\n            [3] = 145629, -- Anti-Magic Zone\n            [4] = 31821,  -- Devotion Aura\n            [5] = 76577,  -- Smoke Bomb\n            [6] = 122507, -- Rallying Cry\n        }\n        \n        aura_env.myOrder = {}\n        aura_env.lineCount = 0\n        for step, stepOrder in ipairs(order) do\n            aura_env.lineCount = aura_env.lineCount + 1\n            for _, data in ipairs(stepOrder) do\n                if data.nickname == WeakAuras.me then\n                    aura_env.initialized = true\n                    aura_env.myOrder[step] = {\n                        powerBreakpoint = data.power,\n                        cdSpellID = indexToSpellID[data.cdIndex]\n                    }\n                end\n            end\n        end\n        \n        aura_env.step = 0\n        aura_env.count = 0\n        \n    elseif event == 'MERFIN_WARNING' then\n        if not aura_env.initialized then return end\n        local _, warning = ...\n        \n        if warning.ID == 'Overload' and not aura_env.IsSpam(5) then\n            aura_env.count = aura_env.count + 1\n        end\n        \n    elseif event == 'UNIT_POWER_UPDATE' then\n        if not aura_env.initialized then return end\n        \n        local max = 0\n        \n        for i = 1, 4 do\n            local bossID = aura_env.stformat('boss%d', i)\n            local bossPower = UnitExists(bossID) and UnitPower(bossID)\n            if bossPower and bossPower > max then\n                max = bossPower\n            end\n        end\n        \n        if max > 90 then\n            aura_env.step  = aura_env.count % aura_env.lineCount + 1\n            \n            local myData = aura_env.myOrder[aura_env.step]\n            if not myData then return end\n            \n            local spellCD = C_Spell.GetSpellCooldown(myData.cdSpellID)\n            \n            if spellCD.duration == 0 then\n                states:Update('', {\n                        progressType = 'static',\n                        value        = max - 90,\n                        total        = myData.powerBreakpoint - 90, \n                        full         = max - 90 >= myData.powerBreakpoint - 90,\n                        icon         = C_Spell.GetSpellTexture(myData.cdSpellID),\n                        name         = C_Spell.GetSpellName(myData.cdSpellID),\n                })\n                return true\n            end\n        end\n        states:Remove('')\n        \n    elseif event == 'OPTIONS' then\n        states:Update('', {\n                progressType = 'static',\n                value        = 98 - 92,\n                total        = 98 - 90,\n                icon         = C_Spell.GetSpellTexture(62618),\n                name         = C_Spell.GetSpellName(62618),\n        })\n        \n    elseif event == 'ENCOUNTER_START' then\n        aura_env.flag = false\n    end\nend",
