["sparkWidth"] = 10,
["sparkHeight"] = 30,
["customText"] = "function()\n    local locale = GetLocale()\n    \n    local maxHP = UnitHealthMax(\"player\") or 0\n    maxHP = (maxHP > 0 and maxHP or 1)\n    \n    -- Middle text: shows damage taken per tick\n    local staggertick = aura_env.state.tooltip1 or 0\n    local tickPercentOfHealth = format(\"%.1f\", (100 / maxHP * staggertick)) .. \"%\"\n    \n    -- Right text: Damage in stagger % of maxhealth\n    local stagger\n    if locale == \"deDE\" or locale == \"zhCN\" or locale == \"zhTW\" or locale == \"ruRU\" then\n        stagger = aura_env.state.tooltip2 or 0\n    else\n        stagger = aura_env.state.tooltip3 or 0\n    end\n    \n    if stagger then\n        local percentOfHealth = 100 / maxHP * stagger\n        local percentOfHealthFormat = format(\"%i\", percentOfHealth) .. \"%\"\n        aura_env.region:SetDurationInfo(percentOfHealth, 100, true)\n        return stagger, staggertick, percentOfHealthFormat\n    end\nend",
["width"] = 405,
["actions"] = {
