["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, _, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 106807 then\n                aura_env.StartCD('GroundPound', 10.5, false, true)\n                aura_env.Warning('GroundPound', aura_env.count['GroundPound'])\n                aura_env.TTS('Dodge Frontal')\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED'\n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 106651 then\n                aura_env.Warning('GoingBananas', amount, spellName)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('GroundPound', 10.5)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
