["custom"] = "local oozesOrder = WeakAuras.InstanceDifficulty() == 'heroic' and {\n    [1] = { 'PURPLE', 'GREEN', 'BLACK', 'BLUE' },\n    [2] = { 'GREEN', 'RED', 'BLUE', 'BLACK' },\n    [3] = { 'GREEN', 'YELLOW', 'BLACK', 'RED' },\n    [4] = { 'BLUE', 'PURPLE', 'GREEN', 'YELLOW' },\n    [5] = { 'BLUE', 'BLACK', 'PURPLE', 'YELLOW' },\n    [6] = { 'PURPLE', 'RED', 'YELLOW', 'BLACK' },\n} or {\n    [1] = { 'PURPLE', 'GREEN', 'BLUE' },\n    [2] = { 'GREEN', 'RED', 'BLACK' },\n    [3] = { 'GREEN', 'YELLOW', 'RED' },\n    [4] = { 'PURPLE', 'BLUE', 'YELLOW' },\n    [5] = { 'BLUE', 'BLACK', 'YELLOW' },\n    [6] = { 'PURPLE', 'RED', 'BLACK' },\n}\n\nlocal patterns = {}\nlocal cfg = aura_env.config.patterns\nfor i, patternN in pairs(cfg) do\n    local i = tonumber(i)\n    patterns[i] = oozesOrder[i][patternN]\nend\n\naura_env.GetPriorityFor = function(n)\n    return patterns[n]\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["custom"] = "function(a,_, n)\n    \n    if not n then\n        return\n    end\n    \n    local target = aura_env.GetPriorityFor(n)\n    \n    if not target then\n        return\n    end\n    \n    WeakAuras.ScanEvents('WA_MERFIN_OOZE_PRIORITY', target)\n    C_VoiceChat.SpeakText(1, 'Focus ' .. target, Enum.VoiceTtsDestination.LocalPlayback, 1, 100)\n    \nend",
