["events"] = "ENCOUNTER_START, CLEU:UNIT_DIED:SPELL_CAST_SUCCESS:SPELL_CAST_START:SPELL_AURA_APPLIED",
["custom"] = "function(a, event,_, subEvent,_, sourceGUID, sourceName,_,_, destGUID, destName,_,_, spellId)\n    \n    if event == 'OPTIONS' then\n        a[''] = {\n            show = true,\n            changed = true,\n            count = 3,\n        }\n        return true\n    end\n    \n    if event == 'ENCOUNTER_START' then\n        aura_env.deadBlood = {}\n        aura_env.count = 0\n        return\n    end\n    \n    if subEvent == 'SPELL_AURA_APPLIED' then\n        if aura_env.tankDebuffs[spellId] then\n            if aura_env.deadBlood[destGUID] and GetTime() - aura_env.deadBlood[destGUID] > 5 then\n                aura_env.count = aura_env.count - 1\n                a[''] = {\n                    show = true,\n                    changed = true,\n                    count = aura_env.count\n                }\n                return true\n            end\n        end\n    end\n    \n    if subEvent == 'SPELL_CAST_SUCCESS' then\n        if spellId == 105219 then\n            aura_env.deadBlood[sourceGUID] = GetTime()\n            aura_env.count = (aura_env.count or 0) + 1\n            a[''] = {\n                show = true,\n                changed = true,\n                count = aura_env.count\n            }\n            return true\n        elseif spellId == 105248 then\n            aura_env.count = aura_env.count - 1\n            a[''] = {\n                show = true,\n                changed = true,\n                count = aura_env.count\n            }\n            return true\n        end\n    end\n    \nend",
