["custom"] = "-- Credit to Merfin\n\nlocal GetMastery, GetSpellCritChance, GetSpellBonusDamage = GetMastery, GetSpellCritChance, GetSpellBonusDamage\nlocal UnitSpellHaste, UnitDamage = UnitSpellHaste, UnitDamage\n\nlocal Round = function(num) \n    return floor(num+.5) \nend\n\naura_env.useDeltaPercent = aura_env.config.deltaPercent\n\naura_env.predictedDamage     = { --[[ ID = damage --]] } -- \naura_env.snapshotDamageCast  = { --[[ ID = damage --]] } -- most recent snapshots\naura_env.snapshotDamage      = { --[[ ID = { destGUID = damage } --]] } -- most recent snapshots\n\naura_env.SendSyncEvent = function(ID, destGUID)\n    \n    local ScanEvent = function(destGUID)\n        local data = { \n            ID       = ID, \n            destGUID = destGUID, \n            predict  = aura_env.predictedDamage[ID], \n            snapshot = aura_env.snapshotDamage[ID][destGUID] \n        }\n        \n        WeakAuras.ScanEvents('MERFIN_SNAPSHOT_CHANGED', data)\n    end\n    \n    if not destGUID then\n        local guidPool = aura_env.snapshotDamage[ID]\n        if not guidPool then return end\n        \n        for destGUID in pairs(guidPool) do\n            ScanEvent(destGUID)\n        end\n        \n        return\n    end\n    \n    ScanEvent(destGUID)\nend\n\naura_env.SetPlayerSpec = function()\n    local specConsts = {\n        [1] = 'AFFLICTION',\n        [2] = 'DEMONOLOGY',\n        [3] = 'DESTRUCTION'\n    }\n    \n    local specID = C_SpecializationInfo.GetSpecialization(false)\n    \n    aura_env.playerSpec = specID and specConsts[specID] or 'NONE'\nend\n\nlocal stats = {}\n\nlocal GetCrit = function(school)\n    local crit = GetSpellCritChance(school)\n    return crit > 100 and 100 or crit\nend\n\naura_env.RefreshStats = function(spec)\n    local haste            = UnitSpellHaste(\"player\")\n    local crit             = GetSpellCritChance(6)\n    local spd              = GetSpellBonusDamage(6)\n    local damageMultiplier = select(7, UnitDamage(\"player\"))\n    local masteryEffect    = select(1, GetMasteryEffect())\n    local critBonus        = 1 + (crit / 100)\n    local masteryBonus     = 1 + masteryEffect / 100\n    \n    stats = {\n        haste            = haste,\n        crit             = crit,\n        spd              = spd,\n        damageMultiplier = damageMultiplier,\n        critBonus        = critBonus,\n        masteryBonus     = masteryBonus,\n        mastery          = masteryEffect\n    }\n    \n    if spec == 'AFFLICTION' then\n        stats.damageBonus = masteryBonus * critBonus\n        \n    elseif spec == 'DEMONOLOGY' then\n        stats.damageBonus = critBonus\n        stats.doomBonus   = 1\n        \n    elseif spec == 'DESTRUCTION' then\n        stats.damageBonus = (1 + (crit / 100)) * (1 + ((masteryEffect + 1) / 100))\n    end\nend\n\nlocal GetDamage = {}\n\nGetDamage['CORRUPTION'] = function()\n    local tickEvery = 2 / (1 + (stats.haste / 100))\n    local ticks     = Round(18 / tickEvery)\n    local duration  = ticks * tickEvery\n    local tickDmg   = (math.floor(176.253) + stats.spd * 0.165) * stats.masteryBonus\n    local damage    = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps       = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['AGONY'] = function()\n    local tickEvery = 3 / (1 + (stats.haste / 100))\n    local ticks     = Round(24 / tickEvery)\n    local duration  = ticks * tickEvery\n    \n    -- Agony scales with stack count from 2 to 10\n    -- For prediction we assume 10 stacks (max DPS)\n    local stack = 10\n    local tickDmg = (math.floor(27.2391) + stats.spd * 0.0255) * stack * stats.masteryBonus\n    local damage  = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps     = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['UA'] = function()\n    local tickEvery = 3 / (1 + (stats.haste / 100))\n    local ticks     = Round(14 / tickEvery)\n    local duration  = ticks * tickEvery\n    local tickDmg   = (math.ceil(309.778) + stats.spd * 0.29) * stats.masteryBonus\n    local damage    = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps       = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['IMMOLATE'] = function()\n    local tickEvery = 3 / (1 + (stats.haste / 100))\n    local ticks     = Round(15 / tickEvery)\n    local duration  = ticks * tickEvery\n    local tickDmg = (1980 + stats.spd * 0.371) * stats.masteryBonus\n    local damage  = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps     = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['DOOM'] = function()\n    local tickEvery = 15 / (1 + (stats.haste / 100))\n    local ticks     = Round(60 / tickEvery)\n    local duration  = ticks * tickEvery\n    \n    local base       = math.floor(502.054)\n    local spdScaling = 0.47\n    local tickDmg    = (base + stats.spd * spdScaling) * stats.doomBonus\n    local damage     = tickDmg * ticks * stats.critBonus * stats.damageMultiplier\n    local dps        = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['DRAIN_SOUL'] = function()\n    local tickEvery = 1 / (1 + (stats.haste / 100))\n    local ticks     = Round(4 / tickEvery)\n    local duration  = ticks * tickEvery\n    local tickDmg   = (math.ceil(274.5274) + stats.spd * 0.257)\n    local damage    = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps       = Round(damage / duration)\n    \n    return dps\nend\n\nGetDamage['MALEFIC_GRASP'] = function()\n    local tickEvery = 1 / (1 + (stats.haste / 100))\n    local ticks     = Round(3 / tickEvery)\n    local duration  = ticks * tickEvery\n    local tickDmg   = (math.floor(141.0024) + stats.spd * 0.132)\n    local damage    = tickDmg * ticks * stats.damageMultiplier * stats.critBonus\n    local dps       = Round(damage / duration)\n    \n    return dps\nend\n\nlocal spells = {\n    ['AFFLICTION']  = { 'CORRUPTION', 'AGONY', 'UA', 'MALEFIC_GRASP', 'DRAIN_SOUL' },\n    ['DEMONOLOGY']  = { 'CORRUPTION', 'DOOM' },\n    ['DESTRUCTION'] = { 'IMMOLATE' },\n    ['NONE']        = {}\n}\n\naura_env.SetPredictedDamage = function(spec)\n    for _, ID in pairs(spells[spec]) do\n        local damagePredict = GetDamage[ID]()\n        \n        if damagePredict ~= aura_env.predictedDamage[ID] then\n            aura_env.predictedDamage[ID] = damagePredict\n            aura_env.SendSyncEvent(ID)\n        end\n    end\n    \nend\n\naura_env.GetPredictDamage = function(ID)\n    local predict = aura_env.predictedDamage[ID]\n    if predict then\n        return predict\n    end\nend\n\n-- Handlers\n\naura_env.snapshotSpellIDs = {\n    [146739] = 'CORRUPTION',\n    [980]    = 'AGONY',\n    [30108]  = 'UA',\n    [348]    = 'IMMOLATE',\n    [603]    = 'DOOM',\n    [103103] = 'MALEFIC_GRASP',\n    [1120]   = 'DRAIN_SOUL'\n}\n\naura_env.OnCastSnapshot = function(ID)\n    aura_env.snapshotDamageCast[ID] = aura_env.GetPredictDamage(ID)\nend\n\naura_env.OnDebuffApplied = function(ID, destGUID)\n    aura_env.snapshotDamage[ID] = aura_env.snapshotDamage[ID] or {}\n    aura_env.snapshotDamage[ID][destGUID] = aura_env.snapshotDamageCast[ID]\n    aura_env.SendSyncEvent(ID, destGUID)\nend\n\naura_env.OnDebuffRemoved = function(ID, destGUID)\n    if aura_env.snapshotDamage[ID] and aura_env.snapshotDamage[ID][destGUID] then\n        aura_env.snapshotDamage[ID][destGUID] = nil\n    end\nend",
["do_custom"] = true,
},
},
