["custom"] = "function(event)\n    if event == 'STATUS' or event == 'PLAYER_SPECIALIZATION_CHANGED' then\n        WeakAuras.ScanEvents('MERFIN_WARLOCK_SNAPSHOT_DB', aura_env)\n        aura_env.SetPlayerSpec()\n    end\n    \n    local spec = aura_env.playerSpec\n    \n    if not spec then \n        return \n    end\n    \n    aura_env.RefreshStats(spec)\n    aura_env.SetPredictedDamage(spec)\nend",
