["custom"] = "function (event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if sourceGUID ~= WeakAuras.myGUID then return end\n            local ID = aura_env.snapshotSpellIDs[spellID]\n            \n            if ID then\n                aura_env.OnCastSnapshot(ID)\n            end\n        end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' \n        or subEvent == 'SPELL_AURA_REFRESH' \n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if sourceGUID == WeakAuras.myGUID then \n                local ID = aura_env.snapshotSpellIDs[spellID]\n                \n                if ID then\n                    aura_env.OnDebuffApplied(ID, destGUID)\n                    return\n                end\n            end\n        end\n        \n        if subEvent == 'SPELL_AURA_REMOVED' then\n            if sourceGUID == WeakAuras.myGUID then\n                local ID = aura_env.snapshotSpellIDs[spellID]\n                \n                if ID then\n                    aura_env.OnDebuffRemoved(ID, destGUID)\n                    return\n                end\n            end\n        end\n    end\nend",
