["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 114062 then\n                if GetTime() - aura_env.lastWondrous > 2 then\n                    local count = aura_env.ManageCounter('increase', 'WondrousRapidity')\n                    aura_env.Warning('WondrousRapidity', count)\n                    local duration = aura_env.IsHeroic and 30 or 20.3\n                    aura_env.StartCD('WondrousRapidity', duration)\n                    aura_env.TTS('Frontal')\n                end\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 114062 then\n                aura_env.lastWondrous = GetTime()\n                local count = aura_env.ManageCounter('increase', 'WondrousRapidity')\n                aura_env.Warning('WondrousRapidity', count)\n                local duration = aura_env.IsHeroic and 31.5 or 21.8\n                aura_env.StartCD('WondrousRapidity', duration)\n                aura_env.TTS('Frontal')\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if USSspellID == 113808 then\n            aura_env.StopCD('GravityFlux')\n            aura_env.Warning('Phase', 2)\n            aura_env.phase = 2\n        elseif USSspellID == 114059 then\n            local count = aura_env.ManageCounter('increase', 'GravityFlux')\n            aura_env.Warning('GravityFlux', count)\n            aura_env.StartCD('GravityFlux', 31.5)\n        end\n        \n    elseif e == 'INSTANCE_ENCOUNTER_ENGAGE_UNIT' then\n        if aura_env.phase == 2 and UnitExists('boss1') and aura_env.IsGUID(UnitGUID('boss1'), 'BOSS') then\n            aura_env.phase = 1\n            aura_env.Warning('Phase', 1)\n            if aura_env.IsHeroic then\n                aura_env.StartCD('GravityFlux', 10.4)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('WondrousRapidity', 6.1)\n        if aura_env.IsHeroic then\n            aura_env.StartCD('GravityFlux', 17.2)\n        end\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
