["init"] = {
["custom"] = "local encounterID = '1504'\nlocal ID          = 'OverwhelmingAssault'\n\nlocal name, icon = C_Spell.GetSpellName(123474), C_Spell.GetSpellTexture(123474)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r » %destName (%amount) %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            roleIcon       = 'TANK',\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName, amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName),\n            amount   = amount\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID, _,_,_, amount = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 123474 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(20.5)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED'\n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 123474 and destGUID ~= WeakAuras.myGUID then\n                aura_env.SendWarning(destName, amount or 1)\n            end\n        end\n    elseif e == 'PHASE_2' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(15.5)\n    end\nend",
