["[事件依赖] 督军佐诺兹"] = {
["outline"] = "OUTLINE",
["wagoID"] = "r2q5DNxZh",
["parent"] = "[T13] 事件依赖",
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs, stformat = tonumber, strsplit, pairs, string.format\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal cooldownData = {\n    ['Berserk'] = { name = 'Berserk', icon = 136224 },\n    ['PsychicDrain'] = { name = 'Psychic Drain', icon = 132303, roleIcon = 'TANK'},\n    ['VoidOfUnmaking'] = { name = 'Void Of Unmaking', icon = 132886, },\n    ['DisruptingShadows'] = { name = 'Disrupting Shadows', icon = 136201, },\n    ['FocusedAnger'] = { name = 'Focused Anger', icon = 136224, },\n}\n\nlocal encounterID = '1294'\n\nlocal CREATURE_ID = {\n    Flail = 55417,\n    Claw = 55418,\n    Eye = 55416,\n}\n\nlocal PRE_WARNING = {\n    ['PsychicDrain'] = true,\n    ['VoidOfUnmaking'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then\n        return 0\n    end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then \n        return false \n    end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\nlocal unitIdPool = { \"target\", \"focus\", \"mouseover\" }\naura_env.GetTarget = function(GUID)\n    for _, unitId in ipairs(unitIdPool) do\n        if UnitExists(unitId) and UnitGUID(unitId) == GUID then\n            local targetunitId = stformat(\"%starget\", unitId)\n            return targetunitId\n        end\n    end\n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        if plateData.namePlateUnitGUID == GUID then\n            local nameplateId = plateData.UnitFrame.displayedUnit\n            local targetunitId = stformat(\"%starget\", nameplateId)\n            return targetunitId\n        end\n    end\n    for unitId in WA_IterateGroupMembers() do\n        local targetunitId = stformat(\"%starget\", unitId)\n        if UnitExists(targetunitId) and UnitGUID(targetunitId) == GUID then\n            return stformat(\"%starget\", targetunitId)\n        end\n    end\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.WipeSchedulers = function()\n    if aura_env.schedulers then \n        for schedulerName, scheduler in pairs(aura_env.schedulers) do\n            WeakAuras.timer:CancelTimer(scheduler)\n        end\n    end\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_T13',\n        'PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.ScheduleEvent = function(subEvent, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[subEvent] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[subEvent])\n    end\n    \n    aura_env.schedulers[subEvent] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        subEvent\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    \n    aura_env.predict[id] = duration + GetTime()\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldownInfo  = {\n        show = true,\n        name = data.name,\n        id = id,\n        icon = data.icon,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        count = count,\n        roleIcon = data.roleIcon,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldownInfo)\n    \n    if not PRE_WARNING[id] then return end\n    \n    aura_env.SchedulePrewarning(id, duration)\nend\n\naura_env.IsCooldownReadyBefore = function(id, before)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (predictedAt - GetTime() > before)\nend\n\naura_env.IsCooldownReady = function(id)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (GetTime() > predictedAt)\nend\n\naura_env.Antispam = function(id, before)\n    local cur = GetTime()\n    if not aura_env.antispams[id] \n    or cur - aura_env.antispams[id] > before then\n        aura_env.antispams[id] = cur\n        return true\n    end\n    return false\nend\n\naura_env.Warning = function(warning, ...)\n    WeakAuras.ScanEvents('WA_MERFIN_T13', 'WARNING', warning, ...)\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    aura_env.WipeSchedulers()\n    \n    aura_env.isAoePhase = false\n    aura_env.isVoidWarned = false\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    aura_env.antispams = {}\n    \n    -- Destination Names\n    aura_env.disruptingNames = {}\n    aura_env.lastDisrupting = 0\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_SUCCESS:SPELL_AURA_APPLIED:SPELL_AURA_APPLIED_DOSE:SPELL_CAST_START:UNIT_DIED, UNIT_SPELLCAST_SUCCEEDED:boss1, CHAT_MSG_MONSTER_YELL, WA_MERFIN_T13_SCHEDULED",
["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId, _, _, _, amount)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellId == 104322 then\n                aura_env.StartCD('PsychicDrain', 20, false, true)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if (spellId == 104377 or spellId == 104378) and not aura_env.isAoePhase then\n                aura_env.isAoePhase = true\n                aura_env.StopCD('FocusedAnger')\n                aura_env.StopCD('PsychicDrain')\n                aura_env.StopCD('DisruptingShadows')\n                aura_env.Warning('BloodPhase')\n                aura_env.ScheduleEvent('BloodPhaseEnd', 30)\n                \n                if aura_env.IsHeroic then\n                    if not aura_env.IsCooldownReadyBefore('VoidOfUnmaking', 45) then\n                        aura_env.StartCD('VoidOfUnmaking', 45.3)\n                        return\n                    end\n                end\n                \n                if not aura_env.IsCooldownReadyBefore('VoidOfUnmaking', 36) then\n                    aura_env.StartCD('VoidOfUnmaking', 54.3)\n                    return\n                end\n            elseif spellId == 104543 then\n                aura_env.StartCD('FocusedAnger', 6, false, true)\n                aura_env.Warning('FocusedAnger', amount or 1)\n            elseif spellId == 106836 then\n                aura_env.Warning('BallTouched', amount or 1)\n            elseif spellId == 103434 then\n                local curTime = GetTime()\n                if curTime - aura_env.lastDisrupting > 5 then\n                    aura_env.StartCD('DisruptingShadows', 25)\n                    aura_env.disruptingNames = {}\n                    aura_env.ScheduleEvent('AnnounceTargetsDisrupting', 0.3)\n                end\n                aura_env.lastDisrupting = curTime\n                aura_env.disruptingNames[#aura_env.disruptingNames + 1] = WA_ClassColorName(destName)\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellId == 104347 then\n                C_Timer.After(0.2, function()\n                        local unitId = aura_env.GetTarget(sourceGUID)\n                        if unitId and UnitName(unitId) == WeakAuras.me then\n                            WeakAuras.ScanEvents('WA_MERFIN_GAZE_ON_YOU')\n                        end\n                end)\n            end\n            \n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'Flail') then\n                WeakAuras.ScanEvents('WA_ZANOZZ_ADD_DEATH', 'Flail')\n            elseif aura_env.IsGUID(destGUID, 'Claw') then\n                WeakAuras.ScanEvents('WA_ZANOZZ_ADD_DEATH', 'Claw')\n            elseif aura_env.IsGUID(destGUID, 'Eye') then\n                WeakAuras.ScanEvents('WA_ZANOZZ_ADD_DEATH', 'Eye')\n            end\n        end\n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if uSpellId == 103571 then\n            if not aura_env.Antispam('VoidOfUnmaking', 5) then\n                return\n            end\n            \n            aura_env.isVoidWarned = true\n            aura_env.Warning('VoidOfUnmaking')\n            aura_env.StartCD('VoidOfUnmaking', 90.3, false, true)\n            \n            if aura_env.IsCooldownReady('PsychicDrain') then\n                aura_env.StartCD('PsychicDrain', 8.5)\n            end\n        end\n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        if msg == 'BloodPhaseEnd' then\n            aura_env.isVoidWarned = false\n            aura_env.isAoePhase = false\n            aura_env.Warning('Phase1')\n            aura_env.StartCD('FocusedAnger', 6)\n            aura_env.StartCD('DisruptingShadows', 6)\n        elseif msg == 'AnnounceTargetsDisrupting' then\n            aura_env.Warning('AnnounceTargetsDisrupting', aura_env.disruptingNames)\n        end\n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('VoidOfUnmaking', 5.5)\n        aura_env.StartCD('FocusedAnger', 10.5)\n        aura_env.StartCD('PsychicDrain', 13)\n        aura_env.StartCD('DisruptingShadows', 25)\n        aura_env.StartCD('Berserk', 360)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
