["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 115297 then\n                if destName == WeakAuras.me then\n                    aura_env.Warning('EvictSoulOnYou')\n                    aura_env.Chat('{rt8} Soul on ' .. WeakAuras.me .. ' {rt8}')\n                else\n                    aura_env.Warning('EvictSoul', destName)\n                end\n            elseif spellID == 115291 then\n                if destName == WeakAuras.me then\n                    aura_env.Warning('SpiritGaleOnYou')\n                else\n                    aura_env.Warning('SpiritGale', destName)\n                end\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 115289 then\n                local count = aura_env.ManageCounter('increase', 'SpiritGale')\n                aura_env.Warning('SpiritGale', count)\n                aura_env.TTS('Interrupt')\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 115147 then\n                local count = aura_env.ManageCounter('increase', 'SummonSpirit')\n                aura_env.Warning('SummonSpirit', count)\n                aura_env.StopCD('SummonSpirit')\n                aura_env.StartCD('RaiseCrusader', 20)\n            elseif spellID == 115297 then\n                aura_env.StartCD('EvictSoul', 41, true)\n            elseif spellID == 115139 then\n                local count = aura_env.ManageCounter('increase', 'RaiseCrusader')\n                aura_env.Warning('RaiseCrusader', count)\n                aura_env.StopCD('RaiseCrusader')\n                local duration = aura_env.IsChallenge and 20 or 40\n                aura_env.StartCD('SummonSpirit', duration)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('RaiseCrusader', 6)\n        aura_env.StartCD('EvictSoul', 15.5)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
