["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 113690 or spellID == 11366 then -- Not sure what spellID\n                local count = aura_env.ManageCounter('increase', 'Pyroblast')\n                aura_env.Warning('Pyroblast', count)\n                aura_env.StartCD('Pyroblast', 6)\n            elseif spellID == 113364 then\n                local count = aura_env.ManageCounter('increase', 'BookBurner')\n                aura_env.Warning('BookBurner', count)\n                aura_env.StartCD('BookBurner', 15.5)\n            elseif spellID == 113691 then\n                local count = aura_env.ManageCounter('increase', 'FireballVolley')\n                aura_env.Warning('FireballVolley', count)\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 113626 then\n                aura_env.StopCD('Pyroblast')\n                local count = aura_env.ManageCounter('increase', 'DragonsBreath')\n                aura_env.Warning('DragonsBreath', count)\n                aura_env.StartCD('DragonsBreath', 50)\n                aura_env.TTS('Stay Behind')\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 113682 and aura_env.IsGUID(destGUID, 'BOSS') then\n                local count = aura_env.ManageCounter('increase', 'QuickenedMind')\n                aura_env.Warning('QuickenedMind', count)\n            end\n        elseif subEvent == 'SPELL_MISSED' or subEvent == 'SPELL_DAMAGE' then\n            if spellID == 113620 and destGUID == WeakAuras.myGUID and aura_env.Antispam(spellID, 2) then\n                aura_env.Warning('BurningBookGTFO')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('Pyroblast', 5)\n        aura_env.StartCD('BookBurner', 20.5)\n        aura_env.StartCD('DragonsBreath', 30)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
