["[Progress] [TSG] Painters Dispatcher"] = {
["width"] = 200,
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["preferToUpdate"] = true,
["parent"] = "[Widget] Painters Leaderboard",
["yOffset"] = 0,
["regionType"] = "empty",
["information"] = {
},
["anchorPoint"] = "CENTER",
["xOffset"] = 0,
["selfPoint"] = "CENTER",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local GetData = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\naura_env.validSpell = {\n    [116322] = GetData(116322),\n    [116199] = GetData(116199),\n    [116301] = GetData(116301),\n    [116304] = GetData(116304),\n}\n\naura_env.scorelist = {}",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "custom",
["custom"] = "function(e, ...)\n    if e ~= \"COMBAT_LOG_EVENT_UNFILTERED\" and e ~= \"ENCOUNTER_END\" then return end\n    \n    if e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, destName, _, _, spellID, _, _, _, amount = ...\n        \n        if not aura_env.validSpell[spellID] then return end\n        \n        local scoreData = aura_env.scorelist[destGUID]\n        \n        if not scoreData then\n            scoreData = {\n                unitName = destName,\n                temporaryScore = 0,\n                totalScore = 0,\n                lastKnownStacks = 7\n            }\n            aura_env.scorelist[destGUID] = scoreData\n        end\n        \n        if subEvent == \"SPELL_AURA_REMOVED_DOSE\" then\n            if not scoreData.lastKnownStacks and amount then\n                scoreData.lastKnownStacks = 7\n            end\n            \n            if amount and scoreData.lastKnownStacks and amount < scoreData.lastKnownStacks then\n                local lostStacks = scoreData.lastKnownStacks - amount\n                scoreData.temporaryScore = scoreData.temporaryScore + lostStacks\n                \n                WeakAuras.ScanEvents(\"PAINTERS_SCORE\", {\n                        unitName = scoreData.unitName,\n                        currentScore = scoreData.totalScore + scoreData.temporaryScore\n                })\n            end\n            \n            scoreData.lastKnownStacks = amount\n            \n        elseif subEvent == \"SPELL_AURA_REMOVED\" then\n            if scoreData.lastKnownStacks and scoreData.lastKnownStacks > 0 then\n                scoreData.temporaryScore = scoreData.temporaryScore + scoreData.lastKnownStacks\n            end\n            \n            scoreData.totalScore = scoreData.totalScore + scoreData.temporaryScore\n            scoreData.temporaryScore = 0\n            scoreData.lastKnownStacks = nil\n            \n            WeakAuras.ScanEvents(\"PAINTERS_SCORE\", {\n                    unitName = scoreData.unitName,\n                    currentScore = scoreData.totalScore\n            })\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        local encounterID = ...\n        if encounterID == 1395 then\n            aura_env.scorelist = {}\n        end\n        \n    elseif e == \"ENCOUNTER_END\" then\n        local encounterID = ...\n        if encounterID ~= 1395 then\n            return\n        end\n        \n        local isLeader = (UnitIsGroupLeader(\"player\") and IsInRaid())\n        \n        if isLeader then\n            local results = {}\n            \n            for _, data in pairs(aura_env.scorelist or {}) do\n                table.insert(results, {\n                        name = data.unitName or \"Unknown\",\n                        score = data.totalScore or 0\n                })\n            end\n            \n            table.sort(results, function(a, b)\n                    return a.score > b.score\n            end)\n            \n            SendChatMessage(\"Painters Leaderboard:\", \"RAID\")\n            \n            for i, entry in ipairs(results) do\n                local msg = string.format(\"%d. %s - %d tiles painted\", i, entry.name, entry.score)\n                SendChatMessage(msg, \"RAID\")\n            end\n        end\n        \n        aura_env.scorelist = {}\n    end\nend",
