["[DP] [Mel'jarak] Corrosive Resin"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'CorrosiveResin'\n\nlocal name, icon = C_Spell.GetSpellName(122064), C_Spell.GetSpellTexture(122064)\n\nlocal options = {\n    ['CorrosiveResin'] = {\n        warningText = \"%icon @cffff8b17%name@r » %destName %icon\",\n    },\n    ['CorrosiveResinGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    }\n}\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID,\n            GUID = GUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n            GUID           = GUID\n        }, options['CorrosiveResin'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID, _,_,_, amount = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 122064 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(36, sourceGUID)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_REFRESH' then\n            if spellID == 122064 then\n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning('CorrosiveResin', destName)\n                end\n            end\n            \n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 122125 and destGUID == WeakAuras.myGUID and aura_env.IsSpam(3) then\n                aura_env.SendWarning('CorrosiveResinGTFO')\n            end\n        end\n        \n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        \n        if npcID == 62405 then\n            aura_env.StopCD(destGUID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, UNIT_DIED, CLEU:SPELL_CAST_START:SPELL_AURA_APPLIED:SPELL_AURA_REFRESH:SPELL_DAMAGE:SPELL_MISSED",
