["custom"] = "function(e, schedEvent, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 120789 then\n                local count = aura_env.ManageCounter('increase', 'DashingStrike')\n                local targetUnit = aura_env.GetTarget(sourceGUID)\n                aura_env.Warning('DashingStrike', count, targetUnit)\n                aura_env.StartCD('DashingStrike', 14.6)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 120759 then\n                local count = aura_env.ManageCounter('increase', 'ThousandBlades')\n                aura_env.Warning('ThousandBlades', count)\n            elseif spellID == 123032 then\n                --aura_env.Chat('{rt2} ' .. WeakAuras.me .. ' carrying keg {rt2}')\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 120759 then\n                aura_env.StartCD('ThousandBlades', 10)\n            elseif spellID == 123032 then\n                --aura_env.Chat('- threw keg -')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('DashingStrike', 8.6)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
