["spellIds"] = {
},
["custom"] = "function(states, event, encounterID, cooldown, config) \n    if event == 'MERFIN_PREWARNING_SHOW' then\n        if not cooldown.countdown then return end\n        \n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        local remaining = cooldown.expirationTime - GetTime()\n        \n        local newState = {\n            show            = true,\n            changed         = true,\n            progressType    = 'timed',\n            autoHide        = true,\n            duration        = remaining,\n            expirationTime  = remaining + GetTime(),\n            voiceActorIndex = cooldown.voiceActorIndex,\n            config          = config,\n        }\n        states:Update(stateName, newState)\n    end\n    \n    \n    if event == 'MERFIN_PREWARNING_HIDE' then\n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        states:Remove(stateName)\n    end\nend",
