["[DP] [Un'sok] Amber Explosion"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1499'\nlocal ID          = 'AmberExplosion'\n\nlocal name, icon = C_Spell.GetSpellName(122398), C_Spell.GetSpellTexture(122398)\n\nlocal options = {\n    ['AmberExplosion'] = {\n        warningText = \"%icon %sourceName @cffff8b17%name@r %icon\",\n    },\n    ['AmberExplosionM'] = {\n        warningText = \"%icon %sourceName @cffff8b17%name@r %icon\",\n    },\n    ['AmberExplosionInterrupt'] = {\n        warningText = ''\n    }\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'AMBER_EXP_' .. (aura_env.playerExp + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function(ID, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID, GUID = GUID })\nend\n\naura_env.StartCD = function(ID, duration, sourceGUID, sourceName, noCount, ignorePrew)\n    local colSrcName = UnitInRaid(sourceName) and WA_ClassColorName(sourceName) or sourceName\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = false,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            noCount        = noCount,\n            GUID           = sourceGUID,\n            sourceName     = colSrcName,\n            sourceGUID     = sourceGUID,\n            isPlayer       = sourceName == WeakAuras.me,\n            ignorePrew     = ignorePrew\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID, sourceName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID         = ID,\n            name       = name,\n            icon       = icon,\n            count      = aura_env.count,\n            sourceName = WA_ClassColorName(sourceName)\n        }, options[ID])\nend\n\naura_env.GetStrikeCD = function()\n    return GetTime() - aura_env.lastStrike\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID, sourceName,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 122398 then -- Amber Explosion Cast\n                if Merfin.GetNPCIDFromGUID(sourceGUID) == 62701 then \n                    -- Cast by a Wild Construct (Not Player)\n                    aura_env.count = aura_env.count + 1\n                    aura_env.StartCD('AmberExplosion', 18, sourceGUID, sourceName, false)\n                    \n                else\n                    -- Cast by a player\n                    local duration = 13\n                    aura_env.playerExp = aura_env.playerExp + 1\n                    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n                    local ignorePrew = sourceGUID ~= WeakAuras.myGUID\n                    aura_env.StartCD('AmberExplosion', duration, sourceGUID, sourceName, true, ignorePrew)\n                    WeakAuras.ScanEvents('WIDGET_RESHAPE_LIFE_EXPLOSION', sourceGUID, duration)\n                end\n                \n                aura_env.SendWarning('AmberExplosion', sourceName)\n                \n            elseif spellID == 122402 then\n                if aura_env.meConstruct and aura_env.GetStrikeCD() < 3.5 then\n                    aura_env.SendWarning('AmberExplosionInterrupt')\n                else\n                    aura_env.SendWarning('AmberExplosionM', sourceName)\n                end\n                \n                aura_env.StartCD('AmberExplosionM', 46, nil, 'Monstrosity')\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 122389 and sourceGUID == WeakAuras.myGUID then\n                aura_env.lastStrike = GetTime()\n            end\n        end\n        \n    elseif e == 'RESHAPE_LIFE' then\n        local subEvent, destGUID, destName = ...\n        \n        if subEvent == 'APPLIED' then\n            if destGUID == WeakAuras.myGUID then\n                aura_env.meConstruct = true\n            end\n            \n            local ignorePrew = destGUID ~= WeakAuras.myGUID\n            local duration = 15\n            aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n            aura_env.StartCD('AmberExplosion', duration, destGUID, destName, true, ignorePrew)\n            \n        elseif subEvent == 'REMOVED' then\n            aura_env.StopCD('AmberExplosion', destGUID)\n            if destGUID == WeakAuras.myGUID then\n                aura_env.meConstruct = false\n            end\n        end\n        \n    elseif e == 'UNSOK_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.StartCD('AmberExplosionM', 55.5, nil, 'Monstrosity')\n        elseif phaseN == 3 then\n            aura_env.StopCD('AmberExplosionM')\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        if npcID == 62701 then\n            aura_env.CancelMRT()\n            aura_env.StopCD('AmberExplosion', destGUID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.playerExp = 0\n        aura_env.count = 0\n        aura_env.lastStrike = 0\n    end\nend",
["spellIds"] = {
