["init"] = {
["custom"] = "local encounterID = '1504'\nlocal ID          = 'Phase2'\n\nlocal name = Merfin:L('Phase 2')\n\nlocal options = {\n    warningText = string.format(\"@cffe3e3e3» %s «@r\", name:upper()),\n    ttsLine = name\n}\n\naura_env.SendWarning = function()\n    local warning = {\n        ID      = ID,\n        name    = name,\n        noCount = true,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, warning, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.MRT = function(event)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    GMRT.F.Note_Timer(event)\nend",
["do_custom"] = true,
},
