["[DP] [Tsulong] Nightmares"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'Nightmares'\n\nlocal function GetSpellInfoTable(spellID)\n    if WeakAuras.IsRetail() then\n        return C_Spell.GetSpellName(spellID), C_Spell.GetSpellTexture(spellID)\n    else\n        local name, _, icon = GetSpellInfo(spellID)\n        return name, icon\n    end\nend\n\nlocal name, icon = GetSpellInfoTable(122777)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r » %destName %icon\",\n    ttsLine = Merfin:L('Dodge'),\n    prewarnTTStext = Merfin:L('Prepare to Dodge')\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function(destName)\n    local data = {\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count,\n        destName = WA_ClassColorName(destName)\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.GetTarget = function(GUID)\n    local stformat = string.format\n    local unitIDPool = {\n        \"boss1\", \"boss2\", \"boss3\", \"boss4\", \"target\", \"focus\", \"mouseover\"\n    }\n    \n    for _, unitID in ipairs(unitIDPool) do\n        if UnitExists(unitID) and UnitGUID(unitID) == GUID then\n            local targetUnitID = stformat(\"%starget\", unitID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        if plateData.namePlateUnitGUID == GUID then\n            local nameplateID = plateData.UnitFrame.displayedUnit\n            local targetUnitID = stformat(\"%starget\", nameplateID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    for unitID in WA_IterateGroupMembers() do\n        local targetUnitID = stformat(\"%starget\", unitID)\n        if UnitExists(targetUnitID) and UnitGUID(targetUnitID) == GUID then\n            return stformat(\"%starget\", targetunitID)\n        end\n    end\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.SendMsg = function()\n    local msg = name:upper()\n    WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', msg, 'YELL')\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 122770 and not aura_env.IsSpam(3) then\n            aura_env.count = aura_env.count + 1\n            \n            if GetTime() - aura_env.nightLast < 106 then\n                aura_env.StartCD(15.5)\n            else\n                aura_env.StopCD()\n            end\n            \n            -- Target Scanner\n            local ticker\n            ticker = C_Timer.NewTicker(0.1, function()\n                    local targetID, targetName = aura_env.GetTarget(UnitGUID(unitID))\n                    if targetID then\n                        aura_env.SendWarning(targetName)\n                        if targetName == WeakAuras.me then\n                            --aura_env.SendMsg()\n                        end\n                        ticker:Cancel()\n                    end\n            end, 15)\n            aura_env.targetScanner = ticker\n        end\n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID, initial = ...\n        \n        if phaseID == 'NightPhase' then\n            aura_env.nightLast = GetTime()\n            \n            if not initial then\n                aura_env.count = 0\n                aura_env.StartCD(10)\n            end\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(15)\n    end\nend",
