["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1407'\nlocal name, icon = 'Arc Combo', 132354\n\nlocal names = {\n    ['QINXI'] = Merfin:L('Qin-xi'),\n    ['JANXI'] = Merfin:L('Jan-xi'),\n}\n\naura_env.StartCD = function(duration, bossID)\n    local ID = bossID == 'QINXI' and 'QinXiCombo' or 'JanXiCombo'\n    \n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        name           = names[bossID],\n        icon           = icon,\n        count          = aura_env.counters[bossID],\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\nlocal creatures = {\n    QINXI = 60399,\n    JANXI = 60400,\n}\n\naura_env.guidCache = {}\naura_env.IsGUID = function(GUID, creature)\n    if not GUID then return end\n    \n    local creatureIDs = creatures[creature]\n    if not creatureIDs then return false end\n    \n    local npcId = aura_env.guidCache[GUID]\n    if not npcId then\n        npcId = Merfin.GetNPCIDFromGUID(GUID)\n        aura_env.guidCache[GUID] = npcId\n    end\n    \n    if type(creatureIDs) == \"table\" then\n        for _, id in ipairs(creatureIDs) do\n            if npcId == id then return true end\n        end\n        return false\n    else\n        return npcId == creatureIDs\n    end\nend\n\naura_env.GetBossID = function(unitID)\n    local unitGUID = UnitGUID(unitID)\n    if aura_env.IsGUID(unitGUID, 'QINXI') then\n        return 'QINXI'\n    end\n    if aura_env.IsGUID(unitGUID, 'JANXI') then\n        return 'JANXI'\n    end\nend\n\naura_env.CounterBoss = function(bossID)\n    local counter = aura_env.combos[bossID] or aura_env.maxCombo\n    \n    counter = counter - 1\n    \n    if aura_env.myTarget == bossID then\n        WeakAuras.ScanEvents('ARC_HELPER_COUNTER', counter)\n    end\n    \n    counter = (counter == 0 and aura_env.maxCombo) or counter\n    \n    aura_env.combos[bossID] = counter\nend\n\naura_env.Schedule = function(seconds, bossID)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[bossID] then\n        aura_env.schedulers[bossID]:Cancel()\n    end\n    \n    local timer = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('STOMP_CHECK', bossID)\n    end)\n    \n    aura_env.schedulers[bossID] = timer\nend\n\naura_env.isPlayerTank = function()\n    if WA_GetUnitDebuff('player', 116818) then -- QinXi\n        return true\n    elseif WA_GetUnitDebuff('player', 117195) then -- Janxi\n        return true\n    end\nend\n\naura_env.GetDirection = function(arc) \n    local isTank = aura_env.isPlayerTank()\n    \n    if arc == 'ARC_LEFT' then\n        return isTank and 'LEFT' or 'RIGHT'\n    elseif arc == 'ARC_RIGHT' then\n        return isTank and 'RIGHT' or 'LEFT'\n    elseif arc == 'ARC_FRONT' then\n        return isTank and 'FORWARD' or 'BEHIND'\n    elseif arc == 'ARC_INNER' then\n        return 'OUT'\n    end\nend\n\nlocal directionTTS = {\n    ['LEFT'] = Merfin:L('Left'),\n    ['RIGHT'] = Merfin:L('Right'),\n    ['OUT'] = Merfin:L('Out'),\n    ['FORWARD'] = Merfin:L('Forward'),\n    ['BEHIND'] = Merfin:L('Behind'),\n}\n\naura_env.AnnounceMove = function(bossID, arc)\n    local dodgeDirection = aura_env.GetDirection(arc)\n    \n    -- Stomp announces only after cast is being cast\n    aura_env.Schedule(5, bossID)\n    \n    if aura_env.myTarget == bossID then\n        WeakAuras.ScanEvents('ARC_HELPER', dodgeDirection)\n        WeakAuras.ScanEvents('MERFIN_TTS', directionTTS[dodgeDirection])\n    end\n    \n    aura_env.CounterBoss(bossID)\nend\n\naura_env.ARCS = {\n    [116968] = 'ARC_LEFT',\n    [116971] = 'ARC_RIGHT',\n    [116972] = 'ARC_FRONT',\n    --[116969] = 'ARC_INNER',\n    --[132425] = 'ARC_INNER',\n}\n\naura_env.IsSpam = function(id, before)\n    aura_env.antispam = aura_env.antispam or {}\n    local cur = GetTime()\n    local last = aura_env.antispam[id]\n    \n    if not last or (cur - last > before) then\n        aura_env.antispam[id] = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        local arc = aura_env.ARCS[spellID]\n        if not arc then return end\n        \n        local bossID = aura_env.GetBossID(unitID)\n        aura_env.AnnounceMove(bossID, arc) \n        \n    elseif e == 'UNIT_POWER_UPDATE' then\n        local unitID = ...\n        local unitGUID = UnitGUID(unitID)\n        local curPower = UnitPower(unitID)\n        local bossID = aura_env.GetBossID(unitID)\n        \n        if curPower == 0 then\n            if not aura_env.IsSpam(bossID .. '0', 1) then\n                aura_env.counters[bossID] = aura_env.counters[bossID] + 1\n                aura_env.StartCD(23, bossID)\n            end\n            \n            if aura_env.schedulers[bossID] then\n                aura_env.schedulers[bossID]:Cancel()\n            end\n            \n        elseif curPower >= 90 and curPower >= aura_env.prevPower[bossID] then\n            aura_env.combos[bossID] = aura_env.maxCombo\n            \n            if aura_env.myTarget == bossID then\n                WeakAuras.ScanEvents('ARC_HELPER_COUNTER', aura_env.combos[bossID])\n            end\n        end\n        \n        aura_env.prevPower[bossID] = curPower\n        \n    elseif e == 'STOMP_CHECK' then\n        local bossID = ...\n        aura_env.AnnounceMove(bossID, 'ARC_INNER')\n        \n    elseif e == 'PLAYER_TARGET_CHANGED' then\n        aura_env.myTarget = (UnitExists('target') and aura_env.GetBossID('target')) or 'NONE'\n        \n    elseif e == 'BOSSES_SCHEDULED' then\n        aura_env.StartCD(23, 'QINXI')\n        aura_env.StartCD(23, 'JANXI')\n        \n    elseif e == 'ENCOUNTER_START' or e == 'STATUS' then\n        aura_env.counters = { ['QINXI'] = 0, ['JANXI'] = 0 }\n        aura_env.maxCombo = WeakAuras.InstanceDifficulty() == 'heroic' and 10 or 5\n        aura_env.myTarget = 'NONE'\n        aura_env.schedulers = {}\n        aura_env.combos = {}\n        aura_env.prevPower = {\n            QINXI = 0,\n            JANXI = 0,\n        }\n    end\nend",
