["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'DespawnFloor'\n\nlocal options = {\n    warningText = \"@cffff4040\" .. Merfin:L(\"Floor is falling\"):upper() .. \"@r\",\n    ttsLine = Merfin:L(\"Floor is falling\"),\n}\n\nlocal name, icon = Merfin:L('Falling Floor'), C_Spell.GetSpellTexture(116994)\n\naura_env.StartCD = function(duration, GUID)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        GUID           = GUID,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
