["events"] = "CLEU:SPELL_DAMAGE:RANGE_DAMAGE:SWING_DAMAGE:SPELL_CAST_SUCCESS:SPELL_PERIODIC_DAMAGE:SPELL_AURA_REMOVED:UNIT_DIED",
["custom"] = "function(a, e, ...)\n    \n    if e == 'OPTIONS' then\n        for i = 1, 3 do\n            a[i] = {\n                show = true,\n                changed = true,\n                progressType = 'static',\n                value = math.random(10000, aura_env.breakpoint),\n                total = aura_env.breakpoint,\n            }\n        end\n        return true\n    end\n    \n    if e ~= 'COMBAT_LOG_EVENT_UNFILTERED' then\n        return\n    end\n    \n    local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellId,_,_, amount = ...\n    \n    if subEvent == 'SPELL_CAST_SUCCESS' then\n        if spellId ~= 105490 then\n            return\n        end\n        \n        a[sourceGUID] = {\n            show = true,\n            changed = true,\n            progressType = 'static',\n            value = aura_env.breakpoint,\n            total = aura_env.breakpoint,\n        }\n        return true\n    end\n    \n    if subEvent == 'SPELL_AURA_REMOVED' then\n        if spellId ~= 105490 then\n            return\n        end\n        \n        if not a[destGUID] then\n            return\n        end\n        \n        a[destGUID].show = false\n        a[destGUID].changed = true\n        return true\n    end\n    \n    -- SWING_DAMAGE, RANGE_DAMAGE, SPELL_DAMAGE\n    \n    if not a[destGUID] then\n        return\n    end\n    \n    if subEvent == 'UNIT_DIED' then\n        a[destGUID].show = false\n        a[destGUID].changed = true\n        return true\n    end\n    \n    local amount = subEvent == 'SWING_DAMAGE' and spellId or amount\n    a[destGUID].value = a[destGUID].value - amount\n    a[destGUID].changed = true\n    a[destGUID].show = a[destGUID].value > 0\n    return true\nend",
