["parent"] = "[BWD] 警报",
["customText"] = "function()\n    local curTime = aura_env.GetTime()\n    if WeakAuras.IsOptionsOpen() then\n        aura_env.unitName = WeakAuras.me\n        aura_env.duration = '|cff8aff00Beam|r: 3s'\n    elseif not aura_env.last then \n        return\n    elseif curTime - aura_env.throttle > 0.1 then\n        aura_env.throttle = curTime\n        aura_env.duration = curTime - aura_env.last\n    end\n    return '|cff8aff00激光|r', aura_env.unitName, aura_env.duration\nend",
