["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Chimaeron\n\nlocal ENTRY = aura_env\nlocal encounterId = 1023\n\nlocal localized = {\n    ['enUS'] = {\n        -- CHAT_MSG_MONSTER_EMOTE\n        EmoteRolePlayStart = 'The Bile-O-Tron springs to life and begins to emit a foul smelling substance.',\n    },\n    \n    ['ruRU'] = {\n        -- CHAT_MSG_MONSTER_EMOTE\n        EmoteRolePlayStart = 'Желчетрон оживает и начинает извергать из себя некое вонючее вещество',\n    },\n    \n    ['koKR'] = {\n        EmoteRolePlayStart = '[키마이론] 전투 시작',\n    },\n    \n    ['zhCN']  = {\n        EmoteRolePlayStart = '胆汁喷洒机恢复运作，并开始喷射一种恶臭的物质。',\n    },\n    \n    ['zhTW']  = {\n        EmoteRolePlayStart = '「好膽」機器人開始活動，並且噴出一種惡臭的物質。',\n    },\n}\n\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    caustic_slime =   { 82935 },\n    break_attack =    { 82881 },\n    double_attack =   { 88826 },\n    feud =            { 88872 },\n    systems_failure = { 88853 },\n    massacre =        { 82848 },\n    fight_start =     { false, 462337 },\n    reroute_power =   { 88861, 133859 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            local delay = 1\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal FailureCheck = function()\n    if not ENTRY.ctx.botOffline and ENTRY.CASTS.massacre >= 2 then\n        Cooldown('systems_failure', 25)\n    end\nend\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    ENTRY.ctx.botOffline = false\n    ENTRY.CASTS.massacre = 0\n    CORE.SetStage(ENTRY, 1)\n    Cooldown('berserk', 450-delay)\n    Cooldown('massacre', 26-delay)\n    PreWarning('massacre', 21-delay)\n    Cooldown('break_attack', 4.5-delay)\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 82848 then\n        ENTRY.CASTS.massacre = (ENTRY.CASTS.massacre or 0) + 1\n        SpecialWarning('massacre')\n        Timer('massacre', 4)\n        Cooldown('massacre', 30)\n        PreWarning('massacre', 25)\n        Cooldown('caustic_slime', 19, '', true)\n        Cooldown('break_attack', 12)\n        CORE.Schedule(ENTRY, 'failure', 5, FailureCheck)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 88872 then\n        Warning('feud')\n    elseif args.spellId == 82934 then\n        WeakAuras.ScanEvents('WA_MERFIN_CHIMAERON_PHASE_2')\n        CORE.SetStage(ENTRY, 2)\n        Warning('phase_2')\n        Cancel('caustic_slime', 'ALL')\n        Cancel('massacre', 'ALL')\n        Cancel('systems_failure', 'ALL')\n        Cancel('reroute_power', 'ALL')\n    elseif args.spellId == 88861 then\n        --Timer('reroute_power', 26)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 82881 then\n        if CORE.IsStage(ENTRY, 1) then\n            Warning('break_attack', args.destName, args.stacks or 1)\n            --Timer('break_attack', args.destName)\n            Cooldown('break_attack', 15)\n        end\n    elseif args.spellId == 88826 then\n        if CORE.IsTanking('player', nil, args.destGUID) then\n            SpecialWarning('double_attack')\n        else\n            Warning('double_attack')\n        end\n    elseif args.spellId == 88853 then\n        ENTRY.ctx.botOffline = true\n        ENTRY.CASTS.massacre = 0\n        SpecialWarning('systems_failure')\n        Cancel('systems_failure', 'COOLDOWN')\n        Timer('reroute_power', 26)\n        \n    elseif not ENTRY.ctx.botOffline and args.spellId == 82935 and CORE.IsDestTypePlayer(args.destFlags) then\n        Warning('caustic_slime', args.destName) \n    end\nend\nENTRY['SPELL_AURA_APPLIED_DOSE'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REFRESH'] = function(args)\n    if args.spellId == 82881 then\n        --Timer('break_attack', args.destName)\n        Cooldown('break_attack', 15)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 88853 then\n        ENTRY.ctx.botOffline = false\n    elseif args.spellId == 82881 then\n        Cancel('break_attack', 'TIMER')\n    end\nend\n\nENTRY['CHAT_MSG_MONSTER_EMOTE'] = function(text)\n    if text == L.EmoteRolePlayStart or text:find(L.EmoteRolePlayStart) then\n        Timer('fight_start', 31.5)\n        PreWarning('fight_start', 26.5, 5)\n    end\nend",
