["[DP] [Shek'zeer] Sonic Blade"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
