},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'SonicBlade'\n\nlocal name, icon = C_Spell.GetSpellName(125886), C_Spell.GetSpellTexture(125886)\n\nlocal options = {\n    ['SonicBlade'] = {\n        warningText = ''\n    },\n    ['SonicBladeAll'] = {\n        warningText = ''\n    }\n}\n\naura_env.StopCD = function(ID, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID, GUID = GUID })\nend\n\naura_env.StartCD = function(ID, duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = false,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n            GUID           = GUID\n        }, options[ID])\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count,\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 125886 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD('SonicBlade', 20, sourceGUID)\n                WeakAuras.ScanEvents('SONIC_BLADE', sourceGUID)\n                \n                if not aura_env.IsSpam(15) then\n                    aura_env.StartCD('SonicBladeAll', 20)\n                end\n            end\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        if npcID == 63589 then\n            aura_env.StopCD('SonicBlade', destGUID)\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.StartCD('SonicBladeAll', 15)\n        elseif phaseN == 1 or phaseN == 3 then\n            aura_env.StopCD('SonicBlade')\n            aura_env.StopCD('SonicBladeAll')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
