},
["init"] = {
["custom"] = "aura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.happenedOnce = {}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(event, ...)\n    if event == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.happenedOnce = {}\n        return\n    end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        if spellID == 115842 or spellID == 115840 or spellID == 115844 or spellID == 115843 then\n            C_Timer.After(1, function()\n                    aura_env.happenedOnce[sourceGUID] = nil\n            end)\n        end\n        return\n    end\n    \n    if event ~= 'UNIT_POWER_UPDATE' then return end\n    \n    local unit = ...\n    local guid = UnitGUID(unit)\n    \n    if aura_env.happenedOnce[guid] then return end\n    \n    local power = UnitPower(unit)\n    \n    if power > 90 then\n        aura_env.happenedOnce[guid] = true\n        aura_env.count = (aura_env.count or 0) + 1\n        GMRT.F.Note_Timer('OVERLOAD_' .. aura_env.count)\n    end\nend",
