["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'FlankingOrders'\n\nlocal options = {\n    warningText = \"@cffff4040%upper:name@r\",\n    prewarnCountVA = 1,\n}\n\nlocal name, icon = C_Spell.GetSpellName(117910), C_Spell.GetSpellTexture(117910)\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = { \n        ID    = ID, \n        count = aura_env.count, \n        name  = name, \n        icon  = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 117910 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local timer = (aura_env.bossActivated and (aura_env.count == 1 and 45 or 40)) or 75\n            aura_env.StartCD(timer)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated = ...\n        if bossID == 'QIANG' then\n            aura_env.bossActivated = activated\n            if not activated then\n                aura_env.StartCD(75)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(25)\n    end\nend",
