["[DP] [Shek'zeer] Cry of Terror"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'CryOfTerror'\n\nlocal name, icon = C_Spell.GetSpellName(123788), C_Spell.GetSpellTexture(123788)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName),\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID,_,_,_, amount = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 123788 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning(destName, amount)\n                aura_env.StartCD(25)\n            end\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 then\n            aura_env.count = 0\n            --aura_env.StartCD(7)\n        elseif phaseN == 2 or phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'SHEKZEER_RETREAT' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(11)\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, SHEKZEER_PHASE, CLEU:SPELL_AURA_APPLIED:SPELL_AURA_APPLIED_DOSE",
