["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    \n    if event == 'UNIT_HEALTH' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        \n        if states[GUID] then\n            local health = 100 * (UnitHealth(unit) / UnitHealthMax(unit))\n            states:Update(GUID, { value = health })\n        end\n        \n    elseif event == 'WIDGET_RESHAPE_LIFE' then\n        local show, unitKey, GUID, unitName = ...\n        if unitKey ~= aura_env.unitKey then return end\n        \n        if show then\n            local health = 100 * (UnitHealth(unitName) / UnitHealthMax(unitName))\n            states:Update(GUID, {\n                    progressType = 'static',\n                    unitName = unitName,\n                    value = health,\n                    total = 100,\n                    name = _G['HEALTH']\n            })\n            \n        elseif states[GUID] then\n            states:Remove(GUID)\n        end\n        \n    elseif event == 'OPTIONS' then\n        states:Update('', { \n                progressType = 'static',\n                unitName = WeakAuras.me,\n                value = 90,\n                total = 100,\n                name = _G['HEALTH']\n        })\n    end\nend",
