["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, _, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 106526 then -- Living Water\n                aura_env.StopCD('LivingWater')\n                aura_env.addSummoned = aura_env.addSummoned + 1\n                aura_env.Warning('LivingWaterSpawned', aura_env.addSummoned)\n            elseif spellID == 106612 then -- Bubble Burst (Phase 2)\n                aura_env.Warning('Phase2')\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'LIVING_WATER') then\n                aura_env.Warning('LivingWaterDied', aura_env.addSummoned)\n                if aura_env.addSummoned < 4 then\n                    aura_env.StartCD('LivingWater', 5, false, true)\n                end\n            end\n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 115167 \n            and destGUID == WeakAuras.myGUID \n            and aura_env.Antispam(spellID, 2) then\n                aura_env.Warning('CorruptingWaters')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('LivingWater', 10)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
