["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'Convert'\n\nlocal name, icon = C_Spell.GetSpellName(122740), C_Spell.GetSpellTexture(122740)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    ttsLine = Merfin:L(\"Mind Control\"),\n    prewarnCountVA = 1,\n    prewarnTTStext = Merfin:L(\"Mind Control Soon\"),\n}\n\naura_env.StopCD = function()\n    local data = { ID = ID }\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, data) -- no options\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        ignorePrew     = aura_env.ignorePrew,\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local names = {}\n    for _, name in ipairs(aura_env.targets) do\n        table.insert(names, WA_ClassColorName(name))\n    end\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = table.concat(names, ', '),\n        name     = name,\n        icon     = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispams[ID] or cur - aura_env.antispams[ID] > before then\n        aura_env.antispams[ID] = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, _, destName, _, _, spellID = ...\n        \n        if spellID == 122740 then\n            if not aura_env.IsSpam(3) then\n                aura_env.targets = {}\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(33)\n                \n                C_Timer.After(0.9, function()\n                        WeakAuras.ScanEvents('CONVERT_TARGETS') \n                end)\n            end\n            \n            table.insert(aura_env.targets, destName) \n        end\n        \n    elseif e == 'CONVERT_TARGETS' then\n        aura_env.SendWarning()\n        \n    elseif e == 'PLATFORM_CHANGED' then\n        aura_env.platformN = ...\n        \n        if aura_env.platformN == 3 then\n            aura_env.StartCD(30)\n        elseif aura_env.platformN == 4 then\n            aura_env.ignorePrew = true\n            aura_env.StartCD(58)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ignorePrew = false\n        aura_env.antispams = {}\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
