["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'Phase2'\nlocal name = Merfin:L('Phase 2')\n\nlocal options = {\n    warningText = string.format(\"@cffe3e3e3» %s «@r\", name:upper()),\n    ttsLine = name,\n}\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {ID = ID, name = name}, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
