["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.ClassColorName = function(name)\n    local _, class = UnitClass(name)\n    local color = RAID_CLASS_COLORS[class]\n    if color then\n        return string.format(\"|cFF%02X%02X%02X%s|r\", color.r * 255, color.g * 255, color.b * 255, name)\n    else\n        return name\n    end\nend\n\naura_env.GetNPCIDFromGUID = function(GUID)\n    local guidType, _, _, _, _, id = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id) or 0\n    end\n    return 0\nend\n\naura_env.markToIndex = {\n    ['star']     = 1,\n    ['circle']   = 2,\n    ['diamond']  = 3,\n    ['triangle'] = 4,\n    ['moon']     = 5,\n    ['square']   = 6,\n    ['cross']    = 7,\n    ['skull']    = 8,\n}",
["do_custom"] = true,
},
["finish"] = {
},
},
["selfPoint"] = "LEFT",
["desaturate"] = false,
["rotation"] = 0,
["font"] = "Friz Quadrata TT",
["crop_y"] = 0.41,
["textureWrapMode"] = "CLAMPTOBLACKADDITIVE",
["startAngle"] = 0,
["useAdjustededMin"] = false,
["regionType"] = "texture",
["blendMode"] = "BLEND",
["slantMode"] = "INSIDE",
["texture"] = "Interface\\AddOns\\WeakAuras\\Media\\Textures\\Circle_White",
["tocversion"] = 50500,
["alpha"] = 1,
["exrtLastSync"] = 1751209613,
["backgroundOffset"] = 0,
["wagoID"] = "H5gs0vTam",
["color"] = {
