0,
0.49803921580315,
},
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        return 2, aura_env.ClassColorName(WeakAuras.me)\n    end\n    \n    local nextStep = aura_env.nextStep\n    local nextPlayer = aura_env.order[nextStep]\n    return nextStep, aura_env.ClassColorName(nextPlayer)\nend",
["desaturateBackground"] = false,
["desaturateForeground"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    if event == 'PROTECTORS_INTERRUPT_ORDER' then\n        local fullOrder = ...\n        aura_env.order = nil\n        aura_env.trackedGUID = nil\n        aura_env.npcID = nil\n        aura_env.spellID = nil\n        \n        local bossConfig = {\n            regail = { npcID = 60585, spellID = 117187 },\n            asani  = { npcID = 60586, spellID = 118312 },\n        }\n        \n        for bossKey, playerList in pairs(fullOrder) do\n            for _, playerName in ipairs(playerList) do\n                if playerName == WeakAuras.me then\n                    aura_env.order = playerList\n                    aura_env.npcID = bossConfig[bossKey].npcID\n                    aura_env.spellID = bossConfig[bossKey].spellID\n                    break\n                end\n            end\n            if aura_env.order then break end\n        end\n        \n        if aura_env.order and aura_env.npcID and aura_env.spellID then\n            aura_env.count = 0\n            aura_env.nextStep = 1\n            \n            local nameplates = C_NamePlate.GetNamePlates()\n            for _, plate in ipairs(nameplates) do\n                local unit = plate.namePlateUnitToken\n                if unit and UnitExists(unit) then\n                    local GUID = UnitGUID(unit)\n                    local npcID = aura_env.GetNPCIDFromGUID(GUID)\n                    \n                    if npcID == aura_env.npcID then\n                        aura_env.trackedGUID = GUID\n                        states:Update('', {\n                                nextStep = aura_env.nextStep,\n                                unit     = unit,\n                        })\n                        break\n                    end\n                end\n            end\n        end\n        return\n    end\n    \n    if not aura_env.order or not aura_env.npcID or not aura_env.spellID then return end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, _, _, _, spellID, _, _, extraSpellID = ...\n        \n        if (subEvent == 'SPELL_CAST_SUCCESS' and spellID == aura_env.spellID and sourceGUID == aura_env.trackedGUID)\n        or (subEvent == 'SPELL_INTERRUPT' and extraSpellID == aura_env.spellID and destGUID == aura_env.trackedGUID) then\n            aura_env.count = (aura_env.count or 0) + 1\n            aura_env.nextStep = (aura_env.count % #aura_env.order) + 1\n            \n            WeakAuras.ScanEvents('INTERRUPT_SELF_WARNING_STOP')\n            \n            if states[''] then\n                states[''].nextStep = aura_env.nextStep\n                states[''].changed = true\n                return true\n            end\n            \n        elseif (subEvent == 'SPELL_CAST_START' and spellID == aura_env.spellID and sourceGUID == aura_env.trackedGUID) then\n            local isPlayer = aura_env.order[aura_env.nextStep] == WeakAuras.me\n            if isPlayer then\n                WeakAuras.ScanEvents('INTERRUPT_SELF_WARNING_START', spellID)\n            end\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_ADDED' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == aura_env.npcID then\n            aura_env.trackedGUID = GUID\n            states:Update('', {\n                    nextStep = aura_env.nextStep,\n                    unit     = unit,\n            })\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_REMOVED' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == aura_env.npcID and GUID == aura_env.trackedGUID then\n            states:Remove('')\n        end\n        \n    elseif event == 'UNIT_DIED' then\n        local _, destGUID = ...\n        if destGUID == aura_env.trackedGUID then\n            aura_env.trackedGUID = nil\n            aura_env.count = 0\n            aura_env.nextStep = 1\n            states:Remove('')\n            WeakAuras.ScanEvents('INTERRUPT_SELF_WARNING_STOP')\n        end\n        \n    elseif event == 'OPTIONS' then\n        aura_env.nextStep = 1\n    end\nend",
