},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1504'\nlocal ID          = 'BladeTempest'\n\nlocal name, icon = C_Spell.GetSpellName(125312), C_Spell.GetSpellTexture(125312)\n\nlocal options = {\n    warningText    = \"@cffff4040%upper:name@r\",\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n    prewarnCountVA = 2,\n}\n\naura_env.MRT = function()\n    local event = 'BLADE_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID   = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 125310 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(60)\n        end\n        \n    elseif e == 'PHASE_2' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.count = 0\n        aura_env.StartCD(60)\n    end\nend",
