["[DP] [Un'sok] Parasitic Growth"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1499'\nlocal ID          = 'ParasiticGrowth'\n\nlocal GetSpellInfoTable = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\nlocal data = {\n    ['ParasiticGrowth'] = GetSpellInfoTable(121949),\n    ['HealingRainOut']  = { name = 'GET OUT OF HEALING RAIN'},\n}\n\nlocal options = {\n    ['ParasiticGrowth'] = {\n        warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    },\n    ['HealingRainOut'] = {\n        warningText = \"@cffff4040\".. C_Spell.GetSpellName(73920):upper() .. \"@r\",\n    }\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = data[ID].name,\n            icon           = data[ID].icon,\n            count          = aura_env.count,\n    }, options['ParasiticGrowth'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = data[ID].name,\n            icon     = data[ID].icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n    }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID, spellName = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 121949 then\n                aura_env.count = aura_env.count + 1\n                \n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning('ParasiticGrowth', destName)\n                end\n                \n                if destGUID == WeakAuras.myGUID then\n                    aura_env.playerAffected = true\n                end\n                \n                aura_env.StartCD('ParasiticGrowth', 35)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 121949 and destGUID == WeakAuras.myGUID then\n                aura_env.playerAffected = false\n            end\n            \n        elseif subEvent == 'SPELL_HEAL' then\n            if not aura_env.playerAffected then return end\n            if spellID == 73921 and destGUID == WeakAuras.myGUID then\n                aura_env.SendWarning('HealingRainOut')\n            end\n        end\n        \n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.playerAffected = false\n        aura_env.count = 0\n        aura_env.StartCD('ParasiticGrowth', 23.5)\n    end\nend",
