},
["init"] = {
["custom"] = "local UnitPower = UnitPower\nlocal UnitName = UnitName\nlocal UnitClass = UnitClass\n\nlocal CLASS_ICONS = {\n    ['DEATHKNIGHT'] = 135771,\n    ['DRUID'] =       132136,\n    ['HUNTER'] =      135495,\n    ['MAGE'] =        135150,\n    ['PALADIN'] =     132325,\n    ['PRIEST'] =      135167,\n    ['ROGUE'] =       135428,\n    ['SHAMAN'] =      136012,\n    ['WARLOCK'] =     136020,\n    ['WARRIOR'] =     135328,\n    ['EVOKER'] =      135328, -- TEST\n}\n\nlocal cachedUnitClass = {}\nlocal GetUnitClassIcon = function(unitName)\n    if not cachedUnitClass[unitName] then\n        local _, class = UnitClass(unitName)\n        cachedUnitClass[unitName] = CLASS_ICONS[class]\n    end\n    return cachedUnitClass[unitName]\nend\n\nlocal sound_threshold = 70\nlocal raid_power = {}\n\naura_env['OPTIONS'] = function(a)\n    a[''] = {\n        show = true,\n        changed = true,\n        progressType = 'static',\n        unitName = WeakAuras.me,\n        value = 74,\n        total = 100,\n        icon = GetUnitClassIcon(WeakAuras.me),\n    }\n    return true\nend\n\naura_env['STATUS'] = function(a)\n    for unit in WA_IterateGroupMembers() do\n        local unitName = UnitName(unit)\n        raid_power[unitName] = 0\n    end\nend\n\naura_env['UNIT_POWER_UPDATE'] = function(a, unitId)\n    local changed = false\n    local unitName = UnitName(unitId)\n    if raid_power[unitName] then\n        local sound = UnitPower(unitId, 10)\n        raid_power[unitName] = sound\n        if sound >= sound_threshold then\n            a[unitName] = a[unitName] or {\n                show = true,\n                changed = true,\n                progressType = 'static',\n                unitName = unitName,\n                total = 100,\n                icon = GetUnitClassIcon(unitId),\n            }\n            a[unitName].value = sound\n            a[unitName].changed = true\n            changed = true\n        elseif a[unitName] then\n            a[unitName].show = false\n            a[unitName].changed = true\n            changed = true\n        end\n    end\n    return changed\nend",
["do_custom"] = true,
},
