["[DP] [SB] 小怪"] = {
["outline"] = "OUTLINE",
["wagoID"] = "1QYhYwGhZ",
["parent"] = "[MerfinDung] 依赖项",
["displayText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID, UnitName = UnitExists, UnitGUID, UnitName\nlocal stformat = string.format\nlocal GetTime = GetTime\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal BuildSpellData = function(id, role)\n    return { \n        name = C_Spell.GetSpellName(id), \n        icon = C_Spell.GetSpellTexture(id),\n        roleIcon = role,\n    }\nend\n\nlocal cooldownData = {\n}\n\nlocal encounterID = 'Trash'\n\nlocal CREATURE_ID = { \n}\n\nlocal PRE_WARNING = {   \n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then return 0 end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then  return false end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\nlocal unitIDPool = { \"target\", \"focus\", \"mouseover\" }\naura_env.GetTarget = function(GUID)\n    for _, unitID in ipairs(unitIDPool) do\n        if UnitExists(unitID) and UnitGUID(unitID) == GUID then\n            local targetUnitID = stformat(\"%starget\", unitID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        if plateData.namePlateUnitGUID == GUID then\n            local nameplateID = plateData.UnitFrame.displayedUnit\n            local targetUnitID = stformat(\"%starget\", nameplateID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    for unitID in WA_IterateGroupMembers() do\n        local targetUnitID = stformat(\"%starget\", unitID)\n        if UnitExists(targetUnitID) and UnitGUID(targetUnitID) == GUID then\n            return stformat(\"%starget\", targetUnitID)\n        end\n    end\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.Antispam = function(id, before)\n    local cur = GetTime()\n    if not aura_env.antispams[id] \n    or cur - aura_env.antispams[id] > before then\n        aura_env.antispams[id] = cur\n        return true\n    end\n    return false\nend\n\naura_env.WipeSchedulers = function()\n    if not aura_env.schedulers then return end\n    for schedulerName, scheduler in pairs(aura_env.schedulers) do\n        WeakAuras.timer:CancelTimer(scheduler)\n    end\nend\n\naura_env.ScheduleEvent = function(id, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        id\n    )\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_BOSS_PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_BOSS_PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_BOSS_PRE_WARNING', 'HIDE', id)\n    end\n    \n    local data = cooldownData[id]\n    if not data then return end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease, GUID)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    aura_env.predict[id] = duration + GetTime()\n    \n    if PRE_WARNING[id] then aura_env.SchedulePrewarning(id, duration) end\n    \n    local data = cooldownData[id]\n    if not data then return end\n    \n    local cooldown  = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        name = data.name,\n        id = id,\n        GUID = GUID,\n        icon = data.icon,\n        count = count,\n        roleIcon = data.roleIcon,\n        special = data.special,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldown)\nend\n\naura_env.Warning = function(...)\n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_WARNING', ...)\nend\n\naura_env.TTS = function(text, voiceID)\n    local voiceID = voiceID or 2\n    WeakAuras.ScanEvents('WA_MERFIN_DUNGEON_TTS', text, voiceID)\nend\n\naura_env.Chat = function(text, chatType)\n    WeakAuras.ScanEvents('WA_MERFIN_DUNGEON_CHAT', text, chatType)\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    \n    aura_env.WipeSchedulers()\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    aura_env.antispams = {}\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, _, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 106546 then\n                local count = aura_env.ManageCounter('increase', 'Bloat')\n                --aura_env.TTS(spellName)\n            elseif spellID == 116162 then\n                local _, targetName = aura_env.GetTarget(sourceGUID)\n                if targetName == WeakAuras.me then\n                    aura_env.Warning('CarbonationOnPlayer')\n                    --aura_env.Chat('{rt2} Carbonation on ' .. WeakAuras.me .. ' {rt2}')\n                end\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 106546 then\n                if destName == WeakAuras.me then\n                    aura_env.Chat('{rt8}')\n                else\n                    aura_env.Warning('BloatAppled', destName)\n                end\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 106546 then\n                if destName == WeakAuras.me then\n                    aura_env.Chat('- cleared -')\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
