["value"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    if not aura_env.last or GetTime() - aura_env.last > 1 then\n        aura_env.last = GetTime()\n        local duration = aura_env.state.expirationTime - GetTime()\n        duration = math.ceil(duration)\n        if duration > 0 then\n            SendChatMessage(math.ceil(duration), 'SAY')\n        end\n    end\nend",
["variable"] = "customcheck",
