["[DP] [Feng] Arcane Resonance"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1390'\nlocal ID          = 'ArcaneResonance'\n\nlocal name, icon = C_Spell.GetSpellName(116417), C_Spell.GetSpellTexture(116417)\n\nlocal options = {\n    ['ArcaneResonance'] = {\n        warningText = '%icon @cffff8b17%name@r (%count) » %destName %icon',\n        ttsLine = Merfin:L('Debuffs'),\n        prewarnTTStext = Merfin:L('Debuffs Soon'),\n        readyText = Merfin:L('DEBUFFS INC.'),\n    },\n    ['ArcaneResonanceGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    },\n}\n\naura_env.MRT = function()\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'RESONANCE_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\n    \nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env.CancelMRT()\n    local after = duration <= 5 and duration or duration - 5\n    aura_env._mrtTimer = C_Timer.NewTimer(after, aura_env.MRT)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['ArcaneResonance'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = destName,\n        name     = name,\n        icon     = icon,\n        color    = color\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 116434 \n            and destGUID == WeakAuras.myGUID \n            and sourceGUID ~= WeakAuras.myGUID then\n                aura_env.SendWarning('ArcaneResonanceGTFO')\n            end\n        end\n        \n        if spellID ~= 116417 then return end\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            aura_env.count = aura_env.count + 1\n            aura_env.StartCD(15.5)\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            table.insert(aura_env.targets, destName)\n            \n            if aura_env.IsSpam(3) then\n                return\n            end\n            \n            C_Timer.After(0.3, function()\n                    for index, destName in ipairs(aura_env.targets) do\n                        aura_env.RaidIcon('SET', destName, index)\n                    end\n                    \n                    local names = {}\n                    for _, name in ipairs(aura_env.targets) do\n                        table.insert(names, WA_ClassColorName(name))\n                    end\n                    \n                    local destNames = table.concat(names, ', ')\n                    aura_env.SendWarning('ArcaneResonance', destNames)\n                    aura_env.targets = {}\n            end)\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            aura_env.RaidIcon('REMOVE', destName)\n        end\n        \n    elseif e == 'PHASE_CHANGED' then\n        local phase = ...\n        \n        if phase == 'ARCANE' then\n            aura_env.count = 0\n            aura_env.StartCD(12)\n            \n        elseif phase == 'END' then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.targets = {}\n        aura_env.CancelMRT()\n    end\nend",
