["init"] = {
["custom"] = "local L = GetLocale()\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        tsulongActive = \"No... the waters... I must... resist... I shall not... fear...\",\n        zorlokActive = \"And so it falls to us, Her chosen voice.\",\n        tayakActive = \"They failed their test. Will you?\",\n        garalonActive = \"Breath of the empress, bring mighty Garalon to us!\",\n    },\n    \n    ['ruRU'] = {\n        --tsulongActive = \"\",\n        --zorlokActive = \"\",\n        tayakActive = \"Они не прошли испытание. Сможете ли вы?\",\n        garalonActive = \"Дыхание императрицы, пошли нам могучего Гаралона!\",\n    }\n}",
["do_custom"] = true,
},
},
["triggers"] = {
