},
["custom"] = "function(event, ...)\n    if event == 'CHAT_MSG_MONSTER_YELL' then\n        local msg = ...\n        if not msg then return end\n        \n        if aura_env.IsEmote(msg, 'tsulongActive') then\n            WeakAuras.ScanEvents('TSULONG_ACTIVE')\n            \n        elseif aura_env.IsEmote(msg, 'zorlokActive') then\n            WeakAuras.ScanEvents('ZORLOK_ACTIVE')\n            \n        elseif aura_env.IsEmote(msg, 'tayakActive') then\n            WeakAuras.ScanEvents('TAYAK_ACTIVE')\n            \n        elseif aura_env.IsEmote(msg, 'garalonActive') then\n            WeakAuras.ScanEvents('GARALON_ACTIVE')\n        end\n    end\nend",
