["init"] = {
["custom"] = "local encounterID = 'Trash'\nlocal ID          = 'SummonZephyr'\n\nlocal name, icon = C_Spell.GetSpellName(124085), C_Spell.GetSpellTexture(124085)\n\nlocal options = {\n    warningText = \"%icon %name %icon\",\n    ttsLine = Merfin:L(\"Dodge\"),\n}\n\naura_env.StopCD = function(destGUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID   = ID,\n            GUID = destGUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            GUID           = GUID,\n            name           = name,\n            icon           = icon\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID      = ID,\n            count   = aura_env.count,\n            noCount = true,\n            name    = name,\n            icon    = icon\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 124085 then\n                aura_env.SendWarning()\n                aura_env.StartCD(15, sourceGUID)\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if Merfin.GetNPCIDFromGUID(destGUID) == 63593 then\n                aura_env.StopCD(destGUID)\n            end\n        end\n    end\nend",
