["[事件依赖] 死亡之翼的背脊"] = {
["outline"] = "OUTLINE",
["wagoID"] = "r2q5DNxZh",
["parent"] = "[T13] 事件依赖",
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\nlocal L = GetLocale()\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal cooldownData = {\n    ['FieryGrip'] = { name = 'Fiery Grip', icon = 538041 },\n}\n\nlocal encounterID = '1291'\n\nlocal CREATURE_ID = {\n    Corruption = { 53891, 56161, 56162 },\n    Amalgamation = 53890,\n    Blood = 53889,\n    Tendons = 56575,\n}\n\nlocal PRE_WARNING = {\n    ['Roll'] = true,\n    ['FieryGrip'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then\n        return 0\n    end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then \n        return false \n    end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    if type(creatureId) == 'table' then\n        for _, creatureNpcId in pairs(creatureId) do\n            if npcId == creatureNpcId then\n                return true\n            end\n        end\n    end\n    return npcId == creatureId\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.WipeSchedulers = function()\n    if aura_env.schedulers then \n        for schedulerName, scheduler in pairs(aura_env.schedulers) do\n            WeakAuras.timer:CancelTimer(scheduler)\n        end\n    end\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_T13',\n        'PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.ScheduleEvent = function(subEvent, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[subEvent] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[subEvent])\n    end\n    \n    aura_env.schedulers[subEvent] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        subEvent\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease, GUID)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    \n    aura_env.predict[id] = duration + GetTime()\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown  = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        name = data.name,\n        id = id,\n        GUID = GUID,\n        icon = data.icon,\n        count = count,\n        roleIcon = data.roleIcon,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldown)\n    \n    if not PRE_WARNING[id] then return end\n    \n    aura_env.SchedulePrewarning(id, duration)\nend\n\naura_env.IsCooldownReadyBefore = function(id, before)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (predictedAt - GetTime() > before)\nend\n\naura_env.IsCooldownReady = function(id)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (GetTime() > predictedAt)\nend\n\naura_env.Warning = function(warning, ...)\n    WeakAuras.ScanEvents('WA_MERFIN_T13', 'WARNING', warning, ...)\nend\n\naura_env.Antispam = function(id, before)\n    local cur = GetTime()\n    if not aura_env.antispams[id] \n    or cur - aura_env.antispams[id] > before then\n        aura_env.antispams[id] = cur\n        return true\n    end\n    return false\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    aura_env.size = WeakAuras.InstanceType()\n    \n    aura_env.WipeSchedulers()\n    \n    -- Reset Flags\n    aura_env.corStatus = {}\n    aura_env.corLast = true\n    aura_env.nextGrip = 0\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    aura_env.antispams = {}\n    \n    -- Destination Names\nend\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then\n        return false\n    end\n    \n    if not aura_env.replicas[L] then\n        return false\n    end\n    \n    local replica = aura_env.replicas[L][compareWith]\n    \n    if not replica then\n        return false\n    end\n    \n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Roll = \"about to roll\",\n        RightRoll = \"about to roll right\",\n        LeftRoll = \"about to roll left\",\n        Levels = \"levels out\",\n        RollFinal = \"rolls\",\n    },\n    ['ruRU'] = {\n        Roll = \"собирается накрениться\",\n        RightRoll = \"собирается накрениться вправо\",\n        LeftRoll = \"собирается накрениться влево\",\n        Levels = \"выравнивается\",\n        RollFinal = \"наклоняется\",\n    },\n    ['zhTW'] = {\n        Roll = \"他準備往\",\n        Levels = \"回復平衡\",\n    },\n    ['koKR'] = {\n        Roll = \"회전하려고\",\n        Levels = \"수평으로 균형을\",\n    },\n    ['itIT'] = {\n        Roll = \"Sta per effettuare un avvitamento\",\n        Levels = \"Fermatelo!!!\",\n    },\n    ['frFR'] = {\n        Roll = \"Sta per effettuare un avvitamento\",\n        Levels = \"Fermatelo!!!\",\n    },\n    ['esES'] = {\n        Roll = \"Sta per effettuare un avvitamento\",\n        Levels = \"Fermatelo!!!\",\n    },\n    ['esMX'] = {\n        Roll = \"Sta per effettuare un avvitamento\",\n        Levels = \"Fermatelo!!!\",\n    },\n    ['deDE'] = {\n        Roll = \"wird gleich\",\n        Levels = \"stabilisiert sich\",\n    },\n    ['zhCN'] = {\n        Roll = \"侧翻滚！\",\n        Levels = \"保持平衡\",\n    },\n}\n\naura_env.oldTimers = aura_env.config.oldTimers\n\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, WA_MERFIN_T13_SCHEDULED, RAID_BOSS_EMOTE, CLEU:SPELL_CAST_SUCCESS:SPELL_CAST_START:UNIT_DIED",
["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId, _, _, _, amount)\n    \n    if e == 'RAID_BOSS_EMOTE' then\n        if aura_env.IsEmote(msg, 'Roll') then\n            aura_env.StartCD('Roll', 5)\n        end\n        if aura_env.IsEmote(msg, 'LeftRoll') then\n            WeakAuras.ScanEvents('WA_MERFIN_ROLL', 'LEFT')\n        elseif aura_env.IsEmote(msg, 'RightRoll') then\n            WeakAuras.ScanEvents('WA_MERFIN_ROLL', 'RIGHT')\n        elseif aura_env.IsEmote(msg, 'Levels') or aura_env.IsEmote(msg, 'RollFinal') then\n            WeakAuras.ScanEvents('WA_MERFIN_ROLL', 'BALANCED')\n            aura_env.StopCD('Roll')\n        end\n        \n    elseif e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        -- BigWigs Pasta\n        if subEvent == 'SPELL_CAST_START' then\n            if spellId == 109379 then\n                if not aura_env.corStatus[sourceGUID] then\n                    aura_env.corStatus[sourceGUID] = 0\n                else\n                    aura_env.corStatus[sourceGUID] = aura_env.corStatus[sourceGUID] + 1\n                end\n                \n                local gripTime\n                if WeakAuras.InstanceType() == 'twentyfive' then\n                    gripTime = 16\n                else\n                    gripTime = 32\n                end\n                gripTime = gripTime - aura_env.corStatus[sourceGUID] * 8\n                local nextGripNew = gripTime + GetTime()\n                \n                if not aura_env.corLast or (aura_env.corLast == sourceGUID and math.abs(aura_env.nextGrip - nextGripNew) > 0.5) then\n                    aura_env.corLast = sourceGUID\n                    aura_env.nextGrip = nextGripNew\n                    aura_env.StartCD('FieryGrip', gripTime, false, true, sourceGUID)\n                end\n                \n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellId == 105490 then\n                aura_env.corStatus[sourceGUID] = nil\n                if aura_env.corLast == sourceGUID or aura_env.corLast == true then\n                    aura_env.corLast = nil\n                    aura_env.StopCD('FieryGrip', sourceGUID)\n                end\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.corLast == destGUID then\n                aura_env.corLast = nil\n            end\n            \n            if aura_env.IsGUID(destGUID, 'Corruption') then\n                aura_env.corStatus[destGUID] = nil\n                aura_env.StopCD('FieryGrip', destGUID)\n            end\n        end\n        \n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        \n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        if WeakAuras.InstanceType() == 'twentyfive' then\n            aura_env.StartCD('FieryGrip', 15, true, false, 'Initial')\n        else\n            aura_env.StartCD('FieryGrip', 27, true, false, 'Initial')\n        end\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
