["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'HeartOfFear'\n\nlocal name, icon = C_Spell.GetSpellName(123845), C_Spell.GetSpellTexture(123845)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r %icon\",\n}\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n    }, options)\nend",
["do_custom"] = true,
},
},
