["init"] = {
["custom"] = "aura_env.region.configGroup = \"holy_power\"\n\nlocal r = aura_env.region\nlocal delay = 0.3\n\nif not r.ag then\n    r.ot = r.bar:CreateTexture()\n    r.ot:SetAllPoints(r.bar.bg)\n    r.ag = r.ot:CreateAnimationGroup()\nend\n\nr.ot:SetAlpha(0)\n\nr.ag:RemoveAnimations()\n\nlocal anim = r.ag:CreateAnimation(\"Alpha\")\n\nanim:SetDuration(delay)\nanim:SetEndDelay(delay)\nanim:SetFromAlpha(1)\nanim:SetToAlpha(0.35)\n\nanim = r.ag:CreateAnimation(\"Alpha\")\n\nanim:SetDuration(delay)\nanim:SetStartDelay(delay)\nanim:SetFromAlpha(0.35)\nanim:SetToAlpha(1)\n\nr.ag:SetLooping(\"Repeat\")\n\n",
["do_custom"] = true,
},
