["【露露】工程手套、火箭靴腰带就绪语音（MOP）"] = {
["outline"] = "OUTLINE",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_custom"] = true,
["custom"] = "-- Author: 露露緹婭@Bilibili\nlocal R = \"Interface\\\\AddOns\\\\Rurutia\\\\【露露】\"\n\nlocal triggerSounds = {\n    [1] = R..\"手套好了.ogg\",       -- 工程附魔（手套）\n    [2] = R..\"腰带好了.ogg\",       -- 工程附魔（腰带）\n    [3] = R..\"披风好了.ogg\",       -- 工程附魔（披风）\n}\n\n-- 获取当前激活的触发器\nlocal activeTriggers = WeakAuras.GetActiveTriggers(aura_env.id)\nif activeTriggers then\n    -- 遍历所有触发器，播放第一个激活的触发器对应的语音\n    for triggerIndex, isActive in pairs(activeTriggers) do\n        if isActive and triggerSounds[triggerIndex] then\n            PlaySoundFile(triggerSounds[triggerIndex], \"Master\")\n            return -- 只播放第一个激活的触发器\n        end\n    end\nend",
},
