},
["custom"] = "function(a,_, nameplateId)\n    \n    if not nameplateId then\n        return\n    end\n    \n    local guid = UnitGUID(nameplateId)\n    local npcId = select(6, strsplit(\"-\", guid))\n    \n    if npcId ~= '56265' then\n        return\n    end\n    \n    local health, healthMax = UnitHealth(nameplateId), UnitHealthMax(nameplateId)\n    local percenthealth = 100 * health / healthMax\n    \n    if percenthealth < 99 then\n        return\n    end\n    \n    \n    local curTime = GetTime()\n    if aura_env.last and curTime - aura_env.last < 20 then\n        return\n    end\n    aura_env.last = curTime\n    \n    a[''] = {\n        show = true,\n        changed = true,\n        progressType = 'timed',\n        duration = 10,\n        expirationTime = 10 + GetTime(),\n        autoHide = true,\n    }\n    \n    return true\nend",
