["[Widget] Sha Ping Pont Distributor"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["parent"] = "[Widget] Sha Ping Pong",
["displayText"] = "%order",
["yOffset"] = 0,
["anchorPoint"] = "TOPLEFT",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["init"] = {
},
["finish"] = {
["hide_all_glows"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    myTarget = {\n        display = 'is my target?',\n        type = 'bool'\n    },\n    \n    debuffed = {\n        display = 'is debuffed?',\n        type = 'bool'\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    aura_env.priorityList = aura_env.priorityList or {}\n    aura_env.indexByName = aura_env.indexByName or {}\n    aura_env.lastChampionHolder = aura_env.lastChampionHolder or nil\n    \n    local HUDDLE_ID   = 120629   -- Huddle in Terror\n    local CHAMPION_ID = 120268   -- Champion of the Light\n    \n    local function markMyTarget()\n        local myIndex = aura_env.indexByName[WeakAuras.me]\n        local hasBuff = aura_env.lastChampionHolder == WeakAuras.me\n        \n        -- Сброс всех myTarget\n        for unit in pairs(states) do\n            if aura_env.indexByName[unit] then\n                states:Update(unit, { myTarget = false })\n            end\n        end\n        \n        if hasBuff and not myIndex then\n            -- Я не в списке, но у меня Champion — цель первый в очереди\n            for _, name in ipairs(aura_env.priorityList) do\n                if states[name] then\n                    states:Update(name, { myTarget = true })\n                    break\n                end\n            end\n        elseif myIndex then\n            -- Я в списке — цель следующий\n            for i = myIndex + 1, #aura_env.priorityList do\n                local nextName = aura_env.priorityList[i]\n                if states[nextName] then\n                    states:Update(nextName, { myTarget = true })\n                    break\n                end\n            end\n        end\n    end\n    \n    local function rebuildPriorityList(newList)\n        aura_env.priorityList = {}\n        aura_env.indexByName = {}\n        \n        for i, name in ipairs(newList) do\n            aura_env.priorityList[i] = name\n            aura_env.indexByName[name] = i\n            \n            states:Update(name, {\n                    show    = true,\n                    order   = i,\n                    unit    = name,\n                    myTarget = false\n            })\n        end\n        \n        markMyTarget()\n    end\n    \n    local function removeFromPriorityList(name)\n        for i, v in ipairs(aura_env.priorityList) do\n            if v == name then\n                table.remove(aura_env.priorityList, i)\n                break\n            end\n        end\n        aura_env.indexByName[name] = nil\n    end\n    \n    if event == \"SHA_PING_PONG_LIST\" then\n        local sortedTargets = ...\n        if not sortedTargets or type(sortedTargets) ~= \"table\" then return end\n        \n        rebuildPriorityList(sortedTargets)\n        return true\n    end\n    \n    if event == \"SHA_PING_PONG_STOP\" then\n        for name in pairs(states) do\n            states:Remove(name)\n        end\n        aura_env.priorityList = {}\n        aura_env.indexByName = {}\n        -- lastChampionHolder сохраняется\n        return true\n    end\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, _, sourceName, _, _, destGUID, _, _, _, spellID = ...\n        \n        -- Champion of the Light получен\n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == CHAMPION_ID then\n            local destName = select(6, GetPlayerInfoByGUID(destGUID))\n            if destName then\n                aura_env.lastChampionHolder = destName\n                \n                -- Удаляем state у нового владельца, если был\n                if states[destName] then\n                    states:Remove(destName)\n                    removeFromPriorityList(destName)\n                end\n                \n                markMyTarget()\n                return true\n            end\n        end\n        \n        -- Huddle in Terror снят\n        if subEvent == \"SPELL_AURA_REMOVED\" and spellID == HUDDLE_ID then\n            local destName = select(6, GetPlayerInfoByGUID(destGUID))\n            if destName and states[destName] then\n                states:Remove(destName)\n                removeFromPriorityList(destName)\n                markMyTarget()\n                return true\n            end\n        end\n    end\nend",
["spellIds"] = {
},
