0.49803921580315,
},
["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        return 2, aura_env.ClassColorName(WeakAuras.me)\n    end\n    \n    local nextStep = aura_env.nextStep\n    local nextPlayer = aura_env.order[nextStep]\n    return nextStep, aura_env.ClassColorName(nextPlayer)\nend",
["desaturateBackground"] = false,
["desaturateForeground"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    if event == 'MELJARAK_INTERRUPT_ORDER' then\n        local fullOrder = ...\n        aura_env.order = nil\n        aura_env.mark = nil\n        aura_env.trackedGUID = nil\n        \n        for mark, playerList in pairs(fullOrder) do\n            for _, playerName in ipairs(playerList) do\n                if playerName == WeakAuras.me then\n                    aura_env.order = playerList\n                    aura_env.mark = mark\n                    break\n                end\n            end\n            if aura_env.order then break end\n        end\n        \n        if aura_env.order then\n            aura_env.count = 0\n            aura_env.nextStep = 1\n            \n            local nameplates = C_NamePlate.GetNamePlates()\n            for _, plate in ipairs(nameplates) do\n                local unit = plate.namePlateUnitToken\n                if unit and UnitExists(unit) then\n                    local GUID = UnitGUID(unit)\n                    local npcID = aura_env.GetNPCIDFromGUID(GUID)\n                    \n                    if npcID == 62408 then\n                        local index = GetRaidTargetIndex(unit)\n                        if index and index == aura_env.markToIndex[aura_env.mark] then\n                            aura_env.trackedGUID = GUID\n                            states:Update('', {\n                                    nextStep = aura_env.nextStep,\n                                    unit     = unit,\n                            })\n                            break\n                        end\n                    end\n                end\n            end\n        end\n        return\n    end\n    \n    if not aura_env.order or not aura_env.mark then return end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, _, _, _, spellID, _, _, extraSpellID = ...\n        \n        if (subEvent == 'SPELL_CAST_SUCCESS' and spellID == 122193 and sourceGUID == aura_env.trackedGUID)\n        or (subEvent == 'SPELL_INTERRUPT' and extraSpellID == 122193 and destGUID == aura_env.trackedGUID) then\n            aura_env.count = (aura_env.count or 0) + 1\n            aura_env.nextStep = (aura_env.count % #aura_env.order) + 1\n            print('aura_env.nextStep', aura_env.nextStep)\n            -- Interrupt Now Warning\n            WeakAuras.ScanEvents('INTERRUPT_SELF_WARNING_STOP')\n            \n            if states[''] then\n                states[''].nextStep = aura_env.nextStep\n                states[''].changed = true\n                return true\n            end\n            \n        elseif (subEvent == 'SPELL_CAST_START' and spellID == 122193 and sourceGUID == aura_env.trackedGUID) then\n            -- Interrupt Now Warning\n            local isPlayer = aura_env.order[aura_env.nextStep] == WeakAuras.me\n            if isPlayer then\n                WeakAuras.ScanEvents('INTERRUPT_SELF_WARNING_START')\n            end\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_ADDED' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == 62408 then\n            local index = GetRaidTargetIndex(unit)\n            if index and index == aura_env.markToIndex[aura_env.mark] then\n                aura_env.trackedGUID = GUID\n                states:Update('', {\n                        nextStep = aura_env.nextStep,\n                        unit     = unit,\n                })\n            end\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_REMOVED' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == 62408 and GUID == aura_env.trackedGUID then\n            states:Remove('')\n        end\n        \n    elseif event == 'UNIT_DIED' then\n        local _, destGUID = ...\n        if destGUID == aura_env.trackedGUID then\n            aura_env.trackedGUID = nil\n            aura_env.count = 0\n            aura_env.nextStep = 1\n            states:Remove('')\n        end\n        \n    elseif event == 'RAID_TARGET_UPDATE' then\n        local nameplates = C_NamePlate.GetNamePlates()\n        for _, plate in ipairs(nameplates) do\n            local unit = plate.namePlateUnitToken\n            if unit and UnitExists(unit) then\n                local GUID = UnitGUID(unit)\n                local npcID = aura_env.GetNPCIDFromGUID(GUID)\n                \n                if npcID == 62408 then\n                    local index = GetRaidTargetIndex(unit)\n                    if index and index == aura_env.markToIndex[aura_env.mark] then\n                        aura_env.trackedGUID = GUID\n                        states:Update('', {\n                                nextStep = aura_env.nextStep,\n                                unit     = unit,\n                        })\n                        break\n                    end\n                end\n            end\n        end\n        \n    elseif event == 'OPTIONS' then\n        aura_env.nextStep = 1\n    end\nend",
["names"] = {
},
["check"] = "event",
["events"] = "MELJARAK_INTERRUPT_ORDER, CLEU:SPELL_CAST_SUCCESS:SPELL_INTERRUPT:SPELL_CAST_START, UNIT_DIED, NAME_PLATE_UNIT_ADDED, NAME_PLATE_UNIT_REMOVED, RAID_TARGET_UPDATE",
["spellIds"] = {
