{
["trigger"] = {
["unit"] = "player",
["type"] = "custom",
["custom"] = "function(states, e, ...)\n    \n    if not aura_env.order or not aura_env.mark then return end\n    \n    if e == 'OPTIONS' then\n        states:Update(i, {\n                progressType   = 'timed',\n                autoHide       = false,\n                duration       = 15,\n                expirationTime = 15 + GetTime(),\n                name           = C_Spell.GetSpellName(122774),\n                nextCount      = math.random(1, 10),\n        })\n    end\n    \n    if e == 'MERFIN_CD_HIDE' then\n        local encounterID, cooldown = ...\n        \n        if cooldown.ID ~= 'Mending' then return end\n        if cooldown.GUID ~= aura_env.trackedGUID then return end\n        \n        states:Remove('')\n        \n    elseif e == 'MERFIN_CD_SHOW_WIDGET' then\n        local encounterID, cooldown = ...\n        \n        if cooldown.ID ~= 'Mending' then return end\n        if cooldown.GUID ~= aura_env.trackedGUID then return end\n\n        local newState = {\n            progressType   = 'timed',\n            duration       = cooldown.duration,\n            expirationTime = cooldown.expirationTime,\n            autoHide       = cooldown.autoHide,\n            icon           = cooldown.icon,\n            name           = cooldown.name,\n            nextCount      = (cooldown.count or 0) + 1,\n            noCount        = cooldown.noCount,\n            cooldownId     = cooldown.ID,\n            sourceName     = cooldown.sourceName,\n            hasSrcName     = cooldown.sourceName ~= nil,\n        }\n        \n        states:Update('', newState)\n    end\nend",
