["[DP] [Mel'jarak] Whirling Blade"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'WhirlingBlade'\n\nlocal name, icon = C_Spell.GetSpellName(121896), C_Spell.GetSpellTexture(121896)\n\nlocal options = {\n    ['WhirlingBlade'] = {\n        warningText = \"@cffff4040%upper:name@r\",\n        ttsLine = Merfin:L('Dodge Blade'),\n    },\n    ['WhirlingBladeGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    },\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n        }, options['WhirlingBlade'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then \n            if spellID == 121898 and destGUID == WeakAuras.myGUID and aura_env.IsSpam(3) then\n                aura_env.SendWarning('WhirlingBladeGTFO')\n            end\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 121896 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('WhirlingBlade')\n                local seconds = aura_env.phase2 and 30 or 45\n                aura_env.StartCD(seconds)\n            end\n        end\n        \n    elseif e == 'MELJARAK_PHASE2' then\n        aura_env.phase2 = true\n        aura_env.StartCD(30)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.phase2 = false\n        aura_env.StartCD(36)\n    end\nend",
