["custom"] = "\n\n",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'DreadShadowsHigh'\n\nlocal name, icon = C_Spell.GetSpellName(122768), C_Spell.GetSpellTexture(122768)\n\nlocal options = {\n    warningText = \"@cffff4040%upper:name@r (x%amount)\",\n    ttsLine = Merfin:L('High Stacks')\n}\n\naura_env.SendWarning = function(amount)\n    local data = {\n        ID = ID,\n        name = name,\n        icon = icon,\n        amount = amount\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID,_,_,_, amount = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' \n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            local stacks = amount or 1\n            if spellID == 122768 and destGUID == WeakAuras.myGUID \n            and stacks >= 12 and not aura_env.IsSpam(5) then\n                aura_env.SendWarning(stacks)\n            end\n        end\n    end\nend",
