["custom"] = "function(states, e, _, warning)\n    if e == 'OPTIONS' then\n        states:Update('', {\n                progressType   = 'timed',\n                duration       = 4.5,\n                expirationTime = 4.5 + GetTime(),\n                autoHide       = true,\n                name           = C_Spell.GetSpellName(123017),\n                count          = 2, \n                destName       = WA_ClassColorName(WeakAuras.me)\n        })\n    end\n    if e == 'MERFIN_WARNING' and warning.ID == 'UnseenStrike' then\n        states:Update('', {\n                progressType   = 'timed',\n                duration       = 4.5,\n                expirationTime = 4.5 + GetTime(),\n                autoHide       = true,\n                name           = warning.name,\n                count          = warning.count, \n                destName       = warning.destName\n        })\n    end\nend",
