["init"] = {
["custom"] = "local UnitGUID = UnitGUID\nlocal UnitExists = UnitExists\nlocal GetRange = WeakAuras.GetRange\nlocal GetTime = GetTime\n\nlocal MOBS_TO_COUNT = {\n    [56265] = true,\n}\n\naura_env['WA_MERFIN_COUNT_ADDS'] = function(a)\n    local nameplates = C_NamePlate.GetNamePlates()\n    local totalPlates = 0\n    for _, plateData in pairs(nameplates) do\n        local npcId = plateData.namePlateNpcId\n        if MOBS_TO_COUNT[npcId] then\n            totalPlates = totalPlates + 1\n        end\n    end\n    \n    a[''] = {\n        show = true,\n        changed = true,\n        count = totalPlates\n    }\n    \n    if totalPlates > 0 then\n        return true\n    end\n    \n    if a[''] then\n        a[''].show = false\n        a[''].changed = true\n        return true\n    end\nend\n\naura_env['STATUS'] = function(a)\n    C_Timer.After(0.1, function() WeakAuras.ScanEvents('WA_MERFIN_COUNT_ADDS') end) \nend\n\naura_env['OPTIONS'] = aura_env['STATUS']\naura_env['NAME_PLATE_UNIT_ADDED'] = aura_env['STATUS']\naura_env['NAME_PLATE_UNIT_REMOVED'] = aura_env['STATUS']\n\n\n",
