["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.IsSpam = function(seconds)\n    local cur = GetTime()\n    if not aura_env.antispam or (cur - aura_env.antispam) > seconds then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.AnnounceCD = function(ID, duration)\n    WeakAuras.ScanEvents('SPECIAL_CAST_CD', ID, duration)\nend\n\naura_env.StartSpecialTimers = function()\n    local huddle = aura_env.huddleUsed\n    local spout = aura_env.spoutUsed\n    local strike = aura_env.strikeUsed\n    \n    if not huddle then\n        -- Huddle in Terror CD starts (10 sec)\n        aura_env.AnnounceCD('HuddleInTerror', 10)\n    elseif not spout and not strike then\n        -- Huddle used, next: Spout or Strike\n        aura_env.AnnounceCD('SpoutStrike', 10)\n    elseif spout and not strike then\n        -- Spout already used, next: Implacable Strike\n        aura_env.AnnounceCD('ImplacableStrike', 9.5)\n    elseif strike and not spout then\n        -- Strike already used, next: Waterspout\n        aura_env.AnnounceCD('Waterspout', 10)\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, destName, _, _, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            --[[if spellID == 120629 then -- Huddle in Terror\n                aura_env.huddleUsed = true\n                aura_env.StartSpecialTimers()\n            end]]--\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 120672 then -- Implacable Strike\n                aura_env.strikeUsed = true\n                aura_env.StartSpecialTimers()\n                \n            elseif spellID == 120519 then -- Waterspout\n                aura_env.spoutUsed = true\n                aura_env.StartSpecialTimers()\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        \n        if spellID == 132608 then -- Huddle in Terror\n            aura_env.huddleUsed = true\n            aura_env.StartSpecialTimers()\n        end\n        \n    elseif e == 'EMERGE' then\n        aura_env.huddleUsed = false\n        aura_env.spoutUsed = false\n        aura_env.strikeUsed = false\n        aura_env.AnnounceCD('SpotStrikeHuddle', 10)\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        if phaseN == 2 then\n            aura_env.huddleUsed = false\n            aura_env.spoutUsed = false\n            aura_env.strikeUsed = false\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.huddleUsed = false\n        aura_env.spoutUsed = false\n        aura_env.strikeUsed = false\n    end\nend",
