},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = 'Trash'\nlocal ID          = 'OverwhelmingAssault'\n\nlocal name, icon = C_Spell.GetSpellName(123474), C_Spell.GetSpellTexture(123474)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r » %destName (%amount) %icon\",\n}\n\naura_env.StopCD = function(destGUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID   = ID,\n            GUID = destGUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            GUID           = GUID,\n            sourceName     = '|cff9d9d9dTakthok|r',\n            name           = name,\n            icon           = icon\n    }, options)\nend\n\naura_env.SendWarning = function(destName, amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            count    = aura_env.count,\n            noCount  = true,\n            destName = WA_ClassColorName(destName),\n            amount   = amount,\n            name     = name,\n            icon     = icon\n    }, options)\nend",
["do_custom"] = true,
},
},
