["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID, _,_,_, amount = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 123474 and Merfin.GetNPCIDFromGUID(sourceGUID) == 64339 then\n                aura_env.StartCD(10, sourceGUID)\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if Merfin.GetNPCIDFromGUID(destGUID) == 64339 then\n                aura_env.StopCD(destGUID)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 123474 and Merfin.GetNPCIDFromGUID(sourceGUID) == 64339 then\n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning(destName, amount or 1)\n                end\n            end\n        end\n    end\nend",
