["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "LEFT",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "-- Example on how to add aura_env table to VDT:\n-- DevTool:AddData(table, \"title\")\n-- DevTool:AddData(aura_env, aura_env.id..\"-env table\")\n\n\naura_env.chosenMarkers1 = {}\naura_env.chosenMarkers2 = {}\naura_env.chosenMarkers3 = {}\naura_env.chosenMarkers4 = {}\naura_env.chosenMarkers5 = {}\naura_env.chosenMarkers6 = {}\naura_env.chosenMarkers7 = {}\naura_env.chosenMarkers8 = {}\naura_env.chosenMarkers9 = {}\naura_env.markersOrder = {}\naura_env.startValueDiff = 0\n\n-- Add it here and in custom options\naura_env.ignoreNameplates = {\n    [190294] = true,  -- Nokhud Stormcaster\n    [129359] = true,  -- Sawtooth Shark\n    [129448] = true,  -- Hammer Shark\n    [199748] = true,  -- Timeline Marauder\n    [208165] = true,  -- Alliance Knight\n    [208193] = true,  -- Paladin of the Silver Hand\n    [207969] = true,  -- Horde Raider\n    [204206] = true,  -- Horde Farseer\n}\n\n-- Populate the markers lists\nfor i = 1, 9 do -- loop through every marker group\n    for y = 1, 8 do\n        if aura_env.config.markers[\"markersGroup\"..i..\"-\"..y] then\n            aura_env[\"chosenMarkers\"..i][y] = true\n        end\n    end\nend\n\n-- Populate the markers order list\nfor i = 1, 8 do\n    aura_env.markersOrder[i] = aura_env.config.markers[\"markersOrder\"..i]\nend\n\n-- Checks if unit is marked and adds it to the used markers table if so\nlocal function AddMarkedUnitToUsedMarkers(unit)\n    if (GetRaidTargetIndex(unit)) then\n        aura_env.usedMarkers[GetRaidTargetIndex(unit)] = true\n    end\nend\n\n-- Populate the enemies list\nfunction aura_env.UpdateTables()\n    aura_env.enemies = {}\n    local instanceId, _ = select(8,GetInstanceInfo())\n    if aura_env.config[\"IID\" .. instanceId] then\n        for _, v in ipairs(aura_env.config[\"IID\" .. instanceId]) do\n            if v.shouldMark then\n                if v.npcId == \"134024\" then -- if it's a Devouring Maggot\n                    aura_env.enemies[v.npcId] = {debuff = 278431, group = tonumber(v.enemyGroup)}\n                else\n                    aura_env.enemies[v.npcId] = {debuff = 0, group = tonumber(v.enemyGroup)}\n                end\n            end\n        end\n    end\nend\n\n-- Check if you or any party member is in combat with the mob\nfunction aura_env.UnitIsInCombatWithParty(unit)\n    for partyMember in WA_IterateGroupMembers(false, true) do\n        if UnitThreatSituation(partyMember, unit) then\n            return true\n        end\n    end\n    return false\nend\n\n-- Return true if correct modifier for mouseover marking is pressed\n-- 1 = None\n-- 2 = Shift\n-- 3 = Ctrl\n-- 4 = Alt\nfunction aura_env.CheckMouseoverModifier()\n    local key = aura_env.config.mouseoverSettings.mouseoverKey\n    if key == 1 then\n        return true\n    elseif key == 2 and IsShiftKeyDown() then\n        return true\n    elseif key == 3 and IsControlKeyDown() then\n        return true\n    elseif key == 4 and IsAltKeyDown() then\n        return true\n    else\n        return false\n    end\nend\n\n-- Add enemy to the marking list if it should be marked\nfunction aura_env.SelectEnemyToMark(unit)\n    local npcId, _ = select(6, strsplit(\"-\", UnitGUID(unit)))\n    \n    if aura_env.enemies[npcId] then\n        local group = aura_env.enemies[npcId].group\n        local debuff = aura_env.enemies[npcId].debuff\n        \n        if debuff ~= 0 then \n            if WA_GetUnitBuff(unit, debuff) then\n                table.insert(aura_env[\"enemiesToMark\"..group], unit)\n            end\n        else \n            table.insert(aura_env[\"enemiesToMark\"..group], unit)\n        end \n    end\nend\n\n-- Iterate through table of enemies and put first free chosen marker on them\nfunction aura_env.MarkEnemies(chosenMarkers, enemiesToMark, startValueDiff)\n    local startValue = 1 + startValueDiff\n    local endValue = 8\n    local stepValue = 1\n    \n    for i = 1, #enemiesToMark do\n        \n        for j = startValue, endValue, stepValue do\n            if aura_env.usedMarkers[aura_env.markersOrder[j]] == false and\n            chosenMarkers[aura_env.markersOrder[j]] == true and\n            not GetRaidTargetIndex(enemiesToMark[i]) then\n                SetRaidTarget(enemiesToMark[i], aura_env.markersOrder[j])\n                aura_env.usedMarkers[aura_env.markersOrder[j]] = true\n                break\n            end\n        end\n    end\nend\n\n-- Checks player, party, boss and nameplates for used markers\nfunction aura_env.GetUsedMarkers()\n    -- Sets all markers as unused\n    for i = 1, 8 do\n        aura_env.usedMarkers[i] = false\n    end\n    \n    -- Don't use marks already used on party1-4 or player\n    for partyMember in WA_IterateGroupMembers(false, true) do\n        AddMarkedUnitToUsedMarkers(partyMember)\n    end\n    \n    -- Don't use marks already used on boss1-4\n    for i = 1, 4 do\n        AddMarkedUnitToUsedMarkers(\"boss\"..i)\n    end\n    \n    -- Don't use marks already used on nameplates\n    for i = 1, 40 do\n        AddMarkedUnitToUsedMarkers(\"nameplate\"..i)\n    end\nend\n\n-- Create tables for used markers and enemies to mark\nfunction aura_env.SetupTables()\n    aura_env.usedMarkers = {}\n    \n    aura_env.enemiesToMark1 = {}\n    aura_env.enemiesToMark2 = {}\n    aura_env.enemiesToMark3 = {}\n    aura_env.enemiesToMark4 = {}\n    aura_env.enemiesToMark5 = {}\n    aura_env.enemiesToMark6 = {}\n    aura_env.enemiesToMark7 = {}\n    aura_env.enemiesToMark8 = {}\n    aura_env.enemiesToMark9 = {}\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["use_genericShowOn"] = true,
["genericShowOn"] = "showOnCooldown",
["subeventPrefix"] = "",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["names"] = {
},
["unevent"] = "auto",
["duration"] = "1",
["subeventSuffix"] = "",
["event"] = "Cooldown Progress (Spell)",
["spellIds"] = {
},
["realSpellName"] = 0,
["use_spellName"] = true,
["custom"] = "function()\n    aura_env.time = aura_env.time or 0\n    if GetTime() >= aura_env.time+0.3 then\n        aura_env.time = GetTime()\n        if not aura_env.enemies then return end\n        \n        -- Trigger the mouseover event on the modifier\n        if aura_env.config.mouseoverSettings.mouseoverKey ~= 1 and aura_env.CheckMouseoverModifier() then\n            WeakAuras.ScanEvents(\"AUTOMARKER_UPDATE_MOUSEOVER\")\n        end\n        \n        aura_env.SetupTables()\n        aura_env.GetUsedMarkers()\n        \n        for i = 1, 40 do\n            local unit = \"nameplate\"..i\n            \n            local npcId, _ = select(6, strsplit(\"-\", UnitGUID(unit) or \"\"))\n            \n            -- Don't check for combat on Afflicted Soul or Incorporeal Being or Afflicted Soul\n            if npcId == \"204560\" or npcId == \"204773\" then\n                aura_env.SelectEnemyToMark(unit)\n            elseif aura_env.UnitIsInCombatWithParty(unit) then\n                aura_env.SelectEnemyToMark(unit)\n            end\n        end\n        \n        -- Mark enemies\n        for i = 1, 9 do\n            if aura_env[\"enemiesToMark\" .. i] then\n                aura_env.MarkEnemies(aura_env[\"chosenMarkers\" .. i], aura_env[\"enemiesToMark\" .. i], 0)\n            end\n        end\n    end\nend",
