{
["trigger"] = {
["use_alwaystrue"] = true,
["duration"] = "5",
["genericShowOn"] = "showOnCooldown",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom_hide"] = "timed",
["instance_size"] = {
