["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'UnstableSha'\n\nlocal name, icon = C_Spell.GetSpellName(122953), C_Spell.GetSpellTexture(122938)\n\nlocal options = {warningText = \"%icon @cffffff80%name@r %icon\"}\n\naura_env.SendWarning = function()\n    local data = {ID = ID, name = name, icon = icon}\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 122953 and not aura_env.IsSpam(3) then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(18)\n        end\n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID = ...\n        \n        if phaseID == 'NightPhase' then\n            aura_env.StopCD()\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.count = 0\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
["spellIds"] = {
