["[DP] [Shek'zeer] Dissonance Field"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'DissonanceField'\n\nlocal GetSpellInfoTable = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\nlocal data = {\n    ['DissonanceField']     = GetSpellInfoTable(128353),\n    ['CorruptedDissonance'] = GetSpellInfoTable(126122),\n}\n\nlocal options = {\n    ['DissonanceField'] = {\n        warningText = \"%icon @cffff8b17%name@r (%count) %icon\",\n        \n    },\n    ['CorruptedDissonance'] = {\n        warningText = \"%icon @cffff8b17%name@r (%count) %icon\",\n    }\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = data[ID].name,\n            icon           = data[ID].icon,\n            count          = aura_env.count,\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = data[ID].name,\n            icon  = data[ID].icon,\n            count = aura_env.count,\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 123255 and not aura_env.IsSpam(2) then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('DissonanceField')\n                if aura_env.count < 2 then\n                    aura_env.StartCD('DissonanceField', 65)\n                else\n                    aura_env.StopCD()\n                end\n                if aura_env.isHeroic then\n                    local seconds = aura_env.count == 1 and 10 or 20\n                    aura_env.StartCD('CorruptedDissonance', seconds, true)\n                end\n            end\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 then\n            aura_env.count = 0\n            aura_env.StartCD('DissonanceField', 20)\n        elseif phaseN == 2 or phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'SHEKZEER_RETREAT' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.count = 0\n        aura_env.StartCD('DissonanceField', 20.5)\n    end\nend",
