},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1407'\nlocal ID          = 'RageActivate'\n\nlocal name = Merfin.GetTitleEJ(5678)\nlocal icon = 463282\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r (%count) %icon\",\n    prewarnTTStext = Merfin:L(\"Prepare to Root\"),\n}\n\naura_env.StartCD = function(duration)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        name           = name,\n        icon           = icon,\n        count          = aura_env.count,\n        GUID           = GUID\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Schedule = function(seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('RAGE_SCHEDULED')\n    end)\nend\n\nlocal rageTimers = {\n    [0]  = 15.6,\n    [1]  = 33,\n    [2]  = 33,\n    [3]  = 33,\n    [4]  = 33,\n    [5]  = 33,\n    [6]  = 83,\n    [7]  = 33,\n    [8]  = 33,\n    [9]  = 83,\n    [10] = 33,\n    [11] = 33,\n    [12] = 83,\n}\n\naura_env.GetDuration = function()\n    return rageTimers[aura_env.count] or 33\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'ADD_ACTIVATION' then\n        local add = ...\n        \n        if add == 'RAGE' then\n            aura_env.StartCD(14)\n            aura_env.Schedule(14)\n        end\n        \n    elseif e == 'RAGE_SCHEDULED' then\n        aura_env.count = aura_env.count + 1\n        aura_env.SendWarning()\n        \n        local duration = aura_env.GetDuration()\n        aura_env.StartCD(duration)\n        aura_env.Schedule(duration)\n        \n        --[[C_Timer.After(6, function()\n                WeakAuras.ScanEvents('MERFIN_TTS', 'Control')\n        end)]]--\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        \n        if aura_env.scheduler then \n            aura_env.scheduler:Cancel() \n        end\n    end\nend",
