},
["custom"] = "function(a, e, unitId)\n    \n    if e == 'NAME_PLATE_UNIT_ADDED' then\n        local guid = UnitGUID(unitId)\n        local npcId = select(6, strsplit(\"-\", guid))\n        \n        if not aura_env.npcId[npcId] then\n            return\n        end\n        \n        local target = unitId .. 'target'\n        if not UnitExists(target) then\n            a[guid] = {\n                show = true,\n                changed = true,\n                unit = unitId,\n            }\n            return true\n        end\n        \n    elseif e == 'NAME_PLATE_UNIT_REMOVED' then\n        \n        local guid = UnitGUID(unitId)\n        if not a[guid] then\n            return\n        end\n        \n        a[guid] = {\n            show = false,\n            changed = true,\n        }\n        \n    elseif e == 'UNIT_THREAT_LIST_UPDATE' then\n        local guid = UnitGUID(unitId)\n        \n        if not a[guid] then\n            return\n        end\n        \n        local npcId = select(6, strsplit(\"-\", guid))\n        if not aura_env.npcId[npcId] then\n            return\n        end\n        \n        local target = unitId .. 'target'\n        if UnitExists(target) then\n            a[guid].show = false\n            a[guid].changed = true\n            return true\n        end\n    end\n    \nend",
