["永春-04-痛击/恐惧痛击（Merfin，依赖）"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["displayText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1431'\n\nlocal function GetSpellInfoTable(spellID)\n    return {\n        name = C_Spell.GetSpellName(spellID),\n        icon = C_Spell.GetSpellTexture(spellID)\n    }\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'DREAD_' .. aura_env.dreadMRTCounter\n    GMRT.F.Note_Timer(event)\nend\n\nlocal data = {\n    ['Trash'] = GetSpellInfoTable(131996),\n    ['DreadThrash'] = GetSpellInfoTable(132007)\n}\n\nlocal options = {\n    ['Trash'] = {warningText = '%icon @cffffff80%name@r %icon'},\n    ['DreadThrash'] = {warningText = '%icon @cffffff80%name@r %icon'},\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(ID, duration)\n    if ID == 'DreadThrash' then\n        aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    end\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = true,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            count = aura_env.count,\n            roleIcon = 'TANK',\n            ignorePrew = not aura_env.onPlatform\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID, GUID)\n    if GUID == WeakAuras.myGUID then return end\n    if aura_env.onPlatform then return end\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            count = aura_env.count\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["events"] = "ENCOUNTER_START, SHA_PHASE, CLEU:SPELL_AURA_APPLIED:SWING_DAMAGE:SWING_MISSED, LEAVE_PLATFORM, ENTER_PLATFORM",
["spellIds"] = {
},
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 131996 then -- Trash\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('Trash', destGUID)\n                \n                if aura_env.phase2 then\n                    if aura_env.count == 3 then\n                        aura_env.dreadMRTCounter = aura_env.dreadMRTCounter + 1\n                        aura_env.StartCD('DreadThrash', 9)\n                    else\n                        aura_env.StartCD('Trash', 9)\n                    end\n                else\n                    aura_env.StartCD('Trash', 9)\n                end\n                \n                -- Trash Hits\n                aura_env.hitsDuringThrash = 3\n                aura_env.hitsThrash = 3\n                WeakAuras.ScanEvents('THRASH_HITS', aura_env.hitsThrash)\n                \n                if aura_env.phase2 then\n                    -- Dread Hits\n                    aura_env.hitsDread = aura_env.hitsDread - 1\n                    WeakAuras.ScanEvents('DREAD_THRASH_HITS', aura_env.hitsDread)\n                end\n                \n            elseif spellID == 132007 then -- Dread Trash\n                aura_env.count = 0\n                aura_env.SendWarning('DreadThrash', destGUID)\n                aura_env.StartCD('Trash', 9)\n                \n                -- Dread Trash Hits\n                aura_env.hitsDuringThrash = 6\n                aura_env.hitsThrash = 3\n                aura_env.hitsDread = 4\n                WeakAuras.ScanEvents('THRASH_HITS', aura_env.hitsThrash)\n                WeakAuras.ScanEvents('DREAD_THRASH_HITS', aura_env.hitsDread)\n            end\n            \n        elseif subEvent == 'SWING_DAMAGE' or subEvent == 'SWING_MISSED' then\n            local npcID = Merfin.GetNPCIDFromGUID(sourceGUID)\n            if npcID ~= 60999 then return end\n            \n            -- Thrash\n            if aura_env.hitsDuringThrash == 0 then\n                aura_env.hitsThrash = aura_env.hitsThrash - 1\n                WeakAuras.ScanEvents('THRASH_HITS', aura_env.hitsThrash)\n                \n            elseif aura_env.hitsDuringThrash > 0 then\n                aura_env.hitsDuringThrash = aura_env.hitsDuringThrash - 1\n            end\n        end\n        \n    elseif e == 'LEAVE_PLATFORM' then\n        aura_env.onPlatform = false\n        \n    elseif e == 'ENTER_PLATFORM' then\n        aura_env.onPlatform = true\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase2 = true\n            aura_env.count = 0\n            aura_env.StopCD('Trash')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        \n        aura_env.hitsThrash = 3\n        aura_env.hitsDread = 4\n        aura_env.hitsDuringThrash = 4\n        aura_env.hitsDuringDread = 0\n        \n        aura_env.onPlatform = false\n        aura_env.phase2 = false\n        aura_env.count = 0\n        aura_env.dreadMRTCounter = 0\n    end\nend",
