["custom"] = "-- Author: 露露緹婭@Bilibili\nlocal e = aura_env\nif not _G[e.id..\"Button\"] then\n    local region = WeakAuras.GetRegion(e.id)\n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\")\n    e.btn:RegisterForClicks(\"LeftButtonUp\",\"LeftButtonDown\", \"RightButtonUp\", \"RightButtonDown\")\n    e.btn:SetAttribute(\"type1\",\"macro\")\n    e.btn:SetAttribute(\"type2\",\"macro\")\n    e.btn:SetAllPoints(region)\nend\n\nlocal btn = _G[e.id..\"Button\"]\nlocal itemID1 = e.config.ItemID1\nlocal itemID2 = e.config.ItemID2\nlocal itemName1 = GetItemInfo(itemID1)\nlocal itemName2 = GetItemInfo(itemID2)\nlocal color1 = e.config.ItemColor1\nlocal color2 = e.config.ItemColor2\n\nbtn:SetAttribute(\"macrotext1\",\"/use item:\"..itemID1)\nbtn:SetAttribute(\"macrotext2\",\"/use item:\"..itemID2)\nbtn:SetScript(\"OnEnter\", function(self)\n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\")\n        GameTooltip:SetText(\"|cffffffff露露的快捷按钮\\n左键：|r|cff\"..color1..itemName1..\"|r\")\nend)\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()",
},
