["[T11] Backend - Nefarian"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Nefarian)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Nefarian\n\nlocal ENTRY = aura_env\nlocal encounterId = 1026\n\nlocal localized = {\n    ['enUS'] = {\n        NefAoe =           \"The air crackles with electricity!\",\n        YellPhase2 =       \"Curse you, mortals! Such a callous disregard for one's possessions must be met with extreme force!\",\n        YellPhase3 =       \"I have tried to be an accommodating host, but you simply will not die! Time to throw all pretense aside and just... KILL YOU ALL!\",\n        YellShadowBlaze =  \"Flesh turns to ash!\",\n        ShadowBlazeExact = \"Shadowblaze Spark in %ds\",\n    },\n    \n    ['ruRU'] = {\n        NefAoe =           \"В воздухе трещат электрические разряды!\",\n        YellPhase2 =       \"Дерзкие смертные! Неуважение к чужой собственности нужно пресекать самым жестоким образом!\",\n        YellPhase3 =       \"Я пытался следовать законам гостеприимства, но вы всё никак не умрете!\",\n        YellShadowBlaze =  \"И плоть превратится в прах!\",\n        ShadowBlazeExact = \"Вспышка пламени тени через %d\",\n    },\n    \n    ['koKR'] = {\n        NefAoe      = \"전기가 튀며 파지직하는 소리가 납니다!\",\n        YellPhase2 = \"저주받을 필멸자들! 내 소중한 작품을 이렇게 망치다니! 쓴맛을 봐야 정신을 차리겠군!\",\n        YellPhase3 = \"품위있는 집주인답게 행동하려 했건만, 네놈들이 도무지 죽질 않는군! 겉치레는 이제 집어치우자고. 그냥 모두 없애 버리겠어!\",\n        YellShadowBlaze = \"살을 재로 만들어 주마!\",\n        ShadowBlazeExact = \"%d초 후 암흑불꽃!\",\n    },\n    \n    ['zhCN'] = {\n        NefAoe      = \"空气中激荡的电流噼啪作响！\",\n        YellPhase2 = \"诅咒你们，凡人！你们丝毫不尊重他人财产的行为必须受到严厉处罚！\",\n        YellPhase3 = \"我一直在尝试扮演好客的主人，可你们就是不肯受死！该卸下伪装了……杀光你们！\",\n        YellShadowBlaze = \"血肉化为灰烬！\",\n        ShadowBlazeExact = \"%d秒后暗影爆燃火花\"\n    },\n    \n    ['zhTW'] = {\n        NefAoe      = \"響起了電流霹啪作響的聲音!\",\n        YellPhase2 = \"詛咒你們，凡人!如此冷酷地漠視他人的所有物必須受到嚴厲的懲罰!\",\n        YellPhase3 = \"我本來只想略盡地主之誼，但是你們就是不肯痛快的受死!是時候拋下一切的虛偽...殺光你們就好!\",\n        YellShadowBlaze = \"化為灰燼吧!\",\n        ShadowBlazeExact = \"暗影炎%d秒\",\n    },\n    \n    ['frFR'] = {\n        NefAoe       = \"L'air craque sous l'électricité !\",\n        YellPhase2 = \"Soyez maudits, mortels! Un tel mépris pour les possessions d'autrui doit être traité avec une extrême fermeté!\", -- à vérifier\n        YellPhase3 = \"J'ai tout fait pour être un hôte accomodant, mais vous ne daignez pas mourir! Oublions les bonnes manières et passons aux choses sérieuses... VOUS TUER TOUS!\",\n        YellShadowBlaze = \"!UNKNOWN!\",\n        ShadowBlazeExact = \"Shadowblaze in %ds\"\n    },\n    \n    ['deDE'] = {\n        NefAoe      = \"Elektrizität lässt die Luft knistern!\",\n        YellPhase2 = \"Verfluchte Sterbliche! Ein solcher Umgang mit dem Eigentum anderer verlangt nach Gewalt!\",\n        YellPhase3 = \"Ich habe versucht, ein guter Gastgeber zu sein, aber ihr wollt einfach nicht sterben! Genug der Spielchen! Ich werde euch einfach... ALLE TÖTEN!\",\n        YellShadowBlaze = \"Fleisch wird zu Asche!\",\n        ShadowBlazeExact = \"Schattensengen in %ds\"\n    },\n    \n    ['esES'] = {\n        NefAoe      = \"¡El aire crepita cargado de electricidad!\",\n        YellPhase2 = \"¡Os maldigo, mortales! ¡Ese cruel menosprecio por las posesiones de uno debe ser castigado con fuerza extrema!\",\n        YellPhase3 = \"He intentado ser un buen anfitrión, pero ¡no morís! Es hora de dejarnos de tonterías y simplemente... ¡MATAROS A TODOS!\",\n        YellShadowBlaze = \"¡Carne a ceniza!\",\n        ShadowBlazeExact = \"Chispa de llamarada de las Sombras en %d s\"\n    },\n    \n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    discharge =              { 77939 },\n    tail_lash =              { 77827 },\n    shadowflame_breath =     { 77826 },\n    shadowflame_barrage =    { 78621 },\n    explosive_cinders =      { 79339 },\n    dominion =               { 79318 },\n    shadowblaze_spark =      { 81031 },\n    shadowblaze =            { 81007 },\n    electrocute =            { 81198 },\n    blast_nova =             { 80734 },\n    stolen_power =           { 80627 },\n    nefarian_landing =       { false, 134154 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\nlocal Schedule = function(after, func, mechanic, ...) CORE.Schedule(ENTRY, mechanic, after, func, ...) end\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal cinderTargets = {}\nlocal dominionTargets = {}\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\n    \nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,interruptId, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    args.interruptId = interruptId\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal NEFARIAN = 41376\nlocal ONYXIA =  41270\n\nlocal shadowblazeTimer = 35\nlocal lastBlaze = 0\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    shadowblazeTimer = 35\n    cinderTargets = {}\n    dominionTargets = {}\n    CORE.SetStage(ENTRY, 1)\n    Timer('nefarian_landing', 30-delay)\n    Cooldown('discharge', 30-delay)\n    --Cooldown('tail_lash', 15, 'Onyxia')\n    --Cooldown('shadowflame_breath', 15, 'Onyxia')\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('berserk', 630-delay)\n        Cooldown('dominion', 45-delay); PreWarning('dominion', 40-delay)\n    end\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 77826 then\n        Warning('shadowflame_breath', args.sourceName)\n        Cooldown('shadowflame_breath', 12, args.sourceName)\n    end\nend\n\nENTRY['SPELL_INTERRUPT'] = function(args)\n    if args.interruptId == 80734 then\n        -- Blast Nova (P2 Mobs Casts)\n        WeakAuras.ScanEvents('BLAST_NOVA', args.destGUID)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 77827 then\n        Warning('tail_lash', args.sourceName)\n        Cooldown('tail_lash', 10, args.sourceName)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 79339 then\n        cinderTargets[#cinderTargets + 1] = args.destName\n        if CORE.IsPlayer(args) then\n            SpecialWarning('explosive_cinders')\n        end\n        if (IsDifficulty('25_HEROIC') and #cinderTargets >= 3) or (IsDifficulty('10_HEROIC') and #cinderTargets >= 1) then\n            WarningMultiply('explosive_cinders', cinderTargets)\n            cinderTargets = {}\n        else\n            CORE.Schedule(ENTRY, 'explosive_cinders', 0.3, WarningMultiply, 'explosive_cinders', cinderTargets)\n            cinderTargets = {}\n        end\n        Cooldown('explosive_cinders', 22); PreWarning('explosive_cinders', 17)\n    elseif args.spellId == 79318 then\n        if AntiSpam('dominion', 3) then\n            Cooldown('dominion', 15); PreWarning('dominion', 10)\n        end\n        dominionTargets[#dominionTargets + 1] = args.destName\n        if CORE.IsPlayer(args) then\n            SpecialWarning('dominion')\n        end\n        if (IsDifficulty('25_HEROIC') and #dominionTargets >= 5) or (IsDifficulty('10_HEROIC') and #dominionTargets >= 2) then\n            WarningMultiply('dominion', dominionTargets)\n            dominionTargets = {}\n        else\n            CORE.Schedule(ENTRY, 'dominion', 0.3, WarningMultiply, 'dominion', dominionTargets)\n            dominionTargets = {}\n        end\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED_DOSE'] = function(args)\n    --if args.spellId == 80627 \nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    \nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 81007 and CORE.IsPlayer(args) and AntiSpam('shadowblaze', 3) then\n        GTFO('shadowblaze')\n    elseif args.spellId == 77939 and AntiSpam('discharge', 10) then\n        Cooldown('discharge', 21)\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nlocal Phase2 = function()\n    CORE.SetStage(ENTRY, 2)\n    Phase('phase_2')\n    Cancel('tail_lash', 'COOLDOWN')\n    Cancel('shadowflame_breath', 'COOLDOWN')\n    Cancel('dominion', 'COOLDOWN'); Cancel('dominion', 'PRE_WARNING')\n    Cancel('discharge', 'COOLDOWN')\n    --Timer('shadowflame_barrage', 150)\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('explosive_cinders', 11.5); PreWarning('explosive_cinders', 6.5)\n    end\nend\n\nENTRY.ShadowBlazeFunction = function()\n    lastBlaze = GetTime()\n    if shadowblazeTimer > 15 then\n        shadowblazeTimer = shadowblazeTimer - 5\n    elseif shadowblazeTimer > 10 and IsDifficulty('10_HEROIC', '25_HEROIC') then\n        shadowblazeTimer = shadowblazeTimer - 5\n    end\n    Cooldown('shadowblaze_spark', shadowblazeTimer); PreWarning('shadowblaze_spark', shadowblazeTimer-5)\n    Schedule(shadowblazeTimer, ENTRY.ShadowBlazeFunction, 'ShadowBlazeFunction')\nend\n\nlocal Phase3 = function()\n    CORE.SetStage(ENTRY, 3)\n    Phase('phase_3')\n    Cancel('explosive_cinders', 'COOLDOWN')\n    Cancel('shadowflame_barrage', 'COOLDOWN')\n    Cooldown('shadowblaze_spark', 12); PreWarning('shadowblaze_spark', 7)\n    Schedule(12, ENTRY.ShadowBlazeFunction, 'ShadowBlazeFunction')\n    Cooldown('dominion', 10); PreWarning('dominion', 5)\nend  \n\nENTRY['CHAT_MSG_MONSTER_YELL'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if msg == L.YellPhase2 or msg:find(L.YellPhase2) then\n        Phase2()\n    elseif msg == L.YellPhase3 or msg:find(L.YellPhase3) then\n        Phase3()\n    elseif msg == L.YellShadowBlaze or msg:find(L.YellShadowBlaze) then\n        SpecialWarning('shadowblaze_spark')\n        Cancel('shadowblaze_spark', 'COOLDOWN')\n        if GetTime() - lastBlaze <= 3 then\n            Cooldown('shadowblaze_spark', shadowblazeTimer); PreWarning('shadowblaze_spark', shadowblazeTimer-5)\n            Schedule(shadowblazeTimer, ENTRY.ShadowBlazeFunction, 'ShadowBlazeFunction')\n        elseif GetTime() - lastBlaze >= 6 then\n            ENTRY.ShadowBlazeFunction()\n        end\n    end\nend \n\nENTRY['RAID_BOSS_EMOTE'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if L.NefAoe and (msg == L.NefAoe or msg:find(L.NefAoe)) then\n        Timer('electrocute', 5)\n    end\nend \n\n",
