["init"] = {
["custom"] = "local encounterID = '1409'\n\naura_env.MRT = function(event) GMRT.F.Note_Timer(event) end\n\nlocal phaseNames = {\n    ['Phase1'] = Merfin:L('Phase 1'),\n    ['Phase2'] = Merfin:L('Phase 2'),\n    ['Phase3'] = Merfin:L('Phase 3')\n}\n\nlocal options = {\n    ['Phase1'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase1']:upper()),\n        ttsLine = phaseNames['Phase1'],\n    },\n    ['Phase2'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase2']:upper()),\n        ttsLine = phaseNames['Phase2'],\n    },\n    ['Phase3'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase3']:upper()),\n        ttsLine = phaseNames['Phase3'],\n    }\n}\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID,\n        {ID = ID, name = phaseNames[ID]}, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
