["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if spellID ~= 117052 then return end\n        local npcID = Merfin.GetNPCIDFromGUID(destGUID)\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            WeakAuras.ScanEvents('PROTECTORS_PHASE_CHANGING', npcID, 2)\n            \n            if not aura_env.IsSpam(5) then\n                aura_env.SendWarning('Phase2')\n                aura_env.MRT('PHASE_2')\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            WeakAuras.ScanEvents('PROTECTORS_PHASE_CHANGING', npcID, 3)\n            \n            if not aura_env.IsSpam(5) then\n                aura_env.SendWarning('Phase3')\n                aura_env.MRT('PHASE_3')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.phase = 1\n    end\nend",
