["init"] = {
["custom"] = "local encounterID = '1431'\n\nlocal function GetSpellInfoTable(spellID)\n    return {\n        name = C_Spell.GetSpellName(spellID),\n        icon = C_Spell.GetSpellTexture(spellID)\n    }\nend\n\nlocal data = {\n    ['Submerge'] = GetSpellInfoTable(120455),\n    ['Emerge'] = GetSpellInfoTable(120458)\n}\n\nlocal options = {\n    ['Submerge'] = {\n        warningText = Merfin:L('Run Out'):upper(), \n        prewarnCountVA = 2,\n        prewarnTTStext = Merfin:L('Stack')\n    },\n    ['Emerge'] = {\n        warningText = Merfin:L('Stack'):upper(), \n        ttsLine = Merfin:L('Stack'),\n    },\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            count = aura_env.count\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            count = aura_env.count\n        }, options[ID])\nend",
["do_custom"] = true,
},
