["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 120458 then\n                WeakAuras.ScanEvents('EMERGE')\n                WeakAuras.ScanEvents('MERFIN_TTS', Merfin:L('Stack'))\n                \n            elseif spellID == 120455 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('Submerge')\n                aura_env.StartCD('Submerge', 57)\n            end\n        end\n        \n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        if spellID == 62535 and aura_env.phase2 then\n            C_Timer.After(1, function()\n                    local delay = 1\n                    local duration = (1 - UnitPower(\"boss1\") / UnitPowerMax(\"boss1\")) * 47\n                    aura_env.StartCD('Submerge', duration-delay)\n            end)\n        end\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase2 = true\n            aura_env.count = 0\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.phase2 = false\n        aura_env.count = 0\n    end\n    \nend",
