["[DP] [MP] 国王试炼"] = {
["outline"] = "OUTLINE",
["wagoID"] = "1QYhYwGhZ",
["parent"] = "[MerfinDung] 依赖项",
["displayText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\n\nlocal L = GetLocale()\n\nlocal encounterID = '1442'\n\nlocal BuildSpellData = function(id, role)\n    return { \n        name = C_Spell.GetSpellName(id), \n        icon = C_Spell.GetSpellTexture(id),\n        roleIcon = role,\n    }\nend\nlocal cooldownData = {\n    -- Kuai the Brute\n    ['Shockwave'] = BuildSpellData(119922),\n    ['Ravage'] = BuildSpellData(119946, 'HEALER'),\n    -- Ming the Cunning\n    ['WhirlingDervish'] = BuildSpellData(119981),\n    ['MagneticField'] = BuildSpellData(120100),\n    -- Haiyan the Unstoppable\n    ['Conflagrate'] = BuildSpellData(120160),\n    ['Meteor'] = BuildSpellData(120195),\n    ['TraumaticBlow'] = BuildSpellData(123655, 'HEALER'),\n}\n\nlocal warningSounds = {\n    ['Shockwave'] = 'specialAlert1',\n    ['Ravage'] = 'minorAlert1',\n    ['RavageOnYou'] = 'importantMechanic',\n    ['WhirlingDervish'] = 'minorAlert1',\n    ['MagneticField'] = 'minorAlert2',\n    ['Conflagrate'] = 'minorAlert1',\n    ['Meteor'] = 'minorAlert2',\n    ['MeteorOnYou'] = 'importantMechanic',\n    ['TraumaticBlow'] = 'minorAlert1',\n    ['TraumaticBlowYou'] = 'minorMechanic',\n    ['DogDied'] = 'minorAlert1',\n}\n\nlocal CREATURE_ID = { \n    KUAI = 61442,\n    MING = 61444,\n    HAIYAN = 61445,\n    MUSHIBA = 61453,\n}\n\nlocal PRE_WARNING = {\n    ['Shockwave'] = true,\n    ['Meteor'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then return 0 end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then  return false end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.Antispam = function(id, before)\n    local cur = GetTime()\n    if not aura_env.antispams[id] \n    or cur - aura_env.antispams[id] > before then\n        aura_env.antispams[id] = cur\n        return true\n    end\n    return false\nend\n\naura_env.WipeSchedulers = function()\n    if not aura_env.schedulers then return end\n    for schedulerName, scheduler in pairs(aura_env.schedulers) do\n        WeakAuras.timer:CancelTimer(scheduler)\n    end\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    \n    aura_env.WipeSchedulers()\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    aura_env.antispams = {}\nend\n\naura_env.ScheduleEvent = function(id, after, ...)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_DUNGEON_SCHEDULED',\n        id,\n        ...\n    )\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_BOSS_PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_BOSS_PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_BOSS_PRE_WARNING', 'HIDE', id)\n    end\n    \n    local data = cooldownData[id]\n    if not data then return end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\nend\n\naura_env.StartCD = function(id, duration, isIncrease, autoHide, GUID)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    aura_env.predict[id] = duration + GetTime()\n    \n    if PRE_WARNING[id] then aura_env.SchedulePrewarning(id, duration) end\n    \n    local data = cooldownData[id]\n    if not data then return end\n    \n    local cooldown  = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        name = data.name,\n        id = id,\n        GUID = GUID,\n        icon = data.icon,\n        count = count,\n        roleIcon = data.roleIcon,\n        special = data.special,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldown)\nend\n\naura_env.Warning = function(warning, ...)\n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_WARNING', warning, ...)\n    local sound = warningSounds[warning]\n    if sound then aura_env.PlaySound(sound) end\nend\n\naura_env.TTS = function(text, voiceID)\n    local voiceID = voiceID or 2\n    WeakAuras.ScanEvents('WA_MERFIN_DUNGEON_TTS', text, voiceID)\nend\n\naura_env.PlaySound = function(...)\n    WeakAuras.ScanEvents('WA_MERFIN_DUNGEON_SOUND', ...)\nend\n\naura_env.Chat = function(text, chatType)\n    WeakAuras.ScanEvents('WA_MERFIN_DUNGEON_CHAT', text, chatType)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 119922 then\n                local count = aura_env.ManageCounter('increase', 'Shockwave')\n                aura_env.Warning('Shockwave', count)\n                aura_env.StartCD('Shockwave', 10.9)\n                aura_env.TTS('Frontal')\n            elseif spellID == 119981 then\n                local count = aura_env.ManageCounter('increase', 'WhirlingDervish')\n                aura_env.Warning('WhirlingDervish', count)\n                aura_env.StartCD('WhirlingDervish', 21.9)\n                aura_env.TTS('Dodge Wind')\n            elseif spellID == 120100 then\n                local count = aura_env.ManageCounter('increase', 'MagneticField')\n                aura_env.Warning('MagneticField', count)\n                aura_env.StartCD('MagneticField', 42.6)\n            elseif spellID == 120160 then\n                local count = aura_env.ManageCounter('increase', 'Conflagrate')\n                aura_env.Warning('Conflagrate', count)\n                aura_env.StartCD('Conflagrate', 20.6)\n            elseif spellID == 123654 then\n                local count = aura_env.ManageCounter('increase', 'LightningBolt')\n                aura_env.Warning('LightningBolt', count)\n                --aura_env.TTS('Interrupt')\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 119946 then\n                local count = aura_env.ManageCounter('increase', 'Ravage')\n                aura_env.StartCD('Ravage', 10.9)\n                if destName == WeakAuras.me then\n                    aura_env.Warning('RavageOnYou')\n                else\n                    aura_env.Warning('Ravage', destName)\n                end\n            elseif spellID == 123655 then\n                local count = aura_env.ManageCounter('increase', 'TraumaticBlow')\n                aura_env.StartCD('TraumaticBlow', 15.8)\n                if destName == WeakAuras.me then\n                    aura_env.Warning('TraumaticBlowYou')\n                else\n                    aura_env.Warning('TraumaticBlow', destName)\n                end\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'MUSHIBA') then\n                aura_env.Warning('DogDied')\n                aura_env.StopCD('Ravage')\n            end\n        end\n        \n    elseif e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        if msg:find(\"meteorstorm\", nil, true) then\n            aura_env.StartCD('Meteor', 43.6, true)\n            local targetUnit = sourceName\n            local targetName = UnitName(targetUnit)\n            if targetName == WeakAuras.me then\n                aura_env.Warning('MeteorOnYou')\n                aura_env.TTS('Run Out')\n                aura_env.Chat('{rt2} Meteor on ' .. WeakAuras.me .. ' {rt2}')\n            else\n                aura_env.Warning('Meteor', targetName)\n            end\n        end\n        \n    elseif e == 'INSTANCE_ENCOUNTER_ENGAGE_UNIT' then\n        local bossGUID = UnitGUID('boss1')\n        \n        aura_env.bossEngaged = aura_env.bossEngaged or 0\n        \n        if aura_env.IsGUID(bossGUID, 'KUAI') then\n            aura_env.bossEngaged = aura_env.bossEngaged + 1\n            aura_env.Warning('Phase', aura_env.bossEngaged)\n            aura_env.StartCD('Shockwave', 15.8)\n            aura_env.StartCD('Ravage', 18.6)\n            \n        elseif aura_env.IsGUID(bossGUID, 'MING') then\n            aura_env.bossEngaged = aura_env.bossEngaged + 1\n            aura_env.Warning('Phase', aura_env.bossEngaged)\n            aura_env.StartCD('WhirlingDervish', 22.7)\n            aura_env.StartCD('MagneticField', 40.9)\n            \n        elseif aura_env.IsGUID(bossGUID, 'HAIYAN') then\n            aura_env.bossEngaged = aura_env.bossEngaged + 1\n            aura_env.Warning('Phase', aura_env.bossEngaged)\n            aura_env.StartCD('Conflagrate', 21.0)\n            aura_env.StartCD('Meteor', 40.6)\n            aura_env.StartCD('TraumaticBlow', 7.6)\n        else\n            aura_env.StopCD('Shockwave')\n            aura_env.StopCD('Ravage')\n            aura_env.StopCD('WhirlingDervish')\n            aura_env.StopCD('MagneticField')\n            aura_env.StopCD('Conflagrate')\n            aura_env.StopCD('Meteor')\n            aura_env.StopCD('TraumaticBlow')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
