},
["custom"] = "function(a, e,_, subEvent, _, sourceGUID, sourceName, _,_, destGUID, destName,_,_, ...)\n    if e == 'OPTIONS' then\n        a[''] = {\n            show = true,\n            changed = true,\n            progressType = 'static',\n            value = aura_env.total/2,\n            total = aura_env.total,\n        }\n        return true\n    elseif subEvent == 'SPELL_AURA_APPLIED' then\n        local spellId = ...\n        if spellId == 93059 then\n            a[''] = {\n                show = true,\n                changed = true,\n                progressType = 'static',\n                value = aura_env.total,\n                total = aura_env.total,\n            }\n            return true\n        end\n    elseif subEvent == 'SPELL_AURA_REMOVED' then\n        local spellId = ...\n        if spellId == 93059 and a[''] then\n            a[''].show = false\n            a[''].changed = true\n            return true\n        end\n    elseif subEvent == 'SPELL_ABSORBED' then\n        local _,_,_,_,_,_,_, shieldId,_,_, amount = ...\n        -- if spell\n        if amount and shieldId == 93059 then\n            a[''].value = a[''].value - amount\n            a[''].changed = true\n            return true\n        else\n            -- is melee\n            local _,_,_,_, shielId,_,_, amount = ...\n            if shielId == 93059 then\n                a[''].value = a[''].value - (amount or 0)\n                a[''].changed = true\n                return true\n            end\n        end\n    end\nend",
