["dynamicDuration"] = false,
["check"] = "event",
["custom"] = "function(states, e, msg)\n    if e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        if aura_env.IsEmote(msg, 'Arrival') then\n            Merfin.LeiShiArrivalTime = GetTime() + 31\n            states:Update('', { \n                    progressType = 'timed', \n                    duration = 31, \n                    expirationTime = 31 + GetTime(), \n                    autoHide = true\n            })\n        end\n    elseif e == 'STATUS' and Merfin.LeiShiArrivalTime then\n        local tilExpire = Merfin.LeiShiArrivalTime - GetTime()\n        if tilExpire > 0 then\n            states:Update('', { \n                    progressType = 'timed', \n                    duration = 31, \n                    expirationTime = Merfin.LeiShiArrivalTime, \n                    autoHide = true\n            })\n        end\n    end\nend",
