["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    myTarget = {\n        display = 'Is My Target',\n        type = 'bool',\n    },\n    \n    dispel = {\n        display = 'Is Dispellable',\n        type = 'bool',\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    if event == 'ENCOUNTER_START' then\n        aura_env.targets = {}\n        aura_env.index = nil\n        return\n    end\n    \n    if event == 'TSULONG_DISPEL_ORDER' then\n        local order = ...\n        aura_env.index = nil\n        for i, group in ipairs(order) do\n            for _, name in ipairs(group) do\n                if name == aura_env.myName then\n                    aura_env.index = i\n                    break\n                end\n            end\n            if aura_env.index then break end\n        end\n        return\n    end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, _, destName, _, _, spellID = ...\n        if spellID ~= 123011 then return end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            table.insert(aura_env.targets, destName)\n            \n            if not aura_env.scheduled then\n                aura_env.scheduled = true\n                C_Timer.After(0.3, function()\n                        for i, name in ipairs(aura_env.targets) do\n                            local isMyTarget = aura_env.index and aura_env.index == i\n                            states:Update(name, {\n                                    unit = name,\n                                    order = i,\n                                    myTarget = isMyTarget,\n                                    dispel = true\n                            })\n                        end\n                        aura_env.targets = {}\n                        aura_env.scheduled = false\n                end)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            states:Remove(destName)\n            return true\n        end\n    end\nend",
