["do_custom"] = true,
["custom"] = "-- Author: 露露緹婭@Bilibili\naura_env.RurutiaFilePath = \"Interface\\\\Addons\\\\SharedMedia_Rurutia\\\\Rurutia\\\\\"\n\naura_env.cooldownConfig = {\n    --[61295] = 10, --激流，测试用\n}\n\nif not aura_env.lastPlayTime then\n    aura_env.lastPlayTime = {}\nend\n\naura_env.RurutiaSoundMap = {\n    --魔古山宝库\n    [116990] = \"【露露】目标是你.ogg\", -- 专注打击\n    [116281] = \"【露露】定身.ogg\", -- 蓝晶冲击\n    [130774] = \"【露露】快躲开.ogg\", -- 紫晶之池\n    [116278] = \"【露露】打小怪.ogg\", --灵魂撕裂\n    [116161] = \"【露露】刷满血量.ogg\", --灵魂越界\n    \n    --BUFF\n    --[61295] = \"【露露】安全安全.ogg\", -- 激流，测试用\n    [116541] = \"【露露】获得增益.ogg\", -- 充能之瓦\n    [115911] = \"【露露】获得增益.ogg\", -- 反射罩\n    [115856] = \"【露露】安全安全.ogg\", -- 废灵壁垒\n    [117549] = \"【露露】获得增益.ogg\", -- 灵魂支配\n    [117543] = \"【露露】回蓝.ogg\", --灵魂支配\n    [132422] = \"【露露】Bingo.ogg\", --机不可失\n}",
