["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId, _, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellId == 106371 then\n                aura_env.StartCD('HourOfTwilight', 45.5, false, true)\n                \n                if aura_env.IsHeroic then\n                    aura_env.StartCD('FadingLight', 13)\n                    return\n                end\n                \n                aura_env.StartCD('FadingLight', 20)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellId == 105925 or spellId == 109075 then\n                \n                local curTime = GetTime()\n                if curTime - aura_env.lastFading > 5 then\n                    local duration = aura_env.IsHeroic and 10 or 15\n                    aura_env.StartCD('FadingLight', duration, false, true)\n                    aura_env.fadingNames = {}\n                    aura_env.ScheduleEvent('AnnounceTargetsFading', 0.3)\n                end\n                aura_env.lastFading = curTime\n                aura_env.fadingNames[#aura_env.fadingNames + 1] = WA_ClassColorName(destName)\n            end\n        end\n        \n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('HourOfTwilight', 45.5)\n        aura_env.StartCD('GiftOfLive', 80, true)\n        aura_env.StartCD('EssenceOfDream', 155, true)\n        aura_env.StartCD('SourceofMagic', 215, true)\n        aura_env.StartCD('Berserk', 360)\n        aura_env.ScheduleEvent('BERSERK_EMPHASIZED', 350)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
