["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal cooldownData = {\n    ['Berserk'] = { name = 'Berserk', icon = 136224 },\n    ['VoidBolt'] = { name = 'Void Bolt', icon = 237561, roleIcon = 'TANK' },\n    ['Oozes'] = { name = 'Oozes', icon = 132108 },\n    ['DigestiveAcid'] = { name = 'Digestive Acid', icon = 136016 },\n    ['SearingBlood'] = { name = 'Searing Blood', icon = 135809 },\n}\n\nlocal encounterID = '1295'\n\nlocal CREATURE_ID = {\n    YORSAHJ = 55312,\n    PURPLE  = 55863,\n    GREEN   = 55862,\n    YELLOW  = 55864,\n    BLACK   = 55867,\n    RED     = 55865,\n    BLUE    = 55866,\n}\n\nlocal PRE_WARNING = {\n    ['Oozes'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then\n        return 0\n    end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then \n        return false \n    end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.WipeSchedulers = function()\n    if aura_env.schedulers then \n        for schedulerName, scheduler in pairs(aura_env.schedulers) do\n            WeakAuras.timer:CancelTimer(scheduler)\n        end\n    end\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_T13',\n        'PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.ScheduleEvent = function(subEvent, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[subEvent] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        subEvent\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease, GUID)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    \n    aura_env.predict[id] = duration + GetTime()\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown  = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        name = data.name,\n        id = id,\n        GUID = GUID,\n        icon = data.icon,\n        count = count,\n        roleIcon = data.roleIcon,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldown)\n    \n    if not PRE_WARNING[id] then return end\n    \n    aura_env.SchedulePrewarning(id, duration)\nend\n\naura_env.IsCooldownReadyBefore = function(id, before)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (predictedAt - GetTime() > before)\nend\n\naura_env.IsCooldownReady = function(id)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (GetTime() > predictedAt)\nend\n\naura_env.Antispam = function(id, before)\n    local cur = GetTime()\n    if not aura_env.antispams[id] \n    or cur - aura_env.antispams[id] > before then\n        aura_env.antispams[id] = cur\n        return true\n    end\n    return false\nend\n\nlocal oozesPattern = {\n    heroic = {\n        [105420] = { 'PURPLE', 'GREEN', 'BLACK', 'BLUE' },\n        [105435] = { 'GREEN', 'RED', 'BLUE', 'BLACK' },\n        [105436] = { 'GREEN', 'YELLOW', 'BLACK', 'RED' },\n        [105437] = { 'BLUE', 'PURPLE', 'GREEN', 'YELLOW' },\n        [105439] = { 'BLUE', 'BLACK', 'PURPLE', 'YELLOW' },\n        [105440] = { 'PURPLE', 'RED', 'YELLOW', 'BLACK' },\n    },\n    normal = {\n        [105420] = { 'PURPLE', 'GREEN', 'BLUE' },\n        [105435] = { 'GREEN', 'RED', 'BLACK' },\n        [105436] = { 'GREEN', 'YELLOW', 'RED' },\n        [105437] = { 'PURPLE', 'BLUE', 'YELLOW' },\n        [105439] = { 'BLUE', 'BLACK', 'YELLOW' },\n        [105440] = { 'PURPLE', 'RED', 'BLACK' },\n    }\n}\n\naura_env.PatternPosition = {\n    [105420] = 1,\n    [105435] = 2,\n    [105436] = 3,\n    [105437] = 4,\n    [105439] = 5,\n    [105440] = 6,\n}\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    \n    aura_env.maxOozes = aura_env.IsHeroic and 4 or 3\n    aura_env.WipeSchedulers()\n    \n    aura_env.isYellowActive = false\n    -- I'm not sure how LFR is displayed\n    aura_env.pattern = oozesPattern[aura_env.IsHeroic and 'heroic' or 'normal']\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    aura_env.antispams = {}\nend\n\nlocal L = GetLocale()\n\nlocal replicas = {\n    [\"enUS\"] = \"UULL\",\n    [\"ruRU\"] = \"УУЛЛ лухук Х'ИУН!\",\n}\n\naura_env.sumForOne = replicas[L]",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_SUCCESS:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED:UNIT_DIED, UNIT_SPELLCAST_SUCCEEDED, WA_MERFIN_T13_SCHEDULED",
["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellId == 104849 then\n                aura_env.StartCD('VoidBolt', 6, false, true)\n            elseif spellId == 105573 then\n                local duration = aura_env.isYellowActive and 3.5 or 8.3\n                aura_env.StartCD('DigestiveAcid', duration, false, true)\n            elseif spellId == 105033 and aura_env.IsGUID(sourceGUID, 'YORSAHJ') then\n                local duration = aura_env.isYellowActive and 3.5 or 6\n                aura_env.StartCD('SearingBlood', duration, false, true)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellId == 104901 and aura_env.IsGUID(destGUID, 'YORSAHJ') then\n                aura_env.isYellowActive = true\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellId == 104901 and aura_env.IsGUID(destGUID, 'YORSAHJ') then\n                aura_env.isYellowActive = false\n            elseif spellId == 104897 and aura_env.IsGUID(destGUID, 'YORSAHJ') then\n                aura_env.StopCD('SearingBlood')\n            elseif spellId == 104898 and aura_env.IsGUID(destGUID, 'YORSAHJ') then\n                aura_env.StopCD('DigestiveAcid')\n            end\n            \n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'PURPLE') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'PURPLE', 'HIDE')\n            elseif aura_env.IsGUID(destGUID, 'GREEN') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'GREEN', 'HIDE')\n            elseif aura_env.IsGUID(destGUID, 'YELLOW') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'YELLOW', 'HIDE')\n            elseif aura_env.IsGUID(destGUID, 'BLACK') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'BLACK', 'HIDE')\n            elseif aura_env.IsGUID(destGUID, 'RED') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'RED', 'HIDE')\n            elseif aura_env.IsGUID(destGUID, 'BLUE') then\n                WeakAuras.ScanEvents('WA_OOZE_SPAWNING', 'BLUE', 'HIDE')\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if not aura_env.pattern[uSpellId] then\n            return\n        end\n        \n        if not aura_env.Antispam('lastOoze', 5) then\n            return\n        end\n        \n        aura_env.StopCD('SearingBlood')\n        aura_env.StopCD('DigestiveAcid')\n        \n        aura_env.StartCD('VoidBolt', 42)\n        \n        local duration = aura_env.IsHeroic and 75 or 90\n        WeakAuras.ScanEvents('WA_OOZE_PATTERN', aura_env.PatternPosition[uSpellId])\n        for _, color in pairs(aura_env.pattern[uSpellId]) do\n            WeakAuras.ScanEvents('WA_OOZE_SPAWNING', color, 'SHOW', duration)\n        end\n        \n        aura_env.StartCD('Oozes', duration, false, true)\n        \n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        \n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('VoidBolt', 6)\n        aura_env.StartCD('Oozes', 22)\n        aura_env.StartCD('Berserk', 600)\n        aura_env.ScheduleEvent('BERSERK_EMPHASIZED', 590)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
