["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'RainOfArrows'\n\nlocal options = {\n    ['RainOfArrows'] = {\n        warningText = \"@cffff4040%upper:name@r\",\n        prewarnCountVA = 1,\n        prewarnTTStext = Merfin:L(\"Spread Out\"),\n    },\n    ['PinnedArrows'] = {\n        warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    },\n}\n\nlocal name, icon = C_Spell.GetSpellName(118122), C_Spell.GetSpellTexture(118122)\n\naura_env.MRT = function()\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'RAIN_OF_ARROWS_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env.CancelMRT()\n    local after = duration <= 5 and duration or duration - 5\n    aura_env._mrtTimer = C_Timer.NewTimer(after, aura_env.MRT)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['RainOfArrows'])\nend\n\naura_env.SendWarning = function(ID)\n    local names = {}\n    for _, name in ipairs(aura_env.targets) do\n        table.insert(names, WA_ClassColorName(name))\n    end\n    \n    local data = { \n        ID       = ID, \n        count    = aura_env.count, \n        destName = table.concat(names, ', '),\n        name     = name,\n        icon     = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 118121 then\n            aura_env.count = aura_env.count + 1\n            local timer = (aura_env.isHeroic and 41 or 50.5)\n            aura_env.StartCD(timer)\n        end\n        \n    elseif e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local  _,_,_,_,_,_,_,_, destName, _, _, spellID = ...\n        \n        if spellID == 118135 then\n            if not aura_env.IsSpam(3) then\n                aura_env.targets = {}\n                \n                C_Timer.After(0.3, function()\n                        WeakAuras.ScanEvents('PINNED_TARGETS') \n                end)\n            end\n            \n            table.insert(aura_env.targets, destName)\n        end\n        \n    elseif e == 'PINNED_TARGETS' then\n        aura_env.SendWarning('PinnedArrows')\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'SUBETAI' then return end\n        \n        if activated then \n            local timer = (aura_env.isHeroic and 40 or 15) - delay\n            aura_env.StartCD(timer)\n        else\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.CancelMRT()\n    end\nend",
