["custom"] = "function(state, event, encounterId, subEvent,_,_,_,_,_,_,_,_,_, spellId)\n    \n    if event == 'OPTIONS' then\n        local duration = math.random(1, 30)\n        state[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            autoHide = false,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            count = math.random(1, 10),\n        }\n        return true\n    end\n    \n    if event == 'ENCOUNTER_START' then\n        aura_env.count = 1\n        state[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            autoHide = false,\n            duration = 12.1,\n            expirationTime = 12.1 + GetTime(),\n            count = aura_env.count,\n        }\n        return true\n    end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if spellId ~= 102582 then\n            return\n        end\n        \n        aura_env.count = aura_env.count + 1\n        state[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            autoHide = false,\n            duration = 15.8,\n            expirationTime = 15.8 + GetTime(),\n            count = aura_env.count,\n        }\n        return true\n    end\n    \nend",
