["custom"] = "local gossips = {\n    [35145] = true, -- TSK Role Play Panda\n    [41380] = true, -- Elegon: Start Gossip\n    [41013] = true, -- ToES: Start Role Play (1)\n    [41012] = true, -- ToES: Start Role Play (2)\n}\n\nfunction aura_env.AutoSelect()\n    if IsControlKeyDown() then return end\n    local gossipInfo = C_GossipInfo.GetOptions()\n    local id = gossipInfo[1] and gossipInfo[1].gossipOptionID\n    if id and gossips[id] then \n        C_GossipInfo.SelectOption(id)\n    end\nend",
