["[MerfinDung] 自动对话"] = {
["outline"] = "OUTLINE",
["wagoID"] = "1QYhYwGhZ",
["authorOptions"] = {
{
["subOptions"] = {
{
["type"] = "description",
["text"] = "Auto Gossips Options",
["fontSize"] = "large",
["width"] = 2,
},
{
["type"] = "toggle",
["default"] = true,
["desc"] = "Prioritizes the Yu'lon buff over all others when you talk to the ring NPC.",
["key"] = "yulon",
["useDesc"] = true,
["name"] = "Yu'lon Priority Pick",
["width"] = 1,
},
},
["hideReorder"] = true,
["useDesc"] = false,
["nameSource"] = 0,
["collapse"] = false,
["width"] = 1,
["useCollapse"] = false,
["noMerge"] = false,
["name"] = "Auto Gossips",
["key"] = "gossip",
["limitType"] = "none",
["groupType"] = "simple",
["type"] = "group",
["size"] = 10,
},
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["init"] = {
["do_custom_load"] = false,
["custom"] = "local cfg = aura_env.config.gossip\nlocal yulonPrio = cfg.yulon\nlocal _, myClass = UnitClass('player')\n\nlocal GetRole = function()\n    local _,role, roleType = WeakAuras.SpecRolePositionForUnit('player')\n    return role, roleType\nend\n\nlocal gossips = {\n    [34873]  = true, -- SoNT: Commander Vo'jak Start\n    \n    -- Blessings SINGLE (Celestial)\n    [134629] = true, -- Yu'lon\n    [134623] = true, -- Chi-Ji\n    [134627] = true, -- Xuen\n    [134628] = true, -- Niuzao\n}\n\nfunction aura_env.AutoSelect()\n    if IsControlKeyDown() then return end\n    local gossipInfo = C_GossipInfo.GetOptions()\n    \n    local role, position = GetRole()\n    \n    for _, gossip in ipairs(gossipInfo) do\n        local id = gossip and gossip.gossipOptionID\n        if id and gossips[id] then \n            C_GossipInfo.SelectOption(id)\n        elseif id == 134679 then -- Chi-Ji\n            if not yulonPrio and role == 'HEALER' then\n                C_GossipInfo.SelectOption(id)\n            end\n        elseif id == 134678 then -- Niuzao\n            if not yulonPrio and role == 'TANK' then\n                C_GossipInfo.SelectOption(id)\n            end\n        elseif id == 134677 then -- Xuen\n            if not yulonPrio and (position == 'MELEE' or myClass == 'HUNTER') then\n                C_GossipInfo.SelectOption(id)\n            end\n        elseif id == 134676 then -- Yu'lon (Casters)\n            if yulonPrio or position == 'RANGED' then\n                C_GossipInfo.SelectOption(id)\n            end\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
["message"] = "",
["do_message"] = false,
["message_type"] = "PRINT",
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
