},
["custom"] = "function(e, ...)\n    if e == \"GOSSIP_SHOW\" then\n        aura_env.AutoSelect()\n    elseif e == 'MODIFIER_STATE_CHANGED' then\n        local mod, state = ...\n        if mod == 'LCTRL' or mod == 'RCTRL' then\n            if state == 0 then\n                aura_env.AutoSelect()\n            end\n        end\n    end\nend",
