},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1504'\nlocal ID          = 'TempestSlash'\n\nlocal name, icon = C_Spell.GetSpellName(122853), C_Spell.GetSpellTexture(122853)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID, _, spellID = ...\n        \n        if spellID == 122839 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local seconds = aura_env.isLfr and 20 or 15.5\n            aura_env.StartCD(seconds)\n        end\n        \n    elseif e == 'PHASE_2' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isLfr = WeakAuras.InstanceDifficulty() == 'lfr'\n        aura_env.count = 0\n        aura_env.StartCD(10)\n    end\nend",
