["[DP] [Emperor] Energizing Smash"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1407'\nlocal ID          = 'EnergizingSmash'\n\nlocal name, icon = C_Spell.GetSpellName(116556), C_Spell.GetSpellTexture(116556)\n\nlocal options = {\n    warningText = \"%icon %name (%count) %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, GUID)\n    local data = {\n        show           = true,\n        autoHide       = false,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        GUID           = GUID,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.IsSpam = function(GUID, before)\n    if not GUID then return true end\n    \n    local cur = GetTime()\n    aura_env.antispams = aura_env.antispams or {}\n    local last = aura_env.antispams[GUID]\n    \n    if not last or (cur - last > before) then\n        aura_env.antispams[GUID] = cur\n        return false\n    end\n    \n    return true\nend\n\nlocal creatures = {\n    EmperorStrength = { 60397 },\n}\n\naura_env.guidCache = {}\naura_env.IsGUID = function(GUID, creature)\n    if not GUID then return end\n    \n    local creatureIDs = creatures[creature]\n    if not creatureIDs then return false end\n    \n    local npcId = aura_env.guidCache[GUID]\n    if not npcId then\n        npcId = Merfin.GetNPCIDFromGUID(GUID)\n        aura_env.guidCache[GUID] = npcId\n    end\n    \n    if type(creatureIDs) == \"table\" then\n        for _, id in ipairs(creatureIDs) do\n            if npcId == id then return true end\n        end\n        return false\n    else\n        return npcId == creatureIDs\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 116556 then\n            local GUID = UnitGUID(unitID)\n            if not aura_env.IsSpam(GUID, 2) then\n                aura_env.StartCD(6, GUID)\n            end\n        end\n        \n    elseif e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        local _,_,_,_,_,_,_, destGUID = ...\n        \n        if aura_env.IsGUID(destGUID, 'EmperorStrength') then\n            aura_env.StopCD(destGUID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.antispams = {}\n    end\nend",
