["init"] = {
["custom"] = "local border = {\n    [[Interface\\AddOns\\WeakAuras\\Media\\Textures\\square_border_1px.tga]],\n    [[Interface\\AddOns\\WeakAuras\\Media\\Textures\\square_border_5px.tga]],\n    [[Interface\\AddOns\\WeakAuras\\Media\\Textures\\square_border_10px.tga]]\n}\naura_env.region.cooldown:SetSwipeTexture(border[aura_env.config.b])\naura_env.region.cooldown:SetSwipeColor(unpack(aura_env.config.c))\n\naura_env.ShowFrame = function(a, d)\n    a[''] = {\n        show = true,\n        autoHide = true,\n        changed = true,\n        progressType = 'timed',\n        duration = d,\n        expirationTime = d + GetTime()\n    }\n    return true\nend\n\naura_env.HideFrame = function(a)\n    if not a[''] then return end\n    a[''] = {\n        show = false,\n        autohide = true, \n    }\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["spellId"] = {
1224929,
},
["duration"] = "10",
["subeventPrefix"] = "SPELL",
["destUnit"] = "player",
["debuffType"] = "HELPFUL",
["type"] = "custom",
["custom_type"] = "stateupdate",
["names"] = {
},
["event"] = "Combat Log",
["events"] = "FRAME_UPDATE, CLEU:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED:SPELL_AURA_APPLIED_DOSE:SPELL_AURA_REMOVED_DOSE",
["custom"] = "function(a, e, ...)\n    if e == 'FRAME_UPDATE' then\n        \n        local currentSpeed = GetUnitSpeed('player')\n        local stopped = currentSpeed == 0 and not IsFalling()\n        \n        if stopped and aura_env.moving then\n            aura_env.moving = false\n            return aura_env.ShowFrame(a, 18)\n        elseif not stopped then\n            aura_env.moving = true\n            return aura_env.HideFrame(a)\n        end\n    end\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        local _,_,_,_,_,_,_, destGUID,_,_,_, spellId = ...\n        \n        if destGUID ~= WeakAuras.myGUID then\n            return\n        end\n        \n        if spellId ~= 1224929 then\n            return\n        end\n        \n        return aura_env.ShowFrame(a, 10)\n    end\nend",
