["[T11] Backend - Sinestra"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Sinestra)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Sinestra\n\nlocal ENTRY = aura_env\nlocal encounterId1 = 1082\nlocal encounterId2 = 1083\n\nlocal localized = {\n    ['enUS'] = {\n        YellDragon = \"Feed, children!  Take your fill from their meaty husks!\",\n        YellEgg =    \"You mistake this for weakness?  Fool!\",\n    },\n    \n    ['ruRU'] = {\n        YellDragon = \"Ешьте, дети мои! Пусть их мясо насытит вас!\",\n        YellEgg    = \"Ты так в этом уверен? Глупец!\",\n    },\n    ['zhCN'] = {\n        YellDragon            = \"吃吧，孩子们！尽情享用他们肥美的躯壳吧！\",\n        YellEgg                = \"你以为就这么简单？愚蠢！\",\n    },\n    ['koKR'] = {\n        YellDragon        = \"얘들아, 먹어치워라\",\n        YellEgg            = \"이게 약해지는 걸로 보이느냐? 멍청한 놈!\",\n    },\n    ['zhTW'] = {\n        YellDragon            = \"吃吧，孩子們!好好享用他們肥嫩的軀殼吧!\",\n        YellEgg                = \"你以為這樣就佔了上風?愚蠢!\",\n    },\n    ['frFR'] = {\n        Quake        = \"Le sol sous vos pieds gronde avec menace...\",\n        Thundershock    = \"L'air qui vous entoure crépite d'énergie...\",\n    },\n    ['deDE'] = {\n        Quake            = \"Der Boden unter Euch grollt unheilvoll...\",\n        Thundershock    = \"Die Luft beginnt, vor Energie zu knistern...\",\n    },\n    ['esES'] = {\n        Quake            = \"El suelo bajo tus pies empieza a temblar ominosamente...\",\n        Thundershock    = \"El aire circundante chisporrotea de energía...\",\n    },\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    orbs =             { false, 458969 },\n    dragon =           { false, 134154 },\n    wrack =            { 89421 },\n    extinction =       { 86227 },\n    red_essence =      { 87946 },\n    breath =           { 90125 },\n    egg_shield =       { 87654 },\n    egg_weakening =    { 87654, 294479 },\n    egg_weaken =       { 87654, 294479 },\n    indomitable =      { 90045 },\n    twilight_essence = { 88146 },\n    twilight_breath =  { 90083 },\n    mana_barrier =     { 87299 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\nlocal Schedule = function(after, func, mechanic, ...) CORE.Schedule(ENTRY, mechanic, after, func, ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId2)\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if (id == encounterId1 or id == encounterId2) and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START']()\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal EGG = 46842\n\nlocal eggRemoved = false\nlocal eggDown = 0\n\nlocal dragonRepeat = function()\n    Warning('dragon')\n    Cooldown('dragon', 50)\nend\n\nENTRY.Orbs = function()\n    Timer('orbs', 15)\n    local orbTimer = 28\n    Cooldown('orbs', orbTimer); PreWarning('orbs', orbTimer-5); Schedule(orbTimer, ENTRY.Orbs, 'orbsRepeat')\nend\n\nENTRY['ON_COMBAT_START'] = function()\n    CORE.SetStage(ENTRY, 1)\n    eggRemoved = false\n    eggDown = 0\n    Cooldown('dragon', 16)\n    Cooldown('breath', 21)\n    local orbTimer = 29\n    Cooldown('orbs', orbTimer); PreWarning('orbs', orbTimer-5); Schedule(orbTimer, ENTRY.Orbs, 'orbsRepeat')\nend\n\nlocal Phase2 = function()\n    CORE.SetStage(ENTRY, 2)\n    CORE.CancelScheduler(ENTRY, 'orbsRepeat')\n    eggDown = 0\n    Cancel('breath', 'ALL')\n    Cancel('orbs', 'ALL')\nend\n\nlocal Phase3 = function()\n    CORE.SetStage(ENTRY, 3)\n    Cancel('egg_weaken', 'ALL')\n    Cooldown('breath', 21)\n    Cooldown('dragon', 5); Schedule(5, dragonRepeat, 'dragonRepeat')\n    local orbTimer = 30\n    Cooldown('orbs', orbTimer); PreWarning('orbs', orbTimer-5); Schedule(orbTimer, ENTRY.Orbs, 'orbsRepeat')\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 90125 then\n        SpecialWarning('breath')\n        Cooldown('breath', 21)\n        PreWarning('breath', 16)\n    elseif args.spellId == 86227 then\n        Warning('extinction')\n        Timer('extinction', 16)\n    elseif args.spellId == 90083 then\n        Cooldown('twilight_breath', 20)\n    elseif args.spellId == 87299 then\n        Timer('mana_barrier', 3)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 90045 then\n        --SpecialWarning('indomitable')\n    elseif args.spellId == 89421 then\n        -- Wrack Casted\n    elseif args.spellId == 89435 then\n        -- Wrack Jumps\n    elseif args.spellId == 87299 then\n        Phase2()\n    elseif args.spellId == 87654 then\n        if AntiSpam('egg_weaken', 3) then\n            Cancel('dragon', 'COOLDOWN')\n            if eggRemoved then\n                SpecialWarning('egg_shield')\n            end\n        end\n    elseif args.spellId == 87946 then\n        \n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 87654 and AntiSpam('egg_weaken', 3) then\n        eggRemoved = true\n        Timer('egg_weaken', 30)\n        SpecialWarning('egg_weaken')\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 88146 and args.destGUID == CORE.PlayerGUID and AntiSpam('twilight_essence', 2) then\n        GTFO('twilight_essence')\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['SWING_DAMAGE'] = function(args)\n    \nend\n\nENTRY['SWING_MISSED'] = function(args)\n    \nend\n\nENTRY['UNIT_DIED'] = function(args)\n    local cId = CORE.GetGuidCreatureId(args.destGUID)\n    if cId == EGG then\n        eggDown = eggDown + 1\n        if eggDown >= 2 then\n            Phase3()\n        end\n    elseif cid == 47265 or cid == 48047 or cid == 48048 or cid == 48049 or cid == 48050 then \n        WeakAuras('WHELP_DIED', args.destGUID)\n    end\nend\n\nENTRY['CHAT_MSG_MONSTER_YELL'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if msg == L.YellDragon or msg:find(L.YellDragon) then\n        Warning('dragon')\n        Cooldown('dragon', 50, '', true)\n    elseif msg == L.YellEgg or msg:find(L.YellEgg) then\n        Timer('egg_weakening', 4)\n    end\nend",
