["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'RandomAbility'\n\nlocal icon = 'NPE_TurnIn'\n\nlocal waterspout = C_Spell.GetSpellName(120519)\nlocal huddle = C_Spell.GetSpellName(132608)\nlocal strike = C_Spell.GetSpellName(120672)\n\nlocal names = {\n    ['SpoutStrike'] = string.format('%s / %s', waterspout, strike),\n    ['HuddleSpout'] = string.format('%s / %s', huddle, waterspout),\n    ['SpotStrikeHuddle'] = 'Random Ability (1 of 3)'\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(subID, duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = names[subID],\n            icon = icon,\n            count = aura_env.count\n    })\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'SPECIAL_CAST_CD' then\n        local ID, duration = ...\n        \n        if ID == 'SpoutStrike' then\n            aura_env.StartCD(ID, duration)\n            \n        elseif ID == 'HuddleSpout' then\n            aura_env.StartCD(ID, duration)\n            \n        elseif ID == 'SpotStrikeHuddle' then\n            aura_env.StartCD(ID, duration)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
