["spellIds"] = {
},
["custom"] = "function(t, event, ...)\n    local s = t[1]\n    if not s then\n        s = {}\n        t[1] = s\n    end\n    s.show = true\n    local isLogging = LoggingCombat()\n    if isLogging == nil then\n        s.isLogging = isLogging\n    end\n    if s.isLogging ~= isLogging then\n        s.changed = true\n        s.isLogging = isLogging\n        s.logging = isLogging and YES or NO\n        s.loggingColored = format(isLogging and \"|cff55FF55%s|r\" or \"|cffFF5555%s|r\", s.logging)\n    end\n    return true\nend",
["events"] = "LOADING_SCREEN_DISABLED, PLAYER_DEAD, PLAYER_ENTERING_WORLD, PLAYER_STARTED_LOOKING, PLAYER_STARTED_MOVING, PLAYER_STOPPED_LOOKING, PLAYER_STOPPED_MOVING, PLAYER_UNGHOST",
