},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'HuddleInTerror'\n\nlocal name, icon = C_Spell.GetSpellName(132608), C_Spell.GetSpellTexture(132608)\n\nlocal options = {\n    warningText = '%icon @cffff8b17%name@r » %destName %icon',\n    prewarnTTStext = Merfin:L('Prepare to throw')\n}\n\naura_env.MRT = function()\n    local event = 'HUDDLE_' .. aura_env.count\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            destName = destName\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 120629 then\n                table.insert(aura_env.targets, destName)\n                \n                if aura_env.IsSpam(3) then\n                    return\n                end\n                \n                aura_env.count = aura_env.count + 1\n                aura_env.MRT()\n                \n                C_Timer.After(0.7, function()\n                        local names = {}\n                        for _, name in ipairs(aura_env.targets) do\n                            table.insert(names, WA_ClassColorName(name))\n                        end\n                        \n                        local destNames = table.concat(names, ', ')\n                        aura_env.SendWarning(destNames)\n                        aura_env.targets = {}\n                end)\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        \n        if spellID == 132608 then \n            aura_env.StopCD('HuddleInTerror')\n            aura_env.StopCD('RandomAbility')\n        end\n        \n    elseif e == 'SPECIAL_CAST_CD' then\n        local ID, duration = ...\n        \n        if ID == 'HuddleInTerror' then\n            aura_env.StartCD(duration)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
