["init"] = {
["custom"] = "local L = GetLocale()\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        roleplay1 = \"Fascinating, I have never heard tales of anything like this. The mogu hide their secrets well.\",\n        roleplay11 = \"This room pulses with energy, but feels unlike any we have seen so far.\",\n        roleplay2 = \"This seems to be a terminal controlling the device. Let's see here...\"\n    },\n    \n    ['ruRU'] = {\n        roleplay1 = \"Потрясающе. Я никогда не слышал о чем-либо подобном. Могу хорошо хранят свои секреты.\",\n        roleplay11 = \"Я чувствую энергию в этом зале. Но она не похожа на то, с чем мы сталкивались раньше.\",\n        roleplay2 = \"Это, должно быть, пульт управления этим устройством. Давай посмотрим поближе...\"\n    },\n}",
["do_custom"] = true,
},
},
