["[DP] [Feng] Phase"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1390'\n\naura_env.SendPhasing = function(phase)\n    WeakAuras.ScanEvents('PHASE_CHANGED', phase)\nend\n\nlocal names = {\n    ['LightningPhase'] = Merfin:L('Lightning Phase'),\n    ['FlamePhase']     = Merfin:L('Flame Phase'),\n    ['ArcanePhase']    = Merfin:L('Arcane Phase'),\n    ['ShadowPhase']    = Merfin:L('Shadow Phase'),\n}\n\nlocal options = {\n    ['LightningPhase'] = {\n        warningText = '@cffe3e3e3' .. names.LightningPhase:upper() .. '@r',\n        ttsLine = Merfin:L('Lightning Phase'),\n    },\n    ['FlamePhase'] = {\n        warningText = '@cffe3e3e3' .. names.FlamePhase:upper() .. '@r',\n        ttsLine = Merfin:L('Flame Phase'),\n    },\n    ['ArcanePhase'] = {\n        warningText = '@cffe3e3e3' .. names.ArcanePhase:upper() .. '@r',\n        ttsLine = Merfin:L('Arcane Phase'),\n    },\n    ['ShadowPhase'] = {\n        warningText = '@cffe3e3e3' .. names.ShadowPhase:upper() .. '@r',\n        ttsLine = Merfin:L('Shadow Phase'),\n    }\n}\n\naura_env.SendWarning = function(ID)\n    local warning = {\n        ID   = ID,\n        name = names[ID]\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, warning, options[ID])\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Lightning = \"Oh great spirit! Grant me the power of the earth!\",\n        Flame = \"Oh exalted one! Through me you shall melt flesh from bone!\",\n        Arcane = \"Oh sage of the ages! Instill to me your arcane wisdom!\",\n        Shadow = \"Great soul of champions past! Bear to me your shield!\",\n    },\n    ['ruRU'] = {\n        Lightning = \"О, великий дух! Даруй мне силу земли!\",\n        Flame = \"О, превозносимый! Моими руками ты отделишь их плоть от костей!\",\n        Arcane = \"О, великий мыслитель! Да снизойдет на меня твоя древняя мудрость!\",\n        Shadow = \"Великие души защитников! Охраняйте меня!\",\n    },\n    ['zhTW'] = {\n        Lightning = \"噢，偉大的靈魂!賜予我大地之力!\",\n        Flame = \"噢，至高的神啊!藉由我來融化他們的血肉吧!\",\n        Arcane = \"噢，上古的賢者!賜予我祕法的智慧!\",\n        Shadow = \"英雄之靈!以盾護我之身!\",\n    },\n    ['ptBR'] = {\n        Lightning = \"\",\n        Flame = \"\",\n        Arcane = \"\",\n        Shadow = \"\",\n    },\n    ['zhCN'] = {\n        Lightning = \"噢，伟大的神灵！赐予我大地的力量！\",\n        Flame = \"噢，至高的神！借我之手融化他们的血肉吧！\",\n        Arcane = \"噢，上古的贤者！赐予我魔法的智慧吧！\",\n        Shadow = \"先烈的英灵！用你的盾保护我吧！\",\n    },\n    ['deDE'] = {\n        Lightning = \"Oh, großer Geist! Gewährt mir die Macht der Erde!\",\n        Flame = \"Oh, Erhabener! Durch mich sollt Ihr das Fleisch von den Knochen schmelzen!\",\n        Arcane = \"Oh, Weiser der Zeitalter! Vertraut mir Euer arkanes Wissen an!\",\n        Shadow = \"Große Seele vergangener Helden! Gewährt mir Euren Schild!\",\n    },\n    ['esES'] = {\n        Lightning = \"¡Oh, gran espíritu! ¡Otórgame el poder de la tierra!\",\n        Flame = \"¡Oh, exaltado! ¡Soy tu herramienta para desgarrar la carne de los huesos!\",\n        Arcane = \"¡Oh, sabio eterno! ¡Transmíteme tu sapiencia Arcana!\",\n        Shadow = \"¡Almas de campeones antiguos! ¡Concededme vuestro escudo!\",\n    },\n    ['frFR'] = {\n        Lightning = \"Ô grand esprit ! Accorde-moi le pouvoir de la terre !\",\n        Flame = \"Ô être exalté ! Grâce à moi vous ferez fondre la chair et les os !\",\n        Arcane = \"Ô sagesse ancestrale ! Distille en moi ta sagesse arcanique !\",\n        Shadow = \"Grandes âmes des champions du passé ! Confiez-moi votre bouclier !\",\n    },\n    ['itIT'] = {\n        Lightning = \"Oh, grande spirito... concedimi il potere della terra!\",\n        Flame = \"Oh, potente! Attraverso me scioglierai la carne dalle ossa!\",\n        Arcane = \"Oh, saggio delle ere! Concedimi la tua saggezza arcana!\",\n        Shadow = \"Grande spirito dei campioni del passato! concedimi il tuo scudo!\",\n    },\n    ['koKR'] = {\n        Lightning = \"오 위대한 영혼이여! 내게 대지의 힘을 부여하라!\",\n        Flame = \"오 고귀한 자여! 나와 함께 발라내자! 뼈에서 살을!\",\n        Arcane = \"오 세기의 현자여! 내게 비전의 지혜를 불어넣어라!\",\n        Shadow = \"과거의 위대한 영웅들이여! 너희의 방패를 빌려다오!\",\n    },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
