["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_MONSTER_YELL' then\n        local msg = ...\n        \n        if aura_env.IsEmote(msg, 'Lightning') then\n            aura_env.SendPhasing('LIGHTNING')\n            aura_env.SendWarning('LightningPhase')\n            \n        elseif aura_env.IsEmote(msg, 'Flame') then\n            aura_env.SendPhasing('FLAME')\n            aura_env.SendWarning('FlamePhase')\n            \n        elseif aura_env.IsEmote(msg, 'Arcane') then\n            aura_env.SendPhasing('ARCANE')\n            aura_env.SendWarning('ArcanePhase')\n            \n        elseif aura_env.IsEmote(msg, 'Shadow') then\n            aura_env.SendPhasing('SHADOW')\n            aura_env.SendWarning('ShadowPhase')\n            \n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        \n        if spellID == 122410 then\n            aura_env.SendPhasing('END')\n        end\n    end\nend\n\n\n",
