["[T11] Backend - Omnotron Defense System"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Omnotron Defense System)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Omnotron Defense System\n\nlocal ENTRY = aura_env\nlocal encounterId = 1027\n\nlocal localized = {\n    ['enUS'] = {},\n    ['ruRU'] = {},\n}\n\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L\n\nENTRY.mechanics = {\n    acquiring_target =      { 79501 },\n    incineration =          { 79023 },\n    barrier =               { 79582 },\n    lightning_conductor =   { 79888 },\n    unstable_shield =       { 79900 },\n    chemical_bomb =         { 80157 },\n    poison_protocol =       { 80053 },\n    poison_shell =          { 79835 },\n    power_generator =       { 79629 },\n    power_conversion =      { 79729 },\n    nefarian_special =      { false, 236448 },\n    grip_of_death =         { 91849 },\n    next_activation =       { false, 415046 },\n    arcane_blowback =       { 91857 },\n    shadow_infusion =       { 92048 },\n    encasing_shadow =       { 92023 },\n    shadow_conductor =      { 92053 },\n    overcharged_generator = { 91857 },\n    poison_puddle =         { 80097 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit =  false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nlocal MAGMATRON =  42178\nlocal ELECTRON =   42179\nlocal TOXITRON =   42180\nlocal ARCANOTRON = 42166\n\nlocal activeBoss = {\n    [MAGMATRON] =  false, -- Magmatron\n    [ELECTRON] =   false, -- Electron\n    [TOXITRON] =   false, -- Toxitron\n    [ARCANOTRON] = false, -- Arcanotron\n}\n\nlocal GetFormattedBossName = function(npcId, destName)\n    if npcId == MAGMATRON then\n        return '|cffff6100' .. destName .. '|r'\n    elseif npcId == ELECTRON then\n        return '|cff00b8ff' .. destName .. '|r'\n    elseif npcId == TOXITRON then\n        return '|cff519700' .. destName .. '|r'\n    elseif npcId == ARCANOTRON then\n        return '|cff005c9d' .. destName .. '|r'\n    end\nend\n\nlocal currentBoss\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            local delay = 1\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                local creatureId = CORE.CetUnitCreatureId('boss1')\n                ENTRY['ON_COMBAT_START'](0.1, creatureId)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.ResetFields(ENTRY)\n    CORE.WipeSchedulers(ENTRY)\n    currentBoss = false\n    isEncounter = false\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0, currentBoss)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,interruptId, stacks)\n    -- For some reason SPELL_AURA_APPLIED is called before ENCOUNTER_START\n    if not IsEntryInitialized() then\n        if subEvent == 'SPELL_AURA_APPLIED' and spellId == 78740 then\n            local creatureId = CORE.GetGuidCreatureId(destGUID)\n            currentBoss = creatureId\n        end\n    elseif IsEntryInitialized() then\n        args = {}\n        args.subEvent = subEvent\n        args.sourceGUID = sourceGUID\n        args.sourceName = sourceName\n        args.destGUID = destGUID\n        args.destName = destName\n        args.spellId = spellId\n        args.stacks = stacks\n        args.interruptId = interruptId\n        return ENTRY[subEvent] and ENTRY[subEvent](args)\n    end\nend\n\n--------------\n--> Main Logic\n--------------\n\nENTRY['BOSS_INACTIVE'] = function(creatureId)\n    activeBoss[creatureId] = false\n    WeakAuras.ScanEvents('WA_ODS_BOSS_DEACTIVATED', creatureId)\n    if creatureId == MAGMATRON then\n        Cancel('acquiring_target', 'ALL')\n        Cancel('incineration', 'ALL')\n        Cancel('barrier', 'ALL')\n    elseif creatureId == ELECTRON then\n        Cancel('lightning_conductor', 'ALL')\n        Cancel('unstable_shield', 'ALL')\n    elseif creatureId == TOXITRON then\n        Cancel('chemical_bomb', 'ALL')\n        Cancel('poison_protocol', 'ALL')\n        Cancel('poison_shell', 'ALL')\n    elseif creatureId == ARCANOTRON then\n        Cancel('power_generator', 'ALL')\n        Cancel('power_conversion', 'ALL')\n    end\nend\n\nENTRY['BOSS_ACTIVATED'] = function(creatureId)\n    activeBoss[creatureId] = true\n    WeakAuras.ScanEvents('WA_ODS_BOSS_ACTIVATED', creatureId)\n    if creatureId == MAGMATRON then\n        ENTRY.CASTS['incineration'] = 0\n        Cooldown('acquiring_target', 20)\n        Cooldown('incineration', 10)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('barrier', 44, '', true)\n        else\n            Cooldown('barrier', 50, '', true)\n        end\n    elseif creatureId == ELECTRON then\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('lightning_conductor', 15)\n            Cooldown('unstable_shield', 40, '', true)\n        else\n            Cooldown('lightning_conductor', 11)\n            Cooldown('unstable_shield', 50)\n        end\n    elseif creatureId == TOXITRON then\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('chemical_bomb', 25)\n            Cooldown('poison_protocol', 15)\n            Cooldown('poison_shell', 40, '', true)\n        else\n            Cooldown('chemical_bomb', 11)\n            Cooldown('poison_protocol', 21)\n            Cooldown('poison_shell', 50, '', true)\n        end\n    elseif creatureId == ARCANOTRON then\n        Cooldown('power_generator', 15)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('power_conversion', 40, '', true)\n        else\n            Cooldown('power_conversion', 50, '', true)\n        end\n    end\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 79023 then\n        SpecialWarning('incineration', nil, 135818)\n        Timer('incineration', 4)\n        ENTRY.CASTS['incineration'] = (ENTRY.CASTS['incineration'] or 0) + 1\n        if ENTRY.CASTS['incineration'] == 1 then\n            Cooldown('incineration', 27)\n        elseif ENTRY.CASTS['incineration'] == 2 and IsDifficulty('10_NORMAL', '25_NORMAL') then\n            Cooldown('incineration', 32)\n        end\n    elseif args.spellId == 79582 then\n        Cancel('barrier', 'COOLDOWN')\n        Timer('barrier', 11.5)\n        if CORE.CetUnitCreatureId('target') == MAGMATRON then\n            local bossName = GetFormattedBossName(MAGMATRON, args.sourceName)\n            SpecialWarning('stop_attack', bossName)\n        end\n    elseif args.spellId == 79900 then\n        Cancel('unstable_shield', 'COOLDOWN')\n        Timer('unstable_shield', 11.5)\n        if CORE.CetUnitCreatureId('target') == ELECTRON then\n            local bossName = GetFormattedBossName(ELECTRON, args.sourceName)\n            SpecialWarning('stop_attack', bossName)\n        end\n    elseif args.spellId == 79835 then\n        Cancel('poison_shell', 'COOLDOWN')\n        Timer('poison_shell', 11.5)\n        if CORE.CetUnitCreatureId('target') == TOXITRON then\n            local bossName = GetFormattedBossName(TOXITRON, args.sourceName)\n            SpecialWarning('stop_attack', bossName)\n        end\n    elseif args.spellId == 79729 then\n        Cancel('power_conversion', 'COOLDOWN')\n        Timer('power_conversion', 11.5)\n        if CORE.CetUnitCreatureId('target') == ARCANOTRON then\n            local bossName = GetFormattedBossName(ARCANOTRON, args.sourceName)\n            SpecialWarning('stop_attack', bossName)\n        end\n    elseif args.spellId == 91849 then\n        Cooldown('nefarian_special', 30)\n        Timer('grip_of_death', 2)\n        SpecialWarning('grip_of_death')\n    elseif args.spellId == 79710 then\n        -- Arcane Annihilator\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args) \n    if args.spellId == 78740 then\n        local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n        local bossName = GetFormattedBossName(creatureId, args.destName)\n        WeakAuras.ScanEvents('BOSS_ACTIVATED', creatureId, bossName)\n        Warning('boss_activated', bossName)\n        Cancel('next activation', 'ALL')\n        ENTRY['BOSS_ACTIVATED'](creatureId)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('next_activation', 30)\n        else\n            Cooldown('next_activation', 45)\n        end\n    elseif args.spellId == 78726 then\n        local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n        ENTRY['BOSS_INACTIVE'](creatureId)\n    elseif args.spellId == 79501 then\n        Warning('acquiring_target', args.destName)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('acquiring_target', 27)\n        else\n            Cooldown('acquiring_target', 40)\n        end\n    elseif args.spellId == 79888 then\n        Warning('lightning_conductor', args.destName)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('lightning_conductor', 20)\n        else\n            Cooldown('lightning_conductor', 25)\n        end\n    elseif args.spellId == 79629 then\n        local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n        if activeBoss[creatureId] then\n            local bossName = GetFormattedBossName(creatureId, args.destName)\n            WeakAuras.ScanEvents('WA_POWER_GENERATOR_ENEMY', bossName, creatureId, true)\n        end\n    elseif args.spellId == 92048 then\n        Cooldown('nefarian_special', 30)\n        Warning('shadow_infusion')\n        Timer('shadow_infusion', 5, args.destName)\n    elseif args.spellId == 92023 then\n        Cooldown('nefarian_special', 30)\n        Warning('encasing_shadow', args.destName)\n    elseif args.spellId == 92053 then\n        SpecialWarning('shadow_conductor', args.destName)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 80157 then\n        Cooldown('chemical_bomb', 30)\n    elseif args.spellId == 80053 then\n        Timer('poison_protocol', 9)\n        Warning('poison_protocol')\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('poison_protocol', 25)\n        else\n            Cooldown('poison_protocol', 45)\n        end\n    elseif args.spellId == 79624 then\n        Warning('power_generator')\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('power_generator', 20)\n        else\n            Cooldown('power_generator', 30)\n        end\n    elseif args.spellId == 91857 then\n        SpecialWarning('overcharged_generator')\n        Timer('arcane_blowback', 7.8)\n        Cooldown('nefarian_special', 30)\n    elseif args.spellId == 79710 then\n        WeakAuras.ScanEvents('ARCANE_ANNIHILATOR', args.sourceGUID)\n    end\nend\n\nENTRY['SPELL_INTERRUPT'] = function(args)\n    if args.interruptId == 79710 then\n        -- Blast Nova (P2 Mobs Casts)\n        WeakAuras.ScanEvents('ARCANE_ANNIHILATOR', args.destGUID)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 79629 then\n        local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n        if activeBoss[creatureId] then\n            local bossName = GetFormattedBossName(creatureId, args.destName)\n            WeakAuras.ScanEvents('WA_POWER_GENERATOR_ENEMY', bossName, creatureId, false)\n        end\n    elseif args.spellId == 92053 then\n        Cancel('shadow_conductor', 'ALL')\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 80097 and args.destGUID == CORE.PlayerGUID and AntiSpam('poison_puddle', 3) then\n        GTFO('poison_puddle')\n    end\nend\n\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['ON_COMBAT_START'] = function(delay, currentBoss)\n    if currentBoss then\n        ENTRY['BOSS_ACTIVATED'](currentBoss)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('next_activation', 30-delay)\n        else\n            Cooldown('next_activation', 45-delay)\n        end\n    end\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('berserk', 600-delay)\n    end\nend",
