["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    entryId = {\n        type = 'string',\n        display = 'ID',\n    },\n    \n    percent = {\n        type = 'number',\n        display = 'Health Percent',\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(a, e, ...)\n    \n    if e == 'OPTIONS' then\n        for i = 1, 3 do\n            a[i] = {\n                show = true,\n                changed = true,\n                progressType = 'static',\n                value = math.random(10000, 499999),\n                total = 499999,\n                name = Merfin:L('Dummy Bar'),\n                mark = '{rt' .. math.random(1,8) .. '}',\n            }\n        end\n        return true\n    end\n    \n    if e == 'STATUS' then\n        aura_env.ClearCache()\n    elseif e == 'RAID_TARGET_UPDATE' then\n        --return aura_env.UpdateRaidTarget(a)\n    elseif e == 'WA_MERFIN_HP_HIDER' then\n        -- extra event to hide certain bars\n        local destGUID = ...\n        if destGUID and a[destGUID] then\n            a[destGUID].show = false\n            a[destGUID].changed = true\n            aura_env.deadGUID[destGUID] = true\n            return true\n        end\n        \n    elseif e == 'FLOOR_FALLING' then\n        for _, state in pairs(a) do\n            if state.entryId == 'ENERGY_CHARGE' then\n                state.show = false\n                state.changed = true\n            end\n        end\n        \n        return true\n        \n    elseif e ~= 'COMBAT_LOG_EVENT_UNFILTERED' then\n        return\n    end\n    \n    local _, subEvent, _, _, _, _, _, destGUID, destName, _, destRaidFlags, swingAmount, swingOverkill, _, amount, overkill = ...\n    \n    if aura_env.deadGUID[destGUID] then\n        return\n    end\n    \n    if subEvent == 'UNIT_DIED' then\n        if a[destGUID] then\n            a[destGUID].show = false\n            a[destGUID].changed = true\n            aura_env.deadGUID[destGUID] = true\n            return true\n        end\n        return\n    end\n    \n    if not aura_env.damage_events[subEvent] then\n        return\n    end\n    \n    local npcId = aura_env.GetNpcId(destGUID)\n    \n    if not aura_env.npcData[npcId] then\n        return\n    end\n    \n    if not a[destGUID] then\n        -- initialize health bar\n        local totalHP, displayName, icon, entryId = aura_env.GetNpcData(npcId)\n        a[destGUID] = {\n            show         = true,\n            changed      = true,\n            progressType = 'static',\n            value        = totalHP,\n            total        = totalHP,\n            percent      = 100,\n            name         = aura_env.GetOption('actualNames') and destName or displayName,\n            icon         = icon,\n            entryId      = entryId,\n        }\n    elseif (subEvent == 'SWING_DAMAGE' and (swingOverkill or 0) > 0) or \n    ((subEvent == 'SPELL_DAMAGE' or subEvent == 'RANGE_DAMAGE') and (overkill or 0) > 0) then\n        -- additional check in case UNIT_DIED is missing\n        a[destGUID].show = false\n        a[destGUID].changed = true\n        aura_env.deadGUID[destGUID] = true\n        return true\n    end\n    \n    local damage = subEvent == 'SWING_DAMAGE' and swingAmount or amount\n    a[destGUID].value = a[destGUID].value - damage\n    a[destGUID].percent = 100 * a[destGUID].value/a[destGUID].total\n    a[destGUID].changed = true\n    a[destGUID].mark = aura_env.GetFormattedFlagMark(destRaidFlags)\n    \n    if a[destGUID].value <= 0 then\n        a[destGUID].show = false\n        aura_env.deadGUID[destGUID] = true\n    end\n    \n    return true\nend",
