["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        states:Update('', {\n                progressType = 'static',\n                value        = 4,\n                total        = 4,\n        })\n    end\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, _, _, _, _, spellID = ...\n        if spellID ~= 123461 then return end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            aura_env.initialized = true\n            aura_env.startHP = UnitHealth(\"boss1\")\n            aura_env.maxHP = UnitHealthMax(\"boss1\")\n            aura_env.lastHP = aura_env.startHP\n            \n            states:Update('', {\n                    progressType = 'static',\n                    value        = 4,\n                    total        = 4,\n            })\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            aura_env.initialized = nil\n            aura_env.startHP = nil\n            aura_env.maxHP = nil\n            aura_env.lastHP = nil\n            states:Remove('')\n        end\n    end\n    \n    if e == 'UNIT_HEALTH' and aura_env.initialized and UnitExists(\"boss1\") then\n        local currentHP = UnitHealth(\"boss1\")\n        \n        if currentHP < aura_env.lastHP then\n            local lostHP = aura_env.startHP - currentHP\n            if lostHP > 0 and aura_env.maxHP then\n                local lostPercent = (lostHP / aura_env.maxHP) * 100\n                local remainingPercent = math.max(0, 4 - lostPercent)\n                states:Update('', {\n                        progressType = 'static',\n                        value        = remainingPercent,\n                        total        = 4,\n                })\n            end\n        end\n        \n        aura_env.lastHP = currentHP\n    end\nend",
["names"] = {
},
["check"] = "event",
["events"] = "CLEU:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED, UNIT_HEALTH:boss1",
