},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = 'Trash'\nlocal ID          = 'TempestSlash'\n\nlocal name, icon = C_Spell.GetSpellName(125692), C_Spell.GetSpellTexture(125692)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r %icon\",\n}\n\naura_env.StopCD = function(destGUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID   = ID,\n            GUID = destGUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            GUID           = GUID,\n            sourceName     = '|cff9d9d9dZarik|r',\n            name           = name,\n            icon           = icon\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID      = ID,\n            count   = aura_env.count,\n            noCount = true,\n            name    = name,\n            icon    = icon\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID = ...\n        \n        if subEvent == 'UNIT_DIED' then\n            if Merfin.GetNPCIDFromGUID(destGUID) == 64341 then\n                aura_env.StopCD(destGUID)\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID, _, spellID = ...\n        \n        if spellID == 125692 then\n            local unitGUID = UnitGUID(unitID)\n            local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n            \n            if npcID == 64341 and not aura_env.IsSpam(3) then\n                aura_env.StartCD(10, UnitGUID(unitID))\n                aura_env.SendWarning()\n            end\n        end\n    end\nend",
