["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "UNIT_SPELLCAST_SUCCEEDED, CHAT_MSG_MONSTER_YELL, CLEU:UNIT_DIED:SWING_DAMAGE:SPELL_DAMAGE:SPELL_PERIODIC_DAMAGE:RANGE_DAMAGE",
["custom"] = "function(state, e, ...)\n    \n    if e == 'OPTIONS' then\n        state[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 231,\n            expirationTime = GetTime() + 231,\n            autoHide = true,\n            count = 15,\n        }\n        return true\n        \n    elseif e == 'STATUS' then\n        local curTime = GetTime()\n        if not _G.MerfinTimerRP or _G.MerfinTimerRP - curTime < 0 then\n            return\n        end\n        \n        state[''] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            duration = _G.MerfinTimerRP - curTime,\n            expirationTime = _G.MerfinTimerRP,\n            autoHide = true,\n        }\n        return true\n        \n    elseif e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, _,_,_, spellId, swingOverkill, _,_, overkill = ...\n        \n        if subEvent == 'UNIT_DIED' then\n            local id = select(6, strsplit(\"-\", destGUID))\n            if not aura_env.validNPC[id] then\n                return\n            end\n            aura_env.DrakeDied(state, destGUID)\n            return true\n        end\n        \n        if subEvent == 'SWING_DAMAGE' and (swingOverkill or 0) > 0 then\n            local id = select(6, strsplit(\"-\", destGUID))\n            if not aura_env.validNPC[id] then\n                return\n            end\n            aura_env.DrakeDied(state, destGUID)\n            return true\n        end\n        \n        if (\n            subEvent == 'SPELL_DAMAGE' \n            or subEvent == 'SPELL_PERIODIC_DAMAGE' \n            or subEvent == 'RANGE_DAMAGE'\n        ) and (overkill or 0) > 0 then\n            local id = select(6, strsplit(\"-\", destGUID))\n            if not aura_env.validNPC[id] then\n                return\n            end\n            aura_env.DrakeDied(state, destGUID)\n            return true\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitId,_, spellId = ...\n        \n        if spellId == 109904 then\n            if not state[''] then\n                return\n            end\n            state[''].show = false\n            state[''].changed = true\n            _G.MerfinTimerRP = nil\n            return true\n        end\n        \n        if spellId == 108161 then\n            if state[''] then\n                return\n            end\n            \n            _G.MerfinTimerRP = GetTime() + 231\n            aura_env.count = 15\n            \n            state[''] = {\n                show = true,\n                changed = true,\n                progressType = 'timed',\n                duration = 231,\n                expirationTime = _G.MerfinTimerRP,\n                autoHide = true,\n                count = 15,\n            }\n            return true\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_YELL' then\n        local msg = ...\n        if aura_env.IsEmote(msg, 'SecondRolePlay') then\n            _G.MerfinTimerRP = GetTime() + 231\n            aura_env.count = 15\n            \n            state[''] = {\n                show = true,\n                changed = true,\n                progressType = 'timed',\n                duration = 231,\n                expirationTime = _G.MerfinTimerRP,\n                autoHide = true,\n                count = 15,\n            }\n            \n            return true\n        end\n        if aura_env.IsEmote(msg, 'UltraxionEnd') then\n            if not state[''] then\n                return\n            end\n            \n            state[''].show = false\n            state[''].changed = true\n            _G.MerfinTimerRP = nil\n            return true\n        end\n    end\nend",
["names"] = {
},
