["parent"] = "[T13] 小型进度条组",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local L = GetLocale()\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then\n        return false\n    end\n    \n    if not aura_env.replicas[L] then\n        return false\n    end\n    \n    local replica = aura_env.replicas[L][compareWith]\n    \n    if not replica then\n        return false\n    end\n    \n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    [\"enUS\"] = {\n        SecondRolePlay = \"It is good to see you again, Alexstrasza. I have been busy in my absence.\",\n        UltraxionEnd = \"Mere whelps, experiments, a means to a greater end. You will see what the research of my clutch has yielded.\",\n    },\n    [\"ruRU\"] = {\n        SecondRolePlay = \"Рад встрече, Алекстраза. Скоро ты увидишь, над чем я трудился.\",\n        UltraxionEnd = \"Детеныши, эксперименты, шаги к будущему величию. Вы увидите, чего я добился.\",\n    },\n    [\"frFR\"] = {\n        SecondRolePlay = \"It is good to see you again, Alexstrasza. I have been busy in my absence.\",\n        UltraxionEnd = \"Mere whelps, experiments, a means to a greater end. You will see what the research of my clutch has yielded.\",\n    },\n    [\"deDE\"] = {\n        SecondRolePlay = \"Es tut gut, Euch wiederzusehen, Alexstrasza. Während meiner Abwesenheit war ich fleißig.\",\n        UltraxionEnd = \"Sie waren bloß Welpen, Experimente, Mittel zu einem Zweck. Ihr werdet sehen, was meine Forschung hervorgebracht hat.\",\n    },\n    [\"esES\"] = {\n        SecondRolePlay = \"Me alegra volver a verte, Alexstrasza. He estado ocupado en mi ausencia.\",\n        UltraxionEnd = \"Simples crías, experimentos, un medio para un fin mayor. Verás el resultado de las investigaciones de mi nidada.\",\n    },\n    [\"koKR\"] = {\n        SecondRolePlay = \"다시 만나 반갑군, 알렉스트라자. 난 떠나 있는 동안 좀 바쁘게 지냈다.\",\n        UltraxionEnd = \"가련한 녀석들, 이 실험은 위대한 결말을 위한 희생이었다. 알 연구의 결과물을 직접 확인해라.\",\n    },\n    [\"zhCN\"] = {\n        SecondRolePlay = \"重逢真令我高兴，阿莱克斯塔萨。分开之后，我可是一直很忙。\",\n        UltraxionEnd = \"这些龙崽子，这些实验，只为一个崇高的目标。你很快就会看到我最伟大的研究成果。\",\n    },\n    [\"zhTW\"] = {\n        SecondRolePlay = \"很高興又見到你，雅立史卓莎。我離開這段時間忙得很。\",\n        UltraxionEnd = \"這些幼龍、實驗品，只不過是實現更偉大目標的手段罷了。你會看到研究的龍蛋有什麼成果。\",\n    }\n}\n\naura_env.validNPC = {\n    ['56249'] = true,\n    ['56250'] = true,\n    ['56251'] = true,\n    ['56252'] = true,\n    ['57281'] = true,\n    ['57795'] = true,\n}\n\naura_env.storedGUIDs = {}\n\naura_env.DrakeDied = function(state, destGUID)\n    if aura_env.storedGUIDs[destGUID] then\n        return\n    end\n    \n    aura_env.storedGUIDs[destGUID] = true\n    aura_env.count = (aura_env.count or 15) - 1\n    \n    if state[''] then\n        state[''].show = aura_env.count >0\n        state[''].count = aura_env.count\n        state[''].changed = true\n    end\n    \n    if aura_env.count <= 0 then\n        _G.MerfinTimerRP = nil\n    end\nend",
["do_custom"] = true,
},
