["init"] = {
["custom"] = "local encounterID = '1395'\nlocal ID          = 'JadeShards'\n\nlocal name, icon = C_Spell.GetSpellName(116223), C_Spell.GetSpellTexture(116223)\n\nlocal options = {\n    warningText = '%icon @cffffff80%name@r (%count) %icon',\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID           = ID,\n        count        = aura_env.count,\n        name         = name,\n        icon         = icon,\n        localization = localization,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local  _, subEvent,_, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID = ...\n        \n        if spellID == 116223 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(9)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        if WeakAuras.InstanceType() == 'twentyfive' and WeakAuras.InstanceDifficulty() ~= 'lfr' then\n            aura_env.StartCD(9)\n        end\n        \n    elseif e == 'ENCOUNTER_ENGAGE' then -- Custom Event for 10 Man\n        local npcID = ...\n        if npcID == 60043 then\n            aura_env.StartCD(9 - 1)\n        end\n    end\nend",
