["customText"] = "-- Author: 露露緹婭@Bilibili\nfunction()\n    if WeakAuras.IsOptionsOpen() then\n        return\"|T463565:12|t 风爆弹：|cffff0000玩家姓名 |T463565:12|t\"\n    end\n    \n    local spellId = 131813\n    local spellInfo = C_Spell.GetSpellInfo(spellId)\n    local spellName = spellInfo and spellInfo.name\n    local spellIcon = spellInfo and spellInfo.iconID\n    \n    local Name = aura_env.state.sourceName\n    if Name then\n        local coloredName = WA_ClassColorName(Name)\n        if coloredName ~= \"\" then\n            Name = coloredName\n        end\n        return[[|T]] .. spellIcon .. [[ :12|t ]] .. spellName .. [[：]] .. Name .. [[ |T]] .. spellIcon .. [[ :12|t]]\n    end\n    \n    return\nend",
