["init"] = {
["custom"] = "local encounterID = '1434'\nlocal ID          = 'ShadowyAttack'\n\nlocal name, icon = Merfin:L('Shadowy Attack'), 574575\n\nlocal options = {\n    warningText = '%icon %name (%count) %icon'\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.ShadowyAttacks = {\n    [117215] = true,\n    [117218] = true, \n    [117219] = true,\n    [117222] = true,\n}",
["do_custom"] = true,
},
},
