["customText"] = "function()\n    return Merfin:L('Ready')\nend",
["sparkRotationMode"] = "AUTO",
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n    cooldownId = {\n        display = 'Cooldown ID',\n        type = 'string',\n    },\n    noCount = {\n        display = 'Missing Counter',\n        type = 'bool'\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        for i = 1, 3 do\n            local duration = math.random(3, 10)\n            local newState = {\n                progressType   = 'timed',\n                autoHide       = false,\n                duration       = duration,\n                expirationTime = duration + GetTime(),\n                name           = Merfin:L('Emphasized Cooldown Bar'),\n                nextCount      = math.random(1, 10),\n            }\n            states:Update(i, newState)\n        end\n    end\n    \n    if e == 'MERFIN_CD_EMPH_HIDE' then\n        local encounterID, cooldown = ...\n        local stateName = encounterID .. cooldown.ID .. (cooldown.GUID or '')\n        states:Remove(stateName)\n        \n    elseif e == 'MERFIN_CD_EMPH_SHOW' then\n        local encounterID, cooldown, duration = ...\n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        local duration = duration or cooldown.duration\n        \n        local newState = {\n            progressType   = 'timed',\n            duration       = cooldown.expirationTime - GetTime(),\n            expirationTime = cooldown.expirationTime,\n            autoHide       = cooldown.autoHide,\n            icon           = cooldown.icon,\n            name           = cooldown.name,\n            nextCount      = (cooldown.count or 0) + 1,\n            noCount        = cooldown.noCount,\n            cooldownId     = cooldown.ID,\n        }\n        states:Update(stateName, newState)\n    end\nend",
