["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'ConsumingTerror'\n\nlocal name, icon = C_Spell.GetSpellName(124849), C_Spell.GetSpellTexture(124849)\n\nlocal options = {\n    warningText   = \"@cffff4040%upper:name@r\",\n    prewarnCountVA = 2,\n    prewarnTTStext = Merfin:L('Prepare to Dodge'),\n    ttsLine        = Merfin:L(\"Dodge\"),\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName),\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 124849 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n                aura_env.StartCD(32)\n            end\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN, delay = ...\n        \n        if phaseN == 3 then\n            aura_env.count = 0\n            aura_env.StartCD(14-(delay or 0))\n        end\n    end\nend",
