["message_type"] = "TTS",
},
["init"] = {
["custom"] = "local wrack = GetSpellInfo(89421)\nlocal UnitName = UnitName\nlocal strsplit = strsplit\nlocal tonumber = tonumber\nlocal _G = _G\n\nlocal MerfinDebuffToolTip = CreateFrame(\"GameTooltip\",\"MerfinDebuffToolTipFrame\", nil, \"GameTooltipTemplate\")\n\nMerfinDebuffToolTip:SetOwner(WorldFrame,\"ANCHOR_NONE\")\n\nlocal GetUnitIdFromName = function(unitName)\n    for unit in WA_IterateGroupMembers() do\n        local uName = UnitName(unit)\n        if unitName == uName then\n            return unit\n        end\n    end\nend\n\naura_env.GetWrackInfo = function(unitName)\n    local unit = GetUnitIdFromName(unitName)\n    if not unit or not UnitExists(unit) then return end\n    for i=1, 40 do\n        local name = UnitDebuff(unit, i)\n        if name == wrack then\n            MerfinDebuffToolTip:ClearLines() \n            MerfinDebuffToolTip:SetUnitDebuff(unit, i)\n            local text = _G[MerfinDebuffToolTip:GetName()..\"TextLeft2\"]:GetText()\n            if not text then break\n            else\n                local _, damage = strsplit(' ', text)\n                return tonumber(damage)\n            end\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
