["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() then\n        return 15320\n    end\n    local dmg = aura_env.GetWrackInfo(WeakAuras.me)\n    aura_env.damage = dmg ~= aura_env.damage and dmg or aura_env.damage\n    return aura_env.damage\nend",
