["[DP] [Garalon] Legs"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1463'\n\nlocal GetSpellInfoTable = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\nlocal data = {\n    ['MendLeg']   = GetSpellInfoTable(123495),\n    ['BrokenLeg'] = GetSpellInfoTable(122786),\n}\n\nlocal options = {\n    ['BrokenLeg'] = {\n        warningText = \"%icon @cffff8b17%name@r (%amount/4) %icon\",\n    },\n    ['MendLeg'] = {\n        warningText = \"%icon @cffffff80%name@r (%amount/4) %icon\",\n    },\n    ['MendLegSwitch'] = {\n        warningText = '@cffff4040' .. Merfin:L(\"Switch Target\"):upper() .. '@r',\n        ttsLine     = Merfin:L(\"Switch Target\"),\n    }\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID,\n    })\nend\n\naura_env.StartCD = function(ID, duration)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            name           = data[ID].name,\n            icon           = data[ID].icon,\n            noCount        = true\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID, amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID      = ID,\n            count   = aura_env.count,\n            noCount = true,\n            name    = data[ID].name,\n            icon    = data[ID].icon,\n            amount  = amount\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            -- Mend Leg\n            if spellID == 123495 then\n                aura_env.legs = aura_env.legs + 1\n                WeakAuras.ScanEvents('LEGS_CHANGED', aura_env.legs)\n                \n                aura_env.SendWarning('MendLeg', aura_env.legs)\n                \n                if aura_env.legs < 4 then\n                    aura_env.StartCD('MendLeg', 30)\n                else\n                    aura_env.StopCD('MendLeg')\n                    aura_env.mendLegTimerRunning = nil\n                end\n                \n                if aura_env.legs == 0 then\n                    aura_env.SendWarning('MendLegSwitch')\n                end\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            -- Broken Leg\n            if spellID == 122786 and Merfin.GetNPCIDFromGUID(destGUID) == 63191 then\n                aura_env.legs = aura_env.legs - 1\n                WeakAuras.ScanEvents('LEGS_CHANGED', aura_env.legs)\n                \n                aura_env.SendWarning('BrokenLeg', aura_env.legs)\n                \n                if not aura_env.mendLegTimerRunning then\n                    aura_env.StartCD('MendLeg', 30)\n                    aura_env.mendLegTimerRunning = true\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.legs = 4\n    end\nend",
["spellIds"] = {
},
