["init"] = {
["custom"] = "-- [T11] Backend - Ascendant Council\n\nlocal ENTRY = aura_env\nlocal encounterId = 1028\n\nlocal localized = {\n    ['enUS'] = {\n        -- RAID_BOSS_EMOTE\n        Quake = \"The ground beneath you rumbles ominously....\",\n        Thundershock = \"The surrounding air crackles with energy....\",\n    },\n    \n    ['ruRU'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"Земля уходит у вас из-под ног...\",\n        Thundershock = \"Воздух потрескивает от скопившейся энергии...\",\n        \n    },\n    ['zhCN'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"你脚下的地面发出不祥的“隆隆”声……\",\n        Thundershock = \"周围的空气因为充斥着强大的能量而发出“噼啪”声……\",\n        \n    },\n    ['koKR'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"발밑의 땅이 불길하게 우르릉거립니다...\",\n        Thundershock = \"주변의 공기가 에너지로 진동합니다...\",\n        \n    },\n    ['zhTW'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"你腳下的地面開始不祥地震動起來....\",\n        Thundershock = \"四周的空氣爆出能量霹啪作響聲音....\",\n        \n    },\n    ['frFR'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"Le sol sous vos pieds gronde avec menace...\",\n        Thundershock = \"L'air qui vous entoure crépite d'énergie...\",\n        \n    },\n    ['deDE'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake = \"Der Boden unter Euch grollt unheilvoll...\",\n        Thundershock    = \"Die Luft beginnt, vor Energie zu knistern...\",        \n    },\n    ['esES'] = {\n        -- RAID_BOSS_EMOTE  \n        Quake            = \"El suelo bajo tus pies empieza a temblar ominosamente...\",\n        Thundershock    = \"El aire circundante chisporrotea de energía...\",\n    },  \n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    -- Feludius\n    glaciate =     { 82746 },\n    hydro_lance =  { 82752 },\n    water_bomb =   { 82699 },\n    heart_of_ice = { 82665 },\n    \n    -- Ignacious\n    aegis_of_flame = { 82631 },\n    inferno_leap =   { 82857 },\n    inferno_rush =   { 82860 },\n    flame_torrent =  { 82777 },\n    burning_blood =  { 82660 },\n    \n    -- Terrastra\n    eruption =       { 83675 },\n    harden_skin =    { 83718 },\n    quake =          { 83565 },\n    gravity_core =   { 92075 },\n    gravity_well =   { 83572 },\n    \n    -- Arion\n    lightning_rod =         { 83099 },\n    chain_lightning =       { 83282 },\n    disperse =              { 83087 },\n    lightning_blast =       { 83070 },\n    thundershock =          { 83067 },\n    static_overload =       { 92067 },\n    call_winds =            { 83491 },\n    \n    -- Inactives\n    frost_beacon =   { 92307 }, -- Feludius\n    flame_strike =   { 92212 }, -- Ignacious\n    \n    -- Elementium Monstrosity\n    lava_seed =     { 84913 },\n    gravity_crush = { 84948 },\n    transition =    { 84918 },\n    liquid_ice =    { 84915 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START']()\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,interruptId, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    args.interruptId = interruptId\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal ARION =     43688\nlocal FELUDIUS =  43687\nlocal IGNACIOUS = 43686\nlocal TERRASTRA = 43689\n\nlocal Phase2 = function()\n    CORE.SetStage(ENTRY, 2)\n    \n    Cancel('glaciate', 'ALL')\n    Cancel('hydro_lance', 'ALL')\n    Cancel('water_bomb', 'ALL')\n    Cancel('heart_of_ice', 'ALL')\n    Cancel('inferno_leap', 'ALL')\n    Cancel('aegis_of_flame', 'ALL')\n    Cancel('flame_torrent', 'ALL')\n    Cancel('burning_blood', 'ALL')\n    \n    Cancel('gravity_core', 'ALL')\n    Cancel('static_overload', 'ALL')\n    \n    Cooldown('quake', 30); PreWarning('quake', 20, 10)\n    Cooldown('harden_skin', 23.5); PreWarning('harden_skin', 20.5)\n    Cooldown('call_winds', 10)\n    Cooldown('gravity_well', 5)\n    \n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('frost_beacon', 25)\n        Cooldown('flame_strike', 28)\n    end\nend\n\nlocal PhaseTransition = function()\n    Cancel('quake', 'ALL')\n    Cancel('thundershock', 'ALL')\n    Cancel('harden_skin', 'ALL')\n    Cancel('eruption', 'ALL')\n    Cancel('disperse', 'ALL')\n    Cancel('flame_strike', 'ALL')\n    Cancel('frost_beacon', 'ALL')\n    \n    Timer('transition', 16.7)\n    PreWarning('transition', 11.7)\nend\n\nlocal Phase3 = function()\n    CORE.SetStage(ENTRY, 3)\n    Cancel('frost_beacon', 'ALL')\n    Cooldown('lava_seed', 18)\n    Cooldown('gravity_crush', 28); PreWarning('gravity_crush', 23)\nend\n\nENTRY['ON_COMBAT_START'] = function()\n    \n    CORE.SetStage(ENTRY, 1)\n    \n    Cooldown('glaciate', 30); PreWarning('glaciate', 25, 8)\n    Cooldown('hydro_lance', 8)\n    Cooldown('water_bomb', 15); PreWarning('water_bomb', 12, 3)\n    Cooldown('heart_of_ice', 18)\n    \n    Cooldown('aegis_of_flame', 31)\n    Cooldown('flame_torrent', 8)\n    Cooldown('burning_blood', 28)\n    Cooldown('inferno_leap', 18)\n    \n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('gravity_core', 25)\n        Cooldown('static_overload', 20)\n    end\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 82746 then\n        -- Feludius: Glaciate \n        Cooldown('glaciate', 33); PreWarning('glaciate', 28, 8) \n        Timer('glaciate', 3)\n        if CORE.CetUnitCreatureId('target') == FELUDIUS then\n            SpecialWarning('glaciate')\n        else\n            Warning('glaciate')\n        end\n        \n    elseif args.spellId == 82752 then\n        Cooldown('hydro_lance', 12)\n        CORE.Schedule(ENTRY, 'hydro_lance', 0.1, CORE.TargettedCast, args.sourceGUID, 'HYDRO_LANCE_TARGET')\n        \n    elseif args.spellId == 82699 then\n        Warning('water_bomb')\n        Cooldown('water_bomb', 33); PreWarning('water_bomb', 30, 3)\n        \n    elseif args.spellId == 83675 then\n        Warning('eruption')\n        Cooldown('eruption', 15)\n        \n    elseif args.spellId == 83718 then\n        Warning('harden_skin')\n        Cooldown('harden_skin', 42); PreWarning('harden_skin', 37)\n        \n    elseif args.spellId == 83565 then\n        \n        Warning('quake')\n        Cancel('quake', 'PRE_WARNING'); Cancel('quake', 'COOLDOWN')\n        Timer('quake', 3)\n        \n        Cooldown('thundershock', 33)\n        PreWarning('thundershock', 23, 10)\n        \n    elseif args.spellId == 83087 then\n        Warning('disperse')\n        Cooldown('disperse', 30)\n        \n    elseif args.spellId == 83070 then\n        Timer('lightning_blast', 4)\n        CORE.Schedule(ENTRY, 'lightning_blast', 0.1, CORE.TargettedCast, args.sourceGUID, 'LIGHTNING_BLAST_TARGET')\n        \n    elseif args.spellId == 83067 then\n        Warning('thundershock')\n        Cancel('thundershock', 'PRE_WARNING'); Cancel('thundershock', 'COOLDOWN')\n        Timer('thundershock', 3)\n        \n        Cooldown('quake', 33)\n        PreWarning('quake', 23, 10)\n        \n    elseif args.spellId == 84913 then\n        Warning('lava_seed')\n        Cooldown('lava_seed', 23)\n        \n    elseif args.spellId == 92212 then\n        Warning('flame_strike')\n        Cooldown('flame_strike', 20)\n    elseif args.spellId == 83491 then\n        -- Call Winds\n        Cooldown('call_winds', 20)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 82636 then\n        Cooldown('aegis_of_flame', 60)\n    elseif args.spellId == 82665 then\n        Cooldown('heart_of_ice', 22)\n    elseif args.spellId == 82660 then\n        Cooldown('burning_blood', 22)\n    elseif args.spellId == 82777 then\n        Cooldown('flame_torrent', 8)\n    elseif args.spellId == 82699 then\n        SpecialWarning('water_bomb')\n    elseif args.spellId == 82752 then\n        WeakAuras.ScanEvents('HYDRO_LANCE', args.sourceGUID)\n    elseif args.spellId == 84913 then\n        SpecialWarning('lava_seed')\n    elseif args.spellId == 83572 then\n        -- Gravity Well\n        Cooldown('gravity_well', 25)\n    end\nend\n\nENTRY['SPELL_INTERRUPT'] = function(args)\n    if args.interruptId == 82752 then\n        WeakAuras.ScanEvents('HYDRO_LANCE', args.destGUID)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 82772 then\n        -- Frozen\n    elseif args.spellId == 82665  then\n        -- Heart of Ice\n        Warning('heart_of_ice', args.destName)\n    elseif args.spellId == 82660 then\n        -- Burning Blood\n        Warning('burning_blood', args.destName)\n    elseif args.spellId == 83099 then\n        -- Lightning Rod\n    elseif args.spellId == 82777 then\n        \n    elseif args.spellId == 82631 then\n        -- Aegis of Flame\n        SpecialWarning('aegis_of_flame')\n        \n    elseif args.spellId == 82762 then\n        -- Waterlogged\n        \n    elseif args.spellId == 84948 then\n        -- Gravity Crush\n        Cooldown('gravity_crush', 24); PreWarning('gravity_crush', 19)\n        Timer('gravity_crush', 6.5)\n        \n    elseif args.spellId == 92307 then\n        -- Frost Beacon\n        if args.destGUID ~= CORE.PlayerGUID then\n            Warning('frost_beacon', args.destName)\n        end\n        if AntiSpam('frost_beacon', 18) then\n            Cooldown('frost_beacon', 20)\n        end\n    elseif args.spellId == 92067 then\n        -- Static Overload\n        Cooldown('static_overload', 20)\n        if args.destGUID ~= CORE.PlayerGUID then\n            Warning('static_overload', args.destName)\n        end\n        \n    elseif args.spellId == 92075 then\n        Cooldown('gravity_core', 20)\n        if args.destGUID ~= CORE.PlayerGUID then\n            Warning('gravity_core', args.destName)\n        end\n        \n    end\nend\nENTRY['SPELL_AURA_REFRESH'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 83099 and args.destGUID == CORE.PlayerGUID then\n        WeakAuras.ScanEvents('LIGHTNING_ROD_RESET')\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 84915 and args.destGUID == CORE.PlayerGUID and AntiSpam('liquid_ice', 2) then\n        GTFO('liquid_ice')\n    elseif args.spellId == 82860 and args.destGUID == CORE.PlayerGUID and AntiSpam('inferno_rush', 2) then\n        GTFO('inferno_rush')\n    elseif args.spellId == 92214 and args.destGUID == CORE.PlayerGUID and AntiSpam('flame_strike', 2) then\n        GTFO('flame_strike')\n    elseif args.spellId == 82857 and AntiSpam('inferno_leap', 2) then\n        Cooldown('inferno_leap', 34)\n    elseif args.spellId == 83282 and args.destGUID == CORE.PlayerGUID and AntiSpam('chain_lightning', 1) then\n        WeakAuras.ScanEvents('LIGHTNING_ROD_SAVED')\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['RAID_BOSS_EMOTE'] = function(msg)\n    if L.Quake and (msg == L.Quake or msg:find(L.Quake)) then\n        --Cooldown('quake', 23)\n        --Warning('quake')\n        \n    elseif L.Thundershock and (msg == L.Thundershock or msg:find(L.Thundershock)) then\n        --Cooldown('thundershock', 23)\n    end\nend\n\nENTRY['UNIT_SPELLCAST_SUCCEEDED'] = function(unitId,_, spellId)\n    if spellId == 94739 and AntiSpam('phase_2', 2) and CORE.GetStage(ENTRY) == 1 then\n        Phase2()\n    elseif spellId == 82285 and AntiSpam('phase_transition', 2) then\n        PhaseTransition()\n    elseif spellId == 84526 and AntiSpam('phase_3', 2) then\n        Phase3()\n    end\nend",
