["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 123963 and not aura_env.IsSpam(2) then\n            aura_env.count = aura_env.count + 1\n            if not aura_env.firstStrikeDone then\n                aura_env.firstStrikeDone = true\n                aura_env.StartCD(32)\n            else\n                aura_env.StartCD(50)\n            end\n        end\n        \n    elseif e == 'KORTHIK_STRIKE_TARGET' then\n        local destName = ...\n        if destName ~= WeakAuras.me then\n            aura_env.SendWarning(destName)\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        \n        if npcID == 62402 then\n            if aura_env.isHeroic then\n                aura_env.StartCD(79)\n            else\n                aura_env.StopCD()\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.count = 0\n        aura_env.firstStrikeDone = false\n        aura_env.StartCD(19)\n    end\nend",
