["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    expirationTime = true,\n    cooldownId = {\n        display = 'Cooldown ID',\n        type = 'string',\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(a, e, ...)\n    if e == 'OPTIONS' then\n        for i = 1, 3 do\n            local duration = math.random(5, 30)\n            a[i] = {\n                show = true,\n                changed = true,\n                progressType = 'timed',\n                autoHide = false,\n                duration = duration,\n                expirationTime = duration + GetTime(),\n                name = 'Cooldown',\n                nextCount = math.random(1, 10),\n            }\n        end\n        return true\n    end\n    \n    if e == 'WA_MERFIN_BOSS_CD_EMPH_HIDE' then\n        local encounterID, cooldown = ...\n        \n        local stateName = encounterID .. cooldown.id .. (cooldown.GUID or '')\n        if a[stateName] then\n            a[stateName].show = false\n            a[stateName].changed = true\n            return true\n        end\n        \n    elseif e == 'WA_MERFIN_BOSS_CD_EMPH' then\n        local encounterID, cooldown, duration = ...\n        local stateName = encounterID .. cooldown.id  .. (cooldown.GUID or '')\n        local duration = duration or cooldown.duration\n        a[stateName] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            autoHide = cooldown.autoHide,\n            name = cooldown.name,\n            icon = cooldown.icon,\n            nextCount = cooldown.count + 1,\n            cooldownId = cooldown.id,\n        }\n        return true\n    end\nend",
