["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'EchoClone'\n\nlocal name, icon = Merfin.GetTitleEJ(6568), C_Spell.GetSpellTexture(127834)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17\" .. name .. \"@r %icon\",\n    ttsLine = name,\n}\n\naura_env.SendWarning = function()\n    local data = {\n        ID    = ID,\n        count = aura_env.count,\n        name  = name,\n        icon  = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.StopCD = function()\n    local data = { ID = ID }\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, data) -- no options\nend\n\naura_env.StartCD = function(duration)\n    local data = {\n        show           = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        autoHide       = true,\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        noCount        = true,\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend",
