["custom"] = "function(e, ...)\n    if e == 'PLATFORM_CHANGED' then\n        local platformN = ...\n        if platformN == 4 then\n            local seconds = 58\n            aura_env.StartCD(seconds)\n            aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n                    WeakAuras.ScanEvents('CLONE_SPAWNED')\n            end)\n        end\n        \n    elseif e == 'CLONE_SPAWNED' then\n        aura_env.StopCD()\n        aura_env.SendWarning()\n        \n    elseif e == 'ENCOUNTER_START' then\n        if aura_env.scheduler then\n            aura_env.scheduler:Cancel()\n        end\n        \n        aura_env.count = 0\n    end\nend",
