["custom"] = "local e = aura_env \nif not _G[e.id..\"Button\"] then \n    local region = WeakAuras.GetRegion(e.id) \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region, \"SecureActionButtonTemplate\") \n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\", \"MiddleButtonUp\")\n    e.btn:SetAttribute(\"type1\",\"macro\")\n    e.btn:SetAttribute(\"type2\",\"macro\")\n    e.btn:SetAttribute(\"type3\",\"macro\")\n    e.btn:SetAllPoints(region) \nend \n\nlocal btn = _G[e.id..\"Button\"] \nbtn:SetAttribute(\"macrotext1\",\"/cancelaura 拯救祝福\\n/cancelaura 强效拯救祝福\")\nbtn:SetAttribute(\"macrotext2\",\"/cancelaura 拯救祝福\\n/cancelaura 强效拯救祝福\")\n--btn:SetAttribute(\"macrotext3\",\"/cast 魔甲术\")\nbtn:SetScript(\"OnEnter\", function(self)               \n        GameTooltip:SetOwner(self, \"ANCHOR_RIGHT\") \n        GameTooltip:SetText(\n            \"|cffffffff左键：|r|cfff7a100\"..\"取消拯救\"..\"|r\\n\"\n            --\"|cffffffff右键：|r|cfff7a100\"..\"取消正义之怒\"..\"|r\\n\"\n            --\"|cffffffff中键：|r|cffff5e4d\"..\"魔甲术\"..\"|r\\n\"\n        , 0, 1, 0, 1, 1)\nend)\n\nbtn:SetScript(\"OnLeave\", function(self) GameTooltip:Hide() end)\nbtn:Show()\n\n--by 露露緹婭@Bilibili，转载请保留出处。",
