["[DP] [Zorlok] Force and Verve"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'ForceAndVerve'\n\nlocal name, icon = C_Spell.GetSpellName(122713), C_Spell.GetSpellTexture(122713)\n\nlocal options = {\n    warningText = '%upper:name',\n    ttsLine = Merfin:L('Hide'),\n    prewarnCountVA = 1,\n    prewarnTTStext = Merfin:L(\"Prepare to hide\"),\n}\n\naura_env.MRT = function()\n    local event = 'FV_' .. aura_env.count\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    local data = { ID = ID }\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, data) -- no options\nend\n\naura_env.StartCD = function(duration, ignorePrew)\n    local data = {\n        show           = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        ignorePrew     = ignorePrew,\n        name           = name,\n        icon           = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID    = ID,\n        count = aura_env.count,\n        name  = name,\n        icon  = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Synch = function(event)\n    WeakAuras.ScanEvents('MERFIN_SYNCH', 'RAID', nil, event) \nend\n\naura_env.IsSpam = function(id, before)\n    local cur = GetTime()\n    aura_env.antispam = aura_env.antispam or {}\n    \n    if not aura_env.antispam[id] or cur - aura_env.antispam[id] > before then\n        aura_env.antispam[id] = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 122713 then\n                if aura_env.platformN < 4 then\n                    aura_env.StartCD(33) -- 35-50\n                else\n                    aura_env.StartCD(49)\n                end\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 122713 then\n                WeakAuras.ScanEvents('FORCE_CAST_SUCCESS')\n            end\n            \n        elseif subEvent == 'UNIT_DIED' then\n            local npcID = Merfin.GetNPCIDFromGUID(destGUID)\n            if npcID == 65174 then -- Echo of Force and Verve\n                WeakAuras.ScanEvents('FORCE_CAST_FINISH')\n                aura_env.StopCD()\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID, _, spellID = ...\n        if spellID == 122933 then -- Clear Throat\n            local unitGUID = UnitGUID(unitID)\n            if not aura_env.IsSpam(unitGUID, 3) then\n                aura_env.Synch('FORCE_PREW_SYNCH')\n            end\n        end\n        \n    elseif e == 'FORCE_PREW_SYNCH' then\n        aura_env.StopCD()\n        aura_env.count = aura_env.count + 1\n        aura_env.SendWarning()\n        aura_env.MRT()\n        \n    elseif e == 'ECHO_STATE' then\n        aura_env.EchoAlive = ...\n        \n    elseif e == 'PLATFORM_CHANGED' then\n        aura_env.platformN = ...\n        aura_env.StopCD()\n        \n        if aura_env.platformN == 1 then\n            aura_env.StartCD(24)\n        elseif aura_env.platformN == 2 then\n            aura_env.StartCD(10)\n        elseif aura_env.platformN == 4 then\n            aura_env.StartCD(38, true)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.platformN = 0\n        aura_env.count = 0\n        aura_env.antispam = {}\n    end\nend",
["spellIds"] = {
