["events"] = "ENCOUNTER_START, PLATFORM_CHANGED, ECHO_STATE, UNIT_SPELLCAST_SUCCEEDED, CLEU:UNIT_DIED:SPELL_CAST_START:SPELL_CAST_SUCCESS, FORCE_PREW_SYNCH",
