["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Cho'gal\n\nlocal ENTRY = aura_env\nlocal encounterId = 1029\n\nlocal localized = {\n    ['enUS'] = {  \n    },\n    \n    ['ruRU'] = {\n    },\n    \n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    -- Phase 1\n    worship =             { 91331 },\n    fury =                { 82524 },\n    flame_orders =        { 81171, 135790 }, \n    flaming_destruction = { 81194 },\n    blaze =               { 81538 },\n    shadow_orders =       { 81556 },\n    empowered_shadows =   { 81572 },\n    adherent =            { 81628, 254090 },\n    corruption_crash =    { 81685 },\n    depravity =           { 81713 },\n    spilled_blood =       { 81757 },\n    fester_blood =        { 82299 },\n    \n    creations =           { 82414 },\n    sickness =            { 82235 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\nlocal Schedule = function(after, func, mechanic, ...) CORE.Schedule(ENTRY, mechanic, after, func, mechanic, ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START']()\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal firstAdd = false\n\nlocal flameOrderCD\nlocal shadowOrderCD\nlocal worshipCD\n\n\nENTRY['ON_COMBAT_START'] = function()\n    \n    CORE.SetStage(ENTRY, 1)\n    \n    firstAdd = false\n    \n    flameOrderCD = 40\n    shadowOrderCD = 40\n    worshipCD = 20.5\n    \n    Cooldown('worship', 10)\n    Cooldown('flame_orders', 5)\n    Cooldown('shadow_orders', 20)\n    Cooldown('berserk', 600)\nend\n\nlocal Phase2 = function()\n    CORE.SetStage(ENTRY, 2)\n    Warning('phase_2')\n    --Cancel('fury', 'ALL')\n    Cancel('adherent', 'ALL')\n    Cancel('worship', 'ALL')\n    Cancel('fester_blood', 'ALL')\n    Cancel('flame_orders', 'ALL')\n    Cancel('shadow_orders', 'ALL')\n    Cancel('empowered_shadows', 'ALL')\n    Cancel('flaming_destruction', 'ALL')\nend\n\nENTRY['ON_COMBAT_END'] = function()\n    \nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 81628 then\n        if not firstAdd then\n            -- Don't ask why. Blizzard ICANT\n            firstAdd = true\n            shadowOrderCD = 50\n            flameOrderCD = 50\n            worshipCD = 36\n            CORE.CancelScheduler(ENTRY, 'flameOrderCD')\n            CORE.CancelScheduler(ENTRY, 'shadowOrderCD')\n            Cooldown('flame_orders', 0)\n            Cooldown('shadow_orders', 0)\n            Cooldown('fury', 0)\n            Cooldown('worship', 0)\n        end\n        \n        Warning('adherent')\n        Cooldown('adherent', 92)\n        Cooldown('fester_blood', 40)\n        \n    elseif args.spellId == 82524 then\n        Warning('fury')\n        Cooldown('fury', 47)\n        \n    elseif args.spellId == 82411 then\n        --\n        \n    elseif args.spellId == 81713 then\n        if IsDifficulty('10_NORMAL', '10_HEROIC') then\n            Cooldown('depravity', 12)\n        else\n            Cooldown('depravity', 6)\n        end\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 82414 then\n        Warning('creations')\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('creations', 40)\n        else\n            Cooldown('creations', 30)\n        end\n    elseif args.spellId == 82630 then\n        Phase2()\n    elseif args.spellId == 81556 then\n        -- Shadow Ordders\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cancel('shadow_orders', 'COOLDOWN'); Warning('shadow_orders'); Timer('shadow_orders', 6.5)\n            Schedule(6.5, Cooldown, 'shadow_orders', shadowOrderCD - 6.5)\n            Schedule(6.5, Cooldown, 'empowered_shadows', 13.5)\n        else\n            Cooldown('empowered_shadows', 10.8)\n        end\n        \n    elseif args.spellId == 81171 then\n        -- Flame Orders\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cancel('flame_orders', 'COOLDOWN'); Warning('flame_orders'); Timer('flame_orders', 6.5)\n            Schedule(6.5, Cooldown, 'flame_orders', flameOrderCD - 6.5)\n            Schedule(6.5, Cooldown, 'flaming_destruction', 13.5)\n        else\n            Cooldown('flaming_destruction', 10.8)\n        end\n    elseif args.spellId == 81685 then\n        CORE.Schedule(ENTRY, 'corrupting_crash', 0.1, CORE.TargettedCast, args.sourceGUID, 'CORRUPTING_CRASH_TARGET')\n    elseif args.spellId == 91303 then\n        Warning('worship')\n        Cooldown('worship', worshipCD)\n    elseif args.spellId == 81757 then\n        Warning('spilled_blood')\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 91317 then\n        Cooldown('worship', worshipCD)\n        \n    elseif args.spellId == 81194 then\n        -- Tank Ability\n        --Cooldown('flaming_destruction', )\n        \n    elseif args.spellId == 81572 then\n        Timer('empowered_shadows', 9)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 81538 and args.destGUID == CORE.PlayerGUID and AntiSpam('blaze', 2) then\n        GTFO('blaze')\n    elseif args.spellId == 81761 and args.destGUID == CORE.PlayerGUID and AntiSpam('spilled_blood', 2) then\n        GTFO('spilled_blood')\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']",
