["init"] = {
["custom"] = "local encounterID = '1434'\nlocal ID          = 'SpiritTotems'\n\nlocal name, icon = C_Spell.GetSpellName(116174), C_Spell.GetSpellTexture(116174)\n\nlocal options = {\n    warningText = '%icon @cffff8b17%name@r (%count) %icon'\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Synch = function()\n    WeakAuras.ScanEvents('MERFIN_SYNCH', 'RAID', nil, 'SPIRIT_TOTEMS_SYNCH') \nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.LatencyCheck = function()\n    return select(4, GetNetStats()) < 250\nend",
["do_custom"] = true,
