["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 116174 and aura_env.LatencyCheck() then\n                aura_env.Synch()\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 117752 and aura_env.diff ~= 7 then\n                aura_env.StopCD()\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        \n        if spellID == 116964 then -- LFR only\n            --aura_env.Synch()\n        end\n        \n    elseif e == 'SPIRIT_TOTEMS_SYNCH' then\n        if not aura_env.IsSpam(10) then\n            aura_env.count = aura_env.count + 1\n            aura_env.StartCD(aura_env.totemTime)\n            aura_env.SendWarning()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        \n        aura_env.diff = WeakAuras.InstanceTypeRaw()\n        local diff = aura_env.diff\n        aura_env.totemTime = (diff == 3 or diff == 5) and 36.5 or (diff == 4 or diff == 6) and 20.5 or 30\n        aura_env.StartCD(aura_env.totemTime - 5)\n    end\nend",
