["sparkWidth"] = 10,
["sparkOffsetX"] = 0,
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["adjustedMax"] = "",
["customText"] = "function()\n    local state = aura_env.state\n    if not state then return end\n    \n    local unitName = state.unitName\n    local index = state.index\n    \n    if not (unitName and index) then return end\n    \n    return string.format('|cff9d9d9d%d.|r %s', index, aura_env.GetClassColorName(unitName))\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["spark"] = false,
["iconSource"] = -1,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://space.bilibili.com/455259",
["icon"] = false,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    isPlayer = {\n        type = 'bool',\n        display = 'Is Player',\n    },\n    \n    isActive = {\n        type = 'bool',\n        display = 'Is Active Step',\n    },\n    \n    isNext = {\n        type = 'bool',\n        display = 'Is Unit Next',\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    if event == 'PHEROMONES_ORDER' then\n        local order = ...\n        aura_env.order = order\n        aura_env.nextUnitName = nil\n        aura_env.currentCarrier = nil\n        \n        if not order or #order == 0 then return end\n        \n        for i = 1, #order do\n            local unitName = order[i]\n            if unitName then\n                states:Update(unitName, {\n                        index = i,\n                        unitName = unitName,\n                        isPlayer = unitName == WeakAuras.me,\n                        isActive = false,\n                        isNext = false,\n                })\n            end\n        end\n        \n        if #order > 1 then\n            local nextName = order[2]\n            if states[nextName] then\n                states:Update(nextName, { isNext = true })\n                aura_env.SendDestName(nextName)\n                aura_env.nextUnitName = nextName\n            end\n        end\n        \n        return true\n        \n    elseif event == 'PHEROMONES_APPLIED' then\n        local destGUID = ...\n        if not destGUID then return end\n        \n        local destName = select(6, GetPlayerInfoByGUID(destGUID))\n        if not destName then return end\n        \n        local prevCarrier = aura_env.currentCarrier\n        if prevCarrier and states[prevCarrier] then\n            states:Remove(prevCarrier)\n            states[prevCarrier] = nil\n        end\n        \n        aura_env.currentCarrier = destName\n        \n        if states[destName] then\n            states:Update(destName, {\n                    isActive = true,\n                    isNext = false\n            })\n        end\n        \n        if states[destName] and states[destName].index then\n            local currentIndex = states[destName].index\n            \n            for unitName, state in pairs(states) do\n                \n                if state.index == currentIndex + 1 then\n                    aura_env.nextUnitName = unitName\n                    states:Update(unitName, { isNext = true })\n                    aura_env.SendDestName(unitName)\n                    break\n                end\n            end\n        end\n        \n        return true\n        \n    elseif event == 'OPTIONS' then\n        local unitNames = { WeakAuras.me, 'Exander', 'Scarpa', 'Devil', 'Julius' }\n        aura_env.order = unitNames\n        aura_env.currentCarrier = nil\n        aura_env.nextUnitName = nil\n        \n        for i, unitName in ipairs(unitNames) do\n            states:Update(unitName, {\n                    index = i,\n                    unitName = unitName,\n                    isPlayer = unitName == WeakAuras.me,\n                    isActive = (i == 1),\n                    isNext = false,\n            })\n        end\n        \n        if #unitNames > 1 then\n            local nextName = unitNames[2]\n            if states[nextName] then\n                states:Update(nextName, { isNext = true })\n                aura_env.SendDestName(nextName)\n                aura_env.nextUnitName = nextName\n            end\n        end\n    end\nend",
