["custom"] = "aura_env.GetClassColorName = function(name)\n    local _, class = UnitClass(name)\n    local color = RAID_CLASS_COLORS[class]\n    if color then\n        return string.format(\"|cFF%02X%02X%02X%s|r\", color.r * 255, color.g * 255, color.b * 255, name)\n    else\n        return name\n    end\nend\n\naura_env.SendDestName = function(destName)\n    WeakAuras.ScanEvents('PHEROMONES_NEXT_DEST', destName)\nend",
