["init"] = {
["custom"] = "local UnitGUID = UnitGUID\nlocal UnitExists = UnitExists\nlocal GetNamePlates = C_NamePlate.GetNamePlates\nlocal GetSpellInfo = GetSpellInfo\n\nlocal icons = {}\nlocal GetSpellIcon = function(spellId)\n    if not icons[spellId] then\n        local _,_, icon = GetSpellInfo(spellId)\n        icons[spellId] = icon\n    end\n    return icons[spellId]\nend\n\naura_env.GetNameplateId = function(guid) \n    local nameplates = GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        local nameplateId = plateData.UnitFrame.displayedUnit\n        local nameplateGUID = UnitExists(nameplateId) and UnitGUID(nameplateId)\n        if nameplateGUID == guid then\n            return nameplateId\n        end\n    end\nend\n\naura_env['COMBAT_LOG_EVENT_UNFILTERED'] = function(a, _,_,_, sourceGUID, sourceName,_,_, destGUID, destName, _,_, spellId, spellName,_,interruptId)\n    local nameplateId = aura_env.GetNameplateId(destGUID)\n    if not nameplateId then return end\n    a[sourceName] = {\n        show = true,\n        changed = true,\n        progressType = 'timed',\n        duration = 3,\n        expirationTime = 3 + GetTime(),\n        autoHide = true,\n        unit = nameplateId,\n        icon = GetSpellIcon(spellId),\n        sourceName = sourceName,\n    }\n    return true\nend\n\naura_env['OPTIONS'] = function(a)\n    a[''] = {\n        show = true,\n        changed = true,\n        progressType = 'timed',\n        duration = 3,\n        expirationTime = 3,\n        autoHide = true,\n        --unit = nameplateId,\n        icon = GetSpellIcon(15487),\n        sourceName = WeakAuras.me,\n    }\n    return true\nend\n\naura_env['STATUS'] = function()\nend",
