["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1390'\nlocal ID          = 'Wildfire'\n\nlocal name, icon = C_Spell.GetSpellName(116793), C_Spell.GetSpellTexture(116793)\n\nlocal options = {\n    ['Wildfire'] = {\n        warningText = '%icon @cffff8b17%name@r » %destName %icon',\n    },\n    ['WildfireGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    },\n}\n\naura_env.SendWarning = function(ID, destName)\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = destName and WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then \n            if spellID == 116793 and destGUID == WeakAuras.myGUID \n            and not aura_env.IsSpam(2) then\n                aura_env.SendWarning('WildfireGTFO')\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 116784 then\n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning('Wildfire', destName)\n                end\n                \n                aura_env.RaidIcon('SET', destName, 1)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 116784 then\n                aura_env.RaidIcon('REMOVE', destName)\n            end\n        end\n    end\nend",
