{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    if event == 'WARNING' then\n        local _, warning = ...\n        if warning.ID == 'AnimatedProtector' then\n            if UnitExists('boss1') then\n                local hper = aura_env.GetUnitHealthPercent('boss1')\n                local idx  = aura_env.FindRangeIndex(hper)\n                if idx then\n                    aura_env.triggered[idx] = true\n                end\n            end\n            states:Remove('')\n            return true\n        end\n    end\n    \n    if event == 'OPTIONS' then\n        aura_env.triggered = {}\n        local name = C_EncounterJournal.GetSectionInfo(6224).title\n        states:Update('', {\n                progressType = 'static',\n                total        = 5,\n                value        = 2.6,\n                prefix       = name .. ' (2/4)',\n        })\n        return\n    end\n    \n    if not UnitExists('boss1') then\n        states:Remove('')\n        return\n    end\n    \n    local hper = aura_env.GetUnitHealthPercent('boss1')\n    \n    for i, range in ipairs(aura_env.ranges) do\n        local offset = aura_env.InRangeOffset(hper, range.min, range.max)\n        if offset then\n            if aura_env.triggered[i] then\n                states:Remove('')\n            else\n                states:Update('', {\n                        progressType = 'static',\n                        total        = 5,\n                        value        = offset,\n                        prefix       = range.prefix,\n                })\n            end\n            return\n        end\n    end\n    \n    states:Remove('')\nend",
["names"] = {
},
["check"] = "event",
["events"] = "UNIT_HEALTH:boss1, MERFIN_WARNING",
