["init"] = {
["custom"] = "local UnitHealth, UnitHealthMax = UnitHealth, UnitHealthMax\n\naura_env.GetUnitHealthPercent = function(unit)\n    local health = UnitHealth(unit)\n    local maxHealth = UnitHealthMax(unit)\n    if maxHealth == 0 then\n        return 0\n    end\n    return (health / maxHealth) * 100\nend\n\naura_env.InRangeOffset = function(value, min, max)\n    if value >= min and value < max then\n        return value - min\n    end\n    return nil\nend\n\naura_env.FindRangeIndex = function(value)\n    for i, r in ipairs(aura_env.ranges) do\n        if value >= r.min and value < r.max then\n            return i\n        end\n    end\nend\n\naura_env.icon = \"|T135862:16:16:0:0:64:64:5:59:5:59|t\"\n\nlocal name = C_EncounterJournal.GetSectionInfo(6224).title\n\naura_env.ranges = {\n    {min = 80.5, max = 85, prefix = name .. ' (1/4)'},\n    {min = 60.5, max = 65, prefix = name .. ' (2/4)'},\n    {min = 40.5, max = 45, prefix = name .. ' (3/4)'},\n    {min = 20.5, max = 25, prefix = name .. ' (4/4)'},\n}\n\naura_env.triggered = aura_env.triggered or {}",
["do_custom"] = true,
