["法系命中（含精准）"] = {
["outline"] = "OUTLINE",
["wagoID"] = "ML4lRsH-M",
["parent"] = "【通用】角色属性（MOP）修改：露露 & Ekkles",
["displayText"] = "%n",
["customText"] = "\n\n",
["shadowYOffset"] = 0,
["anchorPoint"] = "CENTER",
["customTextUpdate"] = "update",
["url"] = "",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.text = aura_env.text or \"\"",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["unit"] = "player",
["event"] = "Health",
["names"] = {
},
["subeventPrefix"] = "SPELL",
["customName"] = "function()\n    return aura_env.text\nend",
["custom"] = "function()\n    -- Why do you always make it so complicated Blizzard?\n    \n    local SPELL_HIT_CAP = 15.00\n    \n    -- Define colors\n    local color_white = \"|cFFFFFFFF\"\n    local color_purple = \"|cFFFFFFFF\"\n    local color_red = \"|cFFFF0000\"\n    local color_orange = \"|cFFFF8800\"\n    local color_yellow = \"|cFFFFFF00\"\n    local color_green = \"|cFF00FF00\"\n    \n    -- Get spell hit rating and percentage\n    local spellHitRating = GetCombatRating(8) or 0\n    local spellHitPercent = GetCombatRatingBonus(8) or 0\n    \n    -- Get total expertise percentage\n    local totalExpertisePercent = GetExpertise() or 0\n    \n    -- Check for Gnome racial bonus\n    local _, race = UnitRace(\"player\")\n    local racialExpertiseBonus = 0\n    local racialIcon = \"\"\n    \n    if race == \"Gnome\" then\n        local mainHandLink = GetInventoryItemLink(\"player\", 16)\n        local offHandLink = GetInventoryItemLink(\"player\", 17)\n        \n        local hasDaggerOrSword = false\n        \n        if mainHandLink then\n            local _, _, _, _, _, _, subType = GetItemInfo(mainHandLink)\n            if subType == \"Daggers\" or subType == \"One-Handed Swords\" then\n                hasDaggerOrSword = true\n            end\n        end\n        \n        if offHandLink and not hasDaggerOrSword then\n            local _, _, _, _, _, _, subType = GetItemInfo(offHandLink)\n            if subType == \"Daggers\" or subType == \"One-Handed Swords\" then\n                hasDaggerOrSword = true\n            end\n        end\n        \n        if hasDaggerOrSword then\n            racialExpertiseBonus = 1.0  -- Gnome racial gives +1% expertise with daggers/swords\n            racialIcon = \" |TInterface\\\\Icons\\\\INV_Weapon_ShortBlade_25:16:16:0:0:64:64:4:60:4:60|t\"\n        end\n    end\n    \n    -- Calculate gear expertise (total - racial)\n    local gearExpertisePercent = totalExpertisePercent - racialExpertiseBonus\n    \n    -- Calculate gear expertise rating equivalent\n    local gearExpertiseRating = 0\n    if gearExpertisePercent > 0 and spellHitRating > 0 and spellHitPercent > 0 then\n        local ratingPerPercent = spellHitRating / spellHitPercent\n        gearExpertiseRating = math.floor(gearExpertisePercent * ratingPerPercent + 0.5)\n    elseif gearExpertisePercent > 0 then\n        -- Fallback: Use approximate MoP rating conversion\n        gearExpertiseRating = math.floor(gearExpertisePercent * 102.45 + 0.5)\n    end\n    \n    -- Calculate racial expertise rating equivalent\n    local racialExpertiseRating = 0\n    if racialExpertiseBonus > 0 then\n        if spellHitRating > 0 and spellHitPercent > 0 then\n            local ratingPerPercent = spellHitRating / spellHitPercent\n            racialExpertiseRating = math.floor(racialExpertiseBonus * ratingPerPercent + 0.5)\n        else\n            racialExpertiseRating = math.floor(racialExpertiseBonus * 102.45 + 0.5)\n        end\n    end\n    \n    -- Get spell hit modifier from talents/buffs\n    local spellHitBonus = 0\n    if GetSpellHitModifier then\n        spellHitBonus = GetSpellHitModifier() or 0\n    end\n    \n    -- Calculate total hit\n    local totalHitPercent = spellHitPercent + totalExpertisePercent + spellHitBonus\n    local totalRating = spellHitRating + gearExpertiseRating + racialExpertiseRating\n    \n    -- Determine gradient color for total percentage only\n    local hitColor\n    local percentOfCap = totalHitPercent / SPELL_HIT_CAP\n    \n    if percentOfCap >= 1.0 then\n        hitColor = color_green\n    elseif percentOfCap >= 0.9 then\n        hitColor = color_yellow\n    elseif percentOfCap >= 0.7 then\n        hitColor = color_orange\n    else\n        hitColor = color_red\n    end\n    \n    -- Display with updated colors\n    if totalExpertisePercent > 0 then\n        local expertiseRatingText\n        if racialExpertiseRating > 0 then\n            expertiseRatingText = string.format(\"(%d+%d)\", gearExpertiseRating, racialExpertiseRating)\n        else\n            expertiseRatingText = string.format(\"(%d)\", gearExpertiseRating)\n        end\n        \n        --aura_env.text = string.format(\"命中 %s%.2f%%|r %s(%d)|r\\n精准 %s%.2f%%|r %s%s|r%s\\n%s总命中|r %s%.2f%%|r %s(%d)|r\",\n        aura_env.text = string.format(\"命中|r %s%.2f%%|r %s|r\",\n            color_white,\n            spellHitPercent,\n            color_purple,\n            spellHitRating,\n            color_white,\n            totalExpertisePercent,\n            color_purple,\n            expertiseRatingText,\n            racialIcon,\n            color_white,\n            hitColor,\n            totalHitPercent,\n            color_purple,\n            totalRating\n        )\n    else\n        -- aura_env.text = string.format(\"命中 %s%.2f%%|r %s(%d)|r\\n%s总命中|r %s%.2f%%|r %s(%d)|r\", \n        aura_env.text = string.format(\"命中|r %s%.2f%%|r %s|r\", \n            color_white,\n            spellHitPercent,\n            color_purple,\n            spellHitRating,\n            color_white,\n            hitColor,\n            totalHitPercent,\n            color_purple,\n            spellHitRating\n        )\n    end\n    \n    return true\nend",
