["type"] = "custom",
["custom"] = "function(states, event, encounterID, cooldown, config)\n    \n    if event == 'OPTIONS' then\n        local newState = {\n            progressType   = 'timed',\n            autoHide       = true,\n            duration       = 5,\n            expirationTime = 5 + GetTime(),\n            name           = '|cffffffff' .. Merfin:L('BIG BANG') .. '|r',\n        }\n        states:Update('', newState)\n    end\n    \n    if event == 'MERFIN_PREWARNING_SHOW' then\n        if not config.pwText then return end\n        \n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        local remaining = cooldown.expirationTime - GetTime()\n        local name = string.format('|c%s%s|r', cooldown.color or 'ffffffff', cooldown.rawName:upper())\n        local sourceName = cooldown.sourceName and cooldown.sourceName:upper()\n        \n        local newState = {\n            show            = true,\n            changed         = true,\n            progressType    = 'timed',\n            autoHide        = true,\n            duration        = remaining,\n            expirationTime  = remaining + GetTime(),\n            name            = name,\n            enableCountdown = cooldown.countdown,\n            voiceActorIndex = cooldown.voiceActorIndex,\n            sourceName      = sourceName,\n            hasSrcName      = sourceName ~= nil,\n        }\n        states:Update(stateName, newState)\n    end\n    \n    \n    if event == 'MERFIN_PREWARNING_HIDE' then\n        local stateName = encounterID .. cooldown.ID  .. (cooldown.GUID or '')\n        states:Remove(stateName)\n    end\n    \nend",
["events"] = "MERFIN_PREWARNING_SHOW, MERFIN_PREWARNING_HIDE",
