["[DP] [Protectors] Cleansing Waters"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1409'\nlocal ID = 'CleansingWaters'\n\nlocal name, icon = C_Spell.GetSpellName(117309), C_Spell.GetSpellTexture(117309)\n\nlocal options = {\n    ['CleansingWaters'] = {warningText = \"%icon @cffffff80%name@r » %destName %icon\"},\n    ['CleansingWatersTarget'] = {warningText = \"@cffff9f40name@r » %destName\"},\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            destName = destName\n    }, options[ID])\nend\n\naura_env.GetTarget = function(GUID)\n    local stformat = string.format\n    local unitIDPool = {\n        \"boss1\", \"boss2\", \"boss3\", \"boss4\", \"target\", \"focus\", \"mouseover\"\n    }\n    \n    for _, unitID in ipairs(unitIDPool) do\n        if UnitExists(unitID) and UnitGUID(unitID) == GUID then\n            local targetUnitID = stformat(\"%starget\", unitID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        if plateData.namePlateUnitGUID == GUID then\n            local nameplateID = plateData.UnitFrame.displayedUnit\n            local targetUnitID = stformat(\"%starget\", nameplateID)\n            return targetUnitID, UnitName(targetUnitID)\n        end\n    end\n    for unitID in WA_IterateGroupMembers() do\n        local targetUnitID = stformat(\"%starget\", unitID)\n        if UnitExists(targetUnitID) and UnitGUID(targetUnitID) == GUID then\n            return stformat(\"%starget\", targetunitID)\n        end\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 117309 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(32.5)\n                \n                local ticker\n                ticker = C_Timer.NewTicker(0.1, function()\n                        local targetID, targetName = aura_env.GetTarget(sourceGUID)\n                        if targetID then\n                            aura_env.SendWarning('CleansingWaters', targetName)\n                            if targetName == UnitName('target') then\n                                aura_env.SendWarning('CleansingWatersTarget', targetName)\n                            end\n                            ticker:Cancel()\n                        end\n                end, 15)\n                aura_env.targetScanner = ticker\n            end\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        if npcID == 60586 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(10)\n    end\nend",
