["[DP] [Gara'jal] Banishment"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1434'\nlocal ID          = 'Banishment'\n\nlocal name, icon = C_Spell.GetSpellName(116272), C_Spell.GetSpellTexture(116272)\n\nlocal options = {\n    ['Banishment'] = {\n        warningText = '%icon @cffffff80%name@r » %destName (%count) %icon'\n    },\n    ['BanishmentOnYou'] = {\n        warningText = '@cffff4040%upper:name@r »' .. WA_ClassColorName(WeakAuras.me) .. '«'\n    },\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            count          = aura_env.count,\n            name           = name,\n            icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['Banishment'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    local colorized = WA_ClassColorName(destName)\n    colorized = colorized ~= '' or destName\n    local data = {\n            ID       = ID,\n            count    = aura_env.count,\n            destName = colorized,\n            name     = name,\n            icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.Synch = function(...)\n    WeakAuras.ScanEvents('MERFIN_SYNCH', 'RAID', nil, 'BANISHMENT_SYNCH', ...) \nend\n\naura_env.LatencyCheck = function()\n    return select(4, GetNetStats()) < 250\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if spellID == 116272 then\n            if not aura_env.LatencyCheck() then return end\n            if not destGUID then return end\n            \n            local destName = select(6, GetPlayerInfoByGUID(destGUID))\n            \n            if not destName or destName == '' then \n                return \n            end\n            \n            aura_env.Synch(destName)\n        end\n        \n    elseif e == 'BANISHMENT_SYNCH' then\n        local destName = ...\n        \n        if not destName or destName == '' then \n            return \n        end\n        \n        aura_env.count = aura_env.count + 1\n        aura_env.StartCD(65)\n        \n        if WeakAuras.me == destName then\n            aura_env.SendWarning('BanishmentOnYou', destName)\n        else\n            aura_env.SendWarning('Banishment', destName)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(65)\n    end\nend",
