["init"] = {
["custom"] = "local encounterID = '1505'\n\nlocal phaseNames = {\n    ['DayPhase'] = {name = Merfin.GetTitleEJ(6315), icon = 135981},\n    ['NightPhase'] = {name = Merfin.GetTitleEJ(6310), icon = 136223}\n}\n\nlocal options = {\n    ['DayPhase'] = {warningText = '@cffe3e3e3%upper:name@r', prewarnCountVA = 2},\n    ['NightPhase'] = {warningText = '@cffe3e3e3%upper:name@r', prewarnCountVA = 2}\n}\n\naura_env.MRT = function(event) GMRT.F.Note_Timer(event) end\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = phaseNames[ID].name,\n        icon = phaseNames[ID].icon\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options[ID])\nend\n\naura_env.SendWarning = function(ID)\n    local data = {ID = ID, name = phaseNames[ID].name}\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 123252 then\n            aura_env.StopCD('DayPhase')\n            WeakAuras.ScanEvents('TSULONG_PHASE', 'DayPhase')\n            aura_env.SendWarning('DayPhase')\n            aura_env.StartCD('NightPhase', 121)\n            aura_env.MRT('DAY')\n            \n        elseif spellID == 122767 then\n            aura_env.StopCD('NightPhase')\n            WeakAuras.ScanEvents('TSULONG_PHASE', 'NightPhase')\n            aura_env.SendWarning('NightPhase')\n            aura_env.StartCD('DayPhase', 121)\n            aura_env.MRT('NIGHT')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        WeakAuras.ScanEvents('TSULONG_PHASE', 'NightPhase', true)\n        aura_env.StartCD('DayPhase', 121)\n    end\nend",
