["custom"] = "local encounterID = '1407'\nlocal ID          = 'TitanGas'\n\nlocal name, icon = C_Spell.GetSpellName(116779), C_Spell.GetSpellTexture(116779)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r %icon\",\n}\n\naura_env.StartCD = function(duration)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'TITAN_GAS' then\n        aura_env.count = aura_env.count + 1\n        aura_env.SendWarning()\n        if aura_env.count < 4 then\n            aura_env.StartCD(150)\n        end\n        \n    elseif e == 'ADD_ACTIVATION' then\n        local add = ...\n        if add == 'BOSSES' then\n            aura_env.StartCD(113)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
