["[DP] [TSG] Petrification"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1395'\nlocal ID          = 'Petrification'\n\nlocal name = C_Spell.GetSpellName(84591)\nlocal icon = C_Spell.GetSpellTexture(125091)\n\nlocal options = {\n    warningText = '%icon %name %icon',\n    prewarnCountVA = 1,\n}\n\nlocal extraTypes = {\n    COBALT   = { 115852, '001E90FF' },\n    JADE     = { 116006, '00008000' },\n    JASPER   = { 116036, '00FF0000' },\n    AMETHYST = { 116057, '00FF44FF' },\n}\n\nlocal extra = {}\nfor ID, data in pairs(extraTypes) do\n    local spellID, color = data[1], data[2]\n    local name, icon = C_Spell.GetSpellName(spellID), C_Spell.GetSpellTexture(spellID)\n    extra[ID] = {\n        name = string.format('|c%s%s|r', color, name),\n        icon = icon\n    }\nend\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        color          = color\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function(extraID)\n    local data = {\n        ID           = ID,\n        count        = aura_env.count,\n        name         = extra[extraID].name,\n        icon         = extra[extraID].icon,\n        color        = color,\n        extraID      = extraID,\n        localization = localization,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.PetrificationID = {\n    [115852] = 'COBALT',\n    [116006] = 'JADE',\n    [116036] = 'JASPER',\n    [116057] = 'AMETHYST'\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        if not spellID then return end\n        \n        local type = aura_env.PetrificationID[spellID]\n        if type then\n            aura_env.count = aura_env.count + 1\n            aura_env.StartCD(76)\n            aura_env.SendWarning(type)\n            aura_env.activePetr = type\n        end\n        \n    elseif e == 'GUARDS_OVERLOAD' then\n        local type = ...\n        if type == aura_env.activePetr then\n            aura_env.StopCD()\n            aura_env.activePetr = 'NONE'\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(5)\n    end\nend",
