["custom"] = "function(e, scheduledEvent, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 107268 then\n                aura_env.StartCD('Sabotage', 12, false, true)\n                if destName == WeakAuras.me then\n                else\n                    aura_env.Warning('SabotageAppled', destName)\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('Sabotage', 15.7)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
