["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if spellID == 116161 or spellID == 116260 then\n            if not aura_env.LatencyCheck() then return end\n            if not destGUID then return end\n            \n            local destName = select(6, GetPlayerInfoByGUID(destGUID))\n            \n            if not destName or destName == '' then \n                return \n            end\n            \n            aura_env.Synch('CROSSED_OVER_SYNCH', destName)\n        end\n        \n    elseif e == 'CROSSED_OVER_SYNCH' then\n        local destName = ...\n        \n        if not destName or destName == '' then \n            return \n        end\n        \n        for _, name in ipairs(aura_env.targets) do\n            if destName == name then\n                return\n            end\n        end\n        \n        table.insert(aura_env.targets, destName)\n        \n        if aura_env.IsSpam(3) then\n            return\n        end\n        \n        C_Timer.After(0.3, function()\n                aura_env.count = aura_env.count + 1\n                \n                local names = {}\n                for _, name in ipairs(aura_env.targets) do\n                    table.insert(names, WA_ClassColorName(name))\n                end\n                \n                local destNames = table.concat(names, ', ')\n                aura_env.SendWarning(destNames)\n                aura_env.targets = {}\n        end)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.targets = {}\n        aura_env.count = 0\n    end\nend",
