["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        states:Update('', {\n                progressType   = 'timed',\n                duration       = 3,\n                expirationTime = 3 + GetTime(),\n                name           = C_Spell.GetSpellName(118105), \n                count          = 2\n        })\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated = ...\n        \n        if bossID == 'SUBETAI' and not activated then\n            states:Remove('')\n        end\n        \n    elseif e == 'MERFIN_WARNING' then\n        local _, warning = ...\n        if warning.ID == 'Volley' then\n            aura_env.name  = warning.name\n            aura_env.count = warning.count\n        end\n        \n    elseif e == 'SUBETAI_VOLLEY_START' then\n        if not states[''] then \n            states:Update('', {\n                    progressType   = 'timed',\n                    duration       = 3,\n                    expirationTime = 3 + GetTime(),\n                    autoHide       = true,\n                    name           = aura_env.name, \n                    count          = aura_env.count,\n                    subCount       = 1,\n            })\n            \n            C_Timer.After(6, function() WeakAuras.ScanEvents('FAIL_SAFE_HIDE_VOLLEY') end)\n            \n        else\n            states[''].subCount = states[''].subCount + 1\n            states[''].paused = false\n            states[''].expirationTime = states[''].remaining + GetTime()\n            states[''].changed = true\n            return true\n        end\n        \n    elseif e == 'FAIL_SAFE_HIDE_VOLLEY' then\n        states:Remove('')\n        \n    elseif e == 'SUBETAI_VOLLEY_PAUSED' then\n        if states[''] and states[''].subCount < 3 then\n            states[''].paused = true\n            states[''].remaining = states[''].expirationTime - GetTime()\n            states[''].changed = true\n            return true\n        end\n    end\nend",
