["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 106942 then\n                aura_env.Warning('ShadowsOfDestruction')\n                aura_env.StartCD('ShadowsOfDestruction', 20, true, true, sourceGUID)\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'DestroyingSha') then\n                aura_env.StopCD('ShadowsOfDestruction', destGUID)\n            end\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_YELL' then\n        if aura_env.IsEmote(msg, 'MasterRoleplay2') then\n            aura_env.Warning('MasterRoleplay2')\n            aura_env.TTS('Stage 2')\n        elseif aura_env.IsEmote(msg, 'MasterRoleplay3') then\n            aura_env.Warning('MasterRoleplay3')\n            aura_env.TTS('Stage 3')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
