["custom"] = "local encounterID = '1409'\nlocal ID = 'LightningPrison'\n\nlocal name, icon = C_Spell.GetSpellName(117436), C_Spell.GetSpellTexture(117436)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    prewarnTTStext = Merfin:L('Debuffs Soon'),\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            destName = destName\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 111850 then\n                if not aura_env.IsSpam(3) then\n                    aura_env.count = aura_env.count + 1\n                    C_Timer.After(0.3, function()\n                            local names = {}\n                            for _, name in ipairs(aura_env.targets) do\n                                table.insert(names, WA_ClassColorName(name))\n                            end\n                            \n                            local destNames = table.concat(names, ', ')\n                            \n                            aura_env.SendWarning(destNames)\n                            aura_env.targets = {}\n                            aura_env.StartCD(25)\n                    end)\n                end\n                \n                table.insert(aura_env.targets, destName) \n            end\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        if npcID == 60585 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n        aura_env.StartCD(15.5)\n    end\nend",
