["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID = 'AmberTrap'\n\nlocal GetSpellInfoTable = function(spellID)\n    return {\n        name = C_Spell.GetSpellName(spellID),\n        icon = C_Spell.GetSpellTexture(spellID)\n    }\nend\n\nlocal options = {\n    ['AmberTrap'] = {warningText = \"%icon @cffffff80%name@r %icon\"},\n    ['Trapped'] = {warningText = \"%icon @cffffff80%name@r » %destName %icon\"},\n    ['Resin'] = {warningText = \"%icon @cffffff80%name@r » %destName %icon\"}\n}\n\nlocal data = {\n    ['AmberTrap'] = GetSpellInfoTable(124748),\n    ['Trapped'] = GetSpellInfoTable(125822),\n    ['Resin'] = GetSpellInfoTable(124097)\n}\n\naura_env.SendWarning = function(ID, destName, amount)\n    local colDestName = destName and\n    (UnitInRaid(destName) and\n        WA_ClassColorName(destName) or destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            count = aura_env.count,\n            destName = colDestName,\n            amount = amount\n    }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID, spellName,_,_, amount = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 124748 then -- Amber Trap\n                aura_env.resinTargets = {}\n                aura_env.SendWarning('AmberTrap', nil, amount or 1)\n            elseif spellID == 125822 then -- Trapped!\n                aura_env.SendWarning('Trapped', destName)\n            elseif spellID == 124097 then -- Sticky Resin\n                if not aura_env.resinTargets[destName] then\n                    aura_env.resinTargets[destName] = true\n                    aura_env.SendWarning('Resin', destName)\n                    \n                    if destName == WeakAuras.me then\n                        WeakAuras.ScanEvents('MERFIN_TTS', spellName)\n                    end\n                end\n            end\n        end\n    elseif e == 'ENCOUNTER_START' then\n        aura_env.resinTargets = {}\n    end\nend",
