["value"] = "function()\n    -- Chat Message\n    if WeakAuras.IsOptionsOpen() then return end\n    if not aura_env.state then return end\n    if aura_env.stacks > 5 then return end\n    \n    local now = GetTime()\n    if now - (aura_env.lastChatUpdate or 0) <= 1 then return end\n    \n    aura_env.lastChatUpdate = now\n    \n    local destName = aura_env.destName\n    if not destName then return end\n    \n    local remainingSeconds = math.ceil(aura_env.state.expirationTime - now)\n    if remainingSeconds > 5 or remainingSeconds <= 0 then return end\n    \n    local msg = destName .. ' ' .. remainingSeconds\n    \n    WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', msg, 'YELL')\nend",
