["[DP] [Tsulong] The Dark of Night"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'DarkOfNight'\n\nlocal function GetSpellInfoTable(spellID)\n    if WeakAuras.IsRetail() then\n        return C_Spell.GetSpellName(spellID), C_Spell.GetSpellTexture(spellID)\n    else\n        local name, _, icon = GetSpellInfo(spellID)\n        return name, icon\n    end\nend\n\nlocal name, icon = GetSpellInfoTable(130013)\n\nlocal options = {\n    warningText = '@cffff4040%upper:name@r', \n    ttsLine = Merfin:L('Adds')\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {ID = ID, name = name, icon = icon, count = aura_env.count}\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 123813 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            aura_env.StartCD(30.5)\n        end\n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID, initial = ...\n        \n        if phaseID == 'NightPhase' then\n            aura_env.nightLast = GetTime()\n            \n            if not initial then\n                aura_env.count = 0\n                aura_env.StartCD(10)\n            end\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(10)\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, UNIT_SPELLCAST_SUCCEEDED:boss1:boss2:boss3, TSULONG_PHASE",
