["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Al'Akir\n\nlocal ENTRY = aura_env\nlocal encounterId = 1034\n\nlocal localized = {\n    ['enUS'] = {},\n    ['ruRU'] = {},\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    ice_storm =        { 88239 },\n    squall_line =      { 91129 },\n    wind_burst =       { 87770 },\n    stormling =        { 88272 },\n    acid_rain =        { 88301 },\n    feedback =         { 87904 },\n    lightning_clouds = { 89588 },\n    lightning_rod =    { 89668 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\nlocal Schedule = function(after, func, mechanic, ...) CORE.Schedule(ENTRY, mechanic, after, func, ...) end\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCOREInit = false\nlocal isEncounter = false\n\nlocal cinderTargets = {}\nlocal dominionTargets = {}\n\nlocal IsEntryInitialized = function()\n    return isCOREInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCOREInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCOREInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START']()\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal isPhase2\n\nENTRY.CloudRepeat = function()\n    \n    ENTRY.CASTS.clouds = ENTRY.CASTS.clouds + 1\n    if ENTRY.CASTS.clouds < 3 then\n        WeakAuras.ScanEvents('SHORT')\n    else\n        ENTRY.CASTS.clouds = 0\n        WeakAuras.ScanEvents('LONG')\n    end\n    \n    Warning('lightning_clouds')\n    local timer = IsDifficulty('10_HEROIC', '25_HEROIC') and 10 or 15\n    Cooldown('lightning_clouds', timer); PreWarning('lightning_clouds', timer-5)\n    Schedule(timer, ENTRY.CloudRepeat, 'cloudRepeat')\nend\n\nlocal Phase2 = function()\n    CORE.SetStage(ENTRY, 2)\n    Cancel('wind_burst', 'ALL')\n    Cancel('ice_storm', 'ALL')\nend\n\nlocal Phase3 = function()\n    CORE.SetStage(ENTRY, 3)\n    \n    ENTRY.CASTS.clouds = 0\n    \n    Cooldown('lightning_clouds', 15.5); PreWarning('lightning_clouds', 10.5)\n    Cooldown('wind_burst', 25)\n    Cooldown('lightning_rod', 20)\n    \n    Cancel('stormling', 'ALL')\n    Cancel('squall_line', 'ALL')\n    Cancel('acid_rain', 'ALL')\nend\n\nENTRY['ON_COMBAT_START'] = function()\n    ENTRY.CASTS.rain = 0\n    ENTRY.CASTS.stormling = 0\n    isPhase2 = false\n    CORE.SetStage(ENTRY, 1)\n    Cooldown('berserk', 600)\n    Cooldown('wind_burst', 26.5); PreWarning('wind_burst', 21.5)\n    Cooldown('ice_storm', 5.5)\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 87770 then\n        SpecialWarning('wind_burst')\n        Cooldown('wind_burst', 30); PreWarning('wind_burst', 25)\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Timer('wind_burst', 4)\n        else\n            Timer('wind_burst', 5)\n        end\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 87904 then\n        Warning('feedback', args.destName, args.amount or 1)\n    elseif args.spellId == 89668 then\n        Warning('lightning_rod', args.destName)\n        Timer('lightning_rod', 5, args.destName)\n        Cooldown('lightning_rod', 15)\n        if args.destGUID == CORE.PlayerGUID then\n            SpecialWarning('lightning_rod')\n        end\n    elseif args.spellId == 88301 and AntiSpam('acid_rain', 2) then\n        ENTRY.CASTS.rain = ENTRY.CASTS.rain + 1\n        if IsDifficulty('10_NORMAL', '25_NORMAL') then\n            Cooldown('acid_rain', 20)\n        else\n            Cooldown('acid_rain', 15)\n        end\n        if CORE.GetStage(ENTRY) ~= 2 then\n            ENTRY.CASTS.stormling = 1\n            Phase2()\n        end\n    end\nend\nENTRY['SPELL_AURA_APPLIED_DOSE'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 89668 then\n        Cancel('lightning_rod', 'TIMER')\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    -- Phase 3 Wind Burst\n    if args.spellId == 88858 and AntiSpam('wind_burst', 5) then\n        Warning('wind_burst')\n        Cooldown('wind_burst', 20)\n    elseif args.spellId == 89588 and args.destGUID == CORE.PlayerGUID and AntiSpam('lightning_clouds', 3) then\n        GTFO('lightning_clouds')\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['SPELL_PERIODIC_DAMAGE'] = function(args)\n    if spellId == 91020 and destGUID == CORE.PlayerGUID and AntiSpam('ice_storm', 4) then\n        GTFO('ice_storm')\n    end\nend\nENTRY['SPELL_PERIODIC_MISSED'] = ENTRY['SPELL_PERIODIC_DAMAGE']\n\nENTRY['UNIT_SPELLCAST_SUCCEEDED'] = function(unitId,_, spellId)\n    if spellId == 91129 and AntiSpam('squall_line', 2) then\n        Warning('squall_line')\n        if CORE.GetStage(ENTRY) ~= 2 then\n            Cooldown('squall_line', 30)\n        else\n            Cooldown('squall_line', 20)\n        end\n    elseif spellId == 88239 and AntiSpam('ice_storm', 2) then\n        Warning('ice_storm')\n        Cooldown('ice_storm', 20)\n        \n    elseif spellId == 88272 and AntiSpam('stormling', 2) then\n        if CORE.GetStage(ENTRY) ~= 2 then\n            ENTRY.CASTS.stormling = 1\n            Phase2()\n        end\n        ENTRY.CASTS.stormling = ENTRY.CASTS.stormling + 1\n        Warning('stormling')\n        Cooldown('stormling', 20, '', false, ENTRY.CASTS.stormling)\n        \n    elseif spellId == 89528 and AntiSpam('phase_3', 2) then\n        Phase3()\n    elseif spellId == 89639 and AntiSpam('lightning_clouds', 2) then\n        ENTRY.CloudRepeat()\n    end\nend \n\n",
["do_custom"] = true,
},
