},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Halifus Wyrmbreaker\n\nlocal ENTRY = aura_env\nlocal encounterId = 1030\n\nlocal localized = {\n    ['enUS'] = {\n        netherRelease = '%s binds the Nether Scion to his will!',\n        slateRelease =  '%s binds the Slate Dragon to his will!',\n        stormRelease =  '%s binds the Storm Rider to his will!',\n        whelpsRelease = '%s binds the Orphaned Emerald Whelp to his will!',\n        timeRelease =   '%s binds the Time Warden to his will!',\n    },\n    \n    ['ruRU'] = {\n        netherRelease = '%s подчиняет |3-3(Потомок рода Пустоты) своей воле!',\n        slateRelease =  '%s подчиняет |3-3(Сланцевый дракон) своей воле!',\n        stormRelease =  '%s подчиняет |3-3(Штормокрыл) своей воле!',\n        whelpsRelease = '%s подчиняет |3-3(Осиротевший изумрудный дракончик) своей воле!',\n        timeRelease =   '%s подчиняет |3-3(Страж времени) своей воле!',\n    },\n    \n    ['zhTW'] = {\n        netherRelease = '哈福斯‧破龍者迫使虛空幼體執行他的意志!',\n        slateRelease =  '哈福斯‧破龍者迫使石板龍執行他的意志!',\n        stormRelease =  '哈福斯‧破龍者迫使風暴騎士執行他的意志!',\n        whelpsRelease = '哈福斯‧破龍者迫使失怙的綠龍寶寶執行他的意志!',\n        timeRelease =   '哈福斯‧破龍者迫使時間看守者執行他的意志!',\n    },\n    ['zhCN'] = {\n        netherRelease = '哈尔弗斯·碎龙者迫使虚空之子服从他的意志！',\n        slateRelease =  '哈尔弗斯·碎龙者迫使岩龙服从他的意志！',\n        stormRelease =  '哈尔弗斯·碎龙者迫使风暴骑手服从他的意志！',\n        whelpsRelease = '哈尔弗斯·碎龙者迫使孤单的翡翠雏龙服从他的意志！',\n        timeRelease =   '哈尔弗斯·碎龙者迫使时光守卫服从他的意志！',\n    },  \n    \n    ['koKR'] = {\n        netherRelease = '%s는 황천의 후예를 자신의 의지에 묶습니다!',\n        slateRelease = '%s는 슬레이트 드래곤을 그의 의지에 묶습니다!',\n        stormRelease = '%s는 스톰 라이더를 자신의 의지에 묶습니다!',\n        whelpsRelease = '%s는 고아가 된 에메랄드 새끼용을 자신의 의지에 묶습니다!',\n        timeRelease = '%s는 시간 감시자를 그의 의지에 묶습니다!',\n    },\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    breath =             { 83707 },\n    breath_pre =         { 83707 },\n    vengeance =          { 87683 },\n    paralysis =          { 84030 },\n    mavelolent_strike =  { 83908 },\n    furious_roar =       { 83710 },\n    shadow_nova =        { 83703 },\n    fireball_barrage =   { 83706 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal phase2\n\nlocal furiousRoar = function()\n    Cancel('furious_roar', 'COOLDOWN')\n    Cooldown('furious_roar', 30)\nend\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    ENTRY.CASTS.roar = 0\n    ENTRY.CASTS.breath = 0\n    ENTRY.CASTS.whelps = 8\n    \n    Cooldown('berserk', 360-delay)\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('breath', 10-delay)\n        Cooldown('shadow_nova', 6.1-delay)\n    end\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 83707 then\n        Timer('breath', 8)\n    elseif args.spellId == 83703 then\n        WeakAuras.ScanEvents('SHADOW_NOVA', args.sourceGUID)\n    elseif args.spellId == 83706 then\n        Timer('fireball_barrage', 10)\n    end\nend\n\nENTRY['SPELL_INTERRUPT'] = function(args)\n    if args.interruptId == 83703 then\n        WeakAuras.ScanEvents('SHADOW_NOVA', args.destGUID)\n    end\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 83710  then\n        if AntiSpam('furious_roar', 6) then\n            ENTRY.CASTS.roar = ENTRY.CASTS.roar + 1\n            SpecialWarning('furious_roar')\n            Cancel('furious_roar', 'COOLDOWN')\n            Cooldown('furious_roar', 30)\n            Timer('furious_roar', 6)\n            CORE.Schedule(ENTRY, 'furious_roar', 30, furiousRoar)\n        end\n        \n    elseif args.spellId == 83707 then\n        ENTRY.CASTS.breath = ENTRY.CASTS.breath + 1\n        Warning('breath')\n        Timer('breath_pre', 2)\n        Cooldown('breath', 25)\n        \n    elseif args.spellId == 83703 then\n        Cooldown('shadow_nova', 7.2)\n        \n    elseif args.spellId == 83707 then\n        Cooldown('scorching_breath', 25)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 87683 then\n        Warning('vengeance', args.destName, args.amount or 1)\n    elseif args.spellId == 84030 then\n        Timer('paralysis', 12)\n        Cooldown('paralysis', 35)\n        PreWarning('paralysis', 30)\n        \n    elseif args.spellId == 83908 then\n        --mavelolent_strike\n    end\nend\nENTRY['SPELL_AURA_APPLIED_DOSE'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    \nend\n\nENTRY['UNIT_DIED'] = function(args)\n    local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n    if creatureId == 44645 then\n        WeakAuras.ScanEvents('DRAKE_DEAD', 1)\n    elseif creatureId == 44652 then\n        WeakAuras.ScanEvents('DRAKE_DEAD', 2)\n    elseif creatureId == 44650 then\n        WeakAuras.ScanEvents('DRAKE_DEAD', 3)\n    elseif creatureId == 44641 then\n        ENTRY.CASTS.whelps = ENTRY.CASTS.whelps - 1\n        WeakAuras.ScanEvents('DRAKE_DEAD', 4, ENTRY.CASTS.whelps)\n    elseif creatureId == 44797 then\n        WeakAuras.ScanEvents('DRAKE_DEAD', 5)\n    end\nend\n\nENTRY['CHAT_MSG_RAID_BOSS_EMOTE'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if L.netherRelease == msg or msg:find(L.netherRelease) then\n        WeakAuras.ScanEvents('DRAKE_ACTIVE', 1)\n    elseif L.slateRelease == msg or msg:find(L.slateRelease) then\n        WeakAuras.ScanEvents('DRAKE_ACTIVE', 2)\n        Cooldown('paralysis', 32)\n        PreWarning('paralysis', 27)\n    elseif L.stormRelease == msg or msg:find(L.stormRelease) then\n        WeakAuras.ScanEvents('DRAKE_ACTIVE', 3)\n    elseif L.whelpsRelease == msg or msg:find(L.whelpsRelease) then\n        WeakAuras.ScanEvents('DRAKE_ACTIVE', 4)\n    elseif L.timeRelease == msg or msg:find(L.timeRelease) then\n        WeakAuras.ScanEvents('DRAKE_ACTIVE', 5)\n    end\nend",
