["op"] = "FRAME_UPDATE",
["value"] = "function()\n    if WeakAuras.IsOptionsOpen() then return end\n    \n    if not Merfin or not Merfin.PlaySound then\n        return\n    end\n    \n    local curTime = GetTime()\n    if curTime - (aura_env.last or 0) > 1 then\n        aura_env.last = curTime\n        local remTime = math.ceil(aura_env.states[1].expirationTime - curTime)\n        if remTime <= 0 then return end\n        \n        if remTime == 5 then\n            Merfin.PlaySound('Explosion in')\n            return\n        end\n        \n        remTime = tostring(remTime)\n        \n        local voiceActor = Merfin.L  == 'ruRU' and 'Fondago' or 'Sally'\n        Merfin.PlaySound(voiceActor .. ' - ' .. remTime)\n    end\nend",
