["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1409'\nlocal ID = 'CorruptedEssence'\n\nlocal name, icon = C_Spell.GetSpellName(118191), C_Spell.GetSpellTexture(118191)\n\nlocal options = {\n    ['CorruptedEssence'] = {\n        warningText = \"%icon %name %icon\",\n    },\n    ['CorruptedEssenceHigh'] = {\n        warningText = \"@cffff4040%upper:name@r (x%amount)\",\n        ttsLine = Merfin:L('High Stacks')\n    }\n}\n\naura_env.SendWarning = function(ID, amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            amount = amount\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID,_,_,_, amount = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' \n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 118191 or spellID == 117905 then\n                if not aura_env.IsSpam(3) then\n                    aura_env.count = aura_env.count + 1\n                    aura_env.SendWarning('CorruptedEssence')\n                end\n                \n                local stacks = amount or 1\n                \n                if destGUID == WeakAuras.myGUID and stacks >= 8 then\n                    aura_env.SendWarning('CorruptedEssenceHigh', stacks)\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
