["[DP] [MV-Trash] Pre Kings Roleplays"] = {
["width"] = 200,
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["preferToUpdate"] = true,
["xOffset"] = 0,
["yOffset"] = 0,
["regionType"] = "empty",
["information"] = {
},
["anchorPoint"] = "CENTER",
["parent"] = "[DP] Trash (Mogu'shan Vaults)",
["selfPoint"] = "CENTER",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local L = GetLocale()\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        roleplay1 = \"Ah, the ancient Vaults of the Kings of Mogu'shan. What might this button do...?\",\n        roleplay2 = \"This looks to be the record of Qiang the Merciless, a great conqueror who ruled his vassals with an iron fist!\",\n        roleplay3 = \"I've heard tales of this one: Subetai the Swift, well known as a masterful archer and genius thief. He stole from the rich, and kept everything for himself.\",\n        roleplay4 = \"What is this? I've heard nothing of this emperor. Meng the Demented? According to these texts, Meng was the most foul and maniacal ruler to ever abuse the imperial throne.\"\n    },\n    \n    ['ruRU'] = {\n        roleplay1 = \"Ах, древние подземелья императоров Могу'шан. Интересно, что делает эта кнопка?..\",\n        roleplay2 = \"А это – запись о царствовании Цяна Безжалостного, великого правителя и беспощадного завоевателя.\",\n        roleplay3 = \"Я слышал предания о Субетае Быстром, искусном лучнике и непревзойденном воре. Помимо этого он был щедрым императором, прославившимся тем, что делился богатством с бедными.\",\n        roleplay4 = \"А это кто? Я ничего не знаю об этом императоре. Мын Безумный... Судя по текстам, он был самым ненормальным правителем из всех, что когда-либо сидели на троне.\"\n    },\n    \n    ['zhCN'] = {\n        roleplay1 = \"啊，魔古山帝王的宝库。这个按钮有什么用…? \",\n        roleplay2 = \"看上去这些就是无情战王齐昂的记录了。无数诸侯都曾臣服于其铁腕统治之下。\",\n        roleplay3 = \"对这个人物我有所耳闻：迅影匪王速不台。传闻中他是个精通箭术的神偷。他劫富却不济贫，将偷盗之物都归为己有。 \",\n        roleplay4 = \"这是什么？我还不曾听闻这个帝王。暴虐疯王蒙恩？根据这段描述，蒙恩是迄今为止最邪恶、最疯狂的暴君。\"\n    },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["duration"] = "25",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["spellIds"] = {
},
["custom"] = "function(event, ...)\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_, destGUID = ...\n        \n        if Merfin.GetNPCIDFromGUID(destGUID) == 61347 then\n            aura_env.counter = (aura_env.counter or 0) + 1\n            if aura_env.counter == 3 then\n                WeakAuras.ScanEvents('PRE_KINGS_ROLEPLAY', 23, 5)\n            end\n        end\n        \n    elseif event == 'CHAT_MSG_MONSTER_SAY' then\n        local msg = ...\n        if not msg then return end\n        \n        if aura_env.IsEmote(msg, 'roleplay1') then\n            WeakAuras.ScanEvents('PRE_KINGS_ROLEPLAY', 19.5, 1)\n            \n        elseif aura_env.IsEmote(msg, 'roleplay2') then\n            WeakAuras.ScanEvents('PRE_KINGS_ROLEPLAY', 7.5, 2)\n            \n        elseif aura_env.IsEmote(msg, 'roleplay3') then\n            WeakAuras.ScanEvents('PRE_KINGS_ROLEPLAY', 7.5, 3)\n            \n        elseif aura_env.IsEmote(msg, 'roleplay4') then\n            WeakAuras.ScanEvents('PRE_KINGS_ROLEPLAY', 7.5, 4)\n        end\n    end\nend",
