["init"] = {
["custom"] = "local encounterID = '1409'\nlocal ID = 'DefiledGround'\n\nlocal name, icon = C_Spell.GetSpellName(117988), C_Spell.GetSpellTexture(117988)\n\nlocal options = {\n    ['DefiledGround'] = {warningText = \"%icon @cffff8b17%name@r %icon\"},\n    ['DefiledGroundGTFO'] = {warningText = string.format(Merfin:L('GTFO'), name:upper())}\n}\n\nlocal LS = LibStub(\"LibSpecialization\")\n\nlocal IsMelee = function()\n    if LS then\n        local _, _, position = LS:MySpecialization()\n        return position == 'MELEE'\n    end\n    return true -- If Lib won't functions on BETA just return true alwasys\nend\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            noCountdown = not IsMelee()\n    }, options)\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 117986 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('DefiledGround')\n                aura_env.StartCD(15.5)\n            end\n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 117988 and destGUID == WeakAuras.myGUID and not aura_env.IsSpam(3) then\n                aura_env.SendWarning('DefiledGroundGTFO')\n            end\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 117975 then -- Expel Corruption\n                aura_env.StartCD(12)\n            end\n        end\n        \n    elseif e == 'PROTECTORS_PHASE_CHANGING' then\n        local npcID, phaseN = ...\n        \n        if npcID == 60583 and phaseN == 2 then\n            aura_env.StartCD(5)\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        if npcID == 60583 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
