["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1407'\nlocal ID          = 'EmperorPhase2'\n\nlocal name = Merfin:L('Phase 2')\nlocal icon = 625910\n\nlocal options = {\n    warningText = string.format(\"@cffe3e3e3» %s «@r\", name:upper()),\n    ttsLine = name,\n}\n\n\naura_env.MRT = function()\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'PHASE_2'\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        name           = name,\n        icon           = icon,\n        noCount        = true,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Schedule = function(seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('BOSSES_SCHEDULED')\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'ADD_ACTIVATION' then\n        local add = ...\n        if add == 'BOSSES' then\n            aura_env.Schedule(10)\n        end\n        \n    elseif e == 'BOSSES_SCHEDULED' then\n        aura_env.SendWarning()\n        aura_env.StopCD()\n        aura_env.MRT()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        local duration = aura_env.isHeroic and 98 or 107\n        aura_env.StartCD(duration)\n    end\nend",
