},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\nlocal msg = C_Spell.GetSpellName(119519) .. ' » ' .. WeakAuras.me\naura_env.SendMsg = function()\n    WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', msg, 'YELL')\nend\n\nlocal UnitDetailedThreatSituation = UnitDetailedThreatSituation\nlocal UnitGroupRolesAssigned = UnitGroupRolesAssigned\nlocal GetPartyAssignment = GetPartyAssignment\n\naura_env.IsTanking = function(targetUnit, sourceUnit)\n    local isTanking, status = UnitDetailedThreatSituation(\n    sourceUnit or \"player\", targetUnit)\n    return isTanking or status == 2 or status == 3\nend\n\naura_env.IsTank = function(unit)\n    return\n    GetPartyAssignment(\"MAINTANK\", unit) or UnitGroupRolesAssigned(unit) ==\n    \"TANK\"\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID, spellName = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 119519 then\n                -- Target Scanner\n                local fired = 0\n                local ticker\n                ticker = C_Timer.NewTicker(0.05, function()\n                        fired = fired + 1\n                        local targetID = 'boss1target'\n                        local targetName = UnitName(targetID)\n                        local isTanking = aura_env.IsTanking('boss1', targetID)\n                        local isTank = aura_env.IsTank(targetID)\n                        local conditionMet = targetName and ((not isTanking and not isTank) or fired > 13)\n                        if conditionMet then\n                            if UnitIsUnit(targetID, 'player') then\n                                --aura_env.SendMsg()\n                            end\n                            ticker:Cancel()\n                        end\n                end, 14)\n            end\n        end\n    end\nend",
