["init"] = {
["custom"] = "local encounterID = '1499'\nlocal ID          = 'AmberScalpel'\n\nlocal name, icon = C_Spell.GetSpellName(121994), C_Spell.GetSpellTexture(121994)\n\nlocal options = {\n    ['AmberScalpel'] = {\n        warningText    = \"%icon @cffffff80%name@r (%count) %icon\",\n        prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n    },\n    ['AmberScalpelGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name:upper()),\n    },\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n        }, options['AmberScalpel'])\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count,\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 121994 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('AmberScalpel')\n                aura_env.StopCD()\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 121994 then\n                aura_env.StartCD(40)\n            end\n            \n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 121995 then\n                aura_env.SendWarning('AmberScalpelGTFO')\n            end\n        end\n        \n    elseif e == 'UNSOK_PHASE' then\n        local phaseN = ...\n        if phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(9)\n    end\nend",
