["[事件依赖] 缚风者哈格拉"] = {
["outline"] = "OUTLINE",
["wagoID"] = "r2q5DNxZh",
["parent"] = "[T13] 事件依赖",
["preferToUpdate"] = true,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal cooldownData = {\n    ['Berserk'] = { name = 'Berserk', icon = 136224 },\n    ['RandomPhase'] = { name = 'Random Phase', icon = 136116 },\n    ['IcePhase'] = { name = 'Ice Phase', icon = 512902 },\n    ['LightPhase'] = { name = 'Light Phase', icon = 135990 },\n    ['Frostflake'] = { name = 'Frostflake', icon = 254883 },\n    ['FocusedAssault'] = { name = 'Focused Assault', icon = 294033, roleIcon = 'TANK' },\n    ['IceLance'] = { name = 'Ice Lance', icon = 237236 },\n    ['IceTomb'] = { name = 'Ice Tomb', icon = 135851 },\n}\n\nlocal encounterID = '1296'\n\nlocal CREATURE_ID = {\n    \n}\n\nlocal PRE_WARNING = {\n    ['RandomPhase'] = true,\n    ['IcePhase'] = true,\n    ['LightPhase'] = true,\n    ['IceTomb'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then\n        return 0\n    end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then \n        return false \n    end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.WipeSchedulers = function()\n    if aura_env.schedulers then \n        for schedulerName, scheduler in pairs(aura_env.schedulers) do\n            WeakAuras.timer:CancelTimer(scheduler)\n        end\n    end\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_T13',\n        'PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.ScheduleEvent = function(subEvent, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[subEvent] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[subEvent])\n    end\n    \n    aura_env.schedulers[subEvent] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        subEvent\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    \n    aura_env.predict[id] = duration + GetTime()\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldownInfo  = {\n        show = true,\n        name = data.name,\n        id = id,\n        icon = data.icon,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        count = count,\n        roleIcon = data.roleIcon,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldownInfo)\n    \n    if not PRE_WARNING[id] then return end\n    \n    aura_env.SchedulePrewarning(id, duration)\nend\n\naura_env.IsCooldownReadyBefore = function(id, before)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (predictedAt - GetTime() > before)\nend\n\naura_env.IsCooldownReady = function(id)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (GetTime() > predictedAt)\nend\n\naura_env.Warning = function(warning, ...)\n    WeakAuras.ScanEvents('WA_MERFIN_T13', 'WARNING', warning, ...)\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    aura_env.size = WeakAuras.InstanceType()\n    \n    aura_env.WipeSchedulers()\n    \n    -- Reset Flags\n    aura_env.phase = 'main'\n    aura_env.pillarsCount = 0\n    aura_env.lastLances = 0\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    \n    -- Destination Names\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, CLEU:SPELL_AURA_APPLIED:SPELL_AURA_APPLIED_DOSE:SPELL_AURA_REMOVED:SPELL_CAST_START:SPELL_CAST_SUCCESS:SPELL_SUMMON, WA_MERFIN_T13_SCHEDULED",
["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId, _, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellId == 105256 then -- Start of Ice Phase\n                aura_env.phase = 'ice'\n                aura_env.pillarsCount = 4\n                aura_env.StopCD('FocusedAssault')\n                aura_env.StopCD('IceLance')\n                aura_env.StopCD('Shatter')\n                aura_env.StopCD('RandomPhase')\n                aura_env.StopCD('LightPhase')\n                aura_env.StopCD('IcePhase')\n                aura_env.StopCD('IceTomb')\n                aura_env.Warning('IcePhaseStart')\n                \n            elseif spellId == 105409 then -- Start of Light Phase\n                aura_env.phase = 'light'\n                if aura_env.size == 'ten' and aura_env.IsHeroic then\n                    aura_env.pillarsCount = 8\n                else\n                    aura_env.pillarsCount = 4\n                end\n                aura_env.StopCD('FocusedAssault')\n                aura_env.StopCD('IceLance')\n                aura_env.StopCD('Shatter')\n                aura_env.StopCD('RandomPhase')\n                aura_env.StopCD('LightPhase')\n                aura_env.StopCD('IcePhase')\n                aura_env.StopCD('IceTomb')\n                aura_env.Warning('LightPhaseStart')\n                \n            elseif spellId == 104448 then\n                aura_env.StopCD('IceTomb')\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellId == 109325 then\n                aura_env.StartCD('Frostflake', 5, false, true)\n            elseif spellId == 107851 then\n                aura_env.StartCD('FocusedAssault', 15, false, true)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellId == 105311 then\n                aura_env.pillarsCount = aura_env.pillarsCount - 1\n                if aura_env.pillarsCount == 0 then\n                    return\n                end\n                aura_env.Warning('FrostPillarsLeft', aura_env.pillarsCount)\n                \n            elseif spellId == 105482 then\n                aura_env.pillarsCount = aura_env.pillarsCount - 1\n                if aura_env.pillarsCount == 0 then\n                    return\n                end\n                aura_env.Warning('LightPillarsLeft', aura_env.pillarsCount)\n                \n            elseif spellId == 105256 then -- End of Ice Phase\n                aura_env.StopCD('Frostflake')\n                aura_env.StartCD('IceLance', 12)\n                aura_env.StartCD('IceTomb', 20)\n                aura_env.StartCD('LightPhase', 62)\n                WeakAuras.ScanEvents('WA_TRANSITION_PHASE_END')\n                \n            elseif spellId == 105409 then -- End of Light Phase\n                aura_env.StartCD('IceLance', 12)\n                aura_env.StartCD('IceTomb', 20)\n                aura_env.StartCD('IcePhase', 62)\n                WeakAuras.ScanEvents('WA_TRANSITION_PHASE_END')\n            end\n            \n        elseif subEvent == 'SPELL_SUMMON' then\n            if spellId == 105297 then\n                local curTime = GetTime()\n                if curTime - aura_env.lastLances < 1 then\n                    return\n                end\n                aura_env.lastLances = curTime\n                aura_env.StartCD('IceLance', 30, false, true)\n            end\n        end\n        \n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        \n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('FocusedAssault', 4)\n        aura_env.StartCD('IceLance', 10)\n        aura_env.StartCD('RandomPhase', 30)\n        --aura_env.StartCD('IceTomb', 10)\n        \n        aura_env.StartCD('Berserk', 480)\n        aura_env.ScheduleEvent('BERSERK_EMPHASIZED', 470)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
