["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'ToxicSlime'\n\nlocal name, icon = C_Spell.GetSpellName(124807), C_Spell.GetSpellTexture(124807)\n\nlocal options = {\n    warningText = \"%icon %name %icon\",\n}\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID, GUID = GUID })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n            GUID           = GUID\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unit,_, spellID = ...\n        \n        if spellID == 124807 then\n            aura_env.count = aura_env.count + 1\n            local sourceGUID = UnitGUID(unit)\n            aura_env.StartCD(14.5, sourceGUID)\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 or phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        \n        if npcID == 63591 then\n            aura_env.StopCD(destGUID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
