["!在登录时禁用暴雪插件性能分析，帧数优化（露露汉化+移植，by Luckyone）"] = {
["outline"] = "OUTLINE",
["authorOptions"] = {
{
["type"] = "header",
["useName"] = true,
["text"] = "自定义选项设置",
["width"] = 1,
},
{
["type"] = "toggle",
["key"] = "print",
["useDesc"] = false,
["default"] = true,
["name"] = "在聊天框打印生效信息",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://afdian.com/a/Rurutia",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "-- 露露备注：此WA项目用于关闭暴雪性能分析，提升帧数，以下是原作者（Luckyone）的注释，使用Grok3汉化\n\n-- 这将在你的游戏中注册一个控制台变量\n-- 这样我们就可以修改它的值来禁用性能分析\n-- 暴雪默认情况下没有注册这个变量\nC_CVar.RegisterCVar('addonProfilerEnabled', '1')\n\n-- 这会将控制台变量设置为0，表示关闭/禁用\n-- 如果你想启用性能分析，将值改为1\nC_CVar.SetCVar('addonProfilerEnabled', '0')\n\n-- 我在这里添加了一个或多个选项，这些选项将出现在\n-- 这个WeakAura选项的“自定义选项”标签中\n-- 每个选项都会有鼠标悬停时的描述\nif aura_env.config.print then\n    \n    local on = C_AddOnProfiler.IsEnabled()\n    if not on then\n        print('|cff4beb2c暴雪插件性能分析已关闭。|r')\n    end\nend",
},
},
