["init"] = {
["custom"] = "local UnitHealth, UnitHealthMax = UnitHealth, UnitHealthMax\n\naura_env.GetUnitHealthPercent = function(unit)\n    local health = UnitHealth(unit)\n    local maxHealth = UnitHealthMax(unit)\n    \n    if maxHealth == 0 then\n        return 0\n    end\n    \n    return (health / maxHealth) * 100\nend\n\naura_env.InRangeOffset = function(value, min, max)\n    if value >= min and value < max then\n        return value - min\n    end\n    return nil\nend\n\naura_env.GetGUIDCreatureID = function(GUID)\n    local guidType, _, id1, _, _, id2 = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id2) or 0\n    elseif guidType == \"Player\" or guidType == \"Item\" then\n        return tonumber(id1) or 0\n    end\n    return 0\nend\n\naura_env.NpcIDToPrefix = {\n    [60709] = C_EncounterJournal.GetSectionInfo(5846).title,\n    [61423] = C_EncounterJournal.GetSectionInfo(5846).title,\n    [60710] = C_EncounterJournal.GetSectionInfo(5852).title,\n    [61427] = C_EncounterJournal.GetSectionInfo(5852).title,\n    [60701] = C_EncounterJournal.GetSectionInfo(5835).title,\n    [61421] = C_EncounterJournal.GetSectionInfo(5835).title,\n}",
