["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, bossID)\n    \n    if event == 'OPTIONS' then\n        states:Update('', {\n                progressType = 'static',\n                total        = 5,\n                value        = 2.6,\n                prefix       = aura_env.NpcIDToPrefix[60709], \n        })\n        return\n    end\n    \n    if UnitExists(bossID) then\n        local hper = aura_env.GetUnitHealthPercent(bossID)\n        local offset = aura_env.InRangeOffset(hper, 30, 35)\n        \n        if offset then\n            local GUID = UnitGUID(bossID)\n            local npcID = aura_env.GetGUIDCreatureID(GUID)\n            local prefix = aura_env.NpcIDToPrefix[npcID]\n            \n            if prefix then\n                states:Update('', {\n                        progressType = 'static',\n                        total        = 5,\n                        value        = offset,\n                        prefix       = prefix,\n                })\n                return\n            end\n        end\n    end\n    \n    states:Remove('')\nend",
