["group_countOperator"] = ">",
["event"] = "Health",
["unit"] = "group",
["useName"] = true,
["custom"] = "function(state, event, subEvent, visibility, cooldownName)\n    \n    if event ~= 'WA_MERFIN_T13' or subEvent ~= 'COOLDOWN' or cooldownName ~= 'DisruptingRoar' then\n        return\n    end\n    \n    if (visibility == 'HIDE' or visibility == 'SHOW') and state[''] then\n        state[''].show = false\n        state[''].changed = true\n        return true\n    end\n    \n    if visibility == 'READY' then\n        state[''] = {\n            show = true,\n            changed = true,\n        }\n        return true\n    end\nend",
