["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    ticked = {\n        display = 'Ticked',\n        type = 'bool'\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, ...)\n    if event == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        \n        if aura_env.rings[spellID] then\n            aura_env.count = aura_env.count + 1\n            if aura_env.count == 4 then\n                states:Update('', {\n                        progressType = 'timed',\n                        duration = 2,\n                        expirationTime = 2 + GetTime(),\n                })\n            end\n        end\n        \n        if spellID == aura_env.ringID then\n            states:Update('', { ticked = true })\n        end\n        \n    elseif event == 'STORM_STARTED' then\n        aura_env.count = 0\n        states:Update('', { \n                progressType = 'static',\n                value = 0,\n                total = 1,\n                ticked = false \n        })\n        \n    elseif event == 'STORM_ENDED' then\n        aura_env.count = 0\n        states:Remove('')\n    end\nend",
