["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_HEALTH' and not aura_env.phase2 then\n        local unitID = ...\n        local unitGUID = UnitGUID(unitID)\n        local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n        \n        if npcID == 62397 then\n            local hp = 100 * UnitHealth(unitID) / UnitHealthMax(unitID)\n            if hp < 75.1 then\n                aura_env.phase2 = true\n                WeakAuras.ScanEvents('MELJARAK_PHASE2')\n                aura_env.SendWarning()\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.phase2 = false\n    end\nend",
