["[DP] [Mel'jarak] Reinforcements"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'Reinforcements'\n\nlocal icon = 624009\n\nlocal options = {\n    warningText    = \"%icon @cffffff80%name@r %icon\",\n    prewarnTTStext = Merfin:L(\"Adds Respawn Soon\"),\n}\n\nlocal utf8upperFirst = function(str)\n    local first = string.utf8sub(str, 1, 1)\n    return (first and first:upper() .. string.utf8sub(str, 2)) or str\nend\n\nlocal GetName = function(ID)\n    local s = Merfin.GetTitleEJ(ID)\n    if GetLocale() == 'enUS' then\n        return (s:match(\"^%s*%S+%s*(.*)$\")) or \"\"\n    elseif GetLocale() == 'ruRU' then\n        local rest = (s:match(\"^%s*[^%-]+%-%s*(.*)$\")) or s\n        return utf8upperFirst(rest)\n    else\n        return s\n    end\nend\n\nlocal mobNames = {\n    ['SRATHIK'] = { name = GetName(6300), icon = 615302 },\n    ['ZARTHIK'] = { name = GetName(6305), icon = 135142 },\n    ['KORTHIK'] = { name = GetName(6334), icon = 135351 },\n}\n\naura_env.mobID = {\n    [62451] = 'SRATHIK',\n    [62452] = 'ZARTHIK',\n    [62447] = 'KORTHIK',\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, mobID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = mobNames[mobID].name,\n            icon           = mobNames[mobID].icon,\n            count          = aura_env.count,\n            GUID           = mobID,\n    }, options)\nend\n\naura_env.SendWarning = function(mobID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = mobNames[mobID].name,\n            icon  = mobNames[mobID].icon,\n            count = aura_env.count,\n    }, options)\nend\n\naura_env.Schedule = function(seconds, ID)\n    aura_env.schedulers = aura_env.schedulers or {}\n    if aura_env.schedulers[ID] then\n        aura_env.schedulers[ID]:Cancel()\n    end\n    local timer = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('REINFORCEMENTS', ID)\n    end)\n    aura_env.schedulers[ID] = timer\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    \n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 125873 then\n            local unitGUID = UnitGUID(unitID)\n            local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n            local mobID = aura_env.mobID[npcID]\n            aura_env.StartCD(60, mobID)\n            aura_env.Schedule(60, mobID)\n        end\n        \n    elseif e == 'REINFORCEMENTS' then\n        local mobID = ...\n        aura_env.SendWarning(mobID)\n        \n        if aura_env.schedulers[mobID] then\n            aura_env.schedulers[mobID]:Cancel()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        \n        if aura_env.schedulers then\n            for mobID in pairs(aura_env.schedulers) do\n                if aura_env.schedulers[mobID] then\n                    aura_env.schedulers[mobID]:Cancel()\n                end\n            end\n        end\n    end\nend",
