["custom"] = "local encounterID = '1500'\nlocal ID          = 'MaterializeProtector'\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r (%count) %icon\",\n    ttsLine = Merfin:L(\"Take the Add\"),\n}\n\nlocal name, icon = C_Spell.GetSpellName(117954), C_Spell.GetSpellTexture(117954)\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 117954 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n                local timer = aura_env.isHeroic and 26 or 41\n                aura_env.StartCD(timer)\n            end\n        end\n        \n    elseif e == 'ELEGON_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 then\n            aura_env.StartCD(15)\n            \n        elseif phaseN == 2 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.count = 0\n        aura_env.StartCD(10)\n    end\nend",
