["init"] = {
["custom"] = "local encounterID = '1506'\nlocal ID          = 'Special'\n\nlocal GetSpellInfoTable = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\nlocal data = {\n    ['Special']        = { name = Merfin:L('Special Ability'), icon = 512902 },\n    ['ProtectRemoved'] = { name = string.format(Merfin:L('%s Removed'), C_Spell.GetSpellName(123250)), icon = C_Spell.GetSpellTexture(123250) }\n}\n\nlocal options = {\n    ['Special']        = {warningText = \"%icon @cffffff80\".. data['Special'].name .. \"@r  %icon\"},\n    ['ProtectRemoved'] = {warningText = \"%icon @cffffff80\".. data['ProtectRemoved'].name .. \"@r  %icon\"},\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    aura_env.expTime = duration + GetTime()\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = data[ID].name,\n            icon           = data[ID].icon,\n            count          = aura_env.count,\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = data[ID].name,\n            icon  = data[ID].icon,\n            count = aura_env.count,\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 123244 then -- Vanish\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD('Special', 50)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 123250 then -- Protect\n                aura_env.specialRemaining = aura_env.expTime - GetTime()\n                aura_env.lastProtect = GetTime()\n                aura_env.StopCD('Special')\n                \n            elseif spellID == 123461 then -- Get Away!\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD('Special', 50)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 123250 then -- Protect\n                aura_env.SendWarning('ProtectRemoved')\n                --if GetTime() > aura_env.expTime then\n                local protectElapsed = GetTime() - aura_env.lastProtect\n                local specialCD = aura_env.specialRemaining - protectElapsed\n                local seconds = specialCD < 5 and 5 or specialCD\n                aura_env.StartCD('Special', seconds)\n                --end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.specialRemaining = 0\n        aura_env.lastProtect = 0\n        aura_env.StartCD('Special', 30.5)\n    end\nend",
