["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'Song'\n\nlocal name, icon = C_Spell.GetSpellName(123791), C_Spell.GetSpellTexture(123791)\n\nlocal options = {\n    warningText = \"%icon %sourceName @cffff8b17%name@r %icon\",\n}\n\nlocal sourceName = {\n    ['ECHO'] = '|cffff8080' .. Merfin:L('Echo') .. '|r',\n    ['BOSS'] = '|cffb5b5b5' .. BOSS .. '|r',\n}\n\naura_env.SendWarning = function(bossID)\n    local data = {\n        ID         = ID,\n        count      = aura_env.count,\n        sourceName = sourceName[bossID],\n        name       = name,\n        icon       = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.GetBossID = function(GUID)\n    local npcID = Merfin.GetNPCIDFromGUID(GUID)\n    local isEcho = npcID == 65173 or npcID == 65174\n    return isEcho and 'ECHO' or 'BOSS'\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
