["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, sourceGUID, sourceName, _, _, _, destName, _, _, spellID = ...\n        \n        if spellID == 123791 then\n            if subEvent == 'SPELL_CAST_START' then\n                local bossID = aura_env.GetBossID(sourceGUID)\n                \n                if bossID == 'ECHO' and aura_env.initialized then\n                    aura_env.initialized = false\n                    WeakAuras.ScanEvents('CLONE_SPAWNED')\n                end\n                \n                --aura_env.SendWarning(bossID)\n                \n            elseif subEvent == 'SPELL_AURA_APPLIED' then\n                WeakAuras.ScanEvents('SONG_APPLIED')\n            elseif subEvent == 'SPELL_AURA_REMOVED' then\n                WeakAuras.ScanEvents('SONG_REMOVED')\n            end\n        end\n        \n    elseif e == 'PLATFORM_CHANGED' then\n        aura_env.platformN = ...\n        \n        if aura_env.platformN == 4 then\n            aura_env.initialized = true\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.initialized = false\n        aura_env.count = 0\n    end\nend",
