["init"] = {
["custom"] = "aura_env.GetNameplateID = function(GUID) \n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, plateData in pairs(nameplates) do\n        local nameplateID = plateData.UnitFrame.displayedUnit\n        local nameplateGUID = UnitExists(nameplateID) and UnitGUID(nameplateID)\n        if nameplateGUID == GUID then\n            return nameplateID\n        end\n    end\nend\n\naura_env.data = {}\n\naura_env['MERFIN_CD_NAMEPLATE_SHOW'] = function(states, _, cooldown)\n    local GUID = cooldown.GUID\n    if not GUID then return end\n    \n    local ID = cooldown.ID\n    \n    aura_env.data[GUID] = aura_env.data[GUID] or {}\n    aura_env.data[GUID][ID] = {\n        duration       = cooldown.duration,\n        expirationTime = cooldown.expirationTime,\n        icon           = cooldown.icon\n    }\n    \n    local nameplateID = aura_env.GetNameplateID(GUID)\n    if not nameplateID then return end\n    \n    local stateKey = GUID .. '_' .. ID\n    states:Update(stateKey, {\n            progressType   = 'timed',\n            duration       = cooldown.duration,\n            expirationTime = cooldown.expirationTime,\n            autoHide       = true,\n            icon           = cooldown.icon,\n            unit           = nameplateID\n    })\nend\n\naura_env['MERFIN_CD_HIDE'] = function(states, _, cooldown)\n    local GUID = cooldown.GUID\n    if not GUID then return end\n    \n    local ID = cooldown.ID\n    \n    if aura_env.data[GUID] then\n        aura_env.data[GUID][ID] = nil\n        \n        if next(aura_env.data[GUID]) == nil then\n            aura_env.data[GUID] = nil\n        end\n    end\n    \n    local stateKey = GUID .. '_' .. ID\n    if states[stateKey] then\n        states:Remove(stateKey)\n    end\nend\n\naura_env['NAME_PLATE_UNIT_ADDED'] = function(states, nameplateID)\n    local GUID = UnitExists(nameplateID) and UnitGUID(nameplateID)\n    \n    if not (GUID and aura_env.data[GUID]) then return end\n    \n    for ID, cooldown in pairs(aura_env.data[GUID]) do\n        local stateKey = GUID .. '_' .. ID\n        states:Update(stateKey, {\n                progressType   = 'timed',\n                duration       = cooldown.duration,\n                expirationTime = cooldown.expirationTime,\n                autoHide       = true,\n                icon           = cooldown.icon,\n                unit           = nameplateID\n        })\n    end\nend\n\naura_env['NAME_PLATE_UNIT_REMOVED'] = function(states, nameplateID)\n    local GUID = UnitGUID(nameplateID)\n    \n    if not GUID then return end\n    \n    for stateKey, _ in pairs(states) do\n        if stateKey:sub(1, #GUID) == GUID and stateKey:sub(#GUID + 1, #GUID + 1) == '_' then\n            states:Remove(stateKey)\n        end\n    end\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
},
