["[DP] [Protectors] Lightning Storm"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 16.999877929688,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1409'\nlocal ID = 'LightningStorm'\n\nlocal name, icon = C_Spell.GetSpellName(118077), C_Spell.GetSpellTexture(118077)\n\nlocal options = {\n    warningText    = \"@cffff4040%upper:name@r\",\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID ~= 118077 then return end\n        \n        if subEvent == 'SPELL_CAST_START' then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local seconds = aura_env.phase == 3 and 32 or 41\n            aura_env.StartCD(seconds)\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            WeakAuras.ScanEvents('STORM_STARTED')\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            WeakAuras.ScanEvents('STORM_ENDED')\n            \n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local _,_, spellID = ...\n        if spellID == 118003 or spellID == 118004 or spellID == 118005 then\n            \n        end\n        \n    elseif e == 'PROTECTORS_PHASE_CHANGING' then\n        local npcID, phaseN = ...\n        \n        if npcID == 60585 then\n            local seconds = phaseN == 2 and 25.5 or 9.5\n            aura_env.StartCD(seconds)\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        if npcID == 60585 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.phase = 1\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START,  PROTECTORS_PHASE_CHANGING, CLEU:SPELL_CAST_START:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED, UNIT_DIED",
