["[DP] [TSG] Overload"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1395'\nlocal ID          = 'Overload'\n\nlocal name, icon = C_Spell.GetSpellName(115840), C_Spell.GetSpellTexture(115840)\n\nlocal options = {\n    ['Overload'] = {\n        warningText = '@cffff4040%upper:name@r',\n    },\n    ['OverloadSoon'] = {\n        warningText = '@cffff4040' .. Merfin:L('Overload Soon'):upper() ..'@r',\n        ttsLine = Merfin:L('Overload Soon'),\n    },\n}\n\nlocal extraTypes = {\n    COBALT   = { 115840, '001E90FF' },\n    JADE     = { 115842, '00008000' },\n    JASPER   = { 115843, '00FF0000' },\n    AMETHYST = { 115844, '00FF44FF' },\n}\n\nlocal extra = {}\nfor ID, data in pairs(extraTypes) do\n    local spellID, color = data[1], data[2]\n    local name, icon = C_Spell.GetSpellName(spellID), C_Spell.GetSpellTexture(spellID)\n    extra[ID] = {\n        name = string.format('|c%s%s|r', color, name),\n        icon = icon\n    }\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['Overload'])\nend\n\naura_env.SendWarning = function(ID, extraID)\n    local data = {\n        ID    = ID,\n        count = aura_env.count,\n        name  = extra[extraID].name,\n        icon  = extra[extraID].icon,\n        extraID = extraID\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.NpcToName = {\n    [60051] = 'COBALT',\n    [60043] = 'JADE',\n    [60047] = 'AMETHYST',\n    [59915] = 'JASPER'\n}\n\naura_env.OverloadID = {\n    [115840] = 'COBALT',\n    [115842] = 'JADE',\n    [115843] = 'JASPER',\n    [115844] = 'AMETHYST'\n}\n\naura_env.IsSpam = function(ID, before)\n    aura_env.antispams = aura_env.antispams or {}\n    local cur = GetTime()\n    if not aura_env.antispams[ID] or cur - aura_env.antispams[ID] > before then\n        aura_env.antispams[ID] = cur\n        return false\n    end\n    return true\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Overload = \"%s is about to Overload!\"\n    },\n    ['ruRU'] = {\n        Overload = \"%s вот-вот перенасытится!\"\n    },\n    ['ptBR'] = {\n        Overload = \"%s está prestes a sobrecarregar!\"\n    },\n    ['deDE'] = {\n        Overload = \"%s überlädt sich gleich!\"\n    },\n    ['frFR'] = {\n        Overload = \"%s est sur le point de surcharger !\"\n    },\n    ['itIT'] = {\n        Overload = \"%s sta per Sovraccaricarsi!\"\n    },\n    ['esES'] = {\n        Overload = \"¡%s se empieza a sobrecargar!\"\n    },\n    ['zhCN'] = {\n        Overload = \"%s即将过载！\"\n    },\n    ['zhTW'] = {\n        Overload = \"%s要超載了!\"\n    },\n    ['koKR'] = {\n        Overload = \"과부하되기 직전입니다!\"\n    }\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local  _, subEvent,_, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID = ...\n        \n        local type = aura_env.OverloadID[spellID]\n        \n        if type and not aura_env.IsSpam('Overload', 5) then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning('Overload', type)\n            WeakAuras.ScanEvents('GUARDS_OVERLOAD', type)\n        end\n        \n    elseif e == 'RAID_BOSS_EMOTE' then\n        local msg, boss = ...\n        \n        if aura_env.IsEmote(msg, 'Overload') and not aura_env.IsSpam('Overloadsoon', 5) then \n            for i = 1, 4 do\n                local bossID = 'boss' .. i\n                if boss == UnitName(bossID) then\n                    local GUID = UnitExists(bossID) and UnitGUID(bossID)\n                    local npcID = GUID and Merfin.GetNPCIDFromGUID(GUID)\n                    local type = aura_env.NpcToName[npcID]\n                    aura_env.SendWarning('OverloadSoon', type)\n                    return\n                end\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.antispams = {}\n    end\nend",
