["[Widget] [Protectors] Focus Boss"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["displayText"] = "%c1 » |cffff4040%c2|r «",
["customText"] = "function()\n    local prefix = Merfin:L('Focus Target')\n    local bossName = WeakAuras.IsOptionsOpen() and C_EncounterJournal.GetSectionInfo(5793).title or aura_env.bossName\n    return prefix:upper(), bossName:upper()\nend",
["shadowYOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["sound"] = "Interface\\AddOns\\WeakAuras\\Media\\Sounds\\Focus.ogg",
["do_sound"] = true,
},
["init"] = {
["custom"] = "aura_env.GetNPCIDFromGUID = function(GUID)\n    local guidType, _, _, _, _, id = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id) or 0\n    end\n    return 0\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    local function GetExpectedNPCID()\n        if aura_env.boss == \"regail\" then\n            return 60585\n        elseif aura_env.boss == \"asani\" then\n            return 60586\n        end\n        return nil\n    end\n    \n    local function HasRelevantNameplate()\n        local expectedID = GetExpectedNPCID()\n        if not expectedID then return false end\n        \n        local nameplates = C_NamePlate.GetNamePlates()\n        for _, plate in ipairs(nameplates) do\n            local unit = plate.namePlateUnitToken\n            if unit and UnitExists(unit) then\n                local guid = UnitGUID(unit)\n                if guid and aura_env.GetNPCIDFromGUID(guid) == expectedID then\n                    if not aura_env.bossName then\n                        aura_env.bossName = UnitName(unit)\n                    end\n                    return true\n                end\n            end\n        end\n        return false\n    end\n    \n    local function CheckFocus()\n        if not aura_env.boss then return end\n        \n        if not HasRelevantNameplate() then\n            states:Remove('')\n            return\n        end\n        \n        if not UnitExists(\"focus\") then\n            states:Update('', {\n                    changed   = true,\n                    show      = true,\n                    bossName  = aura_env.bossName,\n            })\n            return\n        end\n        \n        local focusGUID = UnitGUID(\"focus\")\n        local focusID = aura_env.GetNPCIDFromGUID(focusGUID)\n        if focusID and focusID == GetExpectedNPCID() then\n            states:Remove('')\n        else\n            states:Update('', {\n                    changed   = true,\n                    show      = true,\n                    bossName  = aura_env.bossName,\n            })\n        end\n    end\n    \n    if event == 'PROTECTORS_INTERRUPT_ORDER' then\n        local fullOrder = ...\n        aura_env.order = nil\n        aura_env.boss = nil\n        \n        for boss, playerList in pairs(fullOrder) do\n            for _, name in ipairs(playerList) do\n                if name == WeakAuras.me then\n                    aura_env.order = playerList\n                    aura_env.boss = boss\n                    break\n                end\n            end\n            if aura_env.boss then break end\n        end\n        \n        CheckFocus()\n        \n    elseif event == 'PLAYER_FOCUS_CHANGED' or event == 'RAID_TARGET_UPDATE' then\n        CheckFocus()\n        \n    elseif event == 'NAME_PLATE_UNIT_ADDED' then\n        local unit = ...\n        if not aura_env.boss then return end\n        local expectedID = GetExpectedNPCID()\n        if not expectedID or not UnitExists(unit) then return end\n        \n        local guid = UnitGUID(unit)\n        if guid and aura_env.GetNPCIDFromGUID(guid) == expectedID then\n            if not aura_env.bossName then\n                aura_env.bossName = UnitName(unit)\n            end\n            CheckFocus()\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_REMOVED' then\n        local unit = ...\n        if not aura_env.boss then return end\n        local expectedID = GetExpectedNPCID()\n        if not expectedID then return end\n        \n        local guid = UnitGUID(unit)\n        if guid and aura_env.GetNPCIDFromGUID(guid) == expectedID then\n            CheckFocus()\n        end\n    end\nend",
["names"] = {
