["init"] = {
["custom"] = "local strsplit = strsplit\nlocal bband = bit.band\nlocal pairs = pairs\n\nlocal MerfinTestCharacters = {\n    ['Merfinbang'] = true,\n    ['Merfinx'] = true,\n}\n\naura_env.isDebug = MerfinTestCharacters[WeakAuras.me]\n\naura_env.GetOption = function(optionName)\n    local cfg = aura_env.config.healthbar\n    return cfg[optionName]\nend\n\nlocal GetDifficultyRaw = function()\n    return WeakAuras.InstanceTypeRaw()\nend\n\naura_env.damage_events = {\n    ['SPELL_PERIODIC_DAMAGE'] = true,\n    ['SPELL_DAMAGE'] = true,\n    ['RANGE_DAMAGE'] = true,\n    ['SWING_DAMAGE'] = true,\n}\n\nlocal RAID_ICONS = {\n    [0x00000001] = 1,\n    [0x00000002] = 2,\n    [0x00000004] = 3,\n    [0x00000008] = 4,\n    [0x00000010] = 5,\n    [0x00000020] = 6,\n    [0x00000040] = 7,\n    [0x00000080] = 8,\n}\n\nlocal function GetRaidIconFromFlags(flags)\n    for mask, index in pairs(RAID_ICONS) do\n        if bband(flags, mask) ~= 0 then\n            return index\n        end\n    end\n    return nil\nend\n\nlocal GetFlagMark = function(raidFlag)\n    if not raidFlag then\n        return\n    end\n    \n    local raidIcon = GetRaidIconFromFlags(raidFlag)\n    return raidIcon\nend\n\naura_env.GetFormattedFlagMark = function(raidFlag)\n    local raidIcon = GetFlagMark(raidFlag)\n    \n    if raidIcon then\n        return '{rt' .. raidIcon .. '}'\n    end\nend\n\n-- 3: 10nm, 4: 25nm, 5: 10hc, 6: 25hc\nlocal crystalData = { \n    id = 'HAGARA_CRYSTAL',\n    displayName = 'Crystal', \n    icon = 236214,\n    hp = { \n        [3] = 387450, \n        [5] = 2324700,\n        [4] = 1162350,\n        [6] = 6974100\n    },\n}\n\nlocal corruptionData = {\n    id = 'SPINE_CORRUPTION',\n    displayName = 'Crystal', \n    icon = 254105,\n    hp = { \n        [3] = 457804, \n        [5] = 801372,\n        [4] = 1418935,\n        [6] = 2483996\n    },\n}\n\nlocal manaVoidData = {\n    id = 'YOURSAJ_MANA_VOID',\n    displayName = 'Mana Void',\n    icon = 136116,\n    hp = {\n        [3] = 1549800,\n        [4] = 5036850,\n        [5] = 2014740,\n        [6] = 6509160,\n    }\n}\n\nlocal corruptingParasite = {\n    id = 'MADNESS_PARASITE',\n    displayName = 'Parasite',\n    icon = 524795,\n    hp = {\n        [5] = 3153772,\n        [6] = 9461316,\n    }\n}\n\nlocal elementiumBolt = {\n    id = 'MADNESS_BOLT',\n    displayName = 'Elementium Bolt',\n    icon = 135821,\n    hp = {\n        [3] = 829940,\n        [4] = 2489820,\n        [5] = 995928,\n        [6] = 2987784,\n    }\n}\n\nlocal burningTendons = {\n    id = 'BURNING_TENDONS',\n    displayName = 'Burning Tendons',\n    icon = 538043,\n    hp = {\n        [3] = 3006220,\n        [4] = 9319282,\n        [5] = 12677659,\n        [6] = 33401252,\n    }\n}\n\naura_env.npcData = {\n    -- Yorsaj (Mana Void)\n    ['56231'] = manaVoidData,\n    ['57438'] = manaVoidData,\n    ['57439'] = manaVoidData,\n    ['57437'] = manaVoidData,\n    \n    -- Hagara (Crystals @ Ice Phase)\n    ['56136'] = crystalData,\n    ['57832'] = crystalData,\n    ['57813'] = crystalData,\n    ['57833'] = crystalData,\n    \n    -- Blackhorn (Sappers)\n    ['56923'] = {\n        id = 'BLACKHORN_SAPPER',\n        displayName = 'Sapper', \n        icon = 133709,\n        hp = { \n            [3] = 340828, \n            [5] = 1202925,\n            [4] = 481170,\n            [6] = 1684095\n        },\n    },\n    \n    -- Spine (Burning Tendons)\n    ['56341'] = burningTendons,\n    ['56575'] = burningTendons,\n    \n    -- Corrupting Parasite\n    ['57479'] = corruptingParasite,\n    ['58034'] = corruptingParasite,\n    \n    ['56262'] = elementiumBolt,\n    ['58144'] = elementiumBolt,\n    ['57979'] = elementiumBolt,\n    ['58145'] = elementiumBolt,\n}\n\naura_env.GetNpcData = function(id)\n    if not id then return 0 end\n    local npcData = aura_env.npcData[id]\n    \n    local hp = npcData.hp[aura_env.diffRaw]\n    local displayName = npcData.displayName\n    local icon = npcData.icon\n    local entryId = npcData.id\n    \n    return hp, displayName, icon, entryId\nend\n\naura_env.GetNpcId = function(guid)\n    if not guid then return 0 end\n    if aura_env.cachedGUID[guid] then\n        return aura_env.cachedGUID[guid]\n    end\n    \n    local _, _, _, _, _, npcId = strsplit(\"-\", guid)\n    \n    aura_env.cachedGUID[guid] = npcId\n    return aura_env.cachedGUID[guid]\nend\n\naura_env.UpdateRaidTarget = function(a)\n    \n    if not next(a) then\n        return\n    end\n    \n    --\nend\n\naura_env.ClearCache = function()\n    aura_env.diffRaw = GetDifficultyRaw()\n    aura_env.deadGUID = {}\n    aura_env.cachedGUID = {}\nend\n\naura_env.ClearCache()\n\nif aura_env.isDebug then\n    aura_env.npcData['55689'] = crystalData\nend",
["do_custom"] = true,
},
},
},
