["customText"] = "-- Author: 露露緹婭@Bilibili\nfunction()\n    local default_text = \"自保\"\n    local spellId = aura_env.state and aura_env.state.spellId\n    local RurutiaSpellName = (spellId and GetSpellInfo(spellId)) or default_text\n    \n    local RurutiaSpellIDs = {\n        --恐惧之心\n        [125907] = \"CD延长\", -- 毁灭尖啸\n        [122761] = \"昏迷\", -- 吐气\n        [122706] = \"减伤\", -- 噪音取消\n        [123812] = \"沉默\", -- 狂热信息素\n        [123235] = \"打腿增伤\", -- 致命弱点\n        [122055] = \"无法救人\", -- 残渣\n        [124849] = \"恐惧\", -- 恐惧吞噬\n        [126122] = \"腐蚀力场\", -- 腐蚀不谐力场\n        [124097] = \"快集合\", -- 粘稠树脂\n        [124777] = \"Dot\", -- 毒液炸弹\n        [124821] = \"强化队友\", -- 浸毒护甲\n        \n        -- BUFF\n        [124827] = \"额外伤害\", -- 毒雾\n    }\n    return spellId and RurutiaSpellIDs[spellId] or RurutiaSpellName\nend",
["displayText_format_p_time_precision"] = 1,
["anchorFrameParent"] = false,
["fixedWidth"] = 200,
["authorOptions"] = {
},
["justify"] = "LEFT",
