["customTriggerLogic"] = "function(t)\n    -- 获取角色和职业信息\n    local role = UnitGroupRolesAssigned(\"player\")\n    local classId = select(3, UnitClass(\"player\"))\n    \n    -- 判断是否为特殊职责：治疗角色、坦克角色、团长\n    local isSpecialRole = \n    (role == \"HEALER\")                                -- 治疗\n    or (role == \"TANK\")                               -- 坦克\n    or UnitIsGroupLeader(\"player\")            -- 团长\n    --or UnitIsGroupAssistant(\"player\")        -- 团长助理\n    \n    return t[1] and isSpecialRole and not (t[2] or t[3])\nend",
