["init"] = {
["custom"] = "local encounterID = '1506'\n\nlocal name, icon = C_Spell.GetSpellName(123244), C_Spell.GetSpellTexture(123244)\n\nlocal options = {\n    ['Hide'] = {warningText = \"%icon @cffff8b17%name@r %icon\"},\n    ['HideOver'] = {warningText = \"%icon - @cffff8b17%name@r %icon\", ttsLine = string.format(Merfin:L('%s removed'), name)}\n}\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count,\n    }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 123244 then -- Hide\n                aura_env.count = aura_env.count + 1\n                aura_env.active = true\n                aura_env.SendWarning('Hide')\n                aura_env.encEngageInit = true\n            end\n        end\n        \n    elseif e == 'INSTANCE_ENCOUNTER_ENGAGE_UNIT' then\n        if not aura_env.encEngageInit then\n            return\n        end\n        \n        if aura_env.active then\n            aura_env.active = false\n            return\n        end\n        \n        aura_env.SendWarning('HideOver')\n        aura_env.encEngageInit = false\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.active = false\n    end\nend",
