["init"] = {
["custom"] = "local encounterID = '1431'\n\nlocal name, icon = C_Spell.GetSpellName(119888), C_Spell.GetSpellTexture(119888)\n\nlocal options = {\n    ['DeathBlossom'] = {warningText = '%icon %name %icon'},\n    ['DeathBlossomPrewarn'] = {\n        warningText = string.format(Merfin:L('|cffe64c4c%s SOON|r'), name:upper()),\n        ttsLine = Merfin:L('Death Blossom Soon'),\n    },\n}\n\naura_env.SendWarning = function(ID)\n    if not aura_env.onPlatform then return end\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n        }, options[ID])\nend\n\naura_env.guardians = {[61046] = true, [61038] = true, [61042] = true}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 119888 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('DeathBlossom')\n            end\n        end\n        \n    elseif e == 'UNIT_HEALTH' then\n        if not aura_env.prewarn then return end\n        \n        local unitID = ...\n        local unitGUID = UnitGUID(unitID)\n        local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n        \n        if not aura_env.guardians[npcID] then return end\n        \n        local healthpercent = 100 * UnitHealth(unitID) / UnitHealthMax(unitID)\n\n        if healthpercent < 35 then\n            aura_env.prewarn = false\n            aura_env.SendWarning('DeathBlossomPrewarn')\n        end\n        \n    elseif e == 'LEAVE_PLATFORM' then\n        aura_env.onPlatform = false\n        \n    elseif e == 'ENTER_PLATFORM' then\n        aura_env.onPlatform = true\n        aura_env.prewarn = true\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.onPlatform = false\n        aura_env.count = 0\n    end\nend",
