["[DP] [Trash] Unseen Strike (Maltik)"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = 'Trash'\nlocal ID          = 'UnseenStrike'\n\nlocal name, icon = C_Spell.GetSpellName(123017), C_Spell.GetSpellTexture(123017)\n\nlocal options = {\n    warningText = \"@cffff4040%upper:name@r » %upper:destName\",\n}\n\naura_env.StopCD = function(destGUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID   = ID,\n            GUID = destGUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            GUID           = GUID,\n            sourceName     = '|cff9d9d9dMaltik|r',\n            name           = name,\n            icon           = icon\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            count    = aura_env.count,\n            noCount  = true,\n            destName = WA_ClassColorName(destName),\n            name     = name,\n            icon     = icon\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID = ...\n        \n        if subEvent == 'UNIT_DIED' then\n            if Merfin.GetNPCIDFromGUID(destGUID) == 64340 then\n                aura_env.StopCD(destGUID)\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID, _, spellID = ...\n        \n        if spellID == 122982 then\n            local unitGUID = UnitGUID(unitID)\n            local npcID = Merfin.GetNPCIDFromGUID(unitGUID)\n            \n            if npcID == 64340 and not aura_env.IsSpam(3) then\n                aura_env.StartCD(25, UnitGUID(unitID))\n            end\n        end\n        \n    elseif e == 'UNSEEN_STRIKE_TARGET' then\n        local subEvent, destName = ...\n        \n        if subEvent == 'AURA_APPLIED' then\n            if destName ~= WeakAuras.me then\n                aura_env.SendWarning(destName)\n            end\n            \n            aura_env.RaidIcon('SET', destName, 1)\n            \n        elseif subEvent == 'AURA_REMOVED' then\n            aura_env.RaidIcon('REMOVE', destName)\n        end\n    end\nend",
