["init"] = {
["custom"] = "local aceProfileName = string.format(\"%s - %s\", WeakAuras.me, GetRealmName(\"player\"))\nlocal config = aura_env.config.options\n\naura_env.saved = aura_env.saved or {}\naura_env.saved[WeakAuras.me] = aura_env.saved[WeakAuras.me] or { font = '', bar = '', fontBold = '' }\n\nlocal db = aura_env.saved[WeakAuras.me]\n\nlocal ConfirmReloadWithReason = function(popupDialog, reason)\n    StaticPopupDialogs[popupDialog] = {\n        text           = reason,\n        button1        = \"Reload UI\",\n        button2        = \"Cancel\",\n        timeout        = 0,\n        whileDead      = true,\n        hideOnEscape   = true,\n        preferredIndex = 3,\n        OnAccept       = function()\n            ReloadUI()\n        end\n    }\n    \n    StaticPopup_Show(popupDialog)\nend\n\nlocal UpdateMerfinPlusDB = function(mediaIndex, mediaValue)\n    if not MerfinPlusSaved then\n        print(\"|cff00ff98[Progress] [Core]|r Unable to apply media changes: MerfinPlusDB not found\")\n        return false\n    end\n    \n    local keys = MerfinPlusSaved[\"profileKeys\"]\n    local activeProfile = (keys and keys[aceProfileName]) or \"Default\"\n    \n    local profiles = MerfinPlusSaved[\"profiles\"] or {}\n    profiles[activeProfile] = profiles[activeProfile] or {}\n    profiles[activeProfile][mediaIndex] = mediaValue\n    \n    keys[aceProfileName] = activeProfile\n    return true\nend\n\naura_env.OnInit = function()\n    local configFont = config.raidFont\n    local configFontBold = config.raidFontBold\n    local configBar = config.raidStatusBar\n    \n    local changesMade = false\n    \n    if not db.font or db.font ~= configFont then\n        if UpdateMerfinPlusDB(\"font3\", configFont) then\n            db.font = configFont\n            changesMade = true\n        end\n    end\n    \n    if not db.fontBold or db.fontBold ~= configFontBold then\n        if UpdateMerfinPlusDB(\"font4\", configFontBold) then\n            db.fontBold = configFontBold\n            changesMade = true\n        end\n    end\n    \n    if not db.bar or db.bar ~= configBar then\n        if UpdateMerfinPlusDB(\"bar3\", configBar) then\n            db.bar = configBar\n            changesMade = true\n        end\n    end\n    \n    if changesMade then\n        ConfirmReloadWithReason(\n            \"PROGRESS_MEDIA_CONFIRM_RELOAD\",\n            \"|cff00ff98» [Progress] Raid Media Changes «|r\\n\\nReload UI is required. Reload now?\"\n        )\n    end\nend",
["do_custom"] = true,
},
