["[DP] [Elegon] Stability Flux (Protector)"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = -3,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'StabilityFlux'\n\nlocal name, icon = C_Spell.GetSpellName(117960), C_Spell.GetSpellTexture(117960)\n\nlocal options = {\n    warningText = \"%icon @cffff4040\" .. Merfin:L('Be Aware'):upper() .. \"@r (x%stacks) %icon\",\n}\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.SendWarning = function(stacks)\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        stacks = stacks,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Overcharged = function()\n    local overcharged, _, stacks = WA_GetUnitDebuff('player', 117878)\n    if not overcharged then return end\n    if (aura_env.isHeroic and stacks > 9) or stacks > 14 then\n        aura_env.SendWarning(stacks)\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' and spellID == 117911 then\n            aura_env.Overcharged()\n            \n        elseif (subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED')\n        and spellID == 117912 \n        and WeakAuras.myGUID == destGUID \n        and not aura_env.IsSpam(3) then\n            aura_env.Overcharged()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    end\nend",
["spellIds"] = {
},
