["init"] = {
["custom"] = "local SpeakText = C_VoiceChat.SpeakText\n\nlocal cfg = aura_env.config\n\nif cfg.testSound then\n    WeakAuras.ScanEvents('WA_MERFIN_T13_TTS', 'Merfin Test Sound')\nend",
