["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(e, text, voiceId, speed, volume)\n    if e ~= 'WA_MERFIN_T13_TTS' then return end\n    local cfg = aura_env.config\n    if not cfg.enable then return end\n    \n    local voiceId = (cfg.applyAll and cfg.voiceId) or voiceId or 1\n    local destination = Enum.VoiceTtsDestination.LocalPlayback\n    local speed = speed or 1\n    local volume = (cfg.applyAll and cfg.volume) or volume or 100\n    \n    C_VoiceChat.SpeakText(voiceId, text, destination, speed, volume)\nend",
