["[DP] [Mel'jarak] Amber Prison"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'AmberPrison'\n\nlocal name, icon = C_Spell.GetSpellName(121876), C_Spell.GetSpellTexture(121876)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r » %destName %icon\",\n}\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID,\n            GUID = GUID\n    })\nend\n\naura_env.StartCD = function(duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n            GUID           = GUID\n    }, options)\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = destName,\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 121876 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(36, sourceGUID)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_REFRESH' then\n            if spellID == 121881 then\n                if not aura_env.IsSpam(3) then\n                    aura_env.Schedule('AMBER_PRISON_TARGETS', 0.3)\n                end\n                \n                aura_env.targets[destGUID] = destName\n            end\n        end\n        \n    elseif e == 'AMBER_PRISON_TARGETS' then\n        local names = {}\n        for _, name in pairs(aura_env.targets) do\n            table.insert(names, WA_ClassColorName(name))\n        end\n        local destNames = table.concat(names, ', ')\n        \n        aura_env.SendWarning('AmberPrison', destNames)\n        aura_env.targets = {}\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        \n        if npcID == 62405 then\n            aura_env.StopCD(destGUID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, UNIT_DIED, CLEU:SPELL_CAST_START:SPELL_AURA_APPLIED:SPELL_AURA_REFRESH, AMBER_PRISON_TARGETS",
