["subeventPrefix"] = "SPELL",
["custom"] = "function(e, _, subEvent, channelspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 106823 then -- Dragon Strike (P1)\n                aura_env.StartCD('SerpentStrike', 10.5, false, true)\n                aura_env.Warning('SerpentWave')\n            elseif spellID == 106841 then -- Dragon Strike (P2)\n                aura_env.StartCD('JadeSerpentStrike', 10.5, false, true)\n                aura_env.Warning('SerpentWave')\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 106797 then -- Jade Essence (P2 Start)\n                aura_env.Warning('Phase2')\n                aura_env.StopCD('SerpentStrike')\n            elseif spellID == 107045 then\n                aura_env.StartCD('JadeFire', 3.5, false, true)\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 106797 then -- Jade Essence (P3 Start)\n                aura_env.Warning('Phase3')\n                aura_env.StopCD('JadeSerpentStrike')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
