["[DP] [Shek'zeer] Visions of Demise"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'VisionsOfDemise'\n\nlocal name, icon = C_Spell.GetSpellName(124862), C_Spell.GetSpellTexture(124862)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r » %destName %icon\",\n    prewarnTTStext = Merfin:L('Fears Soon'),\n}\n\naura_env.MRT = function()\n    local event = 'VISIONS_' .. aura_env.count\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = destName,\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 124862 then\n                if not aura_env.IsSpam(3) then\n                    aura_env.count = aura_env.count + 1\n                    aura_env.MRT()\n                    C_Timer.After(0.3, function()\n                            WeakAuras.ScanEvents('VISIONS_TARGETS') \n                    end)\n                end\n                \n                table.insert(aura_env.targets, destName) \n            end\n        end\n        \n    elseif e == 'VISIONS_TARGETS' then\n        local names = {}\n        for index, name in ipairs(aura_env.targets) do\n            table.insert(names, WA_ClassColorName(name))\n            \n            if name == WeakAuras.me then\n                local id, side, msg\n                if index == 3 then\n                    id, side, msg = 'B', \"Back\", \"v\"\n                elseif index <= 2 then\n                    id, side, msg = 'L', \"Left\", \"<<--\"\n                else\n                    id, side, msg = 'R', \"Right\", \"-->>\"\n                end\n                \n                WeakAuras.ScanEvents('MERFIN_TTS', Merfin:L(side))\n                WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', msg, 'SAY')\n                WeakAuras.ScanEvents('SHEKZEER_VISIONS_SIDE', id)\n            end\n        end\n        \n        local destNames = table.concat(names, ', ')\n        \n        aura_env.SendWarning(destNames)\n        aura_env.targets = {}\n        aura_env.StartCD(19.5)\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN, delay = ...\n        \n        if phaseN == 3 then\n            aura_env.targets = {}\n            aura_env.count = 0\n            aura_env.StartCD(7-(delay or 0))\n        end\n    end\nend",
