["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'TotalAnnihilation'\n\nlocal options = {\n    warningText = \"%upper:name\",\n    ttsLine = Merfin:L(\"Soak the Cast\"),\n}\n\n\nlocal name, icon = C_Spell.GetSpellName(129711), C_Spell.GetSpellTexture(129711)\n\naura_env.SendWarning = function(sourceGUID)\n    local data = {\n        ID         = ID,\n        count      = aura_env.count,\n        sourceGUID = sourceGUID,\n        name       = name,\n        icon       = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 129711 then\n            if subEvent == 'SPELL_CAST_START' then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning(sourceGUID)\n            elseif subEvent == 'SPELL_CAST_SUCCESS' then\n                -- Used for Assignment Widget\n                C_Timer.After(0.1, function()\n                        WeakAuras.ScanEvents('TOTAL_ANNIHILATION_CASTED', aura_env.count)\n                end)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
