["[DP] [TSK] Shadow Blast"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'ShadowBlast'\n\nlocal options = {\n    warningText = \"%icon %name %icon\",\n}\n\nlocal name, icon = C_Spell.GetSpellName(117633), C_Spell.GetSpellTexture(117633)\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function(destName)\n    local data = { \n        ID       = ID, \n        count    = aura_env.count, \n        destName = WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID, spellName = ...\n        \n        if spellID == 117628 then\n            aura_env.count = aura_env.count + 1\n            aura_env.StartCD(5)\n            \n            C_Timer.After(0.1, function()\n                    WeakAuras.ScanEvents('CHECK_BLAST_TARGET', spellName) \n            end)\n        end\n        \n    elseif e == 'CHECK_BLAST_TARGET' then\n        local spellName = ...\n        for _, bossID in ipairs({'boss1', 'boss2', 'boss3', 'boss4'}) do\n            local name = UnitCastingInfo(bossID)\n            \n            if name == spellName then\n                local targetName = UnitName(bossID .. 'target')\n                aura_env.SendWarning(targetName)\n            end\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'ZIAN' then return end\n        \n        aura_env.bossActivated = activated\n        \n        if activated then \n            aura_env.StartCD(5-delay)\n        else\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
