["init"] = {
["custom"] = "aura_env.lib = LibStub and LibStub(\"LibSpecialization\", true) or nil\nif not aura_env.lib then return end\n\naura_env.token = {}\n\nlocal function NameToUnit(name)\n    if not name then return nil end\n    if name == GetUnitName(\"player\", true) then return \"player\" end\n    if IsInRaid() then\n        for i = 1, GetNumGroupMembers() do\n            local u = \"raid\"..i\n            if GetUnitName(u, true) == name then return u end\n        end\n    else\n        for i = 1, GetNumSubgroupMembers() do\n            local u = \"party\"..i\n            if GetUnitName(u, true) == name then return u end\n        end\n    end\n    return nil\nend\n\naura_env.lib.RegisterGroup(aura_env.token, function(specId, role, position, sender, talentString)\n        local unit = NameToUnit(sender)\n        if unit and WeakAuras then\n            WeakAuras.ScanEvents(\"STBAN_LIBSPEC_UNIT_UPDATED\", unit)\n        end\nend)",
["do_custom"] = true,
