["init"] = {
["custom"] = "local encounterID = '1499'\nlocal ID          = 'Phase'\n\nlocal phaseNames = {\n    ['Phase2'] = Merfin:L('Phase 2'),\n    ['Phase3'] = Merfin:L('Phase 3'),\n}\n\nlocal options = {\n    ['Phase2'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", phaseNames['Phase2']:upper()),\n        ttsLine = phaseNames['Phase2'],\n    },\n    ['Phase3'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", phaseNames['Phase3']:upper()),\n        ttsLine = phaseNames['Phase3'],\n    },\n}\n\naura_env.MRT = function(event)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.SendWarning = function(ID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID   = ID,\n            name = phaseNames[ID],\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
