["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 122540 then\n                WeakAuras.ScanEvents('UNSOK_PHASE', 2)\n                aura_env.SendWarning('Phase2')\n                aura_env.MRT('PHASE_2')\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 122540 then\n                WeakAuras.ScanEvents('UNSOK_PHASE', 3)\n                aura_env.SendWarning('Phase3')\n                aura_env.MRT('PHASE_3')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        WeakAuras.ScanEvents('UNSOK_PHASE', 1)\n    end\nend",
