["actions"] = {
["start"] = {
["message"] = "你在打脸",
["custom"] = "if aura_env.config.isVoice and not aura_env.isMuteBoss() then\n    local willplay = PlaySoundFile(aura_env.sfile, \"Master\")\n    if not willplay then\n        aura_env.sendMessage(aura_env.ttstext)\n    end\nend\n\n\n\n\n",
["message_tts_voice"] = 0,
["do_custom"] = true,
["do_message"] = false,
["message_type"] = "TTS",
},
["init"] = {
["custom"] = "aura_env.ttstext = \"打脸了\"\naura_env.sfile = \"Interface\\\\AddOns\\\\SharedMedia_Rurutia\\\\Rurutia\\\\【露露】打脸咯.ogg\"\n\nif not ( GetLocale() == \"zhCN\" or GetLocale() == \"zhTW\" ) then\n    -- change Attacking Face voice to english if not cn client.\n    aura_env.ttstext = \"ticking face\"\nend\n\naura_env.encounterID = 0\naura_env.encounterName = \"\"\n\n--静音BOSS战\naura_env.muteBoss = {\n    --塔迪乌斯\n    [1] = \"Thaddius\", --en\n    [2] = \"塔迪乌斯\", --cn\n    [3] = \"泰迪斯\", --tw\n    [4] = \"타디우스\",--kr\n    [5] = \"Таддиус\", --ru\n    --科隆加恩\n    [6] = \"Kologarn\", --en\n    [7] = \"科隆加恩\", --cn\n    [8] = \"柯洛剛恩\", --tw\n    [9] = \"콜로간\",--kr\n    [10] = \"Кологарн\", --ru\n    --欧尔莉亚\n    [11] = \"Auriaya\", --en\n    [12] = \"欧尔莉亚\", --cn\n    [13] = \"奧芮雅\", --tw\n    [14] = \"아우리아야\", --kr\n    [15] = \"Ауриайа\", --ru\n    \n}\n\naura_env.isMuteBoss = function()\n    for k,v in ipairs(aura_env.muteBoss) do\n        if v == UnitName(\"target\") then\n            print(v)\n            return true\n        end\n    end\n    return false\nend\n\naura_env.sendMessage = function(text)\n    C_VoiceChat.SpeakText(0, text, 0, 0, 100)\nend",
["do_custom"] = true,
},
