["[DP] [TSK] Undying Shadows"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'UndyingShadows'\n\nlocal name, icon = C_Spell.GetSpellName(117514), C_Spell.GetSpellTexture(117514)\n\nlocal options = {\n    ['Fixate'] = {\n        warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    },\n    ['ShadowsGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    },\n    ['UndyingShadows'] = {\n        warningText = \"%icon %name %icon\",\n    }\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['UndyingShadows'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    local data = { \n        ID       = ID, \n        count    = aura_env.count, \n        destName = WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 117506 then\n                aura_env.count = aura_env.count + 1\n                aura_env.StartCD(41.5)\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 117506 then\n                aura_env.count = aura_env.count + 1\n                local timer = aura_env.bossActivated and 41.5 or 85\n                aura_env.StartCD(timer)\n            elseif spellID == 117539 then\n                WeakAuras.ScanEvents('COALESCING_SHADOW', sourceGUID)\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 118303 then\n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning('Fixate', destName)\n                end\n                aura_env.shadows[sourceGUID] = (aura_env.shadows[sourceGUID] or 0) + 1\n            end\n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 117558 and destGUID == WeakAuras.myGUID and not aura_env.IsSpam(3) then\n                aura_env.SendWarning('ShadowsGTFO')\n            end\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'ZIAN' then return end\n        \n        aura_env.shadows = {}\n        aura_env.bossActivated = activated\n        \n        if activated then \n            aura_env.StartCD(20-delay)\n        else\n            aura_env.StartCD(30)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
