["[DP] [Un'sok] Reshape Life"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1499'\nlocal ID          = 'ReshapeLife'\n\nlocal name, icon = C_Spell.GetSpellName(122784), C_Spell.GetSpellTexture(122784)\n\nlocal options = {\n    warningText = \"%icon @cffffff40%name@r » %destName %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, expirationTime)\n    aura_env.last = expirationTime\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = false,\n            duration       = duration,\n            expirationTime = expirationTime,\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            duration       = 2.5,\n            expirationTime = 2.5 + GetTime(),\n            count          = aura_env.count,\n            destName       = WA_ClassColorName(destName)\n    }, options)\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend\n\naura_env.GetElapsed = function()\n    if not aura_env.last then return 0 end\n    return aura_env.last - GetTime()\nend\n\naura_env.keyFlags = { [1] = false, [2] = false, [3] = false, [4] = false, [5] = false }\naura_env.unitToKey = {}\n\naura_env.GetAvailableKey = function()\n    for i, taken in ipairs(aura_env.keyFlags) do\n        if not taken then\n            aura_env.keyFlags[i] = true\n            return i\n        end\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 122784 then\n                aura_env.count = aura_env.count + 1\n                \n                --if destGUID ~= WeakAuras.myGUID then\n                aura_env.SendWarning(destName)\n                --end\n                \n                local seconds = aura_env.phase == 3 and 15 or 50\n                aura_env.StartCD(seconds, seconds+GetTime())\n                WeakAuras.ScanEvents('RESHAPE_LIFE', 'APPLIED', destGUID, destName)\n                \n                local key = aura_env.GetAvailableKey()\n                aura_env.keyFlags[key] = true\n                aura_env.unitToKey[destGUID] = key\n                \n                WeakAuras.ScanEvents('WIDGET_RESHAPE_LIFE', true, key, destGUID, destName)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 122370 then\n                WeakAuras.ScanEvents('RESHAPE_LIFE', 'REMOVED', destGUID, destName)\n                \n                local key = aura_env.unitToKey[destGUID]\n                aura_env.keyFlags[key] = false\n                aura_env.unitToKey[destGUID] = nil\n                \n                WeakAuras.ScanEvents('WIDGET_RESHAPE_LIFE', false, key, destGUID, destName)\n            end\n        end\n        \n    elseif e == 'UNSOK_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase = 2\n        elseif phaseN == 3 then\n            aura_env.phase = 3\n            local elapsed = aura_env.GetElapsed()\n            \n            if elapsed > 35.2 or elapsed == 0 then\n                aura_env.StartCD(50, 35.2+GetTime())\n            end\n        end\n        \n    elseif e == 'RESHAPE' then\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.keyFlags = { [1] = false, [2] = false, [3] = true, [4] = false, [5] = false }\n        aura_env.unitToKey = {}\n        aura_env.count = 0\n        aura_env.phase = 1\n        aura_env.StartCD(20, 20+GetTime())\n    end\nend",
