["custom"] = "function(states, event, ...)\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if states[sourceGUID] and spellID == 122389 then\n            states:Update(sourceGUID, { \n                    duration = 6,\n                    expirationTime = 6 + GetTime(),\n                    autoHide = false,\n            })\n        end\n        \n    elseif event == 'WIDGET_RESHAPE_LIFE' then\n        local show, unitKey, GUID = ...\n        \n        if unitKey ~= aura_env.unitKey then return end\n        \n        if show then\n            states:Update(GUID, {\n                    progressType = 'timed',\n                    duration = 6,\n                    expirationTime = GetTime(),\n                    autoHide = false,\n            })\n            \n        elseif states[GUID] then\n            states:Remove(GUID)\n        end\n    end\nend",
