["General Options - LWA - Monk"] = {
["iconSource"] = 0,
["wagoID"] = "l-crrrmCG",
["parent"] = "武僧 中心分组",
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
