["init"] = {
["custom"] = "local encounterID = 'Trash'\n\nlocal GetSpellInfoTable = function(spellID)\n    return {\n        name = C_Spell.GetSpellName(spellID),\n        icon = C_Spell.GetSpellTexture(spellID)\n    }\nend\n\nlocal data = {\n    ['NightTerrors'] = GetSpellInfoTable(125736),\n    ['OverwhelmingFear'] = GetSpellInfoTable(125758)\n}\n\nlocal options = {\n    ['NightTerrors'] = {warningText = \"%icon @cff8f8f8f%name@r %icon\"},\n    ['OverwhelmingFear'] = {warningText = \"%icon @cff8f8f8f%name@r %icon\"}\n}\n\naura_env.StopCD = function(ID, destGUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID,\n        {ID = ID, GUID = destGUID})\nend\n\naura_env.StartCD = function(ID, duration, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = true,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            noCount = true,\n            GUID = GUID,\n            name = data[ID].name,\n            icon = data[ID].icon\n    }, options[ID])\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            count = aura_env.count,\n            noCount = true,\n            name = data[ID].name,\n            icon = data[ID].icon,\n            destName = WA_ClassColorName(destName)\n    }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 125736 then\n                aura_env.SendWarning('NightTerrors')\n                aura_env.StartCD('NightTerrors', 30, sourceGUID)\n                \n            elseif spellID == 125758 then\n                aura_env.SendWarning('OverwhelmingFear', destName)\n                aura_env.StartCD('OverwhelmingFear', 12, sourceGUID)\n            end\n        end\n        \n    elseif e == 'NAME_PLATE_ENTERED_COMBAT' then\n        local _, unitGUID, npcID = ...\n        if npcID == 64368 then\n            aura_env.StartCD('OverwhelmingFear', 5, unitGUID)\n            aura_env.StartCD('NightTerrors', 18.5, unitGUID)\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID = ...\n        if npcID == 64368 then\n            aura_env.StopCD('NightTerrors', destGUID)\n            aura_env.StopCD('OverwhelmingFear', destGUID)\n        end\n    end\nend",
