["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_START:SPELL_AURA_APPLIED:SPELL_CAST_SUCCESS:UNIT_DIED, UNIT_SPELLCAST_SUCCEEDED, WA_MERFIN_T13_SCHEDULED, RAID_BOSS_EMOTE",
["custom"] = "function(e, msg, subEvent, uSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId, _, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellId == 107018 then\n                aura_env.parasiteCasted = false\n                if aura_env.firstAspect then\n                    aura_env.firstAspect = false\n                    aura_env.StartCD('MutatedCorruption', 11, true)\n                    aura_env.StartCD('Impale', 22)\n                    aura_env.StartCD('ElementiumBolt', 45.5, true)\n                    if aura_env.IsHeroic then\n                        aura_env.StartCD('Hemorrhage', 55.5, true)\n                        aura_env.StartCD('Parasite', 11)\n                    else\n                        aura_env.StartCD('Hemorrhage', 85.5, true)\n                    end\n                    aura_env.StartCD('Cataclysm', 115.5+60, true)\n                    return\n                end\n                \n                aura_env.StartCD('MutatedCorruption', 17, true)\n                aura_env.StartCD('Impale', 27.5)\n                aura_env.StartCD('ElementiumBolt', 65.5, true)\n                \n                if aura_env.IsHeroic then\n                    aura_env.StartCD('Hemorrhage', 70.5, true)\n                    aura_env.StartCD('Parasite', 22)\n                else\n                    aura_env.StartCD('Hemorrhage', 100.5, true)\n                end\n                aura_env.StartCD('Cataclysm', 130.5+60)\n                \n            elseif spellId == 106523 then\n                aura_env.StartCD('CataclysmCast', 60)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellId == 106400 then\n                aura_env.StartCD('Impale', 35, false, true)\n            elseif spellId == 106548 then -- Transition\n                aura_env.StopCD('CataclysmCast')\n                aura_env.StopCD('ElementiumBolt')\n                aura_env.StopCD('Hemorrhage')\n                aura_env.StopCD('Cataclysm')\n            elseif spellId == 106834 then -- Phase 2\n                aura_env.StopCD('Impale')\n                aura_env.StopCD('Parasite')\n                aura_env.StopCD('Hemorrhage')\n                aura_env.StartCD('Fragments', 10.5)\n                aura_env.StartCD('Terror', 35.5)\n                aura_env.Warning('Phase2')\n            elseif spellId == 108649 then\n                if aura_env.parasiteCasted then\n                    return\n                end\n                aura_env.parasiteCasted = true\n                aura_env.StartCD('Parasite', 60, true, true)\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellId == 105651 then \n                aura_env.ScheduleEvent('WarnElementiumBolt', 7)\n                aura_env.StartCD('ElementiumBoltSoon', 7)\n            end\n        elseif subEvent == 'UNIT_DIED' then\n            if aura_env.IsGUID(destGUID, 'MutatedCorruption') then\n                aura_env.StopCD('Impale')\n            elseif aura_env.IsGUID(destGUID, 'ElementiumTerror') then\n                --aura_env.StopCD('Tenatus')\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        if uSpellId == 105863 then \n            aura_env.Warning('Hemorrhage')\n            aura_env.StopCD('Hemorrhage')\n        elseif uSpellId == 105551 then\n            aura_env.Warning('BlisteringTentacle')\n        elseif uSpellId == 106775 then\n            aura_env.Warning('Fragments')\n            aura_env.StartCD('Fragments', 90, false, true)\n        elseif uSpellId == 106765 then\n            aura_env.Warning('Terror')\n            aura_env.StartCD('Terror', 90)\n        elseif uSpellId == 197835 then -- DELETE THIS\n            aura_env.StartCD('MutatedCorruption', 17, true)\n            aura_env.StartCD('Impale', 27.5)\n            aura_env.StartCD('ElementiumBolt', 65.5, true)\n        end\n        \n    elseif e == 'WA_MERFIN_T13_SCHEDULED' then\n        if msg == 'WarnElementiumBolt' then\n            aura_env.Warning('ElementiumBoltSoon')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('Berserk', 900)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
