["unit"] = "player",
["custom"] = "function(states, event, ...)\n    \n    if event == 'WIDGET_RESHAPE_LIFE_EXPLOSION' then\n        local GUID, duration = ...\n        \n        if states[GUID] then\n            states:Update(GUID, { \n                    duration = duration,\n                    expirationTime = duration + GetTime(),\n                    autoHide = false,\n            })\n        end\n        \n    elseif event == 'WIDGET_RESHAPE_LIFE' then\n        local show, unitKey, GUID = ...\n        \n        if unitKey ~= aura_env.unitKey then return end\n        \n        if show then\n            states:Update(GUID, {\n                    progressType = 'timed',\n                    duration = 15,\n                    expirationTime = 15 + GetTime(),\n                    autoHide = false,\n            })\n            \n        elseif states[GUID] then\n            states:Remove(GUID)\n        end\n    end\nend",
