["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1506'\nlocal ID          = 'ScaryFog'\n\nlocal name, icon = C_Spell.GetSpellName(123705), C_Spell.GetSpellTexture(123705)\n\nlocal options = {warningText = '%icon %name %icon'}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env.expTime = duration + GetTime()\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count,\n    }, options)\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then aura_env.scheduler:Cancel() end\n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, _, _, _, _, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 123705 then\n                WeakAuras.ScanEvents('SCARY_FOG_REPEAT')\n                \n            elseif spellID == 123244 then\n                aura_env.StopCD()\n                \n                if aura_env.scheduler then\n                    aura_env.scheduler:Cancel()\n                end\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 123705 and not aura_env.IsSpam(2.5) then\n                WeakAuras.ScanEvents('SCARY_FOG_REPEAT')\n            end\n        end\n        \n    elseif e == 'SCARY_FOG_REPEAT' then\n        aura_env.StopCD()\n        \n        if aura_env.scheduler then\n            aura_env.scheduler:Cancel()\n        end\n        \n        aura_env.count = aura_env.count + 1\n        \n        local haste = aura_env.haste or 0\n        local interval = 10 / (1 + haste / 100)\n        \n        aura_env.StartCD(interval)\n        aura_env.Schedule('SCARY_FOG_REPEAT', interval)\n        \n    elseif e == 'AFRAID_HASTE_CHANGED' then\n        aura_env.haste = ...\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.haste = 0\n        aura_env.count = 0\n        aura_env.StartCD(10)\n    end\nend",
