},
["preferToUpdate"] = true,
["yOffset"] = 20,
["anchorPoint"] = "TOP",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["do_custom"] = false,
["custom"] = "",
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["customVariables"] = "{\n    rotation = \"number\",\n    status = \"string\", \n    unit = \"string\"\n}",
["event"] = "Health",
["unit"] = "player",
["custom"] = "-- Author: 露露緹婭@Bilibili\n\nfunction(allstates, event, ...)\n    if not aura_env.initialized then\n        aura_env.interruptCounts = {}\n        aura_env.rotation = 3 --默认使用3轮打断\n        aura_env.trackedNpcs = {\n            [\"60586\"] = true,   -- 长老阿萨尼\n            --[\"165414\"] = true,  -- 堕落的歼灭者，测试用\n        }\n        aura_env.trackedSpells = {\n            [118312] = true,    -- 水箭\n            --[338003] = true,    -- 邪恶箭矢，测试用\n        }\n        aura_env.initialized = true\n    end\n    \n    local function isTrackedNpc(guid)\n        if not guid then return false end\n        local npcId = select(6, string.split(\"-\", guid))\n        return aura_env.trackedNpcs[npcId] == true\n    end\n    \n    local function isTrackedSpell(spellId)\n        return aura_env.trackedSpells[spellId] == true\n    end\n    \n    local function updateVisibleNameplateUnits(changedGUID, status)\n        for _, plateData in ipairs(C_NamePlate.GetNamePlates()) do\n            local unit = plateData.UnitFrame.displayedUnit\n            local guid = UnitGUID(unit)\n            if guid and guid == changedGUID then\n                local currentCount = aura_env.interruptCounts[guid] or 0\n                local displayCount = (currentCount % aura_env.rotation) + 1\n                allstates[guid] = {\n                    show = true,\n                    changed = true,\n                    rotation = displayCount,\n                    status = status or \"Idle\",\n                    unit = unit,\n                }\n            end\n        end\n    end\n    \n    if event == \"OPTIONS\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            rotation = 2,\n            status = \"Idle\",\n            unit = \"target\",\n        }\n        return true\n    end\n    \n    if event == \"ENCOUNTER_START\" then\n        aura_env.interruptCounts = {}\n        return true\n    elseif event == \"NAME_PLATE_UNIT_ADDED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        if not isTrackedNpc(guid) then return false end\n        \n        local currentCount = aura_env.interruptCounts[guid] or 0\n        local displayCount = (currentCount % aura_env.rotation) + 1\n        allstates[guid] = {\n            show = true,\n            changed = true,\n            rotation = displayCount,\n            status = \"Idle\",\n            unit = unit,\n        }\n        return true\n    elseif event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        if allstates[guid] then\n            allstates[guid].show = false\n            allstates[guid].changed = true\n            return true\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent, _, sourceGUID, _, _, _, destGUID, _, _, _, spellId, _, _, extraSpellId = ...\n        \n        if subEvent == \"SPELL_CAST_START\" then\n            if not isTrackedSpell(spellId) or not isTrackedNpc(sourceGUID) then\n                return false\n            end\n            updateVisibleNameplateUnits(sourceGUID, \"Casting\")\n            return true\n        elseif subEvent == \"SPELL_INTERRUPT\" then\n            if not isTrackedSpell(extraSpellId) or not isTrackedNpc(destGUID) then\n                return false\n            end\n            local count = (aura_env.interruptCounts[destGUID] or 0) + 1\n            aura_env.interruptCounts[destGUID] = count\n            updateVisibleNameplateUnits(destGUID, \"Idle\")\n            return true\n        elseif subEvent == \"SPELL_CAST_SUCCESS\" then\n            if not isTrackedSpell(spellId) or not isTrackedNpc(sourceGUID) then\n                return false\n            end\n            local count = (aura_env.interruptCounts[sourceGUID] or 0) + 1\n            aura_env.interruptCounts[sourceGUID] = count\n            updateVisibleNameplateUnits(sourceGUID, \"Idle\")\n            return true\n        end\n    end\n    \n    return false\nend",
["spellIds"] = {
},
