["custom"] = "function(states, event, ...)\n    \n    if event == 'OPTIONS' then\n        local ratioPercent = math.random(0, 250)\n        local deltaPercent   = ratioPercent - 100\n        states:Update('', { ratioPercent = ratioPercent, deltaPercent = deltaPercent })\n        return true\n    end\n    \n    local unit = aura_env.unit\n    local spellID = aura_env.debuffSpellID\n    \n    local isDebuffed = WA_GetUnitDebuff(unit, spellID, 'PLAYER')\n    \n    if not isDebuffed then \n        states:Remove('')\n        return true \n    end\n    \n    if event == 'MERFIN_SNAPSHOT_CHANGED' then\n        local data = ...\n        \n        if data.ID ~= aura_env.debuffID then return end\n        \n        local GUID = UnitGUID(unit)\n        \n        if data.destGUID ~= GUID then return end\n        \n        local predict        = data.predict\n        local targetSnapshot = data.snapshot\n        local ratioPercent   = 100 * predict / targetSnapshot\n        local deltaPercent   = ratioPercent - 100\n        \n        states:Update('', { ratioPercent = ratioPercent, deltaPercent = deltaPercent })\n        \n    elseif event == 'PLAYER_TARGET_CHANGED' then\n        local db = aura_env.snapshotDB\n        \n        if not db then\n            return\n        end\n        \n        local ID = aura_env.debuffID\n        local GUID = UnitGUID(unit)\n        \n        if db.snapshotDamage and db.snapshotDamage[ID] and db.snapshotDamage[ID][GUID] then\n            local predict = db.predictedDamage[ID]\n            local targetSnapshot = db.snapshotDamage[ID][GUID]\n            local ratioPercent   = 100 * predict / targetSnapshot\n            local deltaPercent   = ratioPercent - 100\n            \n            states:Update('', { ratioPercent = ratioPercent, deltaPercent = deltaPercent })\n        end\n    end\nend",
["custom_type"] = "stateupdate",
["check"] = "event",
["customVariables"] = "{\n    ratioPercent = {\n        display = 'Ratio Percent',\n        type = 'number'\n    }\n}",
["events"] = "MERFIN_SNAPSHOT_CHANGED, PLAYER_TARGET_CHANGED, TRIGGER:1",
["unit"] = "player",
},
["untrigger"] = {
},
},
{
