["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["names"] = {
},
["custom"] = "function(a, event, ...)\n    \n    if event == 'TRIGGER' then\n        \n        local updatedTriggerNumber, updatedTriggerStates = ...\n        \n        if updatedTriggerNumber ~= 2 and updatedTriggerNumber ~= 3 then\n            return\n        end\n        \n        if not updatedTriggerStates then\n            return\n        end\n        \n        for unit, state in pairs(updatedTriggerStates) do\n            local percenthealth = state.percenthealth\n            local guid = UnitGUID(unit)\n            \n            if guid and percenthealth then\n                if percenthealth <= 0.01 then\n                    a[guid] = {\n                        show = false,\n                        changed = true,\n                    }\n                else\n                    a[guid] = {\n                        show = true,\n                        changed = true,\n                        progressType = 'static',\n                        value = percenthealth,\n                        total = 100,\n                    }\n                end\n            end\n        end\n        \n        return true\n    end\n    \n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID = ...\n        if a[destGUID] then\n            a[destGUID].show = false\n            a[destGUID].changed = true\n            return true\n        end\n    end\nend",
