["custom"] = "function(a, e, encounterID, cooldown)\n    \n    if e == 'WA_MERFIN_BOSS_CD' then\n        if not cooldown then return end\n        if aura_env.cooldownName ~= cooldown.id then return end\n        \n        local stateName = encounterID .. cooldown.id\n        \n        a[stateName] = {\n            show = true,\n            changed = true,\n            progressType = 'timed',\n            duration = cooldown.duration,\n            expirationTime = cooldown.expirationTime,\n            autoHide = cooldown.autoHide,\n            icon = cooldown.icon,\n            name = cooldown.name,\n            nextCount = (cooldown.count or 0) + 1,\n        }\n        \n        return true\n        \n    elseif e == 'WA_MERFIN_BOSS_CD_HIDE' then\n        if not cooldown then return end\n        if aura_env.cooldownName ~= cooldown.id then return end\n        \n        local stateName = encounterID .. cooldown.id\n        \n        a[stateName] = {\n            show = false,\n            changed = true,\n        }\n        \n        return true\n    end\n    \nend",
