["[Council] Hydro Lance Interrupt"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["parent"] = "[Merfin] T11 打断小助手",
["displayText"] = "%counter",
["yOffset"] = 0,
