["[DP] [Protectors] Touch of Sha"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1409'\nlocal ID = 'TouchOfSha'\n\nlocal name, icon = C_Spell.GetSpellName(117519), C_Spell.GetSpellTexture(117519)\n\nlocal options = {\n    warningText = \"%icon @cffff4040%name@r » %destName %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            destName = destName\n    }, options)\nend\n\naura_env.GetPlayersInSameZone = function()\n    local count = 1 -- (Player)\n    local myZoneID = C_Map.GetBestMapForUnit(\"player\")\n    \n    if not myZoneID then return 0 end\n    \n    for i = 1, GetNumGroupMembers() do\n        local unit = IsInRaid() and (\"raid\" .. i) or (\"party\" .. i)\n        if UnitExists(unit) and not UnitIsUnit(unit, \"player\") then\n            local unitZoneID = C_Map.GetBestMapForUnit(unit)\n            if unitZoneID == myZoneID then count = count + 1 end\n        end\n    end\n    \n    return count\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 117519 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning(destName)\n                \n                if aura_env.count < aura_env.numPlayers then\n                    local seconds = aura_env.isTen and 29 or 12\n                    aura_env.StartCD(seconds)\n                else\n                    aura_env.StopCD()\n                end\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 117519 then\n                aura_env.count = aura_env.count - 1\n            end\n        end\n        \n    elseif e == 'PROTECTORS_PHASE' then\n        local phaseN, npcDied = ...\n        \n        if npcDied == 60583 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isTen = WeakAuras.InstanceType() == 'ten'\n        aura_env.numPlayers = aura_env.GetPlayersInSameZone()\n        aura_env.count = 0\n        aura_env.targets = {}\n        \n        local seconds = aura_env.isTen and 35 or 15\n        aura_env.StartCD(seconds)\n    end\nend",
