["do_glow"] = false,
["glow_thickness"] = 4,
["custom"] = "-- Author: 露露緹婭@Bilibili\n-- 获取当前触发的技能ID\nlocal spellId = aura_env.state and aura_env.state.spellId\nif not spellId or not aura_env.RurutiaSoundMap[spellId] then\n    return\nend\n\nlocal currentTime = GetTime()\n\n-- 检查冷却时间\nif aura_env.cooldownConfig[spellId] then\n    local cooldownTime = aura_env.cooldownConfig[spellId]\n    local lastTime = aura_env.lastPlayTime[spellId] or 0\n    if currentTime - lastTime < cooldownTime then\n        return\n    end\n    aura_env.lastPlayTime[spellId] = currentTime\nend\n\n-- 播放音效\nlocal soundFile = aura_env.RurutiaSoundMap[spellId]\nif not soundFile:match(\"^Interface\\\\\") then\n    soundFile = aura_env.RurutiaFilePath .. soundFile\nend\nPlaySoundFile(soundFile, \"Master\")",
["do_sound"] = false,
["glow_color"] = {
0,
0.54117649793625,
1,
1,
},
