["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID = 'Phase'\n\naura_env.MRT = function(event) GMRT.F.Note_Timer(event) end\n\nlocal phaseNames = {\n    ['Phase1'] = Merfin:L('Phase 1'),\n    ['Phase2'] = Merfin:L('Phase 2'),\n    ['Phase3'] = Merfin:L('Phase 3')\n}\n\nlocal options = {\n    ['Phase1'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase1']:upper()),\n        ttsLine = phaseNames['Phase1'],\n        prewarnTTStext = string.format(Merfin:L('%s soon'), phaseNames['Phase1'])\n    },\n    ['Phase2'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase2']:upper()),\n        ttsLine = phaseNames['Phase2'],\n        prewarnTTStext = string.format(Merfin:L('%s soon'), phaseNames['Phase2'])\n    },\n    ['Phase3'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\",\n            phaseNames['Phase3']:upper()),\n        ttsLine = phaseNames['Phase3'],\n        prewarnTTStext = string.format(Merfin:L('%s soon'), phaseNames['Phase3'])\n    }\n}\n\nlocal icon = 624012\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(ID, duration)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = false,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = phaseNames[ID],\n            icon = icon,\n            noCount = true\n        }, options[ID])\nend\n\naura_env.SendWarning = function(ID, delay)\n    WeakAuras.ScanEvents('SHEKZEER_PHASE', aura_env.phase, delay)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID,\n        {ID = ID, name = phaseNames[ID], icon = icon},\n        options[ID])\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Phase3 = \"No more excuses, Empress! Eliminate these cretins or I will kill you myself!\"\n    },\n    ['zhCN'] = {\n        Phase3 = \"别找借口了，女皇！消灭这些傻瓜，否则我会亲手杀了你！\"\n    },\n    ['deDE'] = {\n        Phase3 = \"KEINE AUSREDEN MEHR, KAISERIN! Tötet diese Idioten oder ich selbst mache Euch den Garaus!\"\n    },\n    ['frFR'] = {\n        Phase3 = \"Assez de vos excuses, impératrice ! Éliminez ces crétins ou je vous achève moi-même !\"\n    },\n    ['koKR'] = {\n        Phase3 = \"변명은 이제 지겹다, 여제! 당장 이 멍청이들을 쓸어버리지 않으면 내가 몸소 널 죽이겠다!\"\n    },\n    ['ruRU'] = {\n        Phase3 = \"Больше никаких оправданий, императрица! Избавься от этих кретинов или я сам убью тебя!\"\n    },\n    ['zhTW'] = {\n        Phase3 = \"不要再找藉口了，女皇!消滅這些侏儒，否則我會親自殺了妳!\"\n    }\n}",
["do_custom"] = true,
},
},
