["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 125451 and aura_env.phase ~= 3 then\n                aura_env.phase = 3\n                aura_env.StopCD('Phase2')\n                aura_env.SendWarning('Phase3', 3)\n                aura_env.MRT('PHASE_3')\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID,_, spellID = ...\n        \n        if spellID == 125304 then\n            aura_env.phase = 1\n            aura_env.StopCD('Phase1')\n            aura_env.SendWarning('Phase1')\n            aura_env.StartCD('Phase2', 151)\n            \n        elseif spellID == 125098 then\n            aura_env.phase = 2\n            aura_env.StopCD('Phase2')\n            aura_env.SendWarning('Phase2')\n            aura_env.StartCD('Phase1', 156.4)\n            aura_env.MRT('PHASE_2')\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_YELL' then\n        local msg = ...\n        \n        if aura_env.IsEmote(msg, 'Phase3') then\n            aura_env.phase = 3\n            aura_env.StopCD('Phase2')\n            aura_env.SendWarning('Phase3', 0)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.phase = 1\n        aura_env.StartCD('Phase2', 151)\n    end\nend",
