["[DP] [Garalon] Phase"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1463'\nlocal ID          = 'Phase2'\n\nlocal name = Merfin:L('Phase 2')\n\nlocal options = {\n    warningText = string.format(\"@cffe3e3e3» %s «@r\", name:upper()),\n    ttsLine = name\n}\n\naura_env.SendWarning = function()\n    local warning = {\n        ID      = ID,\n        name    = name,\n        noCount = true,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, warning, options)\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Under = \"under him\",\n        Phase2 = \"armor plating begins to crack\"\n    },\n    ['zhCN'] = {\n        Under = \"在它下方\",\n        Phase2 = \"巨型盔甲开始碎裂了\"\n    },\n    ['deDE'] = {\n        Under = \"Unter ihm\",\n        Phase2 = \"Plattenrüstung reißt und platzt auf\"\n    },\n    ['frFR'] = {\n        Under = \"sous lui\",\n        Phase2 = \"commence à se fendiller !\"\n    },\n    ['ruRU'] = {\n        Under = \"под ним\",\n        Phase2 = \"доспех Гаралона начинает трескаться и расползаться\"\n    },\n    ['koKR'] = {\n        Under = \"있는 것을 감지하고\",\n        Phase2 = \"장갑이 갈라지면서 쪼개지기\"\n    },\n    ['zhTW'] = {\n        Under = \"在他下面\",\n        Phase2 = \"巨大的裝甲開始破裂並粉碎!\"\n    },\n    ['esES'] = {\n        Under = \"Debajo de él\"\n    },\n}\n\naura_env.MRT = function(event)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    GMRT.F.Note_Timer(event)\nend",
["do_custom"] = true,
},
},
