["custom"] = "aura_env.GetNPCIDFromGUID = function(GUID)\n    local guidType, _, _, _, _, id = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id) or 0\n    end\n    return 0\nend\n\naura_env.guids = {}\n\naura_env.tracked = {\n    -- Heart of Fear\n    [64902] = true, -- Kor'thik Fleshrender (after Mel'jarak)\n    [63569] = true, -- Amber Searsting\n    [63568] = true, -- Amber-Ridden Mushan\n    [64453] = true, -- Set'thik Windblade\n    [64458] = true, -- Kor'thik Warsinger\n    [64454] = true, -- Zar'thik Augurer\n    \n    -- Terrace of Endless Spring\n    [66100] = true, -- Apparition of Terror\n    [64368] = true, -- Apparition of Fear\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["duration"] = "25",
