["unit"] = "player",
["debuffType"] = "HELPFUL",
["spellIds"] = {
},
["custom"] = "function(e, ...)\n    if e == 'UNIT_THREAT_LIST_UPDATE' then\n        local nameplateID = ...\n        local unitGUID = UnitGUID(nameplateID)\n        local npcID = aura_env.GetNPCIDFromGUID(unitGUID)\n        \n        if npcID and aura_env.tracked[npcID] and aura_env.guids[unitGUID] then\n            local inCombat = UnitAffectingCombat(nameplateID)\n            if inCombat then\n                WeakAuras.ScanEvents('NAME_PLATE_ENTERED_COMBAT', nameplateID, unitGUID, npcID)\n            end\n        end\n        \n    elseif e == 'NAME_PLATE_UNIT_ADDED' then\n        local nameplateID = ...\n        local unitGUID = UnitGUID(nameplateID)\n        local npcID = aura_env.GetNPCIDFromGUID(unitGUID)\n        \n        if npcID and aura_env.tracked[npcID] then\n            local inCombat = UnitAffectingCombat(nameplateID)\n            if not inCombat then\n                aura_env.guids[unitGUID] = true\n            else\n                aura_env.guids[unitGUID] = nil\n            end\n        end\n    end\nend",
