["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 128164 and destGUID == WeakAuras.myGUID then\n                --aura_env.Chat('{rt2} ' .. WeakAuras.me .. ' carrying bucket {rt2}')\n            elseif spellID == 114185 then\n                aura_env.Warning('ScarletProtection')\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' and destGUID == WeakAuras.myGUID then\n            if spellID == 128164 then\n                --aura_env.Chat('- threw -')\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 114182 then\n                aura_env.Warning('FireballVolley')\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
