["custom"] = "local encounterID = '1504'\nlocal ID          = 'Intensify'\n\nlocal name, icon = C_Spell.GetSpellName(123471), C_Spell.GetSpellTexture(123471)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r @cffffff40+%damage%@r %icon\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = GetTime() + duration,\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID     = ID,\n            name   = name,\n            icon   = icon,\n            count  = aura_env.count,\n            damage = amount * 5\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID,_,_,_, amount = ...\n        \n        if spellID == 123471 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning(amount or 1)\n            aura_env.StartCD(aura_env.cd)\n        end\n        \n    elseif e == 'PHASE_2' then\n        aura_env.cd = 10\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.cd = 60\n        aura_env.StartCD(aura_env.cd)\n    end\nend",
