},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'Exhale'\n\nlocal name, icon = C_Spell.GetSpellName(122761), C_Spell.GetSpellTexture(122761)\n\nlocal options = {\n    warningText = '%icon %name » %destName %icon'\n}\n\naura_env.SendWarning = function(destName)\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID,_,_,_, amount = ...\n        \n        if spellID == 122761 then\n            if subEvent == 'SPELL_AURA_APPLIED' then\n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning(destName)\n                end\n                \n                aura_env.RaidIcon('SET', destName, 1)\n                \n            elseif subEvent == 'SPELL_AURA_REMOVED' then\n                aura_env.RaidIcon('REMOVE', destName)\n                \n            elseif subEvent == 'SPELL_CAST_START' then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
