["adjustedMax"] = "",
["customText"] = "function()\n    return GROUP\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["spark"] = false,
["iconSource"] = -1,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://space.bilibili.com/455259",
["backgroundColor"] = {
