},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    actual = {\n        display = 'Does Group Soak',\n        type    =  'bool'\n    },\n    \n    next = {\n        display = 'Is Group Next',\n        type    =  'bool'\n    },\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, e, ...)\n    -- Returns true if the player is in the group at 'index' (order[index] is a table of names)\n    local function isPlayerInGroup(index)\n        local group = aura_env.order and aura_env.order[index]\n        if not group then return false end\n        local playerName = UnitName(\"player\")\n        for _, name in ipairs(group) do\n            if name == playerName then\n                return true\n            end\n        end\n        return false\n    end\n    \n    -- Fire ESSENCE_MY_GROUP only when the flag actually changes\n    local function updateMyGroupEvent(index)\n        local isMyGroup = isPlayerInGroup(index)\n        if aura_env.lastIsMyGroup ~= isMyGroup then\n            aura_env.lastIsMyGroup = isMyGroup\n            WeakAuras.ScanEvents('ESSENCE_MY_GROUP', isMyGroup)\n        end\n    end\n    \n    if e == 'PROTECTORS_SWAPS_ORDER' then\n        local order, stacks = ...\n        if not order or not stacks then return end\n        \n        aura_env.order = order\n        aura_env.stacks = stacks\n        aura_env.step = 1\n        aura_env.totalSteps = math.min(#order, #stacks)\n        \n        for i = 1, aura_env.totalSteps do\n            local requiredStacks = stacks[i] or 0\n            states:Update(i, {\n                    progressType = 'static',\n                    value        = 0,\n                    total        = requiredStacks,\n                    group        = i,\n                    actual       = (i == 1),\n                    next         = (i == 2),\n                    index        = i,\n            })\n        end\n        \n        updateMyGroupEvent(aura_env.step)\n        \n    elseif e == 'MERFIN_WARNING' then\n        local _, warning = ...\n        if not warning or warning.ID ~= 'CorruptedEssence' then return end\n        \n        local order = aura_env.order\n        local stacks = aura_env.stacks\n        local step = aura_env.step\n        if not order or not stacks or not step or not order[step] then return end\n        \n        local currentState = states[step]\n        if not currentState then return end\n        \n        local requiredStacks = stacks[step] or 0\n        local newValue = (currentState.value or 0) + 1\n        \n        states:Update(step, {\n                progressType = 'static',\n                value        = math.min(newValue, requiredStacks),\n                total        = requiredStacks,\n                group        = step,\n                actual       = true,\n                next         = (aura_env.step + 1 == step),\n                index        = step,\n        })\n        \n        -- Step complete: advance, wrap to 1 if we passed the last step\n        if newValue >= requiredStacks then\n            states:Remove(step)\n            aura_env.step = aura_env.step + 1\n            \n            if aura_env.step > aura_env.totalSteps then\n                aura_env.step = 1\n                -- Full reset like in 25-man version\n                for i = 1, aura_env.totalSteps do\n                    local required = stacks[i] or 0\n                    states:Update(i, {\n                            progressType = 'static',\n                            value        = 0,\n                            total        = required,\n                            group        = i,\n                            actual       = (i == 1),\n                            next         = (i == 2 and aura_env.totalSteps >= 2),\n                            index        = i,\n                    })\n                end\n            else\n                -- Update only current and next flags around the new step\n                for j = aura_env.step, math.min(aura_env.step + 1, aura_env.totalSteps) do\n                    if states[j] then\n                        states:Update(j, {\n                                actual = (aura_env.step == j),\n                                next   = (aura_env.step + 1 == j),\n                        })\n                    end\n                end\n            end\n            \n            updateMyGroupEvent(aura_env.step)\n        end\n        \n    elseif e == 'OPTIONS' then\n        local step = math.random(1, 5)\n        for i = 1, 5 do\n            local value = math.random(1, 3)\n            states:Update(i, {\n                    progressType = 'static',\n                    value        = value,\n                    total        = value + 1,\n                    group        = i,\n                    actual       = (step == i),\n                    next         = (step == (i + 1)),\n                    index        = i,\n            })\n        end\n    end\nend",
