["[DP] [TSK] Impervious Shield"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["do_custom_load"] = false,
["custom"] = "local encounterID = '1436'\nlocal ID          = 'ImperviousShield'\n\nlocal options = {\n    warningText = \"%icon %name (%count) %icon\",\n    ttsLine = Merfin:L(\"Stop Attack\"),\n    prewarnCountVA = 2,\n    prewarnTTStext = Merfin:L(\"Stop Attack Soon\"),\n}\n\nlocal name, icon = C_Spell.GetSpellName(117961), C_Spell.GetSpellTexture(117961)\n\naura_env.MRT = function()\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'QIANG_SHIELD_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, GUID)\n    aura_env.CancelMRT()\n    local after = duration <= 5 and duration or duration - 5\n    aura_env._mrtTimer = C_Timer.NewTimer(after, aura_env.MRT)\n    local data = {\n        show           = true,\n        autoHide       = false,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        GUID           = GUID\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = { \n        ID    = ID, \n        count = aura_env.count, \n        name  = name, \n        icon  = icon,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 117961 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local timer = aura_env.isTenMen and 62 or 42\n            aura_env.StartCD(timer, sourceGUID)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay, GUID = ...\n        \n        if bossID == 'QIANG' then\n            if activated then\n                aura_env.StartCD(40.7, GUID)\n            else\n                aura_env.StopCD()\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isTenMen = WeakAuras.InstanceType() == 'ten'\n        aura_env.count = 0\n        aura_env.CancelMRT()\n    end\nend",
