["anchorPoint"] = "CENTER",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "aura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.IsHealer = function(unit)\n    if UnitGroupRolesAssigned(unit) == 'HEALER' then\n        return true\n    end\nend\n\naura_env.GetSortedTargets = function()\n    local sorted = {}\n    \n    for i, name in ipairs(aura_env.targets) do\n        table.insert(sorted, { name = name, isHealer = aura_env.IsHealer(name), index = i })\n    end\n    \n    table.sort(sorted, function(a, b)\n            if a.isHealer and not b.isHealer then\n                return true\n            elseif not a.isHealer and b.isHealer then\n                return false\n            else\n                return a.index < b.index\n            end\n    end)\n    \n    local sortedTargets = {}\n    for i, entry in ipairs(sorted) do\n        table.insert(sortedTargets, entry.name)\n    end\n    \n    return sortedTargets\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "custom",
["custom"] = "function(event, ...)\n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, _, _, _, _, _, destName, _, _, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then \n            if spellID == 120629 then -- Huddle\n                table.insert(aura_env.targets, destName)\n                \n                if aura_env.IsSpam(3) then\n                    return\n                end\n                \n                aura_env.affected = 0\n                \n                C_Timer.NewTimer(0.7, function()\n                        local sortedTargets = aura_env.GetSortedTargets()\n                        aura_env.affected = #sortedTargets\n                        WeakAuras.ScanEvents('SHA_PING_PONG_LIST', sortedTargets)\n                        aura_env.targets = {}\n                end)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then \n            if spellID == 120629 and aura_env.affected > 0 then -- Huddle\n                aura_env.affected = aura_env.affected - 1\n                \n                if aura_env.affected == 0 then\n                    WeakAuras.ScanEvents('SHA_PING_PONG_STOP')\n                end\n            end\n        end\n        \n    elseif event == 'ENCOUNTER_START' then\n        aura_env.targets = {}\n    end\nend",
