["custom"] = "local encounterID = '1501'\nlocal ID          = 'Dispatch'\n\nlocal name, icon = C_Spell.GetSpellName(124077), C_Spell.GetSpellTexture(124077)\n\nlocal options = {\n    warningText = \"%upper:name\",\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(sourceName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID         = ID,\n            name       = name,\n            icon       = icon,\n            count      = aura_env.count,\n            sourceName = sourceName,\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID, sourceName,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 124077 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning(sourceName)\n                local seconds = aura_env.isTen and 22 or 12\n                aura_env.StartCD(seconds)\n            end\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 or phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isTen = WeakAuras.InstanceType() == 'ten'\n        aura_env.count = 0\n    end\nend",
