["[Progress] [Protectors] Group Swaps"] = {
["sparkWidth"] = 10,
["sparkOffsetX"] = 0,
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["adjustedMax"] = "",
["customText"] = "function()\n    return GROUP\nend",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["spark"] = false,
["iconSource"] = -1,
["sparkRotation"] = 0,
["sparkRotationMode"] = "AUTO",
["url"] = "https://space.bilibili.com/455259",
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    actual = {\n        display = 'Does Group Soak',\n        type    =  'bool'\n    },\n    \n    next = {\n        display = 'Is Group Next',\n        type    =  'bool'\n    },\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, e, ...)\n    \n    local function updateMyGroupEvent(isMyGroup)\n        if aura_env.lastIsMyGroup ~= isMyGroup then\n            aura_env.lastIsMyGroup = isMyGroup\n            WeakAuras.ScanEvents('ESSENCE_MY_GROUP', isMyGroup)\n        end\n    end\n    \n    if e == 'GROUP_SWAPS_RL' then\n        local config = ...\n        \n        aura_env.config = config\n        aura_env.step = 1\n        aura_env.count = 0\n        aura_env.totalSteps = #config\n        \n        -- Determine player's group\n        local playerGroup = aura_env.GetMyGroup()\n        \n        for i = 1, aura_env.totalSteps do\n            local group, stacks = config[i].group, config[i].stacks\n            \n            states:Update(i, {\n                    progressType = 'static',\n                    value        = 0,\n                    total        = stacks,\n                    group        = group,\n                    actual       = aura_env.step == i,\n                    next         = aura_env.step + 1 == i,\n                    index        = i,\n            })\n        end\n        \n        -- Check if player's group matches the current step's group\n        updateMyGroupEvent(playerGroup and playerGroup == config[aura_env.step].group)\n        \n    elseif e == 'MERFIN_WARNING' then\n        local _, warning = ...\n        \n        if warning and warning.ID == 'CorruptedEssence' then\n            local config = aura_env.config\n            local i = aura_env.step\n            if not config or not config[i] then return end\n            \n            local currentState = states[i]\n            if not currentState then return end\n            \n            local stacks = config[i].stacks\n            local newValue = (currentState.value or 0) + 1\n            \n            -- Update value for the current step\n            states:Update(i, {\n                    progressType = 'static',\n                    value        = math.min(newValue, stacks),\n                    total        = stacks,\n                    group        = config[i].group,\n                    actual       = true,\n                    next         = aura_env.step + 1 == i,\n            })\n            \n            -- If the required stacks are soaked\n            if newValue >= stacks then\n                -- Remove the completed step\n                states:Remove(i)\n                \n                -- Move to the next step\n                aura_env.step = aura_env.step + 1\n                \n                -- Determine player's group again\n                local playerGroup = aura_env.GetMyGroup()\n                \n                -- If finished all steps, reset everything\n                if aura_env.step > aura_env.totalSteps then\n                    aura_env.step = 1\n                    \n                    for j = 1, aura_env.totalSteps do\n                        local group, stepStacks = config[j].group, config[j].stacks\n                        \n                        states:Update(j, {\n                                progressType = 'static',\n                                value        = 0,\n                                total        = stepStacks,\n                                group        = group,\n                                actual       = j == 1,\n                                next         = j == 2,\n                        })\n                    end\n                else\n                    -- Update only current and next steps\n                    for j = aura_env.step, aura_env.step + 1 do\n                        if states[j] then\n                            states:Update(j, {\n                                    actual = aura_env.step == j,\n                                    next   = aura_env.step + 1 == j,\n                            })\n                        end\n                    end\n                end\n                \n                -- Check if player's group matches the new step's group\n                updateMyGroupEvent(playerGroup and playerGroup == config[aura_env.step].group)\n            end\n        end\n        \n    elseif e == 'OPTIONS' then\n        local step = math.random(1, 5)\n        \n        for i = 1, 5 do\n            local value = math.random(1, 3)\n            states:Update(i, {\n                    progressType = 'static',\n                    value        = value,\n                    total        = value + 1,\n                    group        = i,\n                    actual       = step == i,\n                    next         = step == (i + 1),\n                    index        = i,\n            })\n        end\n    end\nend",
["spellIds"] = {
},
