["selfPoint"] = "CENTER",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local L = GetLocale()\n\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Arrival = \"Now you done made me angry!\",\n        Arrival1 = \"Fine, den! Time ta play, friends.\",\n    },\n    ['ruRU'] = {\n        Arrival = \"А вот теперь вы меня разозлили!\",\n        Arrival1 = 'Ну хорошо! Давайте поиграем, \"друзья\".',\n    },\n    ['koKR'] = {\n        Arrival = \"날 열받게 했겠다!\",\n    },\n    ['zhCN'] = {\n        Arrival = \"现在你把我惹毛了！ 缚灵者戈拉亚\",\n        Arrival1 = \"好吧！游戏时间到，“朋友们”。\",\n    },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "event",
["duration"] = "25",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["spellIds"] = {
},
["custom"] = "function(_, msg)\n    if not msg then return end\n    \n    if aura_env.IsEmote(msg, 'Arrival') then\n        aura_env.count = (aura_env.count or 0) + 1\n        \n        if aura_env.count == 2 then\n            WeakAuras.ScanEvents('GARAJAL_ARRIVAL')\n        end\n    end\n    \n    if aura_env.IsEmote(msg, 'Arrival1') then\n        aura_env.count = (aura_env.count or 0) + 1\n        \n        if aura_env.count == 2 then\n            WeakAuras.ScanEvents('GARAJAL_ARRIVAL')\n        end\n    end\nend",
