["custom"] = "-- Credit to Merfin\n\nlocal GetMasteryEffect, GetCritChance, UnitDamage, UnitAttackPower = GetMasteryEffect, GetCritChance, UnitDamage, UnitAttackPower\nlocal floor = math.floor\n\nlocal Round = function(num)\n    return floor(num + 0.5)\nend\n\nlocal CritDamageMult = 2\n\naura_env.predictedDamage     = {}\naura_env.snapshotDamageCast  = {}\naura_env.snapshotDamage      = {}\n\naura_env.useDeltaPercent = aura_env.config.deltaPercent\n\nlocal GetDamage = {}\n\nGetDamage[\"RIP\"] = function(cp, ap, masteryEffect, damageMult, critEffMult)\n    local base = 113 + cp * (320 + 0.0484 * ap)\n    return Round(base * masteryEffect * damageMult * critEffMult)\nend\n\nGetDamage[\"RIP5\"] = function(ap, masteryEffect, damageMult, critEffMult)\n    local base = 113 + 5 * (320 + 0.0484 * ap)\n    return Round(base * masteryEffect * damageMult * critEffMult)\nend\n\nGetDamage[\"RAKE\"] = function(ap, masteryEffect, damageMult, critEffMult)\n    local base = 99 + 0.3 * ap\n    return Round(base * masteryEffect * damageMult * critEffMult)\nend\n\nGetDamage[\"THRASH\"] = function(ap, masteryEffect, damageMult, critEffMult)\n    local base = 686 + 0.141 * ap\n    return Round(base * masteryEffect * damageMult * critEffMult)\nend\n\nlocal stats = {}\n\naura_env.RefreshStats = function()\n    local apBase, apPos, apNeg = UnitAttackPower(\"player\")\n    local ap = apBase + apPos + apNeg\n    local masteryEffect = 1 + GetMasteryEffect() / 100\n    local critChance = math.min(1, GetCritChance() / 100)\n    local damageMult = select(7, UnitDamage(\"player\"))\n    local critEffMult = 1 + (CritDamageMult - 1) * critChance\n    \n    local name = WA_GetUnitBuff(\"player\", 145152)\n    if name then\n        damageMult = damageMult * 1.3\n    end\n    \n    local cp = GetComboPoints(\"player\", \"target\")\n    if cp == 0 then cp = 5 end\n    \n    stats = {\n        ap            = ap,\n        cp            = cp,\n        masteryEffect = masteryEffect,\n        damageMult    = damageMult,\n        critEffMult   = critEffMult\n    }\nend\n\naura_env.SetPredictedDamage = function()\n    local ap            = stats.ap\n    local cp            = stats.cp\n    local masteryEffect = stats.masteryEffect\n    local dmgMult       = stats.damageMult\n    local critEff       = stats.critEffMult\n    \n    local rip    = GetDamage[\"RIP\"](cp, ap, masteryEffect, dmgMult, critEff)\n    local rip5   = GetDamage[\"RIP5\"](ap, masteryEffect, dmgMult, critEff)\n    local rake   = GetDamage[\"RAKE\"](ap, masteryEffect, dmgMult, critEff)\n    local thrash = GetDamage[\"THRASH\"](ap, masteryEffect, dmgMult, critEff)\n    \n    local function update(ID, value)\n        if aura_env.predictedDamage[ID] ~= value then\n            aura_env.predictedDamage[ID] = value\n            aura_env.SendSyncEvent(ID)\n        end\n    end\n    \n    update(\"RIP\", rip)\n    update(\"RIP5\", rip5)\n    update(\"RAKE\", rake)\n    update(\"THRASH\", thrash)\nend\n\naura_env.GetPredictDamage = function(ID)\n    return aura_env.predictedDamage[ID]\nend\n\naura_env.SendSyncEvent = function(ID, destGUID)\n    local function ScanEvent(id, guid)\n        local data = {\n            ID       = id,\n            destGUID = guid,\n            predict  = aura_env.predictedDamage[id],\n            snapshot = aura_env.snapshotDamage[id] and aura_env.snapshotDamage[id][guid] or nil\n        }\n        WeakAuras.ScanEvents(\"MERFIN_SNAPSHOT_CHANGED\", data)\n    end\n    \n    local function SendFor(id)\n        if destGUID then\n            ScanEvent(id, destGUID)\n        else\n            local guidPool = aura_env.snapshotDamage[id]\n            if guidPool then\n                for guid in pairs(guidPool) do\n                    ScanEvent(id, guid)\n                end\n            end\n        end\n    end\n    \n    if ID == \"RIP\" then\n        SendFor(\"RIP\")\n        SendFor(\"RIP5\")\n    else\n        SendFor(ID)\n    end\nend\n\naura_env.snapshotSpellIDs = {\n    [1079]   = \"RIP\",\n    [1822]   = \"RAKE\",\n    [106830] = \"THRASH\"\n}\n\naura_env.OnCastSnapshot = function(ID)\n    aura_env.snapshotDamageCast[ID] = aura_env.GetPredictDamage(ID)\nend\n\naura_env.OnDebuffApplied = function(ID, destGUID)\n    aura_env.snapshotDamage[ID] = aura_env.snapshotDamage[ID] or {}\n    aura_env.snapshotDamage[ID][destGUID] = aura_env.snapshotDamageCast[ID]\n    \n    if ID == \"RIP\" then\n        aura_env.snapshotDamage[\"RIP5\"] = aura_env.snapshotDamage[\"RIP5\"] or {}\n        aura_env.snapshotDamage[\"RIP5\"][destGUID] = aura_env.snapshotDamageCast[\"RIP\"]\n    end\n    \n    aura_env.SendSyncEvent(ID, destGUID)\nend\n\naura_env.OnDebuffRemoved = function(ID, destGUID)\n    if aura_env.snapshotDamage[ID] then\n        aura_env.snapshotDamage[ID][destGUID] = nil\n    end\n    \n    if ID == \"RIP\" and aura_env.snapshotDamage[\"RIP5\"] then\n        aura_env.snapshotDamage[\"RIP5\"][destGUID] = nil\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["spellIds"] = {
},
["custom"] = "function(event)\n    if event == 'STATUS' then\n        WeakAuras.ScanEvents('MERFIN_FERAL_SNAPSHOT_DB', aura_env)\n    end\n    \n    aura_env.RefreshStats()\n    aura_env.SetPredictedDamage()\nend",
["custom_type"] = "status",
["names"] = {
},
["subeventPrefix"] = "SPELL",
["events"] = "PLAYER_SPECIALIZATION_CHANGED, COMBAT_RATING_UPDATE, UNIT_STATS:player, PLAYER_DAMAGE_DONE_MODS, UNIT_DAMAGE:player, UNIT_ATTACK_POWER:player, MASTERY_UPDATE",
["custom_hide"] = "timed",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["type"] = "custom",
["custom"] = "function (event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_SUCCESS' then\n            if sourceGUID ~= WeakAuras.myGUID then return end\n            local ID = aura_env.snapshotSpellIDs[spellID]\n            \n            if ID then\n                aura_env.OnCastSnapshot(ID)\n            end\n        end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' \n        or subEvent == 'SPELL_AURA_REFRESH' \n        or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if sourceGUID == WeakAuras.myGUID then \n                if spellID == 145152 then -- Dream of Cenarius\n                    aura_env.RefreshStats()\n                    aura_env.SetPredictedDamage()\n                    return\n                end\n                \n                local ID = aura_env.snapshotSpellIDs[spellID]\n                \n                if ID then\n                    aura_env.OnDebuffApplied(ID, destGUID)\n                    return\n                end\n            end\n        end\n        \n        if subEvent == 'SPELL_AURA_REMOVED' then\n            if sourceGUID == WeakAuras.myGUID then\n                local ID = aura_env.snapshotSpellIDs[spellID]\n                \n                if ID then\n                    aura_env.OnDebuffRemoved(ID, destGUID)\n                    return\n                end\n            end\n        end\n    end\nend",
