["[T11] Backend - Magmaw"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Magmaw)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Magmaw\n\nlocal ENTRY = aura_env\nlocal encounterId = 1024\n\nlocal localized = {\n    ['enUS'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s slumps forward, exposing his pincers!\",\n        HeadExposed = \"%s becomes impaled on the spike, exposing his head!\",\n        YellPhase2 =  \"Inconceivable! You may actually defeat my lava worm! Perhaps I can help... tip the scales.\",\n    },\n    \n    ['ruRU'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s внезапно падает, выставляя клешки!\",\n        HeadExposed = \"%s насаживается на пику, обнажая голову!\",\n        YellPhase2 =  \"Непостижимо! Вы, кажется, можете уничтожить моего лавового червяка! Пожалуй, я помогу ему.\",\n    },\n    ['koKR'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"기울입니다!\",\n        HeadExposed = \"노출되었습니다!\",\n        YellPhase2 =  \"이런 곤란할 데가! 이러다간 내 용암 벌레가 정말 질 수도 있겠군! 그럼... 내가 상황을 좀 바꿔 볼까?\",\n        \n        -- Custom Texts\n    },\n    ['esES'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"¡%s cae hacia delante y deja expuestas sus tenazas!\",\n        HeadExposed = \"¡%s acaba empalado en el pincho y deja expuesta la cabeza!\",\n        YellPhase2 =  \"¡Inconcebible! ¡Existe la posibilidad de que venzáis a mi gusano de lava! Quizás yo pueda... desequilibrar la balanza.\",\n        \n        -- Custom Texts\n    },\n    ['deDE'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s schlittert nach vorne und entblößt seine Zangen!\",\n        HeadExposed = \"%s spießt sich selbst auf, was seinen Kopf freilegt!\",\n        YellPhase2 =  \"Unfassbar! Ihr könntet tatsächlich meinen Lavawurm besiegen! Vielleicht kann ich helfen... das Zünglein an der Waage zu sein.\",\n        \n        -- Custom Texts\n    },\n    ['frFR'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s s'effondre vers l'avant et expose ses pinces !\",\n        HeadExposed = \"%s vient de s'empaler sur la pointe et expose sa tête !\",\n        YellPhase2 =  \"Inconcevable ! Vous pourriez vraiment vaincre mon ver de lave !\",\n        \n        -- Custom Texts\n    },\n    ['zhTW'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s往前撲倒，露出他的鉗子!\",\n        HeadExposed = \"%s被釘在尖刺上，露出了他的頭!\",\n        YellPhase2 =  \"真難想像!看來你真有機會打敗我的蟲子!也許我可幫忙...扭轉戰局。\",\n        \n        -- Custom Texts\n    },\n    ['zhCN'] = {\n        -- RAID_BOSS_EMOTE / CHAT_MSG_MONSTER_YELL\n        Slump =       \"%s向前倒下，暴露出他的钳子！\",\n        HeadExposed = \"%s将自己钉在刺上，露出了他的头！\",\n        YellPhase2 =  \"难以置信，你们竟然真要击败我的熔岩巨虫了！也许我可以帮你们……扭转局势。\",\n        \n        -- Custom Texts\n    },   \n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    exposed =      { 79011 },\n    pillar_flame = { 78006 },\n    lava_spew    = { 77690 },\n    mangle       = { 89773 },\n    inferno      = { 92154 },\n    armageddon   = { 92177 },\n    ignition     = { 92128 },\n    tantrum      = { 78403 },\n    phase_2      = { false, 236197 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    Cooldown('pillar_flame', 30-delay)\n    PreWarning('pillar_flame', 25-delay)\n    Cooldown('lava_spew', 25-delay)\n    Cooldown('mangle', 90-delay)\n    Cooldown('berserk', 600-delay)\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('inferno', 30-delay)\n    end\nend\n\nENTRY['CHAT_MSG_MONSTER_YELL'] = function(text, playerName)\n    if not IsEntryInitialized() then return end\n    if text == L.YellPhase2 or text:find(L.YellPhase2) then\n        Cancel('inferno', 'ALL')\n        Phase('phase_2')\n    end\nend\n\nENTRY['RAID_BOSS_EMOTE'] = function(text, playerName)\n    if not IsEntryInitialized() then return end\n    if text == L.Slump or text:find(L.Slump) then\n        Cooldown('pillar_flame', 15) \n        PreWarning('pillar_flame', 10)\n    elseif text == L.HeadExposed or text:find(L.HeadExposed) then\n        Timer('exposed', 30)\n        Cooldown('pillar_flame', 40)\n        PreWarning('pillar_flame', 35)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 77690 and AntiSpam('lava_spew', 5) then\n        Timer('lava_spew', 6)\n        SpecialWarning('lava_spew')\n        Cooldown('lava_spew', 22)\n    elseif args.spellId == 92177 then\n        SpecialWarning('armageddon')\n        Timer('armageddon', 8)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 78006 then\n        SpecialWarning('pillar_flame')\n        Cooldown('pillar_flame', 32.5)\n        PreWarning('pillar_flame', 27.5)\n    elseif args.spellId == 78403 then\n        Timer('tantrum', 10, 1)\n    elseif args.spellId == 89773 then\n        WeakAuras.ScanEvents('JUMP_IN', 10)\n        Warning('mangle', args.destName)\n        Timer('mangle', 30, args.destName)\n        Cooldown('mangle', 95)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED_DOSE'] = function(args)\n    if args.spellId == 78403 then\n        Timer('tantrum', 10, nil, args.stacks)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 89773 then\n        Cancel('mangle', 'TIMER')\n    end\nend\n\nENTRY['SPELL_SUMMON'] = function(args)\n    if args.spellId == 92154 then\n        Warning('inferno')\n        Cooldown('inferno', 35)\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 92128 and args.destGUID == CORE.PlayerGUID and AntiSpam('ignition', 4) then\n        Warning('ignition')\n    end\nend\n\nENTRY['SPELL_MISS'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['UNIT_DIED'] = function(args)\n    local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n    if creatureId == 49416 then\n        Cancel('armageddon', 'ALL')\n    end\nend",
["do_custom"] = true,
},
