},
["displayText"] = "%i 你被点名 %i",
["customText"] = "\n\n",
["shadowYOffset"] = 0,
["anchorPoint"] = "TOP",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "local UnitExists, UnitTarget, UnitGUID = UnitExists, UnitTarget, UnitGUID\nlocal GetNameplates = C_NamePlate.GetNamePlates()\nlocal pairs = pairs\nlocal stformat, strfind = string.format, strfind\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType,_, playerdbID,_,_, cid,_ = strsplit(\"-\", GUID or \"\")\n    if cid then\n        return tonumber(cid)\n    end\n    return 0\nend\n\nlocal playerGUID = UnitGUID('player')\nlocal trackedId = 5856\n\nlocal tracked = {}\nlocal InitConfig = function()\n    local cfg = aura_env.config\n    for _, data in pairs(cfg.data) do\n        if data.enable then\n            tracked[data.npcId] = data.icon\n        end\n    end\nend\n\nlocal Untrigger = function(a, unitGUID)\n    if a[unitGUID] then\n        a[unitGUID].show = false\n        a[unitGUID].changed = true\n        return true\n    end\nend\n\nlocal Trigger = function(a, unit, unitGUID, icon)\n    if not a[unitGUID] then\n        a[unitGUID] = {\n            show = true,\n            changed = true,\n            unit = unit,\n            icon = icon,\n        }\n        return true\n    end\nend\n\nlocal ProcessNameplate = function(a, nameplateId)\n    local unitGUID = UnitExists(nameplateId) and UnitGUID(nameplateId)\n    if unitGUID then\n        local npcId = GetGuidCreatureId(unitGUID)\n        if tracked[npcId] then\n            local unitTarget = stformat('%starget', nameplateId)\n            if UnitExists(unitTarget) then\n                local unitTargetGUID = UnitGUID(unitTarget)\n                if unitTargetGUID == playerGUID then\n                    return Trigger(a, nameplateId, unitGUID, tracked[npcId])\n                end\n            end\n            return Untrigger(a, unitGUID)\n        end\n    end\nend\n\naura_env['NAME_PLATE_UNIT_ADDED'] = function(a, nameplateId)\n    return ProcessNameplate(a, nameplateId)\nend\n\naura_env['NAME_PLATE_UNIT_REMOVED'] = function(a, nameplateId)\n    local unitGUID = UnitExists(nameplateId) and UnitGUID(nameplateId)\n    return unitGUID and Untrigger(a, unitGUID)\nend\n\naura_env['UNIT_TARGET'] = function(a, nameplateId)\n    if not strfind(nameplateId, 'nameplate') then return end\n    return ProcessNameplate(a, nameplateId)\nend\n\naura_env['UNIT_THREAT_LIST_UPDATE'] = function(a, nameplateId)\n    if not strfind(nameplateId, 'nameplate') then return end\n    return ProcessNameplate(a, nameplateId)\nend\n\naura_env['STATUS'] = function(a)\n    if not a then return end\n    local changed = false\n    for unitGUID, state in pairs(a) do\n        if not UnitExists(state.unit) then\n            if Untrigger(a, state.unit) then\n                changed = true\n            end\n        end\n    end\n    return changed\nend\n\nInitConfig()",
["do_custom"] = true,
},
