["[DP] [TSK] Maddening Shout"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'MaddeningShout'\n\nlocal name, icon = C_Spell.GetSpellName(117708), C_Spell.GetSpellTexture(117708)\n\nlocal options = {\n    warningText = \"@cffff4040%upper:name@r\",\n    prewarnCountVA = 2,\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n}\n\naura_env.MRT = function()\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'SHOUT_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env.CancelMRT()\n    local after = duration <= 5 and duration or duration - 5\n    aura_env._mrtTimer = C_Timer.NewTimer(after, aura_env.MRT)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function(destName)\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 117708 then\n            aura_env.count = aura_env.count + 1\n            local timer = aura_env.bossActivated and 47 or 77\n            aura_env.StartCD(timer)\n            aura_env.SendWarning(destName)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'MENG' then return end\n        \n        aura_env.bossActivated = activated\n        \n        if activated then \n            local timer = aura_env.isHeroic and 40 or 20.5\n            aura_env.StartCD(timer-delay)\n        else\n            aura_env.StartCD(30)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.CancelMRT()\n    end\nend",
