["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["custom_hide"] = "timed",
["customVariables"] = "{\n    index = {\n        display = 'Placement',\n        type    = 'number'\n    }\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(states, event, data)\n    if event == \"PAINTERS_SCORE\" then\n        local unitName = data.unitName\n        local score = data.currentScore\n        \n        states:Update(unitName, {\n                unitName = unitName,\n                score = score\n        })\n        \n    elseif event == \"OPTIONS\" then\n        local unitNames = { WeakAuras.me, \"Scarpa\", \"Exander\", \"Devil\", \"Trump\" }\n        \n        for _, unitName in pairs(unitNames) do\n            states:Update(unitName, {\n                    unitName = unitName,\n                    score = math.random(1, 70)\n            })\n        end\n    end\n    \n    local entries = {}\n    \n    for id, state in pairs(states) do\n        table.insert(entries, { id = id, score = state.score or 0 })\n    end\n    \n    table.sort(entries, function(a, b)\n            return a.score > b.score\n    end)\n    \n    for index, entry in ipairs(entries) do\n        states:Update(entry.id, { index = index })\n    end\nend",
