["event"] = "Health",
["unit"] = "player",
["subeventPrefix"] = "SPELL",
["custom"] = "function(allstates, event, ...)\n    if event == \"LFG_PROPOSAL_SHOW\" then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = aura_env.duration or 40,\n            expirationTime = GetTime() + (aura_env.duration or 40),\n            autoHide = true\n        }\n        aura_env.startTime = GetTime()\n        C_Timer.After(2, function()\n                if allstates[\"\"] and allstates[\"\"].show then\n                    PlaySoundFile(\"Interface\\\\AddOns\\\\SharedMedia_Rurutia\\\\Rurutia\\\\【露露】排到本咯~.ogg\", \"Master\")\n                end\n        end)\n        WeakAuras.ScanEvents(\"LFG_PROPOSAL_TIMER_START\")\n        return true\n    elseif event == \"LFG_PROPOSAL_FAILED\" or event == \"LFG_PROPOSAL_SUCCEEDED\" then\n        if allstates[\"\"] then\n            allstates[\"\"].show = false\n            allstates[\"\"].changed = true\n            aura_env.startTime = nil\n            return true\n        end\n    elseif event == nil and allstates[\"\"] and allstates[\"\"].show then\n        local currentTime = GetTime()\n        local elapsed = currentTime - (aura_env.startTime or currentTime)\n        local remaining = (aura_env.duration or 40) - elapsed\n        if remaining <= 0 then\n            allstates[\"\"].show = false\n            allstates[\"\"].changed = true\n            allstates[\"\"].time = 0\n            aura_env.startTime = nil\n        else\n            allstates[\"\"].time = remaining\n            allstates[\"\"].changed = true\n        end\n        return true\n    end\n    return false\nend",
