["init"] = {
["custom"] = "local encounterID = '1506'\nlocal ID          = 'AnimatedProtector'\n\nlocal name = C_EncounterJournal.GetSectionInfo(6224).title\nlocal icon = 135862\n\nlocal options = {warningText = \"%icon @cffff8b17%name@r %icon\"}\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count,\n    }, options)\nend",
["do_custom"] = true,
},
},
