["[DP] [Emperor] Emperor's Strength"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1407'\nlocal ID          = 'StrengthActivate'\n\nlocal name = Merfin.GetTitleEJ(5677)\nlocal icon = 133522\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r (%count) %icon\",\n    ttsLine = Merfin:L(\"Strength\"),\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n}\n\naura_env.StartCD = function(duration)\n    local data = {\n        show           = true,\n        autoHide       = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        name           = name,\n        icon           = icon,\n        count          = aura_env.count,\n        GUID           = GUID,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Schedule = function(seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('STRENGTH_SCHEDULED')\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'ADD_ACTIVATION' then\n        local add = ...\n        \n        if add == 'STRENGTH' then\n            aura_env.Schedule(9)\n        end\n        \n    elseif e == 'STRENGTH_SCHEDULED' then\n        aura_env.count = aura_env.count + 1\n        aura_env.SendWarning()\n        if aura_env.count == 4 or aura_env.count == 6 or aura_env.count == 8 then\n            aura_env.StartCD(100)\n        else\n            aura_env.StartCD(50)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        local duration = aura_env.isHeroic and 35 or 42\n        aura_env.StartCD(duration)\n    end\nend",
