["[DP] Set Raid Icon"] = {
["width"] = 200,
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["preferToUpdate"] = true,
["xOffset"] = 0,
["yOffset"] = 0,
["regionType"] = "empty",
