["anchorPoint"] = "CENTER",
["parent"] = "[DP] [T14] Main",
["selfPoint"] = "CENTER",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local SetRaidTarget = SetRaidTarget\nlocal GetNumGroupMembers = GetNumGroupMembers\nlocal UnitExists = UnitExists\nlocal GetRaidTargetIndex = GetRaidTargetIndex\n\naura_env.savedMarks = {}\n\naura_env.SetIcon = function(target, icon)\n    if not target or not UnitExists(target) then return end\n    local currentIcon = GetRaidTargetIndex(target)\n    \n    if not currentIcon then\n        SetRaidTarget(target, icon)\n        aura_env.savedMarks[target] = icon\n    end\nend\n\naura_env.RemoveIcon = function(target)\n    if not target or not UnitExists(target) or not GetRaidTargetIndex(target) then return end\n    SetRaidTarget(target, 0)\n    aura_env.savedMarks[target] = nil\nend\n\naura_env.ClearIcons = function()\n    for i = 1, GetNumGroupMembers() do\n        local unit = 'raid' .. i\n        aura_env.RemoveIcon(unit)\n    end\nend\n\naura_env.IsRaidLeaderOrAssistant = function()\n    if not IsInRaid() then return end\n    \n    for i = 1, GetNumGroupMembers() do\n        local unit = \"raid\"..i\n        if UnitName(unit) == WeakAuras.me then\n            local rank = select(3, GetRaidRosterInfo(i))\n            return rank == 2 or rank == 1 -- 2 = leader, 1 = assistant, 0 = none\n        end\n    end\nend\n\naura_env.IsMarkEnabled = function(encounterID, ID)\n    local config = aura_env.connectedConfig\n    \n    if not config then\n        return true\n    end\n    \n    if config[encounterID] and config[encounterID][ID] then\n        return config[encounterID][ID].setRaidMark\n    end\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(e, ...)\n    \n    if e == 'MERFIN_WARNING_CONFIG' then\n        local sentConfig = ...\n        if not sentConfig then return end\n        aura_env.connectedConfig = sentConfig\n    end\n    \n    if not aura_env.IsRaidLeaderOrAssistant() then \n        return \n    end\n    \n    if e == 'MERFIN_RAID_ICON' then\n        local warning, subEvent, dest, icon = ...\n        if not warning then return end\n        \n        if not aura_env.IsMarkEnabled(warning.encounterID, warning.ID) then\n            return\n        end\n        \n        if subEvent == 'SET' then\n            aura_env.SetIcon(dest, icon)  \n        elseif subEvent == 'REMOVE' then\n            if dest == 'ALL' then\n                aura_env.ClearIcons()\n            else\n                aura_env.RemoveIcon(dest)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_END' then\n        for target in pairs(aura_env.savedMarks) do\n            aura_env.RemoveIcon(target)\n        end\n    end\nend",
