["init"] = {
["custom"] = "local encounterID = '1463'\nlocal ID          = 'Crush'\n\nlocal name, icon = C_Spell.GetSpellName(122774), C_Spell.GetSpellTexture(122774)\n\nlocal options = {\n    warningText    = \"@cfffcc68b%upper:name@r (%count)\",\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name),\n}\n\naura_env.MRT = function()\n    local event = 'CRUSH_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = { Under = \"under him\" },\n    ['zhCN'] = { Under = \"在它下方\" },\n    ['deDE'] = { Under = \"Unter ihm\" },\n    ['frFR'] = { Under = \"sous lui\" },\n    ['ruRU'] = { Under = \"под ним\" },\n    ['koKR'] = { Under = \"있는 것을 감지하고\" },\n    ['zhTW'] = { Under = \"在他下面\" },\n    ['esES'] = { Under = \"Debajo de él\" },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        local msg,_,_,_, destName = ...\n        \n        if msg:find(\"spell:122774\") and not aura_env.IsEmote(msg, 'Under') then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            \n            if aura_env.isHeroic then\n                aura_env.StartCD(37)\n            end\n        end\n        \n    elseif e == 'GARALON_PHASE2' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.count = 0\n        \n        if aura_env.isHeroic then\n            aura_env.StartCD(25.5)\n        end\n        \n    end\nend",
