["[Widget] [Mel'jarak] Focus Mender"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["displayText"] = "%c2 %c1 %c2",
["customText"] = "function()\n    local mark = WeakAuras.IsOptionsOpen() and '{rt6}' or aura_env.mark\n    local prefix = Merfin:L('Focus Target'):upper()\n    return prefix:upper(), mark\nend",
["shadowYOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["sound"] = "Interface\\AddOns\\WeakAuras\\Media\\Sounds\\Focus.ogg",
["do_sound"] = true,
},
["init"] = {
["custom"] = "aura_env.markToIndex = {\n    ['star']     = 1,\n    ['circle']   = 2,\n    ['diamond']  = 3,\n    ['triangle'] = 4,\n    ['moon']     = 5,\n    ['square']   = 6,\n    ['cross']    = 7,\n    ['skull']    = 8,\n}",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    local function HasMarkedNameplate()\n        local indexExpected = tonumber(aura_env.mark:match(\"{rt(%d)}\"))\n        if not indexExpected then return false end\n        \n        local nameplates = C_NamePlate.GetNamePlates()\n        for _, plate in ipairs(nameplates) do\n            local unit = plate.namePlateUnitToken\n            if unit and UnitExists(unit) then\n                local index = GetRaidTargetIndex(unit)\n                if index == indexExpected then\n                    return true\n                end\n            end\n        end\n        return false\n    end\n    \n    local function CheckFocus()\n        if not aura_env.mark then return end\n        if not HasMarkedNameplate() then\n            states:Remove('')\n            return\n        end\n        \n        local focus = \"focus\"\n        if not UnitExists(focus) then\n            states:Update('', {\n                    changed = true,\n                    show    = true,\n                    mark    = aura_env.mark,\n            })\n            return\n        end\n        \n        local index = GetRaidTargetIndex(focus)\n        if index and aura_env.mark == (\"{rt\" .. index .. \"}\") then\n            states:Remove('')\n        else\n            states:Update('', {\n                    changed = true,\n                    show    = true,\n                    mark    = aura_env.mark,\n            })\n        end\n    end\n    \n    if event == 'MELJARAK_INTERRUPT_ORDER' then\n        local fullOrder = ...\n        aura_env.order = nil\n        aura_env.mark = nil\n        \n        for mark, playerList in pairs(fullOrder) do\n            for _, name in ipairs(playerList) do\n                if name == WeakAuras.me then\n                    aura_env.order = playerList\n                    local index = aura_env.markToIndex[mark]\n                    if index then\n                        aura_env.mark = \"{rt\" .. index .. \"}\"\n                    end\n                    break\n                end\n            end\n            if aura_env.mark then break end\n        end\n        \n        CheckFocus()\n        \n    elseif event == 'PLAYER_FOCUS_CHANGED' or event == 'RAID_TARGET_UPDATE' then\n        CheckFocus()\n        \n    elseif event == 'NAME_PLATE_UNIT_ADDED' then\n        local unit = ...\n        if not aura_env.mark then return end\n        local expected = tonumber(aura_env.mark:match(\"{rt(%d)}\"))\n        if not expected then return end\n        \n        if UnitExists(unit) and GetRaidTargetIndex(unit) == expected then\n            CheckFocus()\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_REMOVED' then\n        local unit = ...\n        if not aura_env.mark then return end\n        local expected = tonumber(aura_env.mark:match(\"{rt(%d)}\"))\n        if not expected then return end\n        \n        if GetRaidTargetIndex(unit) == expected then\n            CheckFocus()\n        end\n    end\nend",
