["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'BreathOfFear'\n\nlocal name, icon = C_Spell.GetSpellName(119414), C_Spell.GetSpellTexture(119414)\n\nlocal options = {\n    warningText = '@cffff4040%upper:name@r', \n    prewarnCountVA = 1,\n    prewarnTTStext = string.format(Merfin:L('%s soon'), name)\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'BREATH_' .. (aura_env.counter + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, expirationTime)\n    aura_env.expirationTime = expirationTime or duration + GetTime()\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = aura_env.expirationTime,\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            ignorePrew = aura_env.onPlatform\n    }, options)\nend\n\naura_env.SendWarning = function()\n    if aura_env.onPlatform then return end\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 119414 then\n                if not aura_env.phase2 and not aura_env.IsSpam(5) then\n                    aura_env.count = aura_env.count + 1\n                    aura_env.SendWarning()\n                    aura_env.StartCD(33.3)\n                end\n            end\n        end\n        \n    elseif e == 'LEAVE_PLATFORM' then\n        aura_env.onPlatform = false\n        \n        if aura_env.phase2 then\n            return\n        end\n        \n        -- Restart CD with countdown\n        if GetTime() < aura_env.expirationTime then\n            aura_env.StartCD(33.3, aura_env.expirationTime)\n        end\n        \n    elseif e == 'ENTER_PLATFORM' then\n        -- Restart CD with no countdown\n        aura_env.onPlatform = true\n        aura_env.StartCD(33.3, aura_env.expirationTime)\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase2 = true\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.phase2 = false\n        aura_env.onPlatform = false\n        aura_env.count = 0\n        aura_env.StartCD(33.3)\n    end\nend",
