},
["finish"] = {
},
["init"] = {
["custom"] = "-- The original code was provided by Strace\n\nlocal LibDeflate   = LibStub:GetLibrary(\"LibDeflate\")\nlocal LibSerialize = LibStub(\"LibSerialize\")\nlocal AceComm      = LibStub:GetLibrary(\"AceComm-3.0\")\n\nlocal MESSAGE_PREFIX = \"WA_SYNC_EVENTS\"\n\nlocal ALLOWED_CHANNELS = {\n    [\"PARTY\"]         = true,\n    [\"RAID\"]          = true,\n    [\"INSTANCE_CHAT\"] = true,\n    [\"GUILD\"]         = true,\n    [\"OFFICER\"]       = true,\n}\n\n-- Separate Antispam Caches\nlocal SendCache    = {}\nlocal ReceiveCache = {}\n\nlocal function AddToCache(cache, key, ttl)\n    cache[key] = GetTime() + ttl\nend\n\nlocal function IsInCache(cache, key)\n    local expireTime = cache[key]\n    if not expireTime then return false end\n    if GetTime() > expireTime then\n        cache[key] = nil\n        return false\n    end\n    return true\nend\n\n-- Helper to create consistent keys\nlocal serializeForKey = function(v)\n    local t = type(v)\n    if t == \"string\" then\n        return v\n    elseif t == \"number\" then\n        return string.format(\"%.5f\", v)\n    elseif t == \"boolean\" then\n        return v and \"true\" or \"false\"\n    else\n        return \"?\"\n    end\nend\n\naura_env.SyncEvents = function(channel, target, event, ...)\n    local payload = {...}\n    \n    local key = event\n    for _, v in ipairs(payload) do\n        key = key .. \":\" .. serializeForKey(v)\n    end\n    \n    if IsInCache(SendCache, key) then return end\n    AddToCache(SendCache, key, 1.0)\n    \n    local data = {\n        event   = event,\n        payload = payload,\n    }\n    \n    local serialized = LibSerialize:Serialize(data)\n    local compressed = LibDeflate:CompressDeflate(serialized)\n    local encoded = LibDeflate:EncodeForWoWAddonChannel(compressed)\n    \n    AceComm:SendCommMessage(MESSAGE_PREFIX, encoded, channel, target)\nend\n\nlocal receiveSyncEvent = function(prefix, encoded, channel, sender)\n    if not ALLOWED_CHANNELS[channel] then\n        return false\n    end\n    \n    local compressed = LibDeflate:DecodeForWoWAddonChannel(encoded)\n    if not compressed then return end\n    \n    local serialized = LibDeflate:DecompressDeflate(compressed)\n    if not serialized then return end\n    \n    local success, data = LibSerialize:Deserialize(serialized)\n    if not success then return end\n    \n    local key = data.event\n    for _, v in ipairs(data.payload) do\n        key = key .. \":\" .. serializeForKey(v)\n    end\n    \n    if IsInCache(ReceiveCache, key) then return end\n    AddToCache(ReceiveCache, key, 1.0)\n    \n    WeakAuras.ScanEvents(data.event, unpack(data.payload))\nend\n\nAceComm:RegisterComm(MESSAGE_PREFIX, receiveSyncEvent)",
["do_custom"] = true,
},
