["[DP] [Sha] Platform"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.LeavePlatform = function()\n    aura_env.guardianID = nil\n    aura_env.platformGUIDs = {}\n    aura_env.Unschedule()\n    WeakAuras.ScanEvents('LEAVE_PLATFORM')\nend\n\naura_env.EnterPlatform = function() WeakAuras.ScanEvents('ENTER_PLATFORM') end\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.Unschedule = function()\n    if aura_env.scheduler then aura_env.scheduler:Cancel() end\nend\n\naura_env.Schedule = function(seconds)\n    if aura_env.scheduler then aura_env.scheduler:Cancel() end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents('PLATFORM_CHECK')\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 118977 and destGUID == WeakAuras.myGUID then -- Fearless\n                aura_env.LeavePlatform()\n                \n            elseif spellID == 129147 and destGUID == WeakAuras.myGUID then -- Ominous\n                aura_env.EnterPlatform()\n            end\n            \n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 119862 and not aura_env.platformGUIDs[sourceGUID] then -- Shot\n                aura_env.platformGUIDs[sourceGUID] = true\n                aura_env.guardianID = Merfin.GetNPCIDFromGUID(sourceGUID)\n                \n            elseif spellID == 119888 and aura_env.guardianID then\n                if aura_env.guardianID == Merfin.GetNPCIDFromGUID(sourceGUID) then\n                    aura_env.Schedule(40)\n                end\n            end\n        end\n        \n    elseif e == 'PLATFORM_CHECK' then\n        if WA_GetUnitBuff('player', 117964) then\n            aura_env.LeavePlatform()\n        else\n            aura_env.Schedule(3)\n        end\n        \n    elseif e == 'UNIT_DIED' then\n        local npcID, destGUID = ...\n        \n        if aura_env.platformGUIDs[destGUID] then\n            aura_env.Unschedule()\n            aura_env.Schedule(7)\n        end\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.Unschedule()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.platformGUIDs = {}\n        aura_env.guardianID = nil\n        aura_env.Unschedule()\n    end\nend",
