["init"] = {
["do_custom_load"] = false,
["custom"] = "local UnitHealth, UnitHealthMax = UnitHealth, UnitHealthMax\n\naura_env.GetNPCIDFromUnitID = function(unitID)\n    local GUID = UnitGUID(unitID)\n    local guidType, _, _, _, _, id = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id) or 0\n    end\n    return 0\nend\n\naura_env.GetUnitHealthPercent = function(unit)\n    local health = UnitHealth(unit)\n    local maxHealth = UnitHealthMax(unit)\n    \n    if maxHealth == 0 then\n        return 0\n    end\n    \n    return (health / maxHealth) * 100\nend\n\naura_env.InRangeOffset = function(value, min, max)\n    if value >= min and value < max then\n        return value - min\n    end\n    return nil\nend\n\naura_env.icon = \"|T627685:16:16:0:0:64:64:5:59:5:59|t\"\n\naura_env.ranges = {\n    {min = 66.4, max = 69, prefix = Merfin:L('Phase') .. ' 2'},\n}",
