["[DP] [TSK] Boss Swap"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\n\nlocal options = {\n    warningText = '@cffe3e3e3%name@r (%count)',\n}\n\nlocal IDs = {\n    ['ZIAN']    = { 'ZianActivated',    Merfin.GetTitleEJ(5852) },\n    ['MENG']    = { 'MengActivated',    Merfin.GetTitleEJ(5835) },\n    ['QIANG']   = { 'QiangActivated',   Merfin.GetTitleEJ(5841) },\n    ['SUBETAI'] = { 'SubetaiActivated', Merfin.GetTitleEJ(5846) }\n}\n\nlocal SendWarning = function(rawID)\n    local ID = IDs[rawID]\n    local data = {\n        ID    = IDs[rawID][1],\n        name  = IDs[rawID][2],\n        count = aura_env.count\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.MRT = function(boss)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = boss\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.bossActivated = {}\n\naura_env.BossSwap = function(bossID, activated, ignoreWarning, delay, GUID)\n    aura_env.bossActivated[bossID] = activated\n    WeakAuras.ScanEvents('BOSS_SWAP', bossID, activated, delay, GUID)\n    \n    if activated then\n        aura_env.count = aura_env.count + 1\n        \n        if GetTime() - (aura_env.encStartTime or 0) > 2 then\n            if not ignoreWarning then\n                SendWarning(bossID)\n            end\n        end\n        \n        aura_env.MRT(bossID)\n    end\nend\n\nlocal creatures = {\n    ['ZIAN']    = { 60701, 61421 },\n    ['MENG']    = { 60708, 61429 },\n    ['QIANG']   = { 60709, 61423 },\n    ['SUBETAI'] = { 60710, 61427 },\n}\n\naura_env.IsGUID = function(GUID, bossID)\n    if not GUID then return end\n    \n    local npcId = Merfin.GetNPCIDFromGUID(GUID)\n    \n    if creatures[bossID][1] == npcId \n    or creatures[bossID][2] == npcId then\n        return true\n    end\n    \n    return false\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'UNIT_SPELLCAST_SUCCEEDED' then\n        local unitID, _, spellID = ...\n        \n        if spellID == 118205 and not aura_env.IsSpam(2) then\n            local GUID = UnitGUID(unitID)\n            for _, boss in ipairs({ 'ZIAN', 'MENG', 'QIANG', 'SUBETAI' }) do\n                if aura_env.IsGUID(GUID, boss) then\n                    aura_env.BossSwap(boss, false)\n                    break\n                end\n            end\n        end\n        \n    elseif e == 'INSTANCE_ENCOUNTER_ENGAGE_UNIT' then\n        local curTime = GetTime()\n        \n        --if curTime - aura_env.encStartTime < 1 then\n        --return\n        --end\n        \n        local lastTime = GetTime()\n        local ticker\n        ticker = C_Timer.NewTicker(0.1, function()\n                for i = 1, 5 do\n                    local unitID = (\"boss%d\"):format(i)\n                    local GUID = UnitExists(unitID) and UnitGUID(unitID)\n                    for _, boss in ipairs({ 'ZIAN', 'SUBETAI', 'MENG', 'QIANG' }) do\n                        if aura_env.IsGUID(GUID, boss) and not aura_env.bossActivated[boss] then\n                            local delay = GetTime() - lastTime\n                            aura_env.BossSwap(boss, true, false, delay, GUID)\n                            \n                            if ticker then \n                                ticker:Cancel() \n                            end\n                            \n                            break\n                        end\n                    end\n                end\n        end, 15)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.bossActivated = {\n            ['QIANG']   = false,\n            ['ZIAN']    = false,\n            ['SUBETAI'] = false,\n            ['MENG']    = false,\n        }\n        \n        aura_env.encStartTime = GetTime()\n        aura_env.count = 0\n    end\nend",
