["custom"] = "local encounterID = '1507'\nlocal name        = Merfin:L('Platform')\n\nlocal options = {\n    ['Platform2'] = {\n        warningText = '%icon @cffe3e3e3' .. Merfin:L('Platform 2') .. '@r %icon',\n        ttsLine = Merfin:L('Platform 2')\n    },\n    ['Platform3'] = {\n        warningText = '%icon @cffe3e3e3' .. Merfin:L('Platform 3') .. '@r %icon',\n        ttsLine = Merfin:L('Platform 3')\n    },\n    ['Phase2'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", Merfin:L('Phase 2'):upper()),\n        ttsLine = Merfin:L('Phase 2')\n    }\n}\n\naura_env.SendWarning = function(ID)\n    local data = {\n        ID    = ID,\n        count = aura_env.count,\n        name  = name,\n        icon  = ID == 'Platform2' and 132333 or 135740,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = { Platform = \"flies to one of his platforms!\" },\n    ['deDE'] = { Platform = \"fliegt zu einer seiner Plattformen!\" },\n    ['esES'] = { Platform = \"¡vuela hacia una de sus plataformas!\" },\n    ['frFR'] = { Platform = \"vole jusqu'à l'une de ses plateformes !\" },\n    ['itIT'] = { Platform = \"vola verso una delle sue piattaforme!\" },\n    ['koKR'] = { Platform = \"자신의 플랫폼 중 하나로 날아갑니다!\" },\n    ['ruRU'] = { Platform = \"летит к одной из своих платформ!\" },\n    ['zhTW'] = { Platform = \"飛到其中一個平台上!\" },\n    ['zhCN'] = { Platform = \"飞向其中一个平台！\" },\n}\n\naura_env.MRT = function(event)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    GMRT.F.Note_Timer(event)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 124018 then\n            aura_env.count = 4\n            WeakAuras.ScanEvents('PLATFORM_CHANGED', aura_env.count)\n            aura_env.SendWarning('Phase2')\n            aura_env.MRT('PHASE_2')\n        end\n        \n    elseif e == 'RAID_BOSS_EMOTE' then\n        local msg = ...\n        \n        if aura_env.IsEmote(msg, 'Platform') then\n            aura_env.count = aura_env.count + 1\n            WeakAuras.ScanEvents('PLATFORM_CHANGED', aura_env.count)\n            \n            if aura_env.count > 1 and aura_env.count < 4 then\n                aura_env.SendWarning('Platform' .. aura_env.count)\n                aura_env.MRT('PLATFORM_' .. aura_env.count)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
