["custom"] = "aura_env.bossID = 62511\n\naura_env.MRT = function(percent)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = 'HP_BOSS_' .. percent\n    GMRT.F.Note_Timer(event)\nend",
