["debuffType"] = "HELPFUL",
["custom"] = "function(event, unit)\n    -- Reset on encounter start/end\n    if event == \"ENCOUNTER_START\" or event == \"ENCOUNTER_END\" then\n        aura_env.seenPercents = {}\n        return\n    end\n    \n    if not unit or not unit:match(\"boss\") then return end\n    \n    local guid = UnitGUID(unit)\n    if not guid then return end\n    \n    -- Get npcID using Merfin utility\n    local npcID = Merfin.GetNPCIDFromGUID(guid)\n    if not npcID or npcID ~= aura_env.bossID then\n        return\n    end\n    \n    local hp = UnitHealth(unit)\n    local maxHp = UnitHealthMax(unit)\n    if maxHp == 0 then return end\n    \n    local percent = math.floor((hp / maxHp) * 100)\n    \n    -- Initialize storage if needed\n    aura_env.seenPercents = aura_env.seenPercents or {}\n    \n    -- Trigger event if this percent was not triggered yet\n    if percent > 0 and not aura_env.seenPercents[percent] then\n        aura_env.seenPercents[percent] = true\n        aura_env.MRT(percent)\n    end\nend",
