["[DP] [TSK] Pillage"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'Pillage'\n\nlocal options = {\n    ['Pillage'] = {\n        warningText = \"%icon %name » %destName %icon\",\n    },\n    ['PillageOnYou'] = {\n        warningText = '@cffff4040%upper:name@r »' .. WA_ClassColorName(WeakAuras.me) .. '«'\n    }\n}\n\nlocal name, icon = C_Spell.GetSpellName(118047), C_Spell.GetSpellTexture(118047)\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['Pillage'])\nend\n\naura_env.SendWarning = function(ID, destName)\n    local data = { \n        ID       = ID, \n        count    = aura_env.count, \n        destName = WA_ClassColorName(destName),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        local msg,_,_,_, target = ...\n        if not msg:find(\"spell:118047\") then return end\n        \n        aura_env.count = aura_env.count + 1\n        \n        local timer = aura_env.bossActivated and 41 or 75\n        aura_env.StartCD(timer)\n        \n        local destName = UnitName(target)\n        \n        if destName == WeakAuras.me then\n            aura_env.SendWarning('PillageOnYou', destName)\n            local text = string.format('%s %s!', '{rt8}', C_Spell.GetSpellName(118047))\n            WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', text, 'SAY')\n        else\n            aura_env.SendWarning('Pillage', destName)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated, delay = ...\n        if bossID ~= 'SUBETAI' then return end\n        \n        aura_env.bossActivated = activated\n        \n        if activated then \n            aura_env.StartCD(25-delay)\n        else\n            aura_env.StartCD(30)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
