["[DP] [Sha] Ominous Cackle"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'OminousCackle'\n\nlocal name, icon = C_Spell.GetSpellName(119693), C_Spell.GetSpellTexture(119693)\n\nlocal options = {warningText = '%icon @cffffff80%name@r » %destName %icon'}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, expirationTime)\n    aura_env.expirationTime = expirationTime or duration + GetTime()\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = aura_env.expirationTime,\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            ignorePrew = aura_env.onPlatform\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    if aura_env.onPlatform then return end\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            destName = destName\n    }, options)\nend\n\naura_env.validSpellID = {[119593] = true, [119692] = true, [119693] = true}\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if aura_env.validSpellID[spellID] then\n                aura_env.count = aura_env.count + 1\n                local seconds = (aura_env.isTen or aura_env.isLfr) and 90.5 or 45.5\n                aura_env.StartCD(seconds, nil)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 129147 then\n                \n                table.insert(aura_env.targets, destName)\n                \n                if aura_env.IsSpam(3) then\n                    return\n                end\n                \n                C_Timer.After(0.3, function()\n                        local names = {}\n                        for _, name in ipairs(aura_env.targets) do\n                            table.insert(names, WA_ClassColorName(name))\n                        end\n                        \n                        local destNames = table.concat(names, ', ')\n                        aura_env.SendWarning(destNames)\n                        aura_env.targets = {}\n                end)\n            end\n        end\n        \n    elseif e == 'LEAVE_PLATFORM' then\n        aura_env.onPlatform = false\n        \n        if aura_env.phase2 then\n            return\n        end\n        \n        -- Restart CD with countdown\n        if GetTime() < aura_env.expirationTime then\n            aura_env.StartCD(aura_env.defaultCD, aura_env.expirationTime)\n        end\n        \n    elseif e == 'ENTER_PLATFORM' then\n        -- Restart CD with no countdown\n        aura_env.onPlatform = true\n        aura_env.StartCD(aura_env.defaultCD, aura_env.expirationTime)\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.phase2 = true\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isTen = WeakAuras.InstanceType() == 'ten'\n        aura_env.isLfr = WeakAuras.InstanceDifficulty() == 'lfr'\n        aura_env.defaultCD = (aura_env.isTen or aura_env.isLfr) and 90.5 or 45.5\n        aura_env.count = 0\n        aura_env.targets = {}\n        aura_env.onPlatform = false\n        aura_env.phase2 = false\n        \n        local seconds = (aura_env.isTen or aura_env.isLfr) and 40 or 25.5\n        aura_env.StartCD(seconds)\n    end\nend",
