["triggers"] = {
{
["trigger"] = {
["duration"] = "1",
["genericShowOn"] = "showOnCooldown",
["names"] = {
},
["debuffType"] = "HELPFUL",
["unit"] = "player",
["type"] = "custom",
["subeventSuffix"] = "",
["unevent"] = "auto",
["use_genericShowOn"] = true,
["custom_type"] = "status",
["event"] = "Cooldown Progress (Spell)",
["custom"] = "function()\n    if not aura_env.enemies then return end\n    \n    -- Trigger the mouseover event on the modifier\n    if aura_env.config.options.mouseoverSettings.mouseoverKey ~= 1 \n    and aura_env.CheckMouseoverModifier() then\n        WeakAuras.ScanEvents(\"AUTOMARKER_UPDATE_MOUSEOVER\")\n    end\n    \n    aura_env.SetupTables()\n    aura_env.GetUsedMarkers()\n    \n    local nameplates = C_NamePlate.GetNamePlates()\n    for _, frame in ipairs(nameplates) do\n        local unit = frame.namePlateUnitToken\n        if unit then\n            local guid = UnitGUID(unit)\n            if guid then\n                local npcId = select(6, strsplit(\"-\", guid))\n                if npcId == \"204560\" or npcId == \"204773\" then\n                    aura_env.SelectEnemyToMark(unit)\n                elseif aura_env.UnitIsInCombatWithParty(unit) then\n                    aura_env.SelectEnemyToMark(unit)\n                end\n            end\n        end\n    end\n    \n    -- Mark enemies\n    for i = 1, 9 do\n        if aura_env[\"enemiesToMark\" .. i] then\n            aura_env.MarkEnemies(aura_env[\"chosenMarkers\" .. i], aura_env[\"enemiesToMark\" .. i], 0)\n        end\n    end\nend",
