["unevent"] = "timed",
["custom"] = "function()\n    local unit = \"mouseover\"\n    \n    -- Don't continue if the unit shouldn't be marked\n    if aura_env.UnitIsInCombatWithParty(unit) or GetRaidTargetIndex(unit) or not UnitExists(unit) or UnitIsDead(unit) then return end\n    local npcId, _ = select(6, strsplit(\"-\", UnitGUID(unit)))\n    if not aura_env.enemies or not aura_env.enemies[npcId] then return end\n    \n    aura_env.SetupTables()\n    aura_env.GetUsedMarkers()\n    \n    -- Select enemies for marking\n    if aura_env.CheckMouseoverModifier() then\n        aura_env.SelectEnemyToMark(unit)\n    end\n    \n    -- Mark enemies\n    if not aura_env.ignoreNameplates[tonumber(npcId)] then\n        for i = 1, 9 do\n            if aura_env[\"enemiesToMark\" .. i] then\n                aura_env.MarkEnemies(aura_env[\"chosenMarkers\" .. i], aura_env[\"enemiesToMark\" .. i], 0)\n            end\n        end\n    else\n        -- Mark enemies with no nameplate without overriding marks (aura_env.ignoreNameplates)\n        for i = 1, 9 do\n            if aura_env[\"enemiesToMark\" .. i] then\n                aura_env.MarkEnemies(aura_env[\"chosenMarkers\" .. i], aura_env[\"enemiesToMark\" .. i], aura_env.startValueDiff)\n            end\n        end\n        \n        -- Increase startValueDiff by 1 or reset to 0 if at 7\n        if aura_env.startValueDiff < 7 then\n            aura_env.startValueDiff = aura_env.startValueDiff + 1\n        else\n            aura_env.startValueDiff = 0\n        end\n    end\nend",
