["init"] = {
["custom"] = "local encounterID = '1395'\nlocal ID          = 'AmethystPool'\n\nlocal name, icon = C_Spell.GetSpellName(130774), C_Spell.GetSpellTexture(130774)\n\nlocal options = {\n    warningText = '%icon @cffffff80%name@r (%count) %icon',\n}\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        localization = localization,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID    = ID,\n        count = aura_env.count,\n        name  = name,\n        icon  = icon,\n        localization = localization,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend",
["do_custom"] = true,
},
