["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'AMETHYST_POOL' then\n        aura_env.SendWarning()\n        aura_env.count = aura_env.count + 1\n        \n        local seconds = 11\n        aura_env.StartCD(seconds)\n        aura_env.Schedule('AMETHYST_POOL', seconds)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        \n        if WeakAuras.InstanceType() == 'twentyfive' and WeakAuras.InstanceDifficulty() ~= 'lfr' then\n            local seconds = 11\n            aura_env.StartCD(seconds)\n            aura_env.Schedule('AMETHYST_POOL', seconds)\n        end\n        \n    elseif e == 'ENCOUNTER_ENGAGE' then -- -- Custom Event for 10 Man\n        local npcID = ...\n        if npcID == 60047 then\n            local seconds = 6-1\n            aura_env.StartCD(seconds)\n            aura_env.Schedule('AMETHYST_POOL', seconds)\n        end\n    end\nend",
