["[Core] [T14] Text to Speech"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
1,
1,
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_message"] = false,
["message_type"] = "TTS",
},
["init"] = {
["custom"] = "local L = GetLocale()\nlocal cfg = aura_env.config.options\n\nlocal translations = {\n    ['ruRU'] = {\n        ['Лево'] = 'Left',\n        ['Право'] = 'Right',\n        ['Вперед'] = 'Forward',\n        ['Выбеги'] = 'Move Out',\n        ['Фаза 1'] = 'Phase 1',\n        ['Фаза 2'] = 'Phase 2',\n        ['Фаза 3'] = 'Phase 3',\n        ['Фаза 4'] = 'Phase 4',\n        ['Платформа 2'] = 'Platform 2',\n        ['Платформа 3'] = 'Platform 3',\n        ['Плюс Урон'] = 'Plus Damage',\n        ['Разойдись'] = 'Spread Out',\n        ['Бурсти босса'] = 'Burst the boss',\n    },\n    ['zhCN'] = {\n        ['左'] = 'Left',\n        ['右'] = 'Right',\n        ['向前'] = 'Forward',\n        ['跑开'] = 'Move Out',\n        ['1阶段'] = 'Phase 1',\n        ['2阶段'] = 'Phase 2',\n        ['3阶段'] = 'Phase 3',\n        ['4阶段'] = 'Phase 4',\n        ['2平台'] = 'Platform 2',\n        ['3平台'] = 'Platform 3',\n        -- ['Плюс Урон']   = 'Plus Damage',\n        ['分散'] = 'Spread Out',\n        ['正面'] = 'Burst the boss'\n    }\n}\n\naura_env.LSM = LibStub(\"LibSharedMedia-3.0\")\n\naura_env.IsSoundAvailable = function(key)\n    return aura_env.LSM:Fetch(\"sound\", key, true) ~= nil\nend\n\n-- Returns the lookup key for sound in LSM:\n-- enUS -> use the text itself; others -> mapped enUS token if exists, else nil\naura_env.GetSoundKey = function(text)\n    if L == 'enUS' then return text end\n    local t = translations[L]\n    if t and t[text] then return t[text] end\n    return nil\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.GetVoiceID = function() \n    return (cfg.useSpecificVoiceID and cfg.voiceID) or C_TTSSettings.GetVoiceOptionID(0)\nend\n\nif aura_env.config.options.testSound then\n    if aura_env.IsSpam(1) then return end\n    local text = cfg.testText\n    local voiceID = aura_env.GetVoiceID()\n    local destination = Enum.VoiceTtsDestination.LocalPlayback\n    local speed = cfg.voiceRate\n    local volume = cfg.volume\n    C_VoiceChat.SpeakText(voiceID, text, destination, speed, volume)\nend",
["do_custom"] = true,
},
["finish"] = {
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["custom_hide"] = "timed",
["custom"] = "function(e, text, voiceId, speed, volume)\n    if WeakAuras.IsOptionsOpen() then return end\n    if e ~= 'MERFIN_TTS' then return end\n    if not text then return end\n    \n    -- 1) Try to play a pre-registered sound from LSM\n    local soundKey = aura_env.GetSoundKey(text)             -- enUS: returns text; others: mapped or nil\n    if soundKey then\n        local soundFile = 'M: ' .. soundKey\n        if aura_env.IsSoundAvailable(soundFile) then\n            local soundPath = aura_env.LSM:Fetch(\"sound\", soundFile, true)\n            PlaySoundFile(soundPath, \"Master\")\n            return\n        end\n    end\n    -- Fallback: try original text as-is (in case someone registered it directly)\n    do\n        local fallbackFile = 'M: ' .. text\n        if aura_env.IsSoundAvailable(fallbackFile) then\n            local soundPath = aura_env.LSM:Fetch(\"sound\", fallbackFile, true)\n            PlaySoundFile(soundPath, \"Master\")\n            return\n        end\n    end\n    \n    -- 2) Otherwise use TTS\n    local cfg = aura_env.config.options\n    if not cfg.enable then return end\n    if aura_env.IsSpam(1) then return end\n    \n    local vID = aura_env.GetVoiceID()\n    local destination = Enum.VoiceTtsDestination.LocalPlayback\n    local rate = speed or 1\n    local vol = (cfg.applyAll and cfg.volume) or volume or 100\n    \n    C_VoiceChat.SpeakText(vID, text, destination, rate, vol)\nend",
