["names"] = {
},
["events"] = "TRIGGER:2,NAME_PLATE_UNIT_ADDED,NAME_PLATE_UNIT_REMOVED",
["custom"] = "function(a, e, ...)\n    if e == \"TRIGGER\" then\n        local extra = ...\n        if extra == 2 then\n            if WeakAuras.GetActiveTriggers(aura_env.id)[1] then\n                for _, state in pairs(a) do\n                    state.changed = true\n                    state.show = false\n                end\n            end\n            if WeakAuras.GetActiveTriggers(aura_env.id)[2] then\n                for _, plate in pairs(C_NamePlate.GetNamePlates()) do\n                    local unit = plate.namePlateUnitToken\n                    local npcid = select(6, strsplit(\"-\", UnitGUID(unit)))\n                    if not aura_env.npc[npcid] then\n                        aura_env.a(a, unit)\n                        a[unit].unit = unit\n                    end\n                end\n            end\n            return true\n        end\n        \n    elseif e == \"NAME_PLATE_UNIT_ADDED\" and WeakAuras.GetActiveTriggers(aura_env.id)[2] then\n        local unit = ...\n        local npcid = select(6, strsplit(\"-\", UnitGUID(unit)))\n        if not aura_env.npc[npcid] then\n            aura_env.a(a, unit)\n            a[unit].unit = unit\n            return true\n        end\n        \n    elseif e == \"NAME_PLATE_UNIT_REMOVED\" and WeakAuras.GetActiveTriggers(aura_env.id)[1] then\n        local unit = ...\n        if a[unit] then\n            aura_env.a(a, unit, false)\n            return true\n        end\n    end\nend",
