["do_custom"] = true,
},
["init"] = {
["do_custom"] = true,
["do_custom_unload"] = false,
["custom"] = "aura_env.npc = {\n    [\"62511\"] = true,\n    [\"62691\"] = true,\n    [\"62701\"] = true,\n    [\"62711\"] = true,\n}\n\naura_env.a = function(a, aid, type, total, value)\n    aid = aid or \"\"\n    a[aid] = {}\n    a[aid] = {\n        show = type ~= false and true or false,\n        changed = true,\n    }\n    if type then\n        a[aid].progressType = type\n        if type == \"timed\" then\n            a[aid].duration = total\n            a[aid].expirationTime = value or total + GetTime()\n            a[aid].autoHide = true\n        elseif type == \"static\" then\n            a[aid].total = total\n            a[aid].value = value or total\n        end\n    end\n    a[aid].name = aura_env.text\n    a[aid].stacks = aura_env.count\nend\n\naura_env.visible = function(unit, visibility)\n    if unit then\n        local plate = C_NamePlate.GetNamePlateForUnit(unit)\n        if plate then\n            if IsAddOnLoaded(\"Plater\") and plate.unitFramePlater then\n                C_Timer.After(0, function()\n                        if plate.unitFramePlater and UnitExists(unit) then\n                            if visibility then\n                                plate.unitFramePlater:Show()\n                            else\n                                plate.unitFramePlater:Hide()\n                            end\n                        end\n                end)\n            elseif IsAddOnLoaded(\"NeatPlates\") and plate.carrier then\n                C_Timer.After(0, function()\n                        if plate.carrier and UnitExists(unit) then\n                            if visibility then\n                                plate.carrier:Show()\n                            else\n                                plate.carrier:Hide()\n                            end\n                        end\n                end)\n            elseif IsAddOnLoaded(\"TidyPlates_ThreatPlates\") and plate.TPFrame then\n                C_Timer.After(0, function()\n                        if plate.TPFrame and UnitExists(unit) then\n                            if visibility then\n                                plate.TPFrame:Show()\n                            else\n                                plate.TPFrame:Hide()\n                            end\n                        end\n                end)\n            elseif IsAddOnLoaded(\"Kui_Nameplates\") and plate.kui then\n                C_Timer.After(0, function()\n                        if plate.kui and UnitExists(unit) then\n                            if visibility then\n                                plate.kui:Show()\n                            else\n                                plate.kui:Hide()\n                            end\n                        end\n                end)\n            elseif IsAddOnLoaded(\"ElvUI\") and ElvUI[1] and ElvUI[1].NamePlates and ElvUI[1].NamePlates.Initialized and plate.unitFrame then\n                if visibility then\n                    plate.unitFrame:Show()\n                else\n                    plate.unitFrame:Hide()\n                end\n            elseif IsAddOnLoaded(\"NDUI\") and plate.unitFrame then\n                if visibility then\n                    plate.unitFrame:Show()\n                else\n                    plate.unitFrame:Hide()\n                end\n            elseif plate.UnitFrame then\n                if visibility then\n                    plate.UnitFrame:Show()\n                else\n                    plate.UnitFrame:Hide()\n                end\n            end\n        end\n    end\nend",
["customOnUnload"] = "\n\n\n\n\n\n--作者巴尼\n--Author Barney",
},
