["[T11] Backend - Trash"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Trash\n\nlocal ENTRY = aura_env\n\nlocal localized = {\n    ['enUS'] = {\n        nefRp = 'Ha ha ha ha ha! The heroes have made it to the glorious finale. I take it you are in good spirits? Prepared for the final battle? Then gaze now upon my ultimate creation! RISE, SISTER!',\n    },\n    \n    ['ruRU'] = {\n        nefRp = 'Вот и пришли наши герои к своей славной смерти. Надеюсь, все в настроении? Готовы к последней битве? В таком случае прошу приветствовать мое лучшее творение! ПРОСНИСЬ, СЕСТРА!',\n    },\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L\n\nENTRY.mechanics = {\n    sacrifice =       { 80727 },\n    enrage =          { 80084 },\n    whirlwind =       { 80652 },\n    drakonid_rush =   { 79630 },\n    laser_strike =    { 81063 },\n    flash_bomb =      { 81056 },\n    piercing_grip =   { 80145 },\n    flame_breath =    { 80411 },\n    chain_lightning = { 80646 },\n    shadowflame =     { 79921 },\n    nefarian_rp =     { false, 134154 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit\nend\n\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    \n    if IsEntryInitialized() then\n        args = {}\n        args.subEvent = subEvent\n        args.sourceGUID = sourceGUID\n        args.sourceName = sourceName\n        args.destGUID = destGUID\n        args.destName = destName\n        args.spellId = spellId\n        args.stacks = stacks\n        return ENTRY[subEvent] and ENTRY[subEvent](args)\n    end\nend\n\n--------------\n--> Main Logic\n--------------\n\nENTRY['SPELL_AURA_APPLIED'] = function(args) \n    if args.spellId == 80727 and CORE.IsDestTypePlayer(args.destFlags) then\n        Warning('sacrifice', args.destName)\n        Timer('sacrifice', 20, args.destName)\n    elseif args.spellId == 80084 then\n        Warning('enrage', args.destName)\n        Cooldown('enrage', 25)\n    elseif args.spellId == 80652 then\n        Warning('whirlwind', args.destName)\n        Timer('whirlwind', 5, args.destName)\n    elseif args.spellId == 79630 then\n        Cooldown('drakonid_rush', 30)\n    elseif args.spellId == 80145 then\n        Cooldown('piercing_grip', 40)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED_DOSE'] = function(args) \n    if args.spellId == 80084 then\n        Warning('enrage', args.destName, args.stacks)\n        Cooldown('enrage', 25)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 80727 and CORE.IsDestTypePlayer(args.destFlags) then\n        Cancel('sacrifice', 'ALL')\n    elseif args.spellId == 80652 then\n        Cancel('whirlwind', 'ALL')\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)  \n    if args.spellId == 81063 then\n        Warning('laser_strike')\n        Cooldown('laser_strike', 15)\n    elseif args.spellId == 81056 then\n        Warning('flash_bomb')\n        Cooldown('flash_bomb', 15)\n    elseif args.spellId == 79921 then\n        -- Shadowflame (Left Drake)\n        Timer('shadowflame', 3)\n        Cooldown('shadowflame', 15)\n        PreWarning('shadowflame', 10)\n    elseif args.spellId == 80846 then\n        Cooldown('chain_lightning', 10, args.sourceName, true)\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 80411 and args.destGUID == CORE.PlayerGUID then\n        GTFO('flame_breath')\n    elseif args.spellId == 81063 and args.destGUID == CORE.PlayerGUID then\n        GTFO('laser_strike')\n    elseif args.spellId == 81056 and args.destGUID == CORE.PlayerGUID then\n        GTFO('flash_bomb')\n    end\nend\n\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['UNIT_DIED'] = function(args)\n    local creatureId = CORE.GetGuidCreatureId(args.destGUID)\n    if creatureId == 42800 then\n        ENTRY.CASTS[42800] = (ENTRY.CASTS[42800] or 0) + 1\n        if ENTRY.CASTS[42800] == 2 then\n            Cancel('laser_strike', 'ALL')\n            Cancel('flash_bomb', 'ALL')\n        end\n    elseif creatureId == 42764 then\n        Cancel('shadowflame', 'ALL')\n    end\nend\n\nENTRY['CHAT_MSG_MONSTER_YELL'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if msg == L.nefRp or msg:find(L.nefRp) then\n        Timer('nefarian_rp', 38)\n    end\nend",
