["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    \n    if event == 'UNIT_POWER_UPDATE' then\n        local unit = ...\n        local GUID = UnitGUID(unit)\n        \n        if states[GUID] then\n            local power = UnitPower(unit, 10)\n            states:Update(GUID, { value = power })\n        end\n        \n    elseif event == 'WIDGET_RESHAPE_LIFE' then\n        local show, unitKey, GUID, unitName = ...\n        \n        if unitKey ~= aura_env.unitKey then return end\n        \n        if show then\n            local _, powerToken = UnitPowerType(unitName)\n            states:Update(GUID, {\n                    progressType = 'static',\n                    unitName = unitName,\n                    value = 100,\n                    total = 100,\n                    name = _G[powerToken]\n            })\n            \n        elseif states[GUID] then\n            states:Remove(GUID)\n        end\n        \n    elseif event == 'OPTIONS' then\n        states:Update('', { \n                progressType = 'static',\n                unitName = unitName,\n                value = 50,\n                total = 100,\n                name = _G['ENERGY']\n        })\n    end\nend",
