},
["debuffType"] = "HELPFUL",
["subeventSuffix"] = "_CAST_SUCCESS",
["type"] = "custom",
["custom"] = "function(event, ...)\n    \n    if event == \"PLAYER_TOTEM_UPDATE\" then\n        \n        local index = ({...})[1]\n        \n        if not index then return end\n        \n        local totemActive, _, _, _, _ = GetTotemInfo(index)\n        \n        if aura_env.stacks == nil then\n            \n            aura_env.stacks = 0\n            \n        end\n        \n        if totemActive then\n            \n            if aura_env.stacks < 3 then \n                \n                aura_env.stacks = aura_env.stacks + 1\n                \n            end\n            \n            return true\n            \n        else\n            \n            if aura_env.stacks == 0 then return end\n            \n            if aura_env.removeStacksBlocker then\n                \n                if time() > aura_env.removeStacksBlocker then\n                    aura_env.stacks = aura_env.stacks - 1\n                end\n                \n            else\n                \n                aura_env.stacks = aura_env.stacks - 1\n                \n            end\n            \n            if aura_env.stacks ~= 0 then return true end\n            \n        end\n        \n    elseif event == \"PLAYER_ENTERING_WORLD\" then\n        aura_env.stacks = 0\n        \n        local t1 = GetTotemInfo(1)\n        local t2 = GetTotemInfo(2)\n        local t3 = GetTotemInfo(3)\n        \n        for _, value in pairs({t1, t2, t3}) do\n            \n            if value then\n                \n                aura_env.stacks = aura_env.stacks + 1\n                \n            end\n        end\n        \n        if aura_env.stacks > 0 then return true end\n        \n    end\nend",
["custom_type"] = "status",
["spellIds"] = {
},
["use_spellId"] = true,
["event"] = "Combat Log",
["customStacks"] = "function()\n    return aura_env.stacks\nend\n    \n    ",
