["custom"] = "function(event, ...)\n    \n    if aura_env.stacks == 0 then return true end\n    \n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local spellId = ({...})[3]\n        \n        if spellId == 88751 then\n            \n            aura_env.stacks = 0\n            aura_env.removeStacksBlocker = time() + 3\n            \n            return true\n            \n        end\n    end\nend",
},
