["actions"] = {
["start"] = {
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'ClosedCircuit'\n\nlocal name, icon = C_Spell.GetSpellName(117949), C_Spell.GetSpellTexture(117949)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n}\n\naura_env.SendWarning = function()\n    local names = {}\n    for _, name in ipairs(aura_env.targets) do\n        table.insert(names, WA_ClassColorName(name))\n    end\n    \n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = table.concat(names, ', '),\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if spellID == 117949 then\n            if not aura_env.IsSpam(3) then\n                aura_env.count = aura_env.count + 1\n                aura_env.targets = {}\n                \n                C_Timer.After(0.3, function()\n                        WeakAuras.ScanEvents('CIRCUIT_TARGETS') \n                end)\n            end\n            \n            table.insert(aura_env.targets, destName) \n        end\n        \n    elseif e == 'CIRCUIT_TARGETS' then\n        aura_env.SendWarning()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
