},
["init"] = {
["custom"] = "local tonumber, strsplit, pairs = tonumber, strsplit, pairs\nlocal UnitExists, UnitGUID = UnitExists, UnitGUID\nlocal GetTime = GetTime\n\naura_env.debug = function(...)\n    print('|cffffff00MerfinDebug T13:|r', ...)\nend\n\nlocal cooldownData = {\n    ['Berserk'] = { name = 'Berserk', icon = 136224 },\n    ['StompMorchok'] = { name = 'Stomp', icon = 133594, special = true, },\n    ['CrystalMorchok'] = { name = 'Crystal', icon = 332402, special = true },\n    ['StompKohcrom'] = { name = 'Stomp', icon = 133594, special = true },\n    ['CrystalKohcrom'] = { name = 'Crystal', icon = 332402, special = true },\n    ['EarthenVortex'] = { name = 'EarthenVortex', icon = 433442 },\n    \n}\n\nlocal encounterID = '1292'\n\nlocal CREATURE_ID = {\n    MORCHOK = 55265,\n    KOHCROM = 57773\n}\n\nlocal MRT_CALLBACK = {\n    --[[\n    ['StompMorchok'] = true,\n    ['StompKohcrom'] = true,\n    ]]--\n}\n\nlocal PRE_WARNING = {\n    ['EarthenVortex'] = true,\n    ['Berserk'] = true,\n}\n\nlocal GetGuidCreatureId = function(GUID)\n    local guidType, _, playerdbID, _, _, cid, _ = strsplit(\"-\", GUID or \"\")\n    if guidType and (guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\") then\n        return tonumber(cid)\n    end\n    if guidType and (guidType == \"Player\" or guidType == \"Item\") then\n        return tonumber(playerdbID)\n    end\n    return 0\nend\n\nlocal GetUnitCreatureId = function(unitId)\n    if not UnitExists(unitId) then\n        return 0\n    end\n    local unitGUID = UnitGUID(unitId)\n    return GetGuidCreatureId(unitGUID)\nend\n\naura_env.IsSourceGUID = function(sourceGUID, creature)\n    local creatureId = CREATURE_ID[creature]\n    if not creatureId then \n        return false \n    end\n    local npcId = aura_env.guidCache[sourceGUID] or GetGuidCreatureId(sourceGUID)\n    return npcId == creatureId\nend\n\naura_env.ManageCounter = function(action, mechanicName, value)\n    if action == \"increase\" then\n        aura_env.count[mechanicName] = (aura_env.count[mechanicName] or 0) + 1\n        return aura_env.count[mechanicName]\n    elseif action == \"get\" then\n        return aura_env.count[mechanicName] or 0\n    elseif action == \"set\" then\n        aura_env.count[mechanicName] = value\n        return aura_env.count[mechanicName]\n    else\n        --print(\"Unknown action: \" .. tostring(action))\n    end\nend\n\naura_env.SendNoteMRT = function(id)\n    if GMRT and GMRT.F and GMRT.F.Note_Timer then\n        local customEvent = 'Merfin_CD_Start_' .. id\n        GMRT.F.Note_Timer(customEvent)\n    end\nend\n\naura_env.WipeSchedulers = function()\n    if aura_env.schedulers then \n        for schedulerName, scheduler in pairs(aura_env.schedulers) do\n            WeakAuras.timer:CancelTimer(scheduler)\n        end\n    end\nend\n\naura_env.SchedulePrewarning = function(id, duration)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        duration - 5,\n        'WA_MERFIN_T13',\n        'PRE_WARNING',\n        'SHOW',\n        id\n    )\nend\n\naura_env.ScheduleEvent = function(id, after)\n    aura_env.schedulers = aura_env.schedulers or {}\n    \n    if aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\n    \n    aura_env.schedulers[id] = WeakAuras.timer:ScheduleTimer(\n        WeakAuras.ScanEvents,\n        after,\n        'WA_MERFIN_T13_SCHEDULED',\n        id\n    )\nend\n\naura_env.StopCD = function(id, GUID)\n    aura_env.predict[id] = nil\n    \n    local data = cooldownData[id]\n    \n    if not data then\n        return\n    end\n    \n    local cooldown = {\n        id = id,\n        GUID = GUID,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD_HIDE', encounterID, cooldown)\n    \n    if PRE_WARNING[id] and aura_env.schedulers[id] then\n        WeakAuras.timer:CancelTimer(aura_env.schedulers[id])\n        WeakAuras.ScanEvents('WA_MERFIN_T13', 'PRE_WARNING', 'HIDE', id)\n    end\nend\n\naura_env.StartCD = function(id, duration, autoHide, isIncrease, GUID)\n    local count = aura_env.ManageCounter(isIncrease and 'increase' or 'get', id)\n    \n    aura_env.predict[id] = duration + GetTime()\n    \n    local data = cooldownData[id]\n    \n    if not data then return end\n    \n    local cooldown  = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        name = data.name,\n        id = id,\n        GUID = GUID,\n        icon = data.icon,\n        count = count,\n        roleIcon = data.roleIcon,\n        special = data.special,\n    }\n    \n    WeakAuras.ScanEvents('WA_MERFIN_BOSS_CD', encounterID, cooldown)\n    \n    if not PRE_WARNING[id] then return end\n    \n    aura_env.SchedulePrewarning(id, duration)\nend\n\naura_env.IsCooldownReadyBefore = function(id, before)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (predictedAt - GetTime() > before)\nend\n\naura_env.IsCooldownReady = function(id)\n    local predictedAt = aura_env.predict[id]\n    return predictedAt and (GetTime() > predictedAt)\nend\n\naura_env.ClearCache = function()\n    aura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n    aura_env.echo = WeakAuras.InstanceType() == 'twentyfive' and 5 or 6\n    \n    -- Reset flags\n    aura_env.kohcromSummoned = false\n    aura_env.lastMechanic = 'crystal'\n    \n    aura_env.WipeSchedulers()\n    \n    -- Clear caches and counters\n    aura_env.guidCache = {}\n    aura_env.count = {}\n    aura_env.predict = {}\n    aura_env.schedulers = {}\n    \n    -- Reset flags for first mechanic usage\n    aura_env.firstBloodFor = {\n        MORCHOK = false,\n        KOHCROM = false,\n    }\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, CLEU:SPELL_CAST_START:SPELL_CAST_SUCCESS:SPELL_SUMMON, UNIT_SPELLCAST_CHANNEL_STOP",
["custom"] = "function(e, _, subEvent, channelSpellId, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellId)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellId == 103414 then -- Stomp\n                if aura_env.IsSourceGUID(sourceGUID, 'MORCHOK') then\n                    if not aura_env.kohcromSummoned then \n                        aura_env.lastMechanic = 'stomp' \n                    end\n                    aura_env.StartCD('StompMorchok', 12, false , true)\n                    \n                elseif aura_env.IsSourceGUID(sourceGUID, 'KOHCROM') then\n                    aura_env.StartCD('StompKohcrom', 12, false, true)\n                end\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellId == 109017 then -- Summon Kohcrom\n                aura_env.kohcromSummoned = true\n                local stompCd = aura_env.echo + 6\n                local crystalCd = aura_env.echo + 14\n                \n                if aura_env.lastMechanic == 'crystal' then\n                    aura_env.StartCD('StompMorchok', 6)\n                    aura_env.StartCD('StompKohcrom', 27)\n                    aura_env.StartCD('CrystalMorchok', 14)\n                    aura_env.StartCD('CrystalKohcrom', crystalCd)\n                elseif aura_env.lastMechanic == 'stomp' then\n                    aura_env.StartCD('CrystalMorchok', 6)\n                    aura_env.StartCD('CrystalKohcrom', stompCd)\n                    aura_env.StartCD('StompMorchok', 15)\n                    aura_env.StartCD('StompKohcrom', crystalCd)\n                end\n                \n            elseif spellId == 103821 then -- Start Blood Phase (Grip)\n                WeakAuras.ScanEvents('WA_MERFIN_BLOOD_PHASE_START')\n                aura_env.StopCD('EarthenVortex')\n                aura_env.StopCD('CrystalMorchok')\n                aura_env.firstBloodFor.MORCHOK = true\n                aura_env.StopCD('StompMorchok')\n                \n                if aura_env.kohcromSummoned then\n                    aura_env.firstBloodFor.KOHCROM = true\n                    aura_env.StopCD('StompKohcrom')\n                    aura_env.StopCD('CrystalKohcrom')\n                end\n            end\n            \n        elseif subEvent == 'SPELL_SUMMON' then\n            if spellId == 103639 then -- Crystal\n                if aura_env.IsSourceGUID(sourceGUID, 'MORCHOK') then\n                    if not aura_env.kohcromSummoned then \n                        aura_env.lastMechanic = 'crystal' \n                    end\n                    aura_env.StartCD('CrystalMorchok', 12, false, true)\n                elseif aura_env.IsSourceGUID(sourceGUID, 'KOHCROM') then\n                    aura_env.StartCD('CrystalKohcrom', 12, false, true)\n                end\n            end\n        end\n        \n    elseif e == 'UNIT_SPELLCAST_CHANNEL_STOP' then\n        if channelSpellId == 103851 then -- End Blood Phase\n            WeakAuras.ScanEvents('WA_MERFIN_BLOOD_PHASE_END')\n            local stompCd = 19\n            local crystalCd = 26\n            \n            aura_env.StartCD('EarthenVortex', 75, false, true)\n            aura_env.StartCD('StompMorchok', stompCd)\n            aura_env.StartCD('CrystalMorchok', crystalCd)\n            \n            if aura_env.kohcromSummoned then\n                aura_env.StartCD('StompKohcrom', stompCd + aura_env.echo)\n                aura_env.StartCD('CrystalKohcrom', crystalCd + aura_env.echo)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('StompMorchok', 11)\n        aura_env.StartCD('CrystalMorchok', 16)\n        aura_env.StartCD('EarthenVortex', 56)\n        \n        if aura_env.IsHeroic then\n            aura_env.StartCD('Berserk', 420)\n            aura_env.ScheduleEvent('BERSERK_EMPHASIZED', 410)\n        end\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
