["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'ArcingEnergy'\n\nlocal name, icon = C_Spell.GetSpellName(117945), C_Spell.GetSpellTexture(117945)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r (%count) %icon\",\n}\n\naura_env.StopCD = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID, GUID = GUID })\nend\n\naura_env.StartCD = function(duration, GUID)\n    local data = {\n        show           = true,\n        autoHide       = false,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        GUID           = GUID,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceGUID,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 117945 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n                aura_env.StartCD(11.5, sourceGUID)\n            elseif spellID == 129711 then\n                aura_env.StopCD(sourceGUID)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
