["init"] = {
["custom"] = "local frontend = aura_env\nlocal backend\n\nlocal WA_MAIN_EVENT = 'WA_MERFIN_EQUIPPED_ITEMS'\n\nlocal SendEvent = function(event, ...)\n    WeakAuras.ScanEvents(WA_MAIN_EVENT, event, ...)\nend\n\nlocal EventHandler = EventHandler or {}\n\nEventHandler[WA_MAIN_EVENT] = function(a, subEvent, ...)\n    if subEvent == 'BACKEND_INITIALIZED' then\n        local link_to_backend = ...\n        backend = link_to_backend\n        SendEvent('REGISTER_FRONTEND', frontend)\n    elseif backend then\n        return backend.OnFrontendEvent(a, subEvent, frontend, ...)\n    else\n        \n    end\nend\n\naura_env.OnTSU = function(a, e, ...)\n    return EventHandler[e] and EventHandler[e](a, ...)\nend",
["do_custom"] = true,
},
