["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'SunBreath'\n\nlocal function GetSpellInfoTable(spellID)\n    if WeakAuras.IsRetail() then\n        return C_Spell.GetSpellName(spellID), C_Spell.GetSpellTexture(spellID)\n    else\n        local name, _, icon = GetSpellInfo(spellID)\n        return name, icon\n    end\nend\n\nlocal name, icon = GetSpellInfoTable(122855)\n\nlocal options = {warningText = \"%icon @cffffff80%name@r (%count) %icon\"}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'SUN_BREATH_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = {ID = ID, name = name, icon = icon, count = aura_env.count}\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 122855 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n                if GetTime() - aura_env.dayLast < 100 then\n                    aura_env.StartCD(29)\n                else\n                    aura_env.StopCD()\n                end\n            end\n        end\n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID = ...\n        \n        if phaseID == 'NightPhase' then\n            aura_env.StopCD()\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.dayLast = GetTime()\n            aura_env.count = 0\n            aura_env.StartCD(29)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.count = 0\n    end\nend",
