["【露露】萨满：职业语音合集（就绪语音）"] = {
["outline"] = "OUTLINE",
["authorOptions"] = {
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_custom"] = true,
["custom"] = "-- Author: 露露緹婭@Bilibili\nlocal R = \"Interface\\\\AddOns\\\\Rurutia\\\\【露露】\"\n\nlocal triggerSounds = {\n    [1] = R..\"Link好了.ogg\",       -- 灵魂链接图腾\n    [2] = R..\"电能好了.ogg\",       -- 电能图腾\n    [3] = R..\"升腾好了.ogg\",       -- 升腾\n    [4] = R..\"法潮好了.ogg\",       -- 法力之潮图腾\n    [5] = R..\"奶潮好了.ogg\",       -- 治疗之潮图腾\n    [6] = R..\"灵魂行者.ogg\",       -- 灵魂行者的恩赐\n    [7] = R..\"土爹好了.ogg\",          -- 土元素\n    [8] = R..\"先祖.ogg\",             -- 先祖指引\n    [9] = R..\"雷霆好了.ogg\",      -- 雷霆风暴\n    [10] = R..\"星界好了.ogg\",      -- 星界转移\n    [11] = R..\"战栗好了.ogg\",      -- 战栗图腾\n    [12] = R..\"石壁好了.ogg\",      -- 石壁图腾\n    [13] = R..\"狗狗好啦.ogg\",      -- 野性狼魂\n    [14] = R..\"回收好了.ogg\",      -- 元素的召唤（收回图腾）\n    [15] = R..\"地缚好了.ogg\",      -- 地缚图腾\n    [16] = R..\"陷地好了.ogg\",      -- 陷地图腾\n    [17] = R..\"狂风好了.ogg\",      -- 狂风图腾、风行图腾（MOP）\n    [18] = R..\"幽魂步.ogg\",         -- 幽魂步\n    [21] = R..\"跑快快.ogg\",         -- 灵魂行者的恩赐，开启语音\n}\n\n-- 获取当前激活的触发器\nlocal activeTriggers = WeakAuras.GetActiveTriggers(aura_env.id)\nif activeTriggers then\n    -- 遍历所有触发器，播放第一个激活的触发器对应的语音\n    for triggerIndex, isActive in pairs(activeTriggers) do\n        if isActive and triggerSounds[triggerIndex] then\n            PlaySoundFile(triggerSounds[triggerIndex], \"Master\")\n            return -- 只播放第一个激活的触发器\n        end\n    end\nend",
},
