["[T11] Backend - Theralion and Valiona"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Valiona)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Theralion and Valiona\n\nlocal ENTRY = aura_env\nlocal encounterId = 1032\n\nlocal localized = {\n    ['enUS'] = {\n        -- RAID_BOSS_EMOTE\n        Trigger1 = \"Deep Breath\",\n    },\n    \n    ['ruRU'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"Глубокий вдох\",\n    },\n    ['zhCN'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"深呼吸\",\n    },\n    ['koKR'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"들이쉽니다!\",\n    },\n    ['zhTW'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"深呼吸\",\n    },\n    ['frFR'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"Theralion, je m'occupe du vestibule. Couvre leur fuite !\",\n    },\n    ['deDE'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"Tiefer Atem\",\n    },\n    ['esES'] = {\n        -- RAID_BOSS_EMOTE  \n        Trigger1 = \"Aliento profundo\",\n    },\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    blackout =             { 86788 },\n    dazzling_destruction = { 86408 },\n    fab_flames =           { 86505 },\n    engulfind_magic =      { 86622 },\n    deep_breath =          { 86059, 425956 },\n    twilight_shift =       { 93051 },\n    devouring_flames =     { 86840 },\n    dazzling_destruction = { 86408 },\n    twilight_blast =       { 86369 },\n    twilight_meteorite =   { 86013 },\n    twilight_zone =        { 86214 },\n    next_swap =            { false, 134154 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal markWarned = false\nlocal valionaLanded = false\n\nlocal theralionDelay = function()\n    WeakAuras.ScanEvents('THERALION_LANDED')\n    Cancel('devouring_flames', 'COOLDOWN')\n    Cancel('blackout', 'COOLDOWN')\n    Timer('fab_flames', 10)\n    \n    Cooldown('next_swap', 140)\n    Cooldown('engulfind_magic', 15)\n    Cooldown('deep_breath', 85)\n    PreWarning('deep_breath', 80)\n    \n    valionaLanded = false\nend\n\nlocal valionaDelay = function()\n    WeakAuras.ScanEvents('VALIONA_LANDED')\n    Cancel('engulfind_magic', 'COOLDOWN')\n    \n    Cooldown('next_swap', 100)\n    Cooldown('blackout', 10)\n    Cooldown('devouring_flames', 25); PreWarning('devouring_flames', 20)\nend\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    \n    ENTRY.CASTS.blackout = 0\n    ENTRY.CASTS.dazzling = 0\n    ENTRY.CASTS.devouring_flames = 0\n    ENTRY.CASTS.breath = 0\n    \n    valionaLanded = true\n    \n    Cooldown('next_swap', 100-delay)\n    Cooldown('berserk', 600-delay)\n    Cooldown('blackout', 11-delay)\n    Cooldown('devouring_flames', 25-delay); PreWarning('devouring_flames', 20-delay)\n    Cooldown('dazzling_destruction', 85-delay)\n    \nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    \n    if args.spellId == 86840 then\n        ENTRY.CASTS.devouring_flames = ENTRY.CASTS.devouring_flames + 1\n        Timer('devouring_flames', 2)\n        -- Valiona always casts only 2 flames per phase\n        Cooldown('devouring_flames', 42, '', ENTRY.CASTS.devouring_flames == 2); PreWarning('devouring_flames', 37)\n        SpecialWarning('devouring_flames')\n        \n    elseif args.spellId == 86408 then\n        ENTRY.CASTS.dazzling = ENTRY.CASTS.dazzling + 1\n        Warning('dazzling_destruction', nil, ENTRY.CASTS.dazzling)\n        Cancel('dazzling_destruction', 'COOLDOWN')\n        if ENTRY.CASTS.dazzling == 1 then\n            SpecialWarning('dazzling_destruction')\n        elseif ENTRY.CASTS.dazzling == 3 then\n            CORE.Schedule(ENTRY, 'dazzling_destruction', 5, theralionDelay)\n            ENTRY.CASTS.dazzling = 0\n        end\n        \n    elseif args.spellId == 86369 then\n        CORE.Schedule(ENTRY, 'twilight_blast', 0.1, CORE.TargettedCast, args.sourceGUID, 'TWILIGHT_BLAST_TARGET')\n        -- Twilight Blast (Theralion Air)\n        if not valionaLanded then\n            Cancel('fab_flames', 'TIMER')\n            valionaLanded = true\n        end\n    end\n    \nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 86788 then\n        ENTRY.CASTS.blackout = ENTRY.CASTS.blackout + 1\n        Timer('blackout', 15, args.destName)\n        Cooldown('blackout', 45.5)\n        if args.destGUID == CORE.PlayerGUID then\n            SpecialWarning('blackout')\n        else\n            Warning('blackout', args.destName)\n        end\n        \n    elseif args.spellId == 86622 then\n        -- TODO: Engulfing Magic Targets\n        Cooldown('engulfind_magic', 35)\n        if args.destGUID == CORE.PlayerGUID then\n            SpecialWarning('engulfind_magic')\n        end\n        \n        \n    elseif args.spellId == 93051 then\n        Warning('twilight_shift', args.destName, args.stacks or 1)\n        Cooldown('twilight_shift', 20)\n        \n    elseif args.spellId == 86214 and CORE.PlayerGUID == args.destGUID then\n        if (args.amount or 1) >= 20 and AntiSpam('twilight_zone', 5) then\n            SpecialWarning('twilight_zone', nil, args.amount)\n        end\n    end\nend\nENTRY['SPELL_AURA_APPLIED_DOSE'] = ENTRY['SPELL_AURA_APPLIED']\nENTRY['SPELL_AURA_REFRESH'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 86788 then\n        ENTRY.CASTS.blackout = ENTRY.CASTS.blackout - 1\n        Cancel('blackout', 'TIMER')\n        \n    elseif args.spellId == 86622 then\n        -- TODO\n    elseif args.spellId == 93051 then\n        -- TODO\n    end\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 86505 and destGUID == CORE.PlayerGUID and AntiSpam('fab_flames', 3) then \n        GTFO('fab_flames')\n    end\nend\nENTRY['SPELL_MISSED'] = ENTRY['SPELL_DAMAGE']\n\nENTRY['RAID_BOSS_EMOTE'] = function(msg)\n    if not IsEntryInitialized() then return end\n    if not (L and L.Trigger1) then return end\n    if msg == L.Trigger1 or msg:find(L.Trigger1) then\n        ENTRY.CASTS.breath = ENTRY.CASTS.breath + 1\n        SpecialWarning('deep_breath', nil, ENTRY.CASTS.breath)\n        if ENTRY.CASTS.breath == 1 then\n            Cancel('deep_breath', 'COOLDOWN')\n            Cooldown('dazzling_destruction', 132)\n            CORE.Schedule(ENTRY, 'engulfind_magic', 40, valionaDelay)\n            \n        elseif ENTRY.CASTS.breath == 3 then\n            ENTRY.CASTS.breath = 0\n        end\n    end\nend\n\nENTRY['UNIT_SPELLCAST_SUCCEEDED'] = function(unitId,_, spellId)\n    if spellId == 86497 and not valionaLanded and AntiSpam('fab_flames', 2) then\n        print('COOLDOWN FAB FLAMES')\n        Cooldown('fab_flames', 15)\n    end\nend",
