["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'DreadsSpawn'\n\nlocal name, icon = C_EncounterJournal.GetSectionInfo(6107).title, 132345\n\nlocal options = {warningText = '%icon @cffff8b17%name@r (x%amount) %icon'}\n\naura_env.spawns = {\n    [1] = 1,\n    [2] = 2,\n    [3] = 2,\n    [4] = 3,\n    [5] = 3,\n    [6] = 4,\n    [7] = 4,\n    [8] = 5,\n    [9] = 5,\n    [10] = 6,\n    [11] = 6,\n    [12] = 7,\n    [13] = 7,\n    [14] = 8,\n    [15] = 8,\n    [16] = 9,\n    [17] = 9,\n    [18] = 10,\n    [19] = 10,\n    [20] = 11\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function(spawns)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count,\n            amount = spawns\n    }, options)\nend\n\naura_env.Unshedule = function()\n    if aura_env.scheduler then aura_env.scheduler:Cancel() end\nend\n\naura_env.Schedule = function(event, seconds)\n    aura_env.Unshedule()\n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 120455 then -- Submerge\n                aura_env.count = aura_env.count + 1\n                aura_env.Schedule('DREADS_SPAWN', 3)\n            end\n        end\n        \n    elseif e == 'DREADS_SPAWN' then\n        local spawns = aura_env.spawns[aura_env.count]\n        aura_env.SendWarning(spawns)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.Unshedule()\n    end\nend",
