["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, extraSpellID, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 111649 then\n                aura_env.StartCD('FixateAnger', 12)\n                aura_env.StartCD('UnleashedAnguish', 12)\n            elseif spellID == 115350 then\n                local count = aura_env.ManageCounter('increase', 'FixateAnger')\n                aura_env.StartCD('FixateAnger', 12)\n                if destName == WeakAuras.me then\n                    aura_env.Warning('FixateAngerOnYou')\n                    aura_env.Chat('{rt8} Fixate on ' .. WeakAuras.me .. ' {rt8}')\n                    aura_env.TTS('Fixated')\n                else\n                    aura_env.Warning('FixateAnger', destName)\n                end\n            elseif spellID == 111585 then\n                if destName == WeakAuras.me then\n                    aura_env.Warning('DarkBlazeOnYou')\n                    aura_env.Chat('{rt3} Blaze on ' .. WeakAuras.me .. ' {rt3}')\n                    aura_env.TTS('Out of group')\n                else\n                    aura_env.Warning('DarkBlaze', destName)\n                end\n            end\n        elseif subEvent == 'SPELL_CAST_START' then\n            if spellID == 111570 then\n                local count = aura_env.ManageCounter('increase', 'DeathsGrasp')\n                aura_env.Warning('DeathsGrasp', count)\n                aura_env.StartCD('DeathsGrasp', 34)\n                aura_env.StartCD('ShadowShiv', 12.5)\n                aura_env.TTS('Grip')\n            elseif spellID == 111775 then\n                local count = aura_env.ManageCounter('increase', 'ShadowShiv')\n                aura_env.Warning('ShadowShiv', count)\n                aura_env.StartCD('ShadowShiv', 12.5)\n            elseif spellID == 114262 then -- Phase 3\n                aura_env.Warning('Phase', 3)\n                aura_env.StartCD('DeathsGrasp', 9)\n                aura_env.StartCD('ShadowShiv', 20.5)\n            end\n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 111585 then\n                local count = aura_env.ManageCounter('increase', 'DarkBlaze')\n                aura_env.Warning('DarkBlaze', count)\n            end\n        elseif subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then\n            if spellID == 111628 and destGUID == WeakAuras.myGUID and aura_env.Antispam(spellID, 2) then\n                aura_env.Warning('DarkBlazeGTFO')\n            end\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_SAY' then -- Phase 2\n        if aura_env.IsEmote(msg, 'Phase2') then\n            aura_env.Warning('Phase', 2)\n            aura_env.StopCD('ShadowShiv')\n            aura_env.StopCD('DeathsGrasp')\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        aura_env.StartCD('ShadowShiv', 12)\n        aura_env.StartCD('DeathsGrasp', 30)\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
