["translateType"] = "spiral",
["duration"] = "0.2",
["colorB"] = 1,
["colorG"] = 1,
["use_translate"] = true,
["type"] = "none",
["easeType"] = "none",
["translateFunc"] = "function(progress, startX, startY, deltaX, deltaY)\n    local angle = progress * 2 * math.pi\n    return startX + (progress * deltaX * math.cos(angle)), startY + (progress * deltaY * math.sin(angle))\nend\n",
["preset"] = "bounceDecay",
["alpha"] = 0,
["colorA"] = 1,
["y"] = 10,
["x"] = 10,
["duration_type"] = "seconds",
["easeStrength"] = 3,
["scaley"] = 1,
["rotate"] = 0,
["colorR"] = 1,
["scalex"] = 1,
},
["main"] = {
["colorR"] = 1,
["duration"] = "0.4",
["colorA"] = 1,
["colorG"] = 0.27058824896812,
["use_translate"] = true,
["duration_type"] = "seconds",
["type"] = "none",
["colorType"] = "pulseColor",
["easeType"] = "none",
["translateFunc"] = "function(progress, startX, startY, deltaX, deltaY)\n    local prog\n    if(progress < 0.25) then\n        prog = progress * 4\n    elseif(progress < .75) then\n        prog = 2 - (progress * 4)\n    else\n        prog = (progress - 1) * 4\n    end\n    return startX + (prog * deltaX), startY + (prog * deltaY)\nend\n",
["scaley"] = 1,
["alpha"] = 0,
["easeStrength"] = 3,
["y"] = 0,
["x"] = 5,
["colorB"] = 0,
["use_color"] = false,
["colorFunc"] = "function(progress, r1, g1, b1, a1, r2, g2, b2, a2)\n    local angle = (progress * 2 * math.pi) - (math.pi / 2)\n    local newProgress = ((math.sin(angle) + 1)/2);\n    return r1 + (newProgress * (r2 - r1)),\n         g1 + (newProgress * (g2 - g1)),\n         b1 + (newProgress * (b2 - b1)),\n         a1 + (newProgress * (a2 - a1))\nend\n",
["rotate"] = 0,
["translateType"] = "shake",
["scalex"] = 1,
},
