["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'Recklessness'\n\nlocal name, icon = C_Spell.GetSpellName(125873), C_Spell.GetSpellTexture(125873)\n\nlocal options = {\n    warningText = \"%icon @cffff8b17%name@r %icon\",\n    tssLine = Merfin:L('Burst the boss')\n}\n\naura_env.MRT = function()\n    local event = 'RECKLESNESS_' .. aura_env.count\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID    = ID,\n            name  = name,\n            icon  = icon,\n    }, options)\nend",
["do_custom"] = true,
},
},
