["init"] = {
["custom"] = "local SpeakText = C_VoiceChat.SpeakText\n\nlocal cfg = aura_env.config.options\n\nif cfg.testSound then\n    local text = cfg.testText\n    local voiceID = cfg.voiceID\n    local destination = Enum.VoiceTtsDestination.LocalPlayback\n    local speed = cfg.voiceRate\n    local volume = cfg.volume\n    \n    print(text, voiceID, destination, speed, volume)\n    \n    C_VoiceChat.SpeakText(voiceID, text, destination, speed, volume)\nend",
