["finish"] = {
},
["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'FieldExplodeSoon'\n\nlocal name, icon = Merfin:L('Explosion Soon'), 651087\n\nlocal options = {\n    warningText = \"@cffff4040%upper:name@r\",\n    ttsLine = Merfin:L('Explosion Soon'),\n}\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.Synch = function(GUID)\n    WeakAuras.ScanEvents('MERFIN_SYNCH', 'RAID', nil, 'MERF_NOTE_SYNCH', GUID) \nend\n\naura_env.happenedOnce = {}\naura_env.savedGUIDs = {}\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["event"] = "Health",
["unit"] = "player",
["debuffType"] = "HELPFUL",
["custom"] = "function(event, ...)\n    if event == 'MERF_NOTE_SYNCH' then\n        local guid = ...\n        if not aura_env.savedGUIDs[guid] then\n            aura_env.happenedOnce[guid] = true\n            aura_env.savedGUIDs[guid] = true\n            aura_env.count = (aura_env.count or 0) + 1\n            GMRT.F.Note_Timer('FIELD_' .. aura_env.count)\n            aura_env.SendWarning()\n        end\n    end\n    \n    if event == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.savedGUIDs = {}\n        aura_env.happenedOnce = {}\n        return\n    end\n    \n    if event ~= 'UNIT_HEALTH' then return end\n    local unit = ...\n    if not unit or not UnitExists(unit) then return end\n    \n    if not unit:find(\"^nameplate\") then return end\n    \n    local guid = UnitGUID(unit)\n    if not guid then return end\n    \n    local type, _, _, _, _, npcID = strsplit(\"-\", guid)\n    npcID = tonumber(npcID)\n    \n    if npcID ~= 62847 then return end\n    aura_env.happenedOnce = aura_env.happenedOnce or {}\n    \n    if aura_env.happenedOnce[guid] then return end\n    \n    local health = UnitHealth(unit)\n    local maxHealth = UnitHealthMax(unit)\n    \n    if maxHealth == 0 then return end\n    \n    local percent = (health / maxHealth) * 100\n    \n    if percent <= 10 then\n        aura_env.happenedOnce[guid] = true\n        aura_env.Synch(guid)\n    end\nend",
