["[DP] Cooldowns"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["authorOptions"] = {
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "local UnitIsGroupLeader, UnitIsGroupAssistant, UnitGroupRolesAssigned = UnitIsGroupLeader, UnitIsGroupAssistant, UnitGroupRolesAssigned\nlocal L, stformat = GetLocale(), string.format\n\nlocal roleIcons = {\n    TANK   = '|A:groupfinder-icon-role-large-tank:14:14:0:0|a',\n    DPS    = '|A:groupfinder-icon-role-large-dps:14:14:0:0|a',\n    HEALER = '|A:groupfinder-icon-role-large-heal:16:16:0:0|a',\n}\nlocal roleToIndex = { DAMAGER = 1, TANK = 2, HEALER = 3 }\nlocal extraIcons = { INTERRUPT = \"|TInterface\\\\EncounterJournal\\\\UI-EJ-Icons.blp:14:14:0:0:255:66:198:214:7:27|t\" }\n\nlocal function GetCooldownName(cooldown, config)\n    local name = (config.enabledCustom and config.customName) or cooldown.name\n    local icon = cooldown.roleIcon and (roleIcons[cooldown.roleIcon] or extraIcons[cooldown.roleIcon])\n    return name, icon and (icon .. ' ' .. name) or name\nend\n\nlocal defaultCountVA = {\n    enUS = { 1,  2  },\n    deDE = { 5,  6  },\n    frFR = { 7,  8  },\n    ruRU = { 9,  10 },\n    zhCN = { 11, 12 },\n    zhTW = { 11, 12 },\n}\n\nlocal function GetCountdownVA(options, config)\n    if config.pwCountdownVA > 1 then return config.pwCountdownVA - 1 end\n    local loc = defaultCountVA[L] or defaultCountVA.enUS\n    return (options and loc[options.prewarnCountVA or 1]) or 1\nend\n\nlocal function GetPrewarnTTStext(options, config)\n    if config.prewarnTTStext ~= '' then return config.prewarnTTStext end\n    return Merfin:L(options.prewarnTTStext)\nend\n\nlocal function GetReadyText(config, options, cooldown)\n    if options and options.readyText then return Merfin:L(options.readyText) end\n    return stformat('%s %s', cooldown.rawName:upper(), Merfin:L('INC.'))\nend\n\nlocal berserkOnlyShow, berserkShowOn = false, 60\nlocal playerRole = UnitGroupRolesAssigned('player')\nlocal registered, schedEmph, schedPrewarns, schedPrewarnTTS, schedReady = {}, {}, {}, {}, {}\nlocal schedBerserk\n\nlocal function IsPassThrough()\n    local o = aura_env.connectedConfig\n    return (UnitIsGroupLeader('player') or UnitIsGroupAssistant('player')) and o and o.default.enableRL\nend\n\nlocal function GetConfig(encounterID, cooldownID)\n    local o = aura_env.connectedConfig\n    local d, cd = o.default, o[encounterID][cooldownID]\n    return {\n        emphasizedBar = cd.emphasizedBar or d.emphasizedBar,\n        emphasizedOn  = (cd.emphasizedBar and cd.emphasizedOn) or (d.emphasizedBar and d.emphasizedOn),\n        enabledCustom = cd.enableCustomName, customName = cd.customName,\n        pwText = cd.pwText, pwTexture = cd.pwTexture, pwCountdown = cd.pwCountdown,\n        pwCountdownVA = cd.pwCountdownVA, cooldownBars = cd.cooldownBars, nameplateCD = cd.nameplateCD,\n        announceReady = cd.announceReady, readyText = cd.readyText,\n        prewarnTTS = cd.prewarnTTS, prewarnTTStext = cd.prewarnTTStext\n    }\nend\n\nlocal function IsEncounterEnabled(encounterID)\n    local o = aura_env.connectedConfig\n    return not o or (o[encounterID] and o[encounterID].enableCooldowns) or false\nend\n\nlocal function IsRoleEligible(encounterID, cooldownID)\n    if IsPassThrough() or playerRole == 'NONE' then return true end\n    local o = aura_env.connectedConfig\n    if not o or not o[encounterID] or not o[encounterID][cooldownID] then return true end\n    local elig = o[encounterID][cooldownID].enabledRole\n    return elig[roleToIndex[playerRole]]\nend\n\nlocal function IsCooldownEnabled(encounterID, cooldownID)\n    local o = aura_env.connectedConfig\n    if not o then return true end\n    if not o[encounterID] then print(\"MerfinDebug: couldn't find encounerID options: \", encounterID) return false end\n    if not o[encounterID][cooldownID] then print(\"MerfinDebug: couldn't find cooldown options: \", encounterID, cooldownID) return false end\n    return o[encounterID][cooldownID].enable\nend\n\nlocal function Schedule(store, after, event, encounterID, cooldown, ...)\n    if after and after <= 0 then\n        WeakAuras.ScanEvents(event, encounterID, cooldown, ...)\n        return\n    end\n    store[encounterID] = store[encounterID] or {}\n    local t, id, guid = store[encounterID], cooldown.ID, cooldown.GUID\n    if guid then\n        t[id] = t[id] or {}\n        t[id][guid] = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, after, event, encounterID, cooldown, ...)\n    else\n        t[id] = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, after, event, encounterID, cooldown, ...)\n    end\nend\n\nlocal function Unschedule(store, encounterID, cooldownID, GUID)\n    local enc, cd = store[encounterID], store[encounterID] and store[encounterID][cooldownID]\n    if not enc or not cd then return end\n    if GUID then\n        WeakAuras.timer:CancelTimer(cd[GUID]); cd[GUID] = nil; if not next(cd) then enc[cooldownID] = nil end\n    else\n        WeakAuras.timer:CancelTimer(cd); enc[cooldownID] = nil\n    end\n    if not next(enc) then store[encounterID] = nil end\nend\n\nlocal function ScheduleBerserk(delay, func) schedBerserk = C_Timer.NewTimer(delay, func) end\nlocal function UnscheduleBersek() if schedBerserk then schedBerserk:Cancel() end end\n\nlocal function ScheduleReady(encounterID, cooldown, readyText)\n    Schedule(schedReady, cooldown.expirationTime - GetTime(), 'MERFIN_CD_READY', encounterID, cooldown, readyText)\nend\nlocal function UnscheduleReady(encounterID, cooldownID, GUID)\n    Unschedule(schedReady, encounterID, cooldownID, GUID)\nend\n\nlocal function ScheduleEmphasizer(after, encounterID, cooldown, emphasizedOn)\n    Schedule(schedEmph, after, 'MERFIN_CD_EMPH_SHOW', encounterID, cooldown, emphasizedOn)\nend\nlocal function UnscheduleEmphasizer(encounterID, cooldownID, GUID)\n    Unschedule(schedEmph, encounterID, cooldownID, GUID)\nend\n\nlocal function SchedulePrewarning(after, encounterID, cooldown, config)\n    Schedule(schedPrewarns, after, 'MERFIN_PREWARNING_SHOW', encounterID, cooldown, config)\nend\nlocal function UnschedulePrewarning(encounterID, cooldownID, GUID)\n    Unschedule(schedPrewarns, encounterID, cooldownID, GUID)\nend\n\nlocal function SchedulePrewarnTTS(encounterID, cooldown, text)\n    local after = cooldown.expirationTime - GetTime() - 5\n    if after <= 0 then return end\n    schedPrewarnTTS[encounterID] = schedPrewarnTTS[encounterID] or {}\n    local t, id, guid = schedPrewarnTTS[encounterID], cooldown.ID, cooldown.GUID\n    if guid then\n        t[id] = t[id] or {}\n        t[id][guid] = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, after, 'MERFIN_TTS', text)\n    else\n        t[id] = WeakAuras.timer:ScheduleTimer(WeakAuras.ScanEvents, after, 'MERFIN_TTS', text)\n    end\nend\nlocal function UnschedulePrewarnTTS(encounterID, cooldownID, GUID)\n    Unschedule(schedPrewarnTTS, encounterID, cooldownID, GUID)\nend\n\nlocal function UnregisterCD(encounterID, cooldownID, GUID)\n    local enc = registered[encounterID]; if not enc or not enc[cooldownID] then return end\n    if GUID then enc[cooldownID][GUID] = nil; if not next(enc[cooldownID]) then enc[cooldownID] = nil end\n    else enc[cooldownID] = nil end\nend\n\nlocal function RegisterCD(encounterID, cooldown)\n    local id, guid = cooldown.ID, cooldown.GUID\n    registered[encounterID] = registered[encounterID] or {}\n    if guid then\n        registered[encounterID][id] = registered[encounterID][id] or {}\n        registered[encounterID][id][guid] = cooldown.expirationTime\n    else\n        registered[encounterID][id] = cooldown.expirationTime\n    end\nend\n\naura_env.OnHandler = {}\n\nlocal function CancelAll(store, encID)\n    local enc = store[encID]; if not enc then return end\n    for cdID, v in pairs(enc) do\n        if type(v) == 'table' then\n            for GUID in pairs(v) do Unschedule(store, encID, cdID, GUID) end\n        else\n            Unschedule(store, encID, cdID)\n        end\n    end\nend\n\nlocal function WipeAllEncounters()\n    local currEnc, currEncID = WeakAuras.CurrentEncounter, WeakAuras.CurrentEncounter and tostring(WeakAuras.CurrentEncounter.ID)\n    for encID in pairs(schedEmph) do\n        if not currEncID or currEncID ~= encID then\n            CancelAll(schedEmph, encID)\n            CancelAll(schedPrewarns, encID)\n        end\n    end\nend\n\naura_env.OnHandler.STATUS  = function() WipeAllEncounters() end\naura_env.OnHandler.OPTIONS = function() WipeAllEncounters() end\n\nlocal function HideReady(encounterID, cooldownID, GUID)\n    UnscheduleReady(encounterID, cooldownID, GUID)\n    WeakAuras.ScanEvents('MERFIN_READY_HIDE', encounterID, { ID = cooldownID, GUID = GUID })\nend\nlocal function HidePrewarning(encounterID, cooldownID, GUID)\n    UnschedulePrewarning(encounterID, cooldownID, GUID)\n    WeakAuras.ScanEvents('MERFIN_PREWARNING_HIDE', encounterID, { ID = cooldownID, GUID = GUID })\nend\nlocal function HideEmphasize(encounterID, cooldownID, GUID)\n    UnscheduleEmphasizer(encounterID, cooldownID, GUID)\n    WeakAuras.ScanEvents('MERFIN_CD_EMPH_HIDE', encounterID, { ID = cooldownID, GUID = GUID })\nend\n\nlocal function HideCooldown(encounterID, cooldownID, GUID)\n    UnregisterCD(encounterID, cooldownID, GUID)\n    HideEmphasize(encounterID, cooldownID, GUID)\n    HidePrewarning(encounterID, cooldownID, GUID)\n    UnschedulePrewarnTTS(encounterID, cooldownID, GUID)\n    HideReady(encounterID, cooldownID, GUID)\n    if cooldownID == 'Berserk' then UnscheduleBersek() end\n    WeakAuras.ScanEvents('MERFIN_CD_HIDE', encounterID, { ID = cooldownID, GUID = GUID })\nend\n\naura_env.OnHandler.ENCOUNTER_END = function(encounterID)\n    encounterID = tostring(encounterID)\n    local enc = registered[encounterID]; if not enc then return end\n    for cdID, data in pairs(enc) do\n        if type(data) == 'table' then\n            for GUID in pairs(data) do HideCooldown(encounterID, cdID, GUID) end\n        else\n            HideCooldown(encounterID, cdID)\n        end\n    end\n    if not next(enc) then registered[encounterID] = nil end\n    return true\nend\n\naura_env.OnHandler.MERFIN_CD_START = function(encounterID, cooldown, options)\n    if not cooldown then return end\n    HideEmphasize(encounterID, cooldown.ID, cooldown.GUID)\n    HidePrewarning(encounterID, cooldown.ID, cooldown.GUID)\n    UnschedulePrewarnTTS(encounterID, cooldown.ID, cooldown.GUID)\n    HideReady(encounterID, cooldown.ID, cooldown.GUID)\n    if cooldown.ID == 'Berserk' then UnscheduleBersek() end\n    \n    if not encounterID:find('Trash') then\n        local currEnc = WeakAuras.CurrentEncounter\n        if encounterID ~= (currEnc and tostring(currEnc.id)) then return end\n    end\n    \n    local config = GetConfig(encounterID, cooldown.ID)\n    local rawName, name = GetCooldownName(cooldown, config)\n    cooldown.rawName, cooldown.name, cooldown.icon = rawName, name, cooldown.icon\n    \n    if not cooldown.ignorePrew then\n        cooldown.countdown = config.pwCountdown\n        cooldown.voiceActorIndex = GetCountdownVA(options, config)\n        local remaining = cooldown.expirationTime - GetTime()\n        SchedulePrewarning(remaining - 5, encounterID, cooldown, config)\n    end\n    \n    if config.prewarnTTS then\n        local text = GetPrewarnTTStext(options, config)\n        SchedulePrewarnTTS(encounterID, cooldown, text)\n    end\n    \n    if config.announceReady then\n        local readyText = GetReadyText(config, options, cooldown)\n        ScheduleReady(encounterID, cooldown, readyText)\n    end\n    \n    if cooldown.special then return false end\n    \n    WeakAuras.ScanEvents('MERFIN_CD_SHOW_WIDGET', encounterID, cooldown)\n    RegisterCD(encounterID, cooldown)\n    \n    if not IsEncounterEnabled(encounterID) then return false end\n    if not IsRoleEligible(encounterID, cooldown.ID) then return false end\n    if not IsCooldownEnabled(encounterID, cooldown.ID) then return false end\n    \n    local emphasizedIn = config.emphasizedBar and (cooldown.duration - config.emphasizedOn)\n    \n    if not config.emphasizedBar or emphasizedIn > 0 then\n        if config.cooldownBars[1] then\n            if cooldown.ID == 'Berserk' and berserkOnlyShow then\n                local showIn = (cooldown.expirationTime - GetTime()) - berserkShowOn\n                ScheduleBerserk(showIn, function() WeakAuras.ScanEvents('MERFIN_CD_SHOW', encounterID, cooldown) end)\n            else\n                WeakAuras.ScanEvents('MERFIN_CD_SHOW', encounterID, cooldown)\n            end\n        end\n        for i = 2, 6 do\n            if config.cooldownBars[i] then\n                if cooldown.ID == 'Berserk' and berserkOnlyShow then\n                    local showIn = (cooldown.expirationTime - GetTime()) - berserkShowOn\n                    ScheduleBerserk(showIn, function() WeakAuras.ScanEvents('MERFIN_CD_SHOW_SPECIAL', i - 1, encounterID, cooldown) end)\n                else\n                    WeakAuras.ScanEvents('MERFIN_CD_SHOW_SPECIAL', i - 1, encounterID, cooldown)\n                end\n            end\n        end\n    end\n    \n    WeakAuras.ScanEvents('MERFIN_CD_SHOW_WIDGET', encounterID, cooldown)\n    \n    if config.emphasizedBar then\n        if emphasizedIn > 0 then\n            ScheduleEmphasizer(emphasizedIn, encounterID, cooldown, config.emphasizedOn)\n        else\n            WeakAuras.ScanEvents('MERFIN_CD_EMPH_SHOW', encounterID, cooldown)\n        end\n    end\n    \n    if config.nameplateCD then\n        WeakAuras.ScanEvents('MERFIN_CD_NAMEPLATE_SHOW', encounterID, cooldown)\n    end\nend\n\naura_env.OnHandler.MERFIN_CD_STOP = function(encounterID, cooldown)\n    if not encounterID or not cooldown or not cooldown.ID then return end\n    local enc = registered[encounterID]; if not enc then return end\n    local cd = enc[cooldown.ID]; if not cd then return end\n    if cooldown.GUID then\n        if not cd[cooldown.GUID] then return end\n        HideCooldown(encounterID, cooldown.ID, cooldown.GUID)\n        return true\n    end\n    if type(cd) ~= 'table' then\n        HideCooldown(encounterID, cooldown.ID)\n        return true\n    end\n    for GUID in pairs(cd) do HideCooldown(encounterID, cooldown.ID, GUID) end\nend\n\naura_env.OnHandler.PLAYER_ROLES_ASSIGNED = function()\n    playerRole = UnitGroupRolesAssigned('player')\nend\n\naura_env.OnHandler.MERFIN_CD_CONFIG = function(sentConfig)\n    if not sentConfig then return end\n    aura_env.connectedConfig = sentConfig\n    berserkOnlyShow, berserkShowOn = sentConfig.default.berserkOnlyShow, sentConfig.default.berserkShowOn\nend\n\naura_env.OnHandler.WA_DELAYED_PLAYER_ENTERING_WORLD = function()\n    WeakAuras.ScanEvents('RAID_CONFIG_REQUEST')\nend",
["do_custom"] = true,
},
