["init"] = {
["custom"] = "local encounterID = '1431'\nlocal ID = 'ImplacableStrike'\n\nlocal name, icon = C_Spell.GetSpellName(120672), C_Spell.GetSpellTexture(120672)\n\nlocal options = {\n    warningText = '%upper:name',\n    ttsLine = Merfin:L('Frontal')\n}\n\naura_env.StopCD = function(ID)\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show = true,\n            autoHide = autoHide,\n            duration = duration,\n            expirationTime = duration + GetTime(),\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID = ID,\n            name = name,\n            icon = icon,\n            count = aura_env.count\n    }, options)\nend",
