["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 120672 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning()\n                aura_env.StopCD('ImplacableStrike')\n                aura_env.StopCD('RandomAbility')\n            end\n        end\n        \n    elseif e == 'SPECIAL_CAST_CD' then\n        local ID, duration = ...\n        \n        if ID == 'ImplacableStrike' then\n            aura_env.StartCD(duration)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
