["finish"] = {
},
["init"] = {
["custom"] = "local UnitGroupRolesAssigned, stformat, L = UnitGroupRolesAssigned, string.format, GetLocale()\n\nlocal roleIcons = {\n    TANK   = '|A:groupfinder-icon-role-large-tank:14:14:0:0|a',\n    DPS    = '|A:groupfinder-icon-role-large-dps:14:14:0:0|a',\n    HEALER = '|A:groupfinder-icon-role-large-heal:16:16:0:0|a',\n}\n\nlocal roleToIndex = { DAMAGER = 1, TANK = 2, HEALER = 3 }\n\nlocal function GetIconCropped(warning)\n    local size = 14\n    local iconID = warning.icon\n    if not iconID then return end\n    \n    if warning.isIconAtlas then\n        return CreateAtlasMarkup(iconID, size, size)\n    else\n        return (\"|T%d:%d:%d:0:0|t\"):format(iconID, size, size)\n    end\nend\n\nlocal playerRole = UnitGroupRolesAssigned('player')\n\nlocal function GetWarningValue(options, key)\n    local v = options[key]\n    return Merfin:L(v) or v\nend\n\nlocal function GetFormatString(config, warning, options)\n    local cfgText = config.formatString ~= \"\" and config.formatString\n    local s = cfgText or GetWarningValue(options, 'warningText')\n    \n    s = s:gsub(\"@c(%x%x%x%x%x%x%x%x)(.-)@r\", function(color, text)\n            return \"|c\"..color:upper()..text..\"|r\"\n    end)\n    \n    s = s:gsub(\"@c(%x%x%x%x%x%x%x%x)%%upper:(%w+)@r\", function(color, key)\n            local val = warning[key]; if val == nil then return \"\" end\n            return \"|c\"..color:upper()..tostring(val):upper()..\"|r\"\n    end)\n    \n    s = s:gsub(\"@c(%x%x%x%x%x%x%x%x)%%(%w+)@r\", function(color, key)\n            local val = warning[key]; if val == nil then return \"\" end\n            return \"|c\"..color:upper()..tostring(val)..\"|r\"\n    end)\n    \n    s = s:gsub(\"%%upper:(%w+)\", function(key)\n            local val = warning[key]; if val == nil then return \"\" end\n            return tostring(val):upper()\n    end)\n    \n    s = s:gsub(\"%%(%w+)\", function(key)\n            local val = warning[key]; if val == nil then return \"\" end\n            return tostring(val)\n    end)\n    \n    return s\nend\n\nlocal function GetConfig(encounterID, warning)\n    local cfg = aura_env.connectedConfig\n    local w = cfg[encounterID][warning.ID]\n    return {\n        littleWarning    = w.littleWarning,\n        bigWarning       = w.bigWarning,\n        soundAlertEnable = w.soundAlertEnable,\n        soundAlertType   = w.soundAlertType,\n        ttsEnable        = w.ttsEnable,\n        ttsLine          = w.ttsLine,\n        formatString     = w.formatString,\n    }\nend\n\nlocal function IsEncounterEnabled(encounterID)\n    local cfg = aura_env.connectedConfig\n    return not cfg or (cfg[encounterID] and cfg[encounterID].enableCooldowns) or false\nend\n\nlocal function IsRoleEligible(encounterID, warningID)\n    if playerRole == 'NONE' then return true end\n    local cfg = aura_env.connectedConfig\n    if not cfg or not cfg[encounterID] or not cfg[encounterID][warningID] then return true end\n    return cfg[encounterID][warningID].enabledRole[roleToIndex[playerRole]]\nend\n\nlocal function IsWarningEligible(encounterID, warning)\n    return IsEncounterEnabled(encounterID) and IsRoleEligible(encounterID, warning.ID)\nend\n\naura_env.OnHandler = {}\n\naura_env.OnHandler.STATUS  = function() end\naura_env.OnHandler.OPTIONS = function() end\n\naura_env.OnHandler.PLAYER_ROLES_ASSIGNED = function()\n    playerRole = UnitGroupRolesAssigned('player')\nend\n\naura_env.OnHandler.MERFIN_WARNING = function(encounterID, warning, options)\n    if not warning or not IsWarningEligible(encounterID, warning) then return end\n    \n    local config = GetConfig(encounterID, warning)\n    warning.icon        = GetIconCropped(warning)\n    warning.displayText = GetFormatString(config, warning, options)\n    warning.config      = config\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING_SHOW', warning)\n    \n    if config.soundAlertEnable then\n        WeakAuras.ScanEvents('MERFIN_SOUND', config.soundAlertType)\n    end\n    \n    if config.ttsEnable then\n        local text = (config.ttsLine and config.ttsLine ~= '' and config.ttsLine) or GetWarningValue(options, 'ttsLine') or warning.name\n        WeakAuras.ScanEvents('MERFIN_TTS', text)\n    end\nend\n\naura_env.OnHandler.MERFIN_WARNING_CONFIG = function(sentConfig)\n    if not sentConfig then return end\n    aura_env.connectedConfig = sentConfig\nend\n\naura_env.OnHandler.WA_DELAYED_PLAYER_ENTERING_WORLD = function()\n    WeakAuras.ScanEvents('RAID_CONFIG_REQUEST')\nend\n\n\n\n",
["do_custom"] = true,
},
},
