["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'WindBomb'\n\nlocal name, icon = C_Spell.GetSpellName(131830), C_Spell.GetSpellTexture(131830)\n\nlocal options = {\n    ['WindBomb'] = {\n        warningText = \"%icon @cffff8b17%name@r » %destName %icon\",\n    },\n    ['WindBombGTFO'] = {\n        warningText = string.format(Merfin:L('GTFO'), name:upper()),\n    }\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = destName,\n    }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then \n        aura_env.scheduler:Cancel() \n    end\n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if spellID == 131830 and not aura_env.targets[destGUID] then\n            if not aura_env.IsSpam(3) then\n                aura_env.Schedule('WIND_BOMB_TARGETS', 0.5)\n            end\n            \n            aura_env.targets[destGUID] = destName\n            \n            if destGUID == WeakAuras.myGUID then\n                aura_env.SendWarning('WindBombGTFO')\n            end\n        end\n        \n    elseif e == 'WIND_BOMB_TARGETS' then\n        aura_env.count = aura_env.count + 1\n        \n        local names = {}\n        for _, name in pairs(aura_env.targets) do\n            table.insert(names, WA_ClassColorName(name))\n        end\n        local destNames = table.concat(names, ', ')\n        \n        aura_env.SendWarning('WindBomb', destNames)\n        aura_env.targets = {}\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.targets = {}\n    end\nend",
