["trigger"] = {
["type"] = "custom",
["custom_type"] = "stateupdate",
["customVariables"] = "{\n    damage = {\n        display = 'Damage Taking',\n        type = 'number',\n    }\n}",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["custom"] = "function(a, e,_, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellId,_,_, amount)\n    \n    if subEvent == 'SPELL_AURA_APPLIED' then\n        if spellId == 89421 then\n            aura_env.expTime = 60 + GetTime()\n            a[destGUID] = {\n                show = true,\n                changed = true,\n                progressType = 'timed',\n                duration = 60,\n                expirationTime = aura_env.expTime,\n                autoHide = true,\n                unit = destName,\n                damage = aura_env.GetWrackInfo(destName),\n            }\n            return true\n            \n            \n        elseif spellId == 89435 then\n            local curTime = GetTime()\n            local duration = aura_env.expTime and (aura_env.expTime - curTime) or 60\n            a[destGUID] = {\n                show = true,\n                changed = true,\n                progressType = 'timed',\n                duration = duration,\n                expirationTime = curTime + duration,\n                autoHide = true,\n                unit = destName,\n                damage = aura_env.GetWrackInfo(destName),\n            }\n            return true\n            \n        end\n    elseif subEvent == 'SPELL_PERIODIC_DAMAGE' then\n        if spellId == 89421 or spellId == 89435 then\n            if not a[destGUID] then return end\n            a[destGUID].damage = aura_env.GetWrackInfo(destName)\n            a[destGUID].show = amount > 0\n            a[destGUID].changed = true\n            return true\n        end\n        \n    elseif subEvent == 'SPELL_AURA_REMOVED' then\n        if spellId == 89421 or spellId == 89435 then\n            if not a[destGUID] then return end\n            a[destGUID].show = false\n            a[destGUID].changed = true\n            return true\n        end\n    end\nend",
