["parent"] = "[MerfinDung] 姓名板CD",
["adjustedMax"] = "",
["customText"] = "",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["cooldownEdge"] = false,
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["duration"] = "2",
["subeventPrefix"] = "SPELL",
["destUnit"] = "target",
["spellName"] = {
"Battle Stance",
},
["debuffType"] = "HELPFUL",
["names"] = {
},
["type"] = "custom",
["use_destNpcId"] = false,
["unevent"] = "timed",
["use_unit"] = true,
["custom_type"] = "stateupdate",
["event"] = "Combat Log",
["spellIds"] = {
},
["events"] = "STATUS UNIT_THREAT_LIST_UPDATE RELOE_SPELLCD_STATE_CLEAN RELOE_SPELLCD_STATE_UPDATE UNIT_SPELLCAST_SUCCEEDED:nameplate UNIT_SPELLCAST_START:nameplate CLEU:SPELL_CAST_SUCCESS:SPELL_INTERRUPT:SPELL_CAST_START NAME_PLATE_UNIT_ADDED NAME_PLATE_UNIT_REMOVED RELOE_SPELLCD_DESYNCH",
["use_spellName"] = true,
["custom"] = "function(states, e, ...)\n    local function handleStatusEvent()\n        for i = 1, 40 do\n            local u = \"nameplate\" .. i\n            if UnitExists(u) then\n                local G = UnitGUID(u)\n                aura_env.nameplates[u] = G\n                aura_env.guids[G] = u\n            end\n        end\n    end\n    \n    local function handleNamePlateUnitAddedEvent(u)\n        if not u then return false end\n        \n        local G = UnitGUID(u)\n        aura_env.nameplates[u] = G\n        aura_env.guids[G] = u\n        \n        local updatestate = false\n        for k, state in pairs(aura_env.temp) do\n            if state.GUID == G then\n                if UnitAffectingCombat(u) then\n                    state.unit = u\n                    state.show = true\n                    state.changed = true\n                    states[k] = state\n                    aura_env.temp[k] = nil\n                else\n                    aura_env.units[G] = nil\n                    states[k] = nil\n                    aura_env.temp[k] = nil\n                end\n                updatestate = true\n            end\n        end\n        return updatestate\n    end\n    \n    local function handleNamePlateUnitRemovedEvent(u)\n        if not u then return false end\n        \n        local G = UnitGUID(u)\n        if not G then return false end\n        \n        aura_env.nameplates[u] = nil\n        aura_env.guids[G] = nil\n        \n        local updatestate = false\n        for k, state in pairs(states) do\n            if state.GUID == G then\n                aura_env.temp[k] = state\n                state.show = false\n                state.changed = true\n                updatestate = true\n            end\n        end\n        return updatestate\n    end\n    \n    local function handleSpellCdDesynchEvent(spell, spellID, GUID, desynch, id)\n        if aura_env.id ~= id then return end\n        \n        local now = GetTime()\n        for k, v in pairs(states) do\n            if v.spellID == spellID and v.GUID ~= GUID and now >= v.expirationTime - desynch then\n                WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, v.GUID, spellID, desynch, false, false, 0, v.GUID .. spellID)\n            end\n        end\n        \n        for k, v in pairs(aura_env.temp) do\n            if v.spellID == spellID and v.GUID ~= GUID and now >= v.expirationTime - desynch then\n                v.duration = desynch\n                v.expirationTime = GetTime() + desynch\n            end\n        end\n    end\n    \n    local function handleSpellCdStateCleanEvent(key, expires, id)\n        if aura_env.id ~= id then return false end\n        \n        local state = states[key]\n        local temp = aura_env.temp[key]\n        if (state and state.expirationTime == expires and state.expirationTime < GetTime()) or\n        (temp and temp.expirationTime < GetTime()) then\n            states[key] = nil\n            aura_env.temp[key] = nil\n            return true\n        end\n        return false\n    end\n    \n    local function handleSpellCdStateUpdateEvent(spell, GUID, spellID, duration, combat, type, count, key, id)\n        if aura_env.id ~= id or not spell or not duration then return false end\n        \n        local current = GetTime()\n        local icon = spell.overwrite ~= 0 and aura_env.GetSpellIcon(spell.overwrite) or aura_env.GetSpellIcon(spellID)\n        \n        local state = states[key]\n        local last = aura_env.last[GUID]\n        if (combat and not state) or not last or current > last[1] or icon ~= last[2] or spellID ~= last[3] then\n            if duration <= 0 then\n                states[key] = nil\n                aura_env.temp[key] = nil\n                return true\n            end\n            \n            local data = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = duration,\n                spellID = spellID,\n                expirationTime = current + duration,\n                icon = icon,\n                hide = spell.hide,\n                autoHide = false,\n                GUID = GUID,\n                count = count,\n                unit = aura_env.guids[GUID],\n                spellId = spellID,\n            }\n            \n            if spell.hide == 0 or spell.loop then\n                data.autoHide = true\n            end\n            \n            aura_env.last[GUID] = {current, icon, spellID}\n            \n            if aura_env.guids[GUID] then\n                states[key] = data\n            else\n                aura_env.temp[key] = data\n            end\n            \n            if spell.loop and not combat then\n                C_Timer.After(duration, function()\n                        if aura_env.guids[GUID] then\n                            WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, GUID, spellID, duration, combat, type, count, key)\n                        end\n                end)\n            end\n            \n            return true\n        end\n        return false\n    end\n    \n    local function handleCombatLogEvent(unit, subevent, spellIDUNIT, sourceGUID, sourceName, sflags, _, destGUID, _, dflags, _, spellIDCLEU, _, _, spellIDINT)\n        if sourceGUID and sourceName then\n            if spellIDINT and bit.band(dflags, COMBATLOG_OBJECT_CONTROL_PLAYER) == 0 then\n                aura_env.oninterrupt(spellIDINT, destGUID)\n            elseif subevent == \"SPELL_CAST_SUCCESS\" and bit.band(sflags, COMBATLOG_OBJECT_CONTROL_PLAYER) == 0 and bit.band(sflags, COMBATLOG_OBJECT_REACTION_HOSTILE) > 0 then\n                aura_env.onsuccess(spellIDCLEU, sourceGUID, sourceName, true)\n            elseif subevent == \"SPELL_CAST_START\" and bit.band(sflags, COMBATLOG_OBJECT_CONTROL_PLAYER) == 0 and bit.band(sflags, COMBATLOG_OBJECT_REACTION_HOSTILE) > 0 then\n                aura_env.onstart(spellIDCLEU, sourceGUID)\n            end\n        elseif unit then\n            local GUID = UnitGUID(unit)\n            if GUID then\n                local creature, _, _, _, _, npcID = strsplit(\"-\", GUID)\n                if npcID and (creature == \"Creature\" or creature == \"Vehicle\") then\n                    if e == \"UNIT_THREAT_LIST_UPDATE\" then\n                        if UnitAffectingCombat(unit) and not aura_env.units[GUID] then\n                            aura_env.units[GUID] = {GUID = GUID, time = GetTime()}\n                            for k, _ in pairs(aura_env.spells) do\n                                if aura_env.spells[k].oncombat and aura_env.spells[k].npcID and string.find(aura_env.spells[k].npcID, npcID) then\n                                    aura_env.oncombat(k, GUID)\n                                end\n                            end\n                        end\n                    elseif e == \"UNIT_SPELLCAST_SUCCEEDED\" and spellIDUNIT then\n                        aura_env.onsuccess(spellIDUNIT, GUID, UnitName(unit), false)\n                    elseif e == \"UNIT_SPELLCAST_START\" and spellIDUNIT then\n                        aura_env.onstart(spellIDUNIT, GUID)\n                    end\n                end\n            end\n        end\n    end\n    \n    -- Main event handler\n    if e == \"STATUS\" then\n        handleStatusEvent()\n    elseif e == \"NAME_PLATE_UNIT_ADDED\" then\n        return handleNamePlateUnitAddedEvent(...)\n    elseif e == \"NAME_PLATE_UNIT_REMOVED\" then\n        return handleNamePlateUnitRemovedEvent(...)\n    elseif e == \"RELOE_SPELLCD_DESYNCH\" then\n        handleSpellCdDesynchEvent(...)\n    elseif e == \"RELOE_SPELLCD_STATE_CLEAN\" then\n        return handleSpellCdStateCleanEvent(...)\n    elseif e == \"RELOE_SPELLCD_STATE_UPDATE\" then\n        return handleSpellCdStateUpdateEvent(...)\n    else\n        handleCombatLogEvent(...)\n    end\nend",
