["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-- Initialize aura_env properties\naura_env.IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\naura_env.spells = {}\naura_env.nameplates = {}\naura_env.guids = {}\naura_env.temp = {}\naura_env.units = {}\naura_env.progtime = {}\naura_env.proglast = {}\naura_env.last = {}\naura_env.GetSpellInfo = WeakAuras.IsRetail() and C_Spell.GetSpellInfo or GetSpellInfo\n\naura_env.GetSpellIcon = function(spellId)\n    if WeakAuras.IsRetail() then\n        return C_Spell.GetSpellInfo(spellId).iconID\n    end\n    return select(3, GetSpellInfo(spellId))\nend\n\n-- Convert spells from custom options\naura_env.OnInit = function()\n    \n    for _, v in ipairs(aura_env.config.spells) do\n        \n        local difficultyCheck = v.difficulty == (aura_env.IsHeroic and 2 or 1) or v.difficulty == 3\n        \n        if v.spellID ~= 0 and v.active and difficultyCheck then\n            local spell = {\n                active = v.active,\n                icon = select(3, aura_env.GetSpellInfo(v.spellID)),\n                duration = v.duration,\n                intduration = v.intduration,\n                onstart = v.casttype == 1,\n                onsuccess = v.casttype == 2,\n                tank = v.tank,\n                heal = v.heal,\n                mdps = v.mdps,\n                rdps = v.rdps,\n                hide = v.hideafter,\n                overwrite = v.overwrite,\n                npcID = v.npcID,\n                oncombat = v.oncombat,\n                combattimer = v.combattimer,\n                loop = v.loop,\n                progressive = v.progressive,\n                repeating = v.repeating,\n                other = 0,\n                npcIDoffset = v.npcIDoffset,\n                offsetnum = v.offsetnum,\n                offset = {},\n                desynch = v.desynch,\n            }\n            \n            -- Parse npcIDoffset and offsetnum\n            if v.npcIDoffset ~= \"\" and v.offsetnum ~= \"\" then\n                local i = 1\n                while true do\n                    local timer = tonumber(select(i, strsplit(\" \", v.offsetnum)))\n                    local npcID = select(i, strsplit(\" \", v.npcIDoffset))\n                    if not timer or not npcID then break end\n                    spell.offset[npcID] = timer\n                    i = i + 1\n                end\n            end\n            \n            -- Parse spelltrigger and spelltimer\n            if v.spelltrigger ~= \"0\" and v.spelltrigger ~= \"\" then\n                spell.other = {}\n                local i = 1\n                while true do\n                    local timer = tonumber(select(i, strsplit(\" \", v.spelltimer)))\n                    local sid = tonumber(select(i, strsplit(\" \", v.spelltrigger)))\n                    if not timer or not sid then break end\n                    spell.other[sid] = timer\n                    i = i + 1\n                end\n            end\n            \n            -- Parse progressive timers\n            if v.progressive ~= \"0\" and v.progressive ~= \"\" then\n                spell.progressive = {}\n                local i = 1\n                while true do\n                    local timer = tonumber(select(i, strsplit(\" \", v.progressive)))\n                    if not timer then break end\n                    table.insert(spell.progressive, timer)\n                    i = i + 1\n                end\n            end\n            \n            aura_env.spells[v.spellID] = spell\n        end\n    end\nend\n\naura_env.OnInit()\n\n-- Role check function\naura_env.rolecheck = function(spell)\n    return true\nend\n\n-- Boss unit check\naura_env.bossunit = function(GUID)\n    for i = 1, 10 do\n        if not UnitExists(\"boss\" .. i) then break end\n        if GUID == UnitGUID(\"boss\" .. i) then\n            return true\n        end\n    end\n    return false\nend\n\n-- Spell interrupt handler\naura_env.oninterrupt = function(spellID, GUID)\n    local spell, key = aura_env.spells[spellID], GUID .. spellID\n    if spell and spell.intduration > 0 and aura_env.rolecheck(spell) and ((not aura_env.last[key]) or GetTime() > aura_env.last[key] + 0.1) then\n        aura_env.last[key] = GetTime()\n        WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, GUID, spellID, spell.intduration, false, false, 0, key, aura_env.id)\n    end\nend\n\n-- Spell cast start handler\naura_env.onstart = function(spellID, GUID, name)\n    local spell, key = aura_env.spells[spellID], GUID .. spellID\n    local npcID = select(6, strsplit(\"-\", GUID))\n    if spell and spell.onstart and ((not aura_env.last[key]) or GetTime() > aura_env.last[key] + 0.1) then\n        aura_env.last[key] = GetTime()\n        local count, duration = -1, aura_env.rolecheck(spell) and spell.duration\n        if type(spell.other) == \"table\" then\n            for k, v in pairs(spell.other) do\n                local spello = aura_env.spells[k] or spell\n                if aura_env.spells[k] and aura_env.spells[k].active then\n                    WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spello, GUID, k, v, false, false, 0, GUID .. k, aura_env.id)\n                end\n            end\n        end\n        if type(spell.progressive) == \"table\" then\n            duration, count = aura_env.getprogressivetimer(spell, spellID, GUID, duration, key)\n        end\n        if duration then\n            duration = type(spell.offset) == \"table\" and spell.offset[npcID] or duration\n            WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, GUID, spellID, duration, false, false, count + 1, key, aura_env.id)\n        end\n        if spell.desynch ~= 0 then\n            WeakAuras.ScanEvents(\"RELOE_SPELLCD_DESYNCH\", spell, spellID, GUID, spell.desynch, aura_env.id)\n        end\n    end\nend\n\n-- Spell cast success handler\naura_env.onsuccess = function(spellID, GUID, name, CLEU)\n    local spell, key = aura_env.spells[spellID], GUID .. spellID\n    local npcID = select(6, strsplit(\"-\", GUID))\n    if spell and spell.onsuccess and ((not aura_env.last[key]) or GetTime() > aura_env.last[key] + 0.1) then\n        aura_env.last[key] = GetTime()\n        local count, duration = -1, aura_env.rolecheck(spell) and spell.duration\n        if type(spell.other) == \"table\" then\n            for k, v in pairs(spell.other) do\n                local spello = aura_env.spells[k] or spell\n                if aura_env.spells[k] and aura_env.spells[k].active then\n                    WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spello, GUID, k, v, false, false, 0, GUID .. k, aura_env.id)\n                end\n            end\n        end\n        if duration and type(spell.progressive) == \"table\" then\n            duration, count = aura_env.getprogressivetimer(spell, spellID, GUID, duration, key)\n        end\n        if duration then\n            duration = type(spell.offset) == \"table\" and spell.offset[npcID] or duration\n            WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, GUID, spellID, duration, false, true, count + 1, key, aura_env.id)\n        end\n    end\nend\n\n-- Combat handler\naura_env.oncombat = function(spellID, GUID)\n    local spell = aura_env.spells[spellID]\n    if spell and spell.oncombat and aura_env.rolecheck(spell) then\n        WeakAuras.ScanEvents(\"RELOE_SPELLCD_STATE_UPDATE\", spell, GUID, spellID, spell.combattimer, true, spell.onsuccess, 0, GUID .. spellID, aura_env.id)\n    end\nend\n\n-- Progressive timer calculation\naura_env.getprogressivetimer = function(spell, spellID, GUID, duration, key)\n    aura_env.progtime[key] = (aura_env.progtime[key] or 0) + 1\n    local timer = spell.progressive[aura_env.progtime[key]]\n    if not timer then\n        if spell.repeating then\n            aura_env.progtime[key] = 1\n            timer = spell.progressive[1]\n        else\n            timer = math.min(unpack(spell.progressive))\n        end\n    end\n    return timer or duration, aura_env.progtime[key]\nend",
