["[DP] [Tsulong] The Light of Day"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'TheLightOfDay'\n\nlocal name, icon = C_Spell.GetSpellName(123716), C_Spell.GetSpellTexture(123716)\n\nlocal options = {warningText = \"%icon @cffffff80%name@r » %destName %icon\"}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function(destName)\n    local data = {\n        ID = ID,\n        name = name,\n        icon = icon,\n        count = aura_env.count,\n        destName = WA_ClassColorName(destName)\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Schedule = function(event, seconds)\n    if aura_env.scheduler then aura_env.scheduler:Cancel() end\n    \n    aura_env.scheduler = C_Timer.NewTimer(seconds, function()\n            WeakAuras.ScanEvents(event)\n    end)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            \n            if spellID == 123716 then\n                aura_env.SendWarning(destName)\n            end\n        end\n        \n    elseif e == 'LIGHT_OF_DAY_CD' then\n        aura_env.count = aura_env.count + 1\n        if aura_env.scheduler then \n            aura_env.scheduler:Cancel() \n        end\n        aura_env.StartCD(10)\n        aura_env.Schedule('LIGHT_OF_DAY_CD', 10)\n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID = ...\n        \n        if phaseID == 'NightPhase' then\n            if aura_env.scheduler then \n                aura_env.scheduler:Cancel() \n            end\n            aura_env.StopCD()\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.count = 0\n            aura_env.StartCD(10)\n            aura_env.Schedule('LIGHT_OF_DAY_CD', 10)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        if aura_env.scheduler then \n            aura_env.scheduler:Cancel() \n        end\n    end\nend",
