["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'UnstableEnergy'\n\nlocal options = {\n}\n\nlocal name = C_Spell.GetSpellName(116997)\nlocal icon = 136048\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 116997 then\n            aura_env.count = aura_env.count + 1\n            \n            local baseCastTime = 4\n            local stacks = select(3, WA_GetUnitBuff('boss1', 117204)) or 0\n            local speedPerStack = 0.20\n            local totalSpeed = stacks * speedPerStack\n            local newCastTime = baseCastTime / (1 + totalSpeed)\n            \n            aura_env.StartCD(newCastTime)\n        end\n        \n    elseif e == 'ELEGON_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
