["init"] = {
["custom"] = "local encounterID = '1501'\nlocal ID          = 'EyesOfTheEmpress'\n\nlocal GetSpellInfoTable = function(spellID)\n    return { name = C_Spell.GetSpellName(spellID), icon = C_Spell.GetSpellTexture(spellID) }\nend\n\nlocal data = {\n    ['EyesOfTheEmpress']    = GetSpellInfoTable(123707),\n    ['ServantOfTheEmpress'] = GetSpellInfoTable(123713),\n}\n\nlocal options = {\n    ['EyesOfTheEmpress'] = {\n        warningText = \"%icon @cffffff80%name@r » %destName (%amount) %icon\",\n    },\n    ['ServantOfTheEmpress'] = {\n        warningText = \"@cffff4040%upper:name@r » %upper:destName\",\n    },\n}\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = data[ID].name,\n            icon           = data[ID].icon,\n            roleIcon       = 'TANK',\n            count          = aura_env.count,\n        }, options['EyesOfTheEmpress'])\nend\n\naura_env.SendWarning = function(ID, destName, amount)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = data[ID].name,\n            icon     = data[ID].icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName),\n            amount   = amount\n        }, options[ID])\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID,_,_,_, amount = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 123707 then\n                aura_env.count = aura_env.count + 1\n                aura_env.SendWarning('EyesOfTheEmpress', destName, amount or 1)\n                aura_env.StartCD(11)\n            elseif spellID == 123713  then\n                aura_env.SendWarning('ServantOfTheEmpress', destName)\n            end\n        end\n        \n    elseif e == 'SHEKZEER_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 1 then\n            aura_env.count = 0\n            aura_env.StartCD(11)\n        elseif phaseN == 2 or phaseN == 3 then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n        aura_env.StartCD(11)\n    end\nend",
