["[T11] Backend - Atramedes"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Atramedes)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Artemedes\n\nlocal ENTRY = aura_env\nlocal encounterId = 1022\n\nlocal localized = {\n    ['enUS'] = {\n        -- CHAT_MSG_MONSTER_YELL  \n        YellNefarianAdd = \"Atramedes, the heroes are right THERE!\",\n        YellAirPhase    = \"Yes, run! With every step your heart quickens. The beating, loud and thunderous... Almost deafening. You cannot escape!\",\n    },\n    \n    ['ruRU'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"Атрамед, они вон там!\",\n        YellAirPhase =    \"Бегите! С каждым шагом ваши сердца бьются все быстрее. Они стучат так громко, оглушительно громко... Вам не сбежать!\",\n    },\n    ['koKR'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"아트라메데스, 적은 바로 저기에 있다!\",\n        YellAirPhase =    \"그래, 도망가라! 발을 디딜 때마다 맥박은 빨라지지. 점점 더 크게 울리는구나... 귀청이 터질 것만 같군! 넌 달아날 수 없다!\",\n    },\n    ['zhCN'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"艾卓曼德斯，那些英雄就在那边！\",\n        YellAirPhase =    \"对，跑吧！每跑一步你的心跳都会加快。这心跳声，洪亮如雷，震耳欲聋。你逃不掉的！\",\n    },\n    ['zhTW'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"亞特拉米德，英雄們就在那!\",\n        YellAirPhase =    \"沒錯，逃吧!每一步都會讓你的心跳加速。跳得轟隆作響...震耳欲聾。你逃不掉的!\",\n    },\n    ['frFR'] = {\n        -- CHAT_MSG_MONSTER_YELL\n        YellAirPhase =    \"Oui, fuyez ! Chaque foulée accélère votre cœur. Les battements résonnent comme le tonnerre... Assourdissant. Vous ne vous échapperez pas !\",\n    },\n    ['esES'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"¡Atramedes, los héroes están justo AHÍ!\",\n        YellAirPhase =   \"¡Sí, corred! Con cada paso, vuestros corazones se aceleran. El latido, fuerte y clamoroso... Casi ensordecedor. ¡No podéis escapar!\",\n        \n    },\n    ['deDE'] = {\n        -- CHAT_MSG_MONSTER_YELL \n        YellNefarianAdd = \"Atramedes, die Helden sind direkt DA DRÜBEN!\",\n        YellAirPhase =  \"Ja, lauft! Jeder Schritt lässt Euer Herz stärker klopfen. Laut und heftig... ohrenbetäubend. Es gibt kein Entkommen!\",\n        \n    },\n    \n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    sonic_breath =    { 78075 },\n    tracking =        { 78092 },\n    phase_shift =     { 92681 },\n    obnoxious =       { 92677 },\n    searing_flames =  { 77840 },\n    sonar_pulse =     { 77672 },\n    avoid_circles =   { 77672 },\n    pestered =        { 92685 },\n    shields_left =    { false, 132360 },\n    adds =            { false, 236294 },\n    air_phase =       { false, 236747 },\n    ground_phase =    { false, 409597 },\n    boss_stunned =    { 77717 },\n    modulation =      { 77612 },\n    shield_used =     { false, 132360 },\n    switch =          { false, 136218 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.sourceFlags = sourceFlags\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal GroundPhase = function()\n    Cooldown('sonic_breath', 25); PreWarning('sonic_breath', 20)\n    Cooldown('sonar_pulse', 15)\n    Cooldown('searing_flames', 38)\n    Cooldown('air_phase', 85)\n    Cooldown('modulation', 12)\nend\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    ENTRY.CASTS.shields = 10\n    ENTRY.CASTS.searing_flames = 0\n    WeakAuras.ScanEvents('SHIELDS_COUNT', ENTRY.CASTS.shields)\n    Cooldown('modulation', 15-delay)\n    Cooldown('sonar_pulse', 10-delay)\n    Cooldown('sonic_breath', 25-delay) PreWarning('sonic_breath', 20-delay)\n    Cooldown('searing_flames', 45-delay)\n    Cooldown('air_phase', 90-delay)\n    if IsDifficulty(\"10_HEROIC\", \"25_HEROIC\") then\n        Cooldown('berserk', 600-delay)\n    end\nend\n\nENTRY['ON_COMBAT_END'] = function()\n    \nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 92677 then\n        Warning('obnoxious')\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 78075 then\n        Cooldown('sonic_breath', 41); PreWarning('sonic_breath', 36)\n        Warning('sonic_breath')\n    elseif args.spellId == 77840 then\n        -- Searing Flame\n        ENTRY.CASTS.searing = (ENTRY.CASTS.searing or 0) + 1\n        Cancel('searing_flames', 'ALL')\n        SpecialWarning('searing_flames')\n        Timer('searing_flames', 6)\n    elseif args.spellId == 92681 then\n        Warning('phase_shift')\n    elseif args.spellId == 77672 then\n        SpecialWarning('avoid_circles')\n        Cooldown('sonar_pulse', 10)\n    elseif args.spellId == 77612 then\n        Cooldown('modulation', 15)\n    elseif args.spellId == 78168 or args.spellId == 77611 and CORE.IsDestTypePlayer(args.sourceFlags) then\n        Warning('shield_used', args.sourceName)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 78092 then\n        if CORE.IsPlayer(args) then\n            SpecialWarning('tracking')\n        else\n            Warning('tracking', args.destName)\n        end\n        WeakAuras.ScanEvents('BEAM_START', args.destName)\n    elseif args.spellId == 77717 and CORE.GetGuidCreatureId(args.destGUID) == 41442 then\n        Warning('boss_stunned', args.destName)\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 78092 then\n        WeakAuras.ScanEvents('BEAM_STOPPED')\n    elseif args.spellId == 92681 then\n        SpecialWarning('switch')\n    end\nend\n\nENTRY['UNIT_DIED'] = function(args)\n    if CORE.IsNPC(args.destFlags) and CORE.GetGuidCreatureId(args.destGUID) ~= 49740 then\n        ENTRY.CASTS.shields = (ENTRY.CASTS.shields or 10) - 1\n        WeakAuras.ScanEvents('SHIELDS_COUNT', ENTRY.CASTS.shields)\n        Warning('shields_left', nil, ENTRY.CASTS.shields or 0)\n    end\nend\n\nENTRY['CHAT_MSG_MONSTER_YELL'] = function(text, playerName)\n    if not IsEntryInitialized() then return end\n    if text == L.YellAirPhase or text:find(L.YellAirPhase) then\n        Warning('air_phase')\n        Timer('air_phase', 31.5)\n        Cancel('sonic_breath', 'ALL')\n        Cancel('sonar_pulse', 'ALL')\n        Cancel('searing_flames', 'ALL')\n        Cancel('air_phase', 'ALL')\n        Cancel('modulation', 'ALL')\n        CORE.Schedule(ENTRY, 'ground_phase', 31.5, GroundPhase)\n    elseif text == L.YellNefarianAdd or text:find(L.YellNefarianAdd) then\n        Warning('adds')\n    end\nend",
["do_custom"] = true,
