["[DP] [Garalon] Pheromones"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1463'\nlocal ID          = 'Pheromones'\n\nlocal name, icon = C_Spell.GetSpellName(122835), C_Spell.GetSpellTexture(122835)\n\nlocal options = {\n    ['Pheromones' ] = {\n        warningText = \"%icon @cffffff80%name@r » %destName %icon\",\n    },\n    ['PheromonesTrail'] = {\n        warningText = string.format(Merfin:L('GTFO'), name),\n    }\n}\n\naura_env.SendWarning = function(ID, destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName)\n        }, options[ID])\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID, spellName = ...\n        \n        if subEvent == 'SPELL_DAMAGE' or subEvent == 'SPELL_MISSED' then \n            if spellID == 123120 and destGUID == WeakAuras.myGUID \n            and not aura_env.IsSpam(3) then\n                aura_env.SendWarning('PheromonesTrail')\n            end\n            \n        elseif subEvent == 'SPELL_AURA_APPLIED' or subEvent == 'SPELL_AURA_APPLIED_DOSE' then\n            if spellID == 122835 then\n                aura_env.count = aura_env.count + 1\n                WeakAuras.ScanEvents('PHEROMONES_APPLIED', destGUID)\n                \n                if destGUID ~= WeakAuras.myGUID then\n                    aura_env.SendWarning('Pheromones', destName)\n                else\n                    local msg = string.format('%s %s!', '{rt8}', C_Spell.GetSpellName(122835))\n                    WeakAuras.ScanEvents('MERFIN_SEND_CHAT_MESSAGE', msg, 'SAY')\n                end\n                \n                aura_env.RaidIcon('SET', destName, 8)\n                \n                local isPungency,_, stacks = WA_GetUnitDebuff(destName, 123081)\n                WeakAuras.ScanEvents('PUNGENCY_STACKS', destGUID, stacks or 0)\n                \n            elseif spellID == 123081 then\n                local _,_, stacks = WA_GetUnitDebuff(destName, 123081)\n                WeakAuras.ScanEvents('PUNGENCY_STACKS', destGUID, stacks)\n            end\n            \n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 122835 then\n                aura_env.RaidIcon('REMOVE', destName)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
