["custom"] = "local encounterID = '1504'\nlocal ID          = 'UnseenStrike'\n\nlocal name, icon = C_Spell.GetSpellName(122994), 236188\n\nlocal options = {\n    warningText    = \"@cffff4040%upper:name@r » %upper:destName\",\n    ttsLine        = Merfin:L(\"Stack\"),\n    prewarnTTStext = Merfin:L(\"Prepare to stack\"),\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'STRIKE_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env.CancelMRT()\n    local after = duration <= 5 and duration or duration - 5\n    aura_env._mrtTimer = C_Timer.NewTimer(after, aura_env.MRT)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function(destName)\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n            destName = WA_ClassColorName(destName),\n    }, options)\nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["events"] = "ENCOUNTER_START, CHAT_MSG_RAID_BOSS_EMOTE, UNSEEN_STRIKE_TARGET, PHASE_2",
["names"] = {
},
["check"] = "event",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        local msg,_,_,_, target = ...\n        \n        if msg:find(\"spell:122949\") then\n            aura_env.count = aura_env.count + 1\n            GMRT.F.Note_Timer('UNSEEN_USS_' .. aura_env.count)\n            aura_env.StartCD(53) -- 53-60\n            aura_env.SendWarning(target)\n        end\n        \n    elseif e == 'UNSEEN_STRIKE_TARGET' then\n        local subEvent, destName = ...\n        \n        if subEvent == 'AURA_APPLIED' then\n            aura_env.RaidIcon('SET', destName, 8)\n            \n        elseif subEvent == 'AURA_REMOVED' then\n            aura_env.RaidIcon('REMOVE', destName)\n        end\n        \n    elseif e == 'PHASE_2' then\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isLfr = WeakAuras.InstanceDifficulty() == 'lfr'\n        aura_env.count = 0\n        aura_env.StartCD(30.5)\n    end\nend",
