},
["custom"] = "function(a, e,_, mechanic,_,_,_,_, stacks)\n    if e == 'WA_MERFIN_RAID_HANDLER' \n    and mechanic == 'dazzling_destruction' \n    and stacks and stacks >= 0 then\n        if not a[''] then  \n            a[''] = {\n                show = true,\n                changed = true,\n                progressType = 'static',\n                total = 3,\n            }\n        end\n        a[''].value = stacks\n        a[''].changed = true\n        if stacks == 3 then\n            C_Timer.After(3, function() WeakAuras.ScanEvents('DAZZLING_DESTRUCTION_GONZO') end)\n        end\n        return true\n        \n    elseif e == 'DAZZLING_DESTRUCTION_GONZO' and a[''] then\n        a[''].show = false\n        a[''].changed = true\n        return true\n    elseif e == 'OPTIONS' then\n        a[''] = {\n            show = true,\n            changed = true,\n            progressType = 'static',\n            value = 1,\n            total = 3,\n        }\n        return true\n    end\nend\n\n\n",
