["anchorPoint"] = "TOPLEFT",
["cooldownSwipe"] = true,
["cooldownEdge"] = true,
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["custom_hide"] = "timed",
["event"] = "Health",
["unit"] = "player",
["custom_type"] = "stateupdate",
["subeventPrefix"] = "SPELL",
["custom"] = "function(states, event, ...)\n    \n    if event == 'OPTIONS' then\n        aura_env.order = { WeakAuras.me }\n        aura_env.nextStep = 1\n        states:Update('', { step = 1 })\n        return true\n    end\n    \n    if event == 'TSULONG_LOD_ORDER' then\n        local order = ...\n        aura_env.order = order \n        aura_env.isDay = false\n        return\n    end\n    \n    if not aura_env.order then return end\n    if #aura_env.order == 0 then return end\n    \n    if event == 'LIGHT_OF_DAY_CD' then\n        aura_env.count = aura_env.count + 1\n        aura_env.nextStep = aura_env.count + 1\n        \n        if aura_env.order[aura_env.nextStep] == WeakAuras.me then\n            WeakAuras.ScanEvents('MERFIN_TTS', Merfin:L('You are next'))\n            WeakAuras.ScanEvents('ELEGON_NEXT_REMINDER')\n        end\n        \n        states:Update('', { step = aura_env.nextStep })\n        \n    elseif event == 'MERFIN_PREWARNING_SHOW' then\n        if aura_env.isDay then return end\n        local _, cooldown = ...\n        if cooldown.ID ~= 'DayPhase' then return end\n        \n        aura_env.count = 0\n        aura_env.nextStep = aura_env.count + 1\n        \n        if aura_env.order[aura_env.nextStep] == WeakAuras.me then\n            WeakAuras.ScanEvents('MERFIN_TTS', Merfin:L('You are next'))\n            WeakAuras.ScanEvents('TSULONG_LOD_NEXT_REMINDER')\n        end\n        \n        states:Update('', { step = aura_env.nextStep })\n        \n    elseif event == 'TSULONG_PHASE' then\n        local phaseID = ...\n        \n        if phaseID == 'DayPhase' then\n            aura_env.count = aura_env.count + 1\n            aura_env.nextStep = aura_env.count + 1\n            aura_env.isDay = true\n            \n            if aura_env.order[aura_env.nextStep] == WeakAuras.me then\n                WeakAuras.ScanEvents('MERFIN_TTS', Merfin:L('You are next'))\n                WeakAuras.ScanEvents('ELEGON_NEXT_REMINDER')\n            end\n            \n            states:Update('', { step = aura_env.nextStep })\n            \n        elseif phaseID == 'NightPhase' then\n            aura_env.isDay = false\n            aura_env.count = 0\n            states:Remove('')\n        end\n        \n    end\nend",
["names"] = {
},
["check"] = "event",
["events"] = "TSULONG_LOD_ORDER, LIGHT_OF_DAY_CD, TSULONG_PHASE, MERFIN_PREWARNING_SHOW",
["spellIds"] = {
},
["debuffType"] = "HELPFUL",
},
["untrigger"] = {
},
},
{
["trigger"] = {
["unit"] = "player",
["type"] = "custom",
["custom"] = "function(states, e, ...)\n    if e == 'OPTIONS' then\n        states:Update('', {\n                progressType   = 'timed',\n                autoHide       = false,\n                duration       = 10,\n                expirationTime = 10 + GetTime(),\n                nextCount      = math.random(1, 10),\n        })\n    end\n    \n    if e == 'MERFIN_CD_HIDE' then\n        local encounterID, cooldown = ...\n        if cooldown.ID ~= 'TheLightOfDay' then return end\n        states:Remove('')\n        \n    elseif e == 'MERFIN_PREWARNING_SHOW' then\n        if aura_env.isDay then return end\n        local _, cooldown = ...\n        if cooldown.ID ~= 'DayPhase' then return end\n        \n        states:Update('', {\n                progressType    = 'timed',\n                autoHide        = true,\n                duration        = 5,\n                expirationTime  = 5 + GetTime(),\n        })\n        \n    elseif e == 'MERFIN_CD_SHOW_WIDGET' then\n        local encounterID, cooldown = ...\n        if cooldown.ID ~= 'TheLightOfDay' then return end\n        states:Update('', {\n                progressType   = 'timed',\n                duration       = cooldown.duration,\n                expirationTime = cooldown.expirationTime,\n                autoHide       = cooldown.autoHide,\n        })\n    end\nend",
