["[DP] [T14] Berserk"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local ID = 'Berserk'\n\nlocal name, icon = C_Spell.GetSpellName(45078), 136206\n\naura_env.StartCD = function(encounterID, duration)\n    WeakAuras.ScanEvents('MERFIN_CD_START', tostring(encounterID), {\n            show           = true,\n            autoHide       = true,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            noCount        = true,\n            name           = name,\n            icon           = icon\n    })\nend\n\naura_env.SendWarning = function(encounterID)\n    WeakAuras.ScanEvents('MERFIN_WARNING', tostring(encounterID), {\n            ID       = ID,\n            name     = name,\n            icon     = icon\n    })\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 45078 then\n            local currEnc = WeakAuras.CurrentEncounter\n            local currEncID = currEnc and tostring(currEnc.ID)\n            aura_env.SendWarning(currEncID)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        local diff = WeakAuras.InstanceDifficulty()\n        local encounterID = ...\n        \n        -- Protectors of the Endless\n        if encounterID == 1409 then\n            if diff ~= 'lfr' then\n                aura_env.StartCD(encounterID, 490)\n            end\n            \n            -- Tsulong\n        elseif encounterID == 1505 then\n            if diff ~= 'lfr' then\n                aura_env.StartCD(encounterID, 490)\n            end\n            \n            -- Lei Shi\n        elseif encounterID == 1506 then\n            local seconds = diff == 'heroic' and 420 or 600\n            aura_env.StartCD(encounterID, seconds)\n            \n            -- Sha of Fear\n        elseif encounterID == 1431 then\n            aura_env.StartCD(encounterID, 900)\n            \n            -- Zorlok\n        elseif encounterID == 1507 then\n            local IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n            local timer = IsHeroic and 660 or 600\n            aura_env.StartCD(encounterID, timer)\n            \n            -- Tayak\n        elseif encounterID == 1504 then\n            local IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n            aura_env.StartCD(encounterID, 490)\n            \n            -- Garalon\n        elseif encounterID == 1463 then\n            local IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n            local seconds = IsHeroic and 420 or 720\n            aura_env.StartCD(encounterID, seconds)\n            \n            -- Wind Lord\n        elseif encounterID == 1498 then\n            aura_env.StartCD(encounterID, 480)\n            \n            -- Unsok\n        elseif encounterID == 1499 then\n            aura_env.StartCD(encounterID, 600)\n            \n            -- Shekzeer\n        elseif encounterID == 1501 then\n            aura_env.StartCD(encounterID, 900)\n            \n            -- The Stone Guard\n        elseif encounterID == 1395 then\n            local IsHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n            local timer = IsHeroic and 420 or 480\n            aura_env.StartCD(encounterID, timer)\n            \n            -- Feng\n        elseif encounterID == 1390 then\n            aura_env.StartCD(encounterID, 600)\n            \n            -- Garajal\n        elseif encounterID == 1434 then\n            aura_env.StartCD(encounterID, 360)\n            \n            -- The Spirit Kings\n        elseif encounterID == 1436 then\n            aura_env.StartCD(encounterID, 600)\n            \n            -- Elegon\n        elseif encounterID == 1500 then\n            aura_env.StartCD(encounterID, 570)\n            \n            -- Emperors\n        elseif encounterID == 1407 then\n            aura_env.StartCD(encounterID, 780)\n            \n        end\n        \n    elseif e == 'SHA_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.StartCD(1431, 900)\n        end\n    end\nend",
