["init"] = {
["custom"] = "local encounterID = '1507'\nlocal ID          = 'Attenuation'\n\nlocal name, icon = C_Spell.GetSpellName(127834), C_Spell.GetSpellTexture(127834)\n\nlocal options = {\n    ['Attenuation'] = {\n        warningText = \"%icon %name %icon\",\n        prewarnCountVA = 2,\n        prewarnTTStext = Merfin:L(\"Sonic Rings Soon\"),\n    },\n    ['AttenuationL'] = {\n        warningText = \"%icon %name %icon\",\n        ttsLine = Merfin:L(\"Dodge to Left\"),\n    },\n    ['AttenuationR'] = {\n        warningText = \"%icon %name %icon\",\n        ttsLine = Merfin:L(\"Dodge to Right\"),\n    }\n}\n\nlocal sourceName = {\n    ['ECHO'] = '|cff40ff40' .. Merfin:L('Echo') .. '|r',\n    ['BOSS'] = '|cffff4040' .. BOSS .. '|r',\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'ATTEN_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function(bossID)\n    aura_env.CancelMRT()\n    local data = {\n        ID   = ID,\n        GUID = bossID,\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, data) -- no options\nend\n\naura_env.StartCD = function(duration, bossID)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    local data = {\n        show           = true,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        GUID           = bossID,\n        sourceName     = sourceName[bossID],\n        name           = name,\n        icon           = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options['Attenuation'])\nend\n\naura_env.SendWarning = function(ID, bossID)\n    local data = {\n        ID         = ID,\n        count      = aura_env.count,\n        sourceName = bossID and sourceName[bossID],\n        name       = name,\n        icon       = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.GetBossID = function(GUID)\n    local npcID = Merfin.GetNPCIDFromGUID(GUID)\n    local isEcho = npcID == 65173 or npcID == 65174\n    return isEcho and 'ECHO' or 'BOSS'\nend\n\naura_env.InRangeWith = function(GUID)\n    if aura_env.platformN == 4 then\n        return true\n    end\n    \n    local bossID = aura_env.platformN == 3 and 'ECHO' or 'BOSS'\n    local _, max = WeakAuras.GetRange('boss1')\n    return (bossID == 'BOSS' and max < 60) or (bossID == 'ECHO' and max >= 60)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent, _, sourceGUID, sourceName, _, _, destGUID, _, _, _, spellID = ...\n        \n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 127834 then\n                aura_env.count = aura_env.count + 1\n                \n                local bossID = aura_env.GetBossID(sourceGUID)\n                WeakAuras.ScanEvents('ATTEN_CAST_START', bossID)\n                aura_env.SendWarning('Attenuation', bossID)\n                \n                if aura_env.platformN < 4 then\n                    aura_env.StartCD(32.5, bossID)\n                else\n                    local timer = 40 -- PTR Change\n                    aura_env.StartCD(timer, bossID)\n                end\n                \n            elseif spellID == 122474 or spellID == 122496 or spellID == 123721 then\n                if aura_env.InRangeWith(sourceGUID) then\n                    aura_env.SendWarning('AttenuationL')\n                end\n                \n            elseif spellID == 122479 or spellID == 122497 or spellID == 123722 then\n                if aura_env.InRangeWith(sourceGUID) then\n                    aura_env.SendWarning('AttenuationR')\n                end\n            end\n            \n        elseif subEvent == 'SPELL_CAST_SUCCESS' then\n            if spellID == 127834 then\n                local bossID = aura_env.GetBossID(sourceGUID)\n                WeakAuras.ScanEvents('ATTEN_CAST_SUCCESS', bossID)\n            end\n            \n        elseif subEvent == 'UNIT_DIED' then\n            local npcID = Merfin.GetNPCIDFromGUID(destGUID)\n            if npcID == 65173 then -- Echo of Attenuation\n                aura_env.StopCD('ECHO')\n                WeakAuras.ScanEvents('ATTEN_CAST_FINISH', 'ECHO')\n            end\n        end\n        \n    elseif e == 'ECHO_STATE' then\n        aura_env.EchoAlive = ...\n        \n    elseif e == 'PLATFORM_CHANGED' then\n        aura_env.platformN = ...\n        \n        if aura_env.platformN == 2 then\n            local bossGUID = UnitGUID('boss1')\n            aura_env.StartCD(23, 'BOSS')\n        elseif aura_env.platformN == 3 then\n            local bossGUID = UnitGUID('boss1')\n            aura_env.StopCD('BOSS')\n            aura_env.StartCD(10, 'ECHO')\n        elseif aura_env.platformN == 4 then\n            local bossGUID = UnitGUID('boss1')\n            aura_env.StartCD(20, 'BOSS')\n        end\n        \n    elseif e == 'CLONE_SPAWNED' then\n        aura_env.StartCD(20, 'ECHO')\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.platformN = 0\n        aura_env.count = 0\n        aura_env.CancelMRT()\n    end\nend",
