["init"] = {
["custom"] = "local ClassColorName = function(name)\n    local _, class = UnitClass(name)\n    local color = RAID_CLASS_COLORS[class]\n    if color then\n        return string.format(\"|cFF%02X%02X%02X%s|r\", color.r * 255, color.g * 255, color.b * 255, name)\n    else\n        return name\n    end\nend\n\naura_env.BuildStringLine = function(line)\n    local result = \"\"\n    for i, name in ipairs(line) do\n        local coloredName = ClassColorName(name)\n        \n        if UnitGroupRolesAssigned(name) == \"HEALER\" then\n            coloredName = \"|A:groupfinder-icon-role-large-heal:16:16:0:0|a\" .. coloredName\n        end\n        \n        if name == WeakAuras.me then\n            coloredName = \">> \" .. coloredName .. \" <<\"\n        end\n        \n        result = result .. coloredName\n        if i < #line then\n            result = result .. \"\\n\"\n        end\n    end\n    return result\nend\n\naura_env.IsPlayerInStep = function(nextStep)\n    if not aura_env.order or not nextStep then return false end\n    \n    local stepList = aura_env.order[nextStep]\n    if not stepList then return false end\n    \n    for _, name in ipairs(stepList) do\n        if name == WeakAuras.me then\n            return true\n        end\n    end\n    \n    return false\nend\n\naura_env.GetNPCIDFromGUID = function(GUID)\n    local guidType, _, _, _, _, id = strsplit(\"-\", GUID or \"\")\n    if guidType == \"Creature\" or guidType == \"Vehicle\" or guidType == \"Pet\" then\n        return tonumber(id) or 0\n    end\n    return 0\nend",
