["customText"] = "function()\n    \n    if WeakAuras.IsOptionsOpen() then\n        local nextStep = aura_env.nextStep\n        local order = { WeakAuras.me, 'Merfin' }\n        local nextPlayers = aura_env.BuildStringLine(order)\n        return nextStep, nextPlayers\n    end\n    \n    local nextStep = aura_env.nextStep\n    local nextPlayers = aura_env.BuildStringLine(aura_env.order[nextStep])\n    return nextStep, nextPlayers\nend",
