["custom"] = "function(states, event, ...)\n    if event == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_, sourceName,_,_,_,_,_,_,_, spellID, spellName,_, extraSpellID = ...\n        \n        if (subEvent == 'SPELL_CAST_SUCCESS' and spellID == 117628)\n        or (subEvent == 'SPELL_INTERRUPT' and extraSpellID == 117628) then\n            if not aura_env.order then return end\n            if aura_env.lineCount == 0 then return end\n            \n            aura_env.count = aura_env.count + 1\n            aura_env.nextStep = (aura_env.count % aura_env.lineCount) + 1\n            \n            if states[''] then\n                states[''].nextStep = aura_env.nextStep\n                states[''].changed = true\n                return true\n            end\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_ADDED' then\n        if not aura_env.order then return end\n        if aura_env.lineCount == 0 then return end\n        \n        local nameplateID = ...\n        local GUID = UnitGUID(nameplateID)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == 60701 or npcID == 61421 then\n            states:Update('', { \n                    nextStep = aura_env.nextStep,\n                    unit     = nameplateID,\n            })\n        end\n        \n    elseif event == 'NAME_PLATE_UNIT_REMOVED' then\n        if not aura_env.order then return end\n        if aura_env.lineCount == 0 then return end\n        \n        local nameplateID = ...\n        local GUID = UnitGUID(nameplateID)\n        local npcID = aura_env.GetNPCIDFromGUID(GUID)\n        \n        if npcID == 60701 or npcID == 61421 then\n            states:Remove('')\n        end\n        \n        \n    elseif event == 'KINGS_INTERRUPT_ORDER' then\n        local order, lineCount = ...\n        aura_env.order, aura_env.lineCount = order, lineCount\n        \n        if not aura_env.order then return end\n        if aura_env.lineCount == 0 then return end\n        \n        aura_env.count = 0\n        aura_env.nextStep = (aura_env.count % aura_env.lineCount) + 1\n        \n    elseif event == 'OPTIONS' then\n        aura_env.nextStep = 1\n    end\nend",
