["events"] = "PLAYER_ENTERING_WORLD, CHALLENGE_MODE_START, CHALLENGE_MODE_COMPLETED, WORLD_STATE_TIMER_START, SCENARIO_CRITERIA_UPDATE, PLAYER_ENTERING_WORLD, ZONE_CHANGED_INDOORS, CHALLENGE_MODE_LEADERS_UPDATE",
["custom"] = "function(states, event)\n    \n    if event == \"OPTIONS\" and select(3, GetInstanceInfo()) ~= 8 then\n        aura_env.GenerateDummyCriteria(states)\n        return true\n    end\n    \n    if not C_ChallengeMode.IsChallengeModeActive() then\n        states:RemoveAll()\n        return true\n    end\n    \n    aura_env.UpdateAllCriteria(states)\n    return true\nend",
