["init"] = {
["custom"] = "aura_env.FormatTime = function(seconds)\n    local m = math.floor(seconds / 60)\n    local s = seconds % 60\n    return string.format(\"%02d:%02d\", m, s)\nend\n\naura_env.UpdateAllCriteria = function(states)\n    local _, elapsedTime = GetWorldElapsedTime(1)\n    if not elapsedTime then elapsedTime = 0 end\n    \n    local _, _, steps = C_Scenario.GetStepInfo()\n    for i = 1, steps do\n        local info = C_ScenarioInfo.GetCriteriaInfo(i)\n        if not info then break end\n        \n        local id    = info.criteriaID\n        local state = states[id]\n        \n        local updateData = {\n            value                   = info.quantity,\n            completed               = info.completed,\n            text                    = string.format(\"%d/%d\", info.quantity, info.totalQuantity),\n        }\n        \n        if info.completed and state and not state.completed then\n            local formatted = aura_env.FormatTime(elapsedTime)\n            updateData.completedTime = elapsedTime\n            updateData.formattedCompletedTime = formatted\n        end\n        \n        if not state then\n            updateData.show         = true\n            updateData.progressType = \"static\"\n            updateData.name         = info.description or (\"Objective \"..i)\n            updateData.icon         = info.assetID or 134400\n            updateData.total        = info.totalQuantity\n            updateData.index        = i\n        end\n        \n        states:Update(id, updateData)\n    end\nend\n\n\naura_env.GenerateDummyCriteria = function(states)\n    for i = 1, 4 do\n        local isBoss = (i < 4)\n        local name = isBoss and (\"Dummy Boss \" .. i) or \"Dummy Enemies\"\n        local total = isBoss and 1 or 10\n        local progress = isBoss and (i <= 2 and 1 or 0) or 4\n        local completed = isBoss and (i <= 2) or false\n        local formattedTime = aura_env.FormatTime(i * 60)\n        \n        states:Update(i, {\n                show                    = true,\n                progressType            = \"static\",\n                name                    = name,\n                icon                    = isBoss and (134400 + i) or 134407,\n                value                   = progress,\n                total                   = total,\n                completed               = completed,\n                completedTime           = completed and (i * 60) or nil,\n                formattedCompletedTime  = completed and formattedTime or nil,\n                text                    = string.format(\"%d/%d\", progress, total),\n                index                   = i,\n        })\n    end\nend",
["do_custom"] = true,
},
},
