["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1434'\nlocal ID          = 'VoodooDoll'\n\nlocal name, icon = C_Spell.GetSpellName(122151), C_Spell.GetSpellTexture(122151)\n\nlocal options = {\n    warningText = '%icon @cffffff80%name@r » %destName %icon'\n}\n\naura_env.SendWarning = function(destName)\n    local data = {\n        ID       = ID,\n        count    = aura_env.count,\n        destName = destName,\n        name     = name,\n        icon     = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend\n\naura_env.Synch = function(event, destName)\n    WeakAuras.ScanEvents('MERFIN_SYNCH', 'RAID', nil, event, destName) \nend\n\naura_env.RaidIcon = function(subEvent, dest, icon)\n    local warningInfo = { encounterID = encounterID, ID = ID }\n    WeakAuras.ScanEvents('MERFIN_RAID_ICON', warningInfo, subEvent, dest, icon)\nend\n\naura_env.IsSpam = function(before)\n    local cur = GetTime()\n    if not aura_env.antispam or cur - aura_env.antispam > before then\n        aura_env.antispam = cur\n        return false\n    end\n    return true\nend\n\naura_env.LatencyCheck = function()\n    return select(4, GetNetStats()) < 250\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID,_,_,_, spellID = ...\n        \n        if spellID ~= 122151 then return end\n        if not destGUID then return end\n        \n        if not aura_env.LatencyCheck() then return end\n        \n        local destName = select(6, GetPlayerInfoByGUID(destGUID))\n        \n        if not destName or destName == '' then \n            return \n        end\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            aura_env.Synch('VOODOO_DOLL_SYNCH', destName)\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            aura_env.Synch('VOODOO_DOLL_END_SYNCH', destName)\n        end\n        \n    elseif e == 'VOODOO_DOLL_SYNCH' then\n        \n        local destName = ...\n        \n        if not destName or destName == '' then \n            return \n        end\n        \n        for _, name in ipairs(aura_env.targets) do\n            if destName == name then\n                return\n            end\n        end\n        \n        table.insert(aura_env.targets, destName)\n        \n        if aura_env.IsSpam(3) then\n            return\n        end\n        \n        C_Timer.After(0.3, function()\n                aura_env.count = aura_env.count + 1\n                \n                for index, destName in ipairs(aura_env.targets) do\n                    aura_env.RaidIcon('SET', destName, index)\n                end\n                \n                local names = {}\n                for _, name in ipairs(aura_env.targets) do\n                    table.insert(names, WA_ClassColorName(name))\n                end\n                \n                local destNames = table.concat(names, ', ')\n                aura_env.SendWarning(destNames)\n                aura_env.targets = {}\n        end)\n        \n    elseif e == 'VOODOO_DOLL_END_SYNCH' then\n        local destName = ...\n        \n        if not destName or destName == '' then \n            return \n        end\n        \n        aura_env.RaidIcon('REMOVE', destName)\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.targets = {}\n        aura_env.count = 0\n    end\nend",
["spellIds"] = {
},
