},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal ID          = 'FocusPower'\n\nlocal name, icon = C_Spell.GetSpellName(119358), C_Spell.GetSpellTexture(119358)\n\nlocal options = {\n    warningText = \"%icon %name %icon\",\n    ttsLine = Merfin:L(\"Focus Charges\"),\n}\n\naura_env.SendWarning = function()\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        name   = name,\n        icon   = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 119358 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n        end\n        \n    elseif e == 'ELEGON_PHASE' then\n        local phaseN = ...\n        \n        if phaseN == 2 then\n            aura_env.count = 0\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.count = 0\n    end\nend",
