["[T11] Backend - Conclave"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Conclave)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Conclave\n\nlocal ENTRY = aura_env\nlocal encounterId = 1035\n\nlocal localized = {\n    ['enUS'] = {\n        -- CHAT_MSG_MONSTER_YELL\n        gather_strength = \"begins to gather strength\",\n    },\n    \n    ['ruRU'] = {\n        -- CHAT_MSG_MONSTER_EMOTE  \n        gather_strength = '%s близок к обретению абсолютной силы',\n    },\n    \n    ['zhCN'] = {\n        gather_strength    = \"即将获得全部力量！\",\n    },\n    \n    ['koKR'] = {\n        gatherstrength    = \"힘을 모으기 시작합니다!\",\n    },\n}\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    -- Anshall\n    soothing_breeze = { 86207 },\n    nurture =         { 85422 }, \n    toxic_spores =    { 86281 },\n    -- Nezir\n    wind_chill =      { 84645 },\n    permafrost =      { 86081 },\n    ice_patch =       { 86111 },\n    -- Rohash\n    slicing_gale =    { 86182 },\n    wind_blast =      { 86193 },\n    \n    summon_tornados = { 86192 },\n    storm_shield =    { 93059 },\n    gather_strength = { 86307 },\n    \n    \n    special =         { false, 132866 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\n--local WarningMultiply = function(...) SendPrototype('WARNING_MULTIPLY', ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\n--local Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal Schedule = function(after, func, mechanic, ...) CORE.Schedule(ENTRY, mechanic, after, func, ...) end\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START']()\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.destFlags = destFlags\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal ANSHAL = 45870\nlocal NEZIR =  45871\nlocal ROHASH = 45872\n\nlocal deadBoss = {\n    [ANSHAL] = false,\n    [NEZIR] =  false,\n    [ROHASH] = false,\n}\n\nlocal bossPlatform = 0\nlocal unitIds = { 'boss1', 'boss2', 'boss3' }\nENTRY.BossCheck = function()\n    for _, bossId in ipairs(unitIds) do\n        local GUID = UnitExists(bossId) and UnitGUID(bossId)\n        if GUID and WeakAuras.GetRange(bossId) < 60 then\n            local npcId = CORE.GetGuidCreatureId(GUID)\n            if npcId ~= bossPlatform then\n                WeakAuras.ScanEvents('PLATFORM_CHANGED', npcId)\n            end\n            bossPlatform = npcId\n            break\n        end\n    end\n    Schedule(1.5, ENTRY.BossCheck, 'bossCheck')\nend\n\nENTRY['ON_COMBAT_START'] = function()\n    local timer = IsDifficulty('10_HEROIC', '25_HEROIC') and 60 or 120\n    ENTRY.CASTS.windBlast = 0\n    \n    bossPlatform = 0\n    Schedule(0.1, ENTRY.BossCheck, 'bossCheck')\n    \n    -- Anshal\n    Cooldown('soothing_breeze', 16)\n    Cooldown('nurture', 25)\n    -- Nezir\n    Cooldown('wind_chill', 10)\n    Cooldown('permafrost', 10)\n    Cooldown('ice_patch', 15)\n    -- Rohash\n    Cooldown('wind_blast', 30); PreWarning('wind_blast', 25)\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('storm_shield', 27.5)\n    end\n    \n    Cooldown('special', 90); PreWarning('special', 85)\n    Cooldown('berserk', 480)\nend\n\nENTRY['ON_COMBAT_END'] = function()\nend\n\nlocal bossRevive = function(npcId)\n    if npcId then\n        deadBoss[npcId] = false\n    end\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 86182 then\n        Schedule(0.1, CORE.TargettedCast, 'gale_target', args.sourceGUID, 'GALE_TARGET')\n    elseif args.spellId == 86205 then\n        -- Soothing Breeze (Anshal)\n        Cooldown('soothing_breeze', 30)\n    elseif args.spellId == 86192 then\n        -- Summon Tornados (Rohash)\n        SpecialWarning('summon_tornados')\n    elseif args.spellId == 86307 then\n        local npcId = CORE.GetGuidCreatureId(args.sourceGUID)\n        deadBoss[npcId] = true\n        local timer = IsDifficulty('10_HEROIC', '25_HEROIC') and 60 or 120\n        Schedule(timer, bossRevive, 'bossRevive', npcId)\n        local BOSS = (npcId == ANSHAL and 'ANSHAL') or (npcId == NEZIR and 'NEZIR') or (npcId == ROHASH and 'ROHASH')\n        WeakAuras.ScanEvents('BOSS_DIED', BOSS, timer)\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 85422 then\n        Cooldown('nurture', 115)\n        Warning('nurture')\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('toxic_spores', 21)\n        end\n        \n    elseif args.spellId == 86082 then\n        Cooldown('permafrost', 10)\n        \n    elseif (args.spellId == 84638 or args.spellId == 84643 or args.spellId == 84644) and AntiSpam('special', 3) then\n        Warning('special')\n        Timer('special', 15)\n        if not deadBoss[NEZIR] then\n            Cooldown('permafrost', 15)\n            Cooldown('wind_chill', 15)\n        end\n        if not deadBoss[ANSHAL] then\n            Cooldown('soothing_breeze', 35)\n            Cooldown('nurture', 52)\n        end\n        if not deadBoss[ROHASH] then\n            Cooldown('wind_blast', 20); PreWarning('wind_blast', 15)\n            if  IsDifficulty('10_HEROIC', '25_HEROIC') then\n                Cooldown('storm_shield', 52)\n            end\n        end\n        Cooldown('special', 117); PreWarning('special', 112)\n        \n    elseif args.spellId == 86281 and AntiSpam('toxic_spores', 3) then\n        Warning('toxic_spores')\n        Timer('toxic_spores', 5)\n        Cooldown('toxic_spores', 21)\n        \n    elseif args.spellId == 84645 then\n        Cooldown('wind_chill', 10.5)\n        \n    elseif args.spellId == 86193 then\n        ENTRY.CASTS.windBlast = ENTRY.CASTS.windBlast + 1\n        SpecialWarning('wind_blast')\n        Timer('wind_blast', 11.5)\n        if ENTRY.CASTS.windBlast == 1 then\n            Cooldown('wind_blast', 80); PreWarning('wind_blast', 75)\n        else\n            Cooldown('wind_blast', 60); PreWarning('wind_blast', 55)\n        end\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 93059 then\n        -- Storm Shield\n        Cooldown('storm_shield', 117)\n    end\nend\nENTRY['SPELL_AURA_APPLIED_DOSE'] = ENTRY['SPELL_AURA_APPLIED']\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\nend\n\nENTRY['SPELL_DAMAGE'] = function(args)\n    if args.spellId == 86111 and args.destGUID == CORE.PlayerGUID and AntiSpam('ice_patch', 3) then\n        GTFO('ice_patch')\n    end\nend\n\nENTRY['SPELL_HEAL'] = function(args)\n    if args.spellId == 95218 and  CORE.GetGuidCreatureId(args.destGUID) == ANSHAL and AntiSpam('move_boss', 3) then\n        if CORE.IsTanking('player', nil, args.destGUID) then\n            --SpecialWarning('MOVE_BOSS')\n        end\n    end\nend\n\nENTRY['UNIT_SPELLCAST_SUCCEEDED'] = function(_,_, spellId)\n    if spellId == 86122 and AntiSpam('ice_patch', 3) then\n        Warning('ice_patch')\n        Cooldown('ice_patch', 15)\n    end\nend",
["do_custom"] = true,
},
