["subeventPrefix"] = "SPELL",
["custom"] = "function(e, msg, subEvent, USSspellID, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName, _, _, amount)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        if subEvent == 'SPELL_CAST_START' then\n            if spellID == 120946 and aura_env.Antispam(spellID, 2) then\n                aura_env.Warning('ResinShell')\n            end\n        elseif subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 123032 and sourceGUID == WeakAuras.myGUID then\n               --aura_env.Chat('{rt2} ' .. WeakAuras.me .. ' carrying keg {rt2}')\n            elseif spellID == 119388 and destGUID == WeakAuras.myGUID then\n               --aura_env.Chat('{rt2} ' .. WeakAuras.me .. ' bomb {rt2}')\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 123032 and sourceGUID == WeakAuras.myGUID then\n                --aura_env.Chat('- threw keg -')\n            elseif spellID == 119388 and destGUID == WeakAuras.myGUID then\n                --aura_env.Chat('- threw -')\n            end\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_YELL' then\n        if aura_env.IsEmote(msg, 'CommanderBossStart') then\n            aura_env.StopCD('CommanderAddsWave')\n            aura_env.Warning('CommanderBossStart')\n        elseif aura_env.IsEmote(msg, 'CommanderWave1') then\n            aura_env.Warning('CommanderAddsWave', 1)\n            aura_env.StartCD('CommanderAddsWave', 65, true)\n        elseif aura_env.IsEmote(msg, 'CommanderWave2') then\n            aura_env.Warning('CommanderAddsWave', 2)\n            aura_env.StartCD('CommanderAddsWave', 60, true)\n        elseif aura_env.IsEmote(msg, 'CommanderWave3') then\n            aura_env.Warning('CommanderAddsWave', 3)\n            aura_env.StartCD('CommanderAddsWave', 60, true)\n        elseif aura_env.IsEmote(msg, 'CommanderWave4') then\n            aura_env.Warning('CommanderAddsWave', 4)\n            aura_env.StartCD('CommanderAddsWave', 89, true)\n        end\n        \n    elseif e == 'CHAT_MSG_MONSTER_SAY' then\n        if aura_env.IsEmote(msg, 'CommanderWave0') then\n            aura_env.StartCD('CommanderAddsWave', 20)\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.ClearCache()\n        \n    elseif e == 'STATUS' then\n        aura_env.ClearCache()\n        \n    elseif e == 'OPTIONS' and not WeakAuras.IsAuraLoaded(aura_env.id) then\n        aura_env.WipeSchedulers()\n    end\nend",
