["custom"] = "local encounterID = '1434'\nlocal ID          = 'Frenzy'\n\nlocal name, icon = C_Spell.GetSpellName(117752), C_Spell.GetSpellTexture(117752)\n\nlocal options = {\n    warningText = '@cffff4040%upper:name@r'\n}\n\naura_env.SendWarning = function(amount)\n    local data = {\n            ID    = ID,\n            count = aura_env.count,\n            name  = name,\n            icon  = icon\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
