["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1436'\nlocal ID          = 'Annihilate'\n\nlocal options = {\n    warningText = \"%icon %name (%count) %icon\",\n    ttsLine = Merfin:L(\"Frontal\"),\n}\n\nlocal name, icon = C_Spell.GetSpellName(117948), C_Spell.GetSpellTexture(117948)\n\naura_env.StopCD = function()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, { ID = ID })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    local data = {\n        show           = true,\n        autoHide       = autoHide,\n        duration       = duration,\n        expirationTime = duration + GetTime(),\n        ID             = ID,\n        count          = aura_env.count,\n        name           = name,\n        icon           = icon,\n        forcePrewarn   = true,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, data, options)\nend\n\naura_env.SendWarning = function()\n    local data = { \n        ID    = ID, \n        count = aura_env.count, \n        name  = name, \n        icon  = icon \n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 117948 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local timer = aura_env.isHeroic and 32.5 or 39\n            aura_env.StartCD(timer)\n        end\n        \n    elseif e == 'BOSS_SWAP' then\n        local bossID, activated = ...\n        \n        if bossID == 'QIANG' and not activated then\n            aura_env.StopCD()\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.isHeroic = WeakAuras.InstanceDifficulty() == 'heroic'\n        aura_env.count = 0\n        aura_env.StartCD(11.5)\n    end\nend",
