["exrtLastSync"] = 1751115562,
["actions"] = {
["start"] = {
},
["init"] = {
["do_custom_load"] = false,
["custom"] = "local GetTime = GetTime\nlocal UnitClassBase, UnitName, UnitGUID, UnitAffectingCombat, UnitGroupRolesAssigned = UnitClassBase, UnitName, UnitGUID, UnitAffectingCombat, UnitGroupRolesAssigned\n\naura_env.rlConfig = {}\naura_env.roster = {}\naura_env.encStart = 0\n\naura_env.RefreshRoster = function()\n    for unit in WA_IterateGroupMembers() do\n        if UnitClassBase(unit) == \"WARRIOR\" then\n            local unitName = UnitName(unit)\n            if aura_env.roster[unitName] then\n                aura_env.roster[unitName].role = UnitGroupRolesAssigned(unit)\n            else\n                aura_env.roster[unitName] = {\n                    unit        = unit,\n                    unitName    = unitName,\n                    role        = UnitGroupRolesAssigned(unit),\n                    useTime     = 0,\n                    expTime     = 0,\n                    buffExpTime = 0,\n                }\n            end\n        end\n    end\nend\n\n-- Handlers\n\naura_env['STATUS'] = function(states)\n    aura_env.RefreshRoster()\n    \n    -- Left Units\n    for unitName in pairs(states) do\n        if not (UnitInRaid(unitName) or UnitInParty(unitName) or unitName == WeakAuras.me) then\n            aura_env.roster[unitName] = nil\n            states:Remove(unitName)\n        end\n    end\n    \n    return aura_env.UpdateStates(states)\nend\n\naura_env['OPTIONS'] = function(states)\n    \nend\n\naura_env['BANNER_MANAGER_SETTINGS'] = function(_, sender, config)\n    aura_env.rlConfig = config\n    --print('|cffc79c6e[Merfin Banner Manager]|r has received configuration data from ' .. sender)\nend\n\naura_env['GROUP_ROSTER_UPDATE'] = function(states)\n    aura_env.RefreshRoster()\n    \n    -- Left Units\n    for unitName in pairs(states) do\n        if not (UnitInRaid(unitName) or UnitInParty(unitName) or unitName == WeakAuras.me) then\n            aura_env.roster[unitName] = nil\n            states:Remove(unitName)\n        end\n    end\n    \n    return aura_env.UpdateStates(states)\nend\n\naura_env['ROLE_CHANGED_INFORM'] = function(states, changedName, fromName, oldRole, newRole)\n    if not aura_env.roster[changedName] then\n        return\n    end\n    \n    aura_env.roster[changedName].role = newRole\nend\n\naura_env['ENCOUNTER_START'] = function(states)\n    aura_env.encStart = GetTime()\nend\n\naura_env['ENCOUNTER_END'] = function(states)\n    local elapsed = GetTime() - aura_env.encStart\n    if elapsed >= 30 then\n        for _, unitData in pairs(aura_env.roster) do\n            unitData.expTime = 0\n        end\n        \n        return aura_env.UpdateStates(states)\n    end\nend\n\naura_env['SHA_PHASE'] = function(states, phaseN)\n    if phaseN == 2 then\n        for _, unitData in pairs(aura_env.roster) do\n            unitData.expTime = 0\n        end\n        \n        return aura_env.UpdateStates(states)\n    end\nend\n\naura_env['COMBAT_LOG_EVENT_UNFILTERED'] = function(states,_, subEvent,_, sourceGUID, sourceName,_,_,_,_,_,_, spellID)\n    if subEvent ~= 'SPELL_CAST_SUCCESS' then return end\n    if spellID ~= 114207 then return end\n    \n    local unitData = aura_env.roster[sourceName]\n    if not unitData then return end\n    \n    local curTime = GetTime()\n    unitData.useTime     = curTime\n    unitData.expTime     = 180 + curTime\n    unitData.buffExpTime = 10 + curTime\n    \n    C_Timer.After(10 + 0.1, function()\n            WeakAuras.ScanEvents('MERFIN_BANNER_UPDATE', sourceName)\n    end)\n    \n    C_Timer.After(180 + 0.1, function()\n            WeakAuras.ScanEvents('MERFIN_BANNER_UPDATE', sourceName)\n    end)\n    \n    states[sourceName].duration       = 10\n    states[sourceName].expirationTime = unitData.buffExpTime\n    states[sourceName].active         = true\n    states[sourceName].changed        = true\n    \n    aura_env.SortPriorities(states)\n    \n    return true\nend\n\naura_env['MERFIN_BANNER_UPDATE'] = function(states, unitName)\n    if states[unitName] then\n        return aura_env.UpdateStates(states)\n    end\nend\n\n-- State Updater\n\naura_env.SortPriorities = function(states)\n    local sorted = {}\n    \n    for _, state in pairs(states) do\n        if state and state.unitName then\n            table.insert(sorted, state)\n        end\n    end\n    \n    local RolePriority = {\n        HEALER = 1,\n        TANK = 2,\n        DAMAGER = 3,\n        NONE = 4\n    }\n    \n    table.sort(sorted, function(a, b)\n            -- Group 1: Active totems come first, sorted by expirationTime (earlier = higher)\n            if a.active and not b.active then\n                return true\n            elseif not a.active and b.active then\n                return false\n            elseif a.active and b.active then\n                if (a.expirationTime or math.huge) ~= (b.expirationTime or math.huge) then\n                    return (a.expirationTime or math.huge) < (b.expirationTime or math.huge)\n                end\n            end\n            \n            -- Group 2: Ready (not on cooldown) sorted before those still on cooldown\n            if not a.onCooldown and b.onCooldown then\n                return true\n            elseif a.onCooldown and not b.onCooldown then\n                return false\n            end\n            \n            -- Group 3: Role priority (HEALER > TANK > DAMAGER > NONE)\n            local roleA = (aura_env.roster[a.unitName] and aura_env.roster[a.unitName].role) or \"NONE\"\n            local roleB = (aura_env.roster[b.unitName] and aura_env.roster[b.unitName].role) or \"NONE\"\n            if RolePriority[roleA] ~= RolePriority[roleB] then\n                return (RolePriority[roleA] or 4) < (RolePriority[roleB] or 4)\n            end\n            \n            -- Group 4: Alphabetical order fallback\n            return a.unitName < b.unitName\n    end)\n    \n    local foundNext = false\n    for i, state in ipairs(sorted) do\n        state.index = i\n        state.changed = true\n        \n        if not foundNext and not state.active and not state.onCooldown then\n            state.next = true\n            foundNext = true\n        else\n            state.next = false\n        end\n    end\nend\n\naura_env.UpdateStates = function(states)\n    for unitName in pairs(aura_env.roster) do\n        local curTime = GetTime()\n        \n        local data = aura_env.roster[unitName] or {}\n        local useTime = data.useTime\n        local expTime = data.expTime\n        local sinceUsed = curTime - useTime\n        local isActive = sinceUsed < 10\n        \n        states[unitName] = {\n            show           = true,\n            changed        = true,\n            progressType   = 'timed',\n            duration       = (isActive and 10) or 180,\n            expirationTime = (isActive and data.buffExpTime) or data.expTime or 0,\n            autoHide       = false,\n            unitName       = unitName,\n            active         = isActive,\n            onCooldown     = curTime < (data.expTime or 0)\n        }\n    end\n    \n    aura_env.SortPriorities(states)\n    return true\nend",
["do_custom"] = true,
},
