["hide_all_glows"] = true,
},
["init"] = {
["do_custom"] = false,
["custom"] = "-- Author: 露露緹婭@Bilibili\naura_env.RurutiaFilePath = \"Interface\\\\Addons\\\\SharedMedia_Rurutia\\\\Rurutia\\\\\"\n\naura_env.cooldownConfig = {\n    --[61295] = 10, --激流，测试用\n}\n\nif not aura_env.lastPlayTime then\n    aura_env.lastPlayTime = {}\nend\n\naura_env.RurutiaSoundMap = {\n    --恐惧之心\n    [118091] = \"【露露】快躲开.ogg\", -- 大地污染\n    [117235] = \"【露露】获得增益.ogg\", -- 被净化\n    [122789] = \"【露露】Bingo.ogg\", -- 阳光\n    [123716] = \"【露露】获得增益.ogg\", -- 灼日圣光\n    [129189] = \"【露露】获得增益.ogg\", -- 煞能宝珠\n    [120519] = \"【露露】快躲开.ogg\", -- 龙卷水涌\n    \n    --BUFF\n    [118977] = \"【露露】获得增益.ogg\", -- 无畏\n}",
},
