["[DP] [Mel'jarak] Rain of Blades"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1498'\nlocal ID          = 'RainOfBlades'\n\nlocal name, icon = C_Spell.GetSpellName(122406), C_Spell.GetSpellTexture(122406)\n\nlocal options = {\n    warningText    = \"%icon %name %icon\",\n    prewarnTTStext = Merfin:L(\"AOE Soon\"),\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'BLADES_' .. (aura_env.count + 1)\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function()\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {\n            ID = ID\n    })\nend\n\naura_env.StartCD = function(duration, autoHide)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, {\n            show           = true,\n            autoHide       = autoHide,\n            duration       = duration,\n            expirationTime = duration + GetTime(),\n            ID             = ID,\n            name           = name,\n            icon           = icon,\n            count          = aura_env.count,\n    }, options)\nend\n\naura_env.SendWarning = function()\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, {\n            ID       = ID,\n            name     = name,\n            icon     = icon,\n            count    = aura_env.count,\n    }, options)\nend",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _,_,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if spellID == 122406 then\n            aura_env.count = aura_env.count + 1\n            aura_env.SendWarning()\n            local seconds = aura_env.phase2 and 48 or 60\n            aura_env.StartCD(seconds)\n        end\n        \n    elseif e == 'MELJARAK_PHASE2' then\n        aura_env.phase2 = true\n        aura_env.StopCD()\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.count = 0\n        aura_env.phase2 = false\n        aura_env.StartCD(60)\n    end\nend",
