["[DP] [Tsulong] Terrorize"] = {
["outline"] = "OUTLINE",
["exrtLastSender"] = "Jfkx-ClassicBetaPvE",
["wagoID"] = "H5gs0vTam",
["color"] = {
1,
1,
1,
1,
},
["displayText"] = "",
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["custom"] = "\n\n",
["do_custom"] = false,
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "local encounterID = '1505'\nlocal ID = 'Terrorize'\n\nlocal function GetSpellInfoTable(spellID)\n    return {\n        name = C_Spell.GetSpellName(spellID),\n        icon = C_Spell.GetSpellTexture(spellID)\n    }\nend\n\naura_env.terrorLoc = C_EncounterJournal.GetSectionInfo(6316).title\n\nlocal data = {\n    ['Terrorize'] = GetSpellInfoTable(123011),\n    ['EmbodiedTerror'] = {name = aura_env.terrorLoc, icon = 627685}\n}\n\nlocal options = {\n    ['Terrorize'] = {warningText = \"%icon @cffffff80%name@r » %destName %icon\"},\n    ['EmbodiedTerror'] = {warningText = \"%icon @cffffff80%name@r (%count) %icon\"}\n}\n\naura_env.CancelMRT = function()\n    if aura_env._mrtTimer and aura_env._mrtTimer.Cancel then\n        aura_env._mrtTimer:Cancel()\n        aura_env._mrtTimer = nil\n    end\nend\n\naura_env.MRT = function()\n    local event = 'TERRORIZE_' .. aura_env.count\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.StopCD = function(ID)\n    aura_env.CancelMRT()\n    WeakAuras.ScanEvents('MERFIN_CD_STOP', encounterID, {ID = ID})\nend\n\naura_env.StartCD = function(ID, duration, autoHide)\n    aura_env._mrtTimer = C_Timer.NewTimer(duration - 5, aura_env.MRT)\n    local payload = {\n        show = true,\n        autoHide = autoHide,\n        duration = duration,\n        expirationTime = duration + GetTime(),\n        ID = ID,\n        name = data[ID].name,\n        icon = data[ID].icon,\n        count = aura_env.count\n    }\n    WeakAuras.ScanEvents('MERFIN_CD_START', encounterID, payload, options[ID])\nend\n\naura_env.SendWarning = function(ID, destName)\n    local warn = {\n        ID = ID,\n        name = data[ID].name,\n        icon = data[ID].icon,\n        count = aura_env.count,\n        destName = destName\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, warn, options[ID])\nend\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    \n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_, destGUID, destName,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 123012 then\n                aura_env.StopCD('Terrorize')\n                \n                local npcID = Merfin.GetNPCIDFromGUID(destGUID)\n                if npcID == 62442 then\n                    aura_env.SendWarning('Terrorize', destName)\n                end\n            end\n        end \n        \n    elseif e == 'RAID_BOSS_EMOTE' then\n        local msg = ...\n        \n        if msg:find(aura_env.terrorLoc) then\n            aura_env.count = aura_env.count + 1\n            aura_env.StartCD('Terrorize', 13.5, true)\n            \n            if aura_env.count < 3 then\n                aura_env.SendWarning('EmbodiedTerror')\n                aura_env.StartCD('EmbodiedTerror', 41)\n            else\n                aura_env.StopCD('EmbodiedTerror')\n            end\n        end\n        \n        \n    elseif e == 'TSULONG_PHASE' then\n        local phaseID = ...\n        \n        if phaseID == 'NightPhase' then\n            aura_env.StopCD('EmbodiedTerror')\n            aura_env.StopCD('Terrorize')\n            \n        elseif phaseID == 'DayPhase' then\n            aura_env.count = 0\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.CancelMRT()\n        aura_env.count = 0\n    end\nend",
["spellIds"] = {
},
["events"] = "ENCOUNTER_START, RAID_BOSS_EMOTE, TSULONG_PHASE, CLEU:SPELL_AURA_APPLIED",
["names"] = {
