["[T11] Backend - Maloriak"] = {
["outline"] = "OUTLINE",
["wagoID"] = "SqAL2pX1r",
["authorOptions"] = {
{
["type"] = "toggle",
["default"] = false,
["key"] = "test",
["useDesc"] = false,
["name"] = "Test Mode (Maloriak)",
["width"] = 1,
},
},
["displayText_format_p_time_dynamic_threshold"] = 60,
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
["do_glow"] = false,
},
["init"] = {
["custom"] = "-- [T11] Backend - Maloriak\n\nlocal ENTRY = aura_env\nlocal encounterId = 1025\n\nlocal localized = {\n    ['enUS'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red =   \"red|r vial into the cauldron!\",\n        yell_blue =  \"blue|r vial into the cauldron!\",\n        yell_green = \"green|r vial into the cauldron!\",\n        yell_dark =  \"dark|r magic into the cauldron!\",\n    },\n    \n    ['ruRU'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red =   \"красный|r пузырек в котел!\",\n        yell_blue =  \"синий|r пузырек в котел!\",\n        yell_green = \"зеленый|r пузырек в котел!\",\n        yell_dark =  \"магию к котлу!\",\n    },\n    \n    ['koKR'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"붉은색|r 약병을 가마솥\",\n        yell_blue= \"푸른색|r 약병을 가마솥\",\n        yell_green= \"초록색|r 약병을 가마솥\",\n        yell_dark= \"암흑|r 마법을 사용합니다!\"\n    },\n    \n    ['zhCN'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"红瓶|r扔进了大锅里！\",\n        yell_blue= \"蓝瓶|r扔进了大锅里！\",\n        yell_green= \"绿瓶|r扔进了大锅里！\",\n        yell_dark= \"黑暗|r魔法！\",\n    },\n    \n    ['zhTW'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"紅色|r瓶子到鍋子裡!\",\n        yell_blue= \"藍色|r瓶子到鍋子裡!\",\n        yell_green= \"綠色|r瓶子到鍋子裡!\",\n        yell_dark= \"黑暗|r魔法到鍋子裡!\",\n    },\n    \n    ['frFR'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"Flacon rouge|r dans le chaudron !\",\n        yell_blue= \"Flacon bleu|r dans le chaudron !\",\n        yell_green= \"Flacon vert|r dans le chaudron !\",\n        yell_dark= \"Flacon sombre|r dans le chaudron !\"\n    },\n    \n    ['deDE'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"Flacon rouge|r dans le chaudron !\",\n        yell_blue= \"Flacon bleu|r dans le chaudron !\",\n        yell_green= \"Flacon vert|r dans le chaudron !\",\n        yell_dark= \"Flacon sombre|r dans le chaudron !\"\n    },\n    \n    ['esES'] = {\n        -- RAID_BOSS_EMOTE\n        yell_red= \"rojo|r a la caldera!\",\n        yell_blue= \"azul|r a la caldera!\",\n        yell_green= \"verde|r a la caldera!\",\n        yell_dark= \"oscura|r en el caldero!\"\n    },\n}\n\nlocal L = localized[GetLocale()] or localized['enUS']\n\nENTRY.L = L \n\nENTRY.mechanics = {\n    -- Phases\n    phase_dark =        { false, 237056 },\n    phase_blue_or_red = { false, 133781 },\n    phase_blue =        { false, 134800 },\n    phase_red =         { false, 134804 },\n    phase_green =       { false, 134790 },\n    -- Static Spells\n    arcane_storm =       { 77896 },\n    release_abberation = { 77569 },\n    abberations_left =   { 77569 },\n    remedy =             { 77912 },\n    growth_catalyst =    { 77987 },\n    -- Blue Phase\n    flash_freeze =       { 77699 },\n    biting_chill =       { 77760 },\n    -- Red Phase\n    consuming_flames =   { 77786 },\n    scorching_blast =    { 77679 },\n    -- Green Phase\n    debilitating_slime = { 77615 },\n    -- Dark Phase\n    engulfing_darkness = { 92754 },\n    dark_sludge =        { 92930 },\n    free_to_heal =       { false },\n    -- Phase 2\n    magma_jets =         { 78194 },\n    absolute_zero =      { 78223 },\n}\n\nlocal CORE\n\nlocal SendPrototype = function(TYPE, mechanic, ...)\n    CORE.Prototype(ENTRY, TYPE, mechanic, ...)\nend\n\nlocal Warning = function(mechanic, ...) SendPrototype('WARNING', mechanic, ...) end\nlocal SpecialWarning = function(mechanic, ...) SendPrototype('SPECIAL_WARNING', mechanic, ...) end\nlocal PreWarning = function(mechanic, ...) SendPrototype('PRE_WARNING', mechanic, ...) end\nlocal Timer = function(...) SendPrototype('TIMER', ...) end\nlocal Cooldown = function(...) SendPrototype('COOLDOWN', ...) end\nlocal Cancel = function(...) return SendPrototype('CANCEL', ...) end\nlocal Phase = function(...) return SendPrototype('PHASE', ...) end\nlocal GTFO = function(...) return SendPrototype('GTFO', ...) end\n\nlocal AntiSpam = function(mechanic, timer) return CORE.AntiSpam(ENTRY, mechanic, timer) end\nlocal IsDifficulty = function(...) return CORE.IsDifficulty(...) end\n\nlocal isCoreInit = false\nlocal isEncounter = false\n\nlocal IsEntryInitialized = function()\n    return isCoreInit and isEncounter\nend\n\nlocal stage\nlocal SetStage = function(n)\n    stage = n\nend\n\nENTRY['WA_MERFIN_RAID'] = function(subEvent, link_to_core)\n    if subEvent == 'CORE_CONNECTION' then\n        CORE = link_to_core\n        isCoreInit = true\n        CORE.ResetFields(ENTRY)\n        if aura_env.config.test then\n            ENTRY['ENCOUNTER_START'](encounterId)\n        end\n        if WeakAuras.CurrentEncounter and WeakAuras.CurrentEncounter.id == encounterId  then\n            isEncounter = true\n            CORE.WipeSchedulers(ENTRY)\n            CORE.ResetFields(ENTRY)\n            -- If Encounter Got Started during WA Options Open\n            local boss1healthp = CORE.GetUnitHealthPercent('boss1')\n            if boss1healthp and boss1healthp > 99 then\n                ENTRY['ON_COMBAT_START'](0.1)\n            end\n        end\n    end\nend\n\nENTRY['STATUS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['OPTIONS'] = function()\n    if CORE then CORE.WipeSchedulers(ENTRY) end\nend\n\nENTRY['ENCOUNTER_END'] = function()\n    if not IsEntryInitialized() then return end\n    CORE.WipeSchedulers(ENTRY)\n    CORE.ResetFields(ENTRY)\n    isEncounter = false\n    ENTRY['ON_COMBAT_END']()\nend\n\nENTRY['ENCOUNTER_START'] = function(id)\n    if id == encounterId and isCoreInit then\n        isEncounter = true\n        CORE.WipeSchedulers(ENTRY)\n        CORE.ResetFields(ENTRY)\n        ENTRY['ON_COMBAT_START'](0)\n    end\nend\n\nlocal args\nENTRY['COMBAT_LOG_EVENT_UNFILTERED'] = function(timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellId, spellName,_,_, stacks)\n    if not IsEntryInitialized() then return end\n    args = {}\n    args.subEvent = subEvent\n    args.sourceGUID = sourceGUID\n    args.sourceName = sourceName\n    args.destGUID = destGUID\n    args.destName = destName\n    args.spellId = spellId\n    args.stacks = stacks\n    return ENTRY[subEvent] and ENTRY[subEvent](args)\nend\n\n--------------\n--> Main Logic\n--------------\n\nlocal phases = {\n    dark =  false,\n    blue =  false,\n    red =   false,\n    green = false,\n}\n\nlocal FreeToHeal = function()\n    WeakAuras.ScanEvents('free_to_heal')\nend\n\nlocal ScheduleDarkness = function()\n    Timer('engulfing_darkness', 8)\nend\n\nENTRY['ON_COMBAT_START'] = function(delay)\n    SetStage(1)\n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('berserk', 720-delay)\n        Cooldown('phase_dark', 18.5-delay); PreWarning('phase_dark', 13.5-delay)\n    else\n        Cooldown('berserk', 420-delay)\n        Cooldown('phase_blue_or_red', 18.5-delay); PreWarning('phase_blue_or_red', 13.5-delay)\n    end\n    \n    ENTRY.CASTS.adds = 18\n    \n    Cooldown('arcane_storm', 10-delay)\n    Cooldown('release_abberation', 15-delay)\nend\n\nENTRY['ON_COMBAT_END'] = function()\n    \nend\n\nlocal PhaseDark = function()\n    Phase('phase_dark')\n    WeakAuras.ScanEvents('PHASE_CHANGE', 'dark')\n    \n    Cancel('phase_dark', 'COOLDOWN'); Cancel('phase_dark', 'PRE_WARNING')\n    Cancel('arcane_storm', 'ALL')\n    Cancel('release_abberation', 'ALL')\n    \n    Cooldown('phase_blue_or_red', 100); PreWarning('phase_blue_or_red', 95)\n    Cooldown('engulfing_darkness', 16.5)\nend\n\nlocal PhaseBlue = function()\n    phases.blue = true\n    Phase('phase_blue')\n    WeakAuras.ScanEvents('PHASE_CHANGE', 'blue')\n    \n    Cancel('phase_blue', 'COOLDOWN'); Cancel('phase_blue', 'PRE_WARNING')\n    Cancel('phase_blue_or_red', 'COOLDOWN')\n    Cancel('engulfing_darkness', 'ALL')\n    Cancel('scorching_blast', 'ALL')\n    \n    Cooldown(phases.red and 'phase_green' or 'phase_red', 49); PreWarning(phases.red and 'phase_green' or 'phase_red', 44)\n    Cooldown('release_abberation', 15)\n    Cooldown('arcane_storm', 19)\n    Cooldown('flash_freeze', 22)\nend\n\nlocal PhaseRed = function()\n    phases.red = true\n    Phase('phase_red')\n    WeakAuras.ScanEvents('PHASE_CHANGE', 'red')\n    \n    Cancel('phase_red', 'COOLDOWN'); Cancel('phase_red', 'PRE_WARNING')\n    Cancel('phase_blue_or_red', 'COOLDOWN')\n    Cancel('flash_freeze', 'ALL')\n    Cancel('engulfing_darkness', 'ALL')\n    \n    Cooldown(phases.blue and 'phase_green' or 'phase_blue', 49); PreWarning(phases.blue and 'phase_green' or 'phase_blue', 44)\n    Cooldown('release_abberation', 15)\n    Cooldown('arcane_storm', 19)\n    Cooldown('scorching_blast', 22)\nend\n\nlocal PhaseGreen = function()\n    phases.red = false\n    phases.blue = false\n    Phase('phase_green')\n    WeakAuras.ScanEvents('PHASE_CHANGE', 'green')\n    \n    Cancel('phase_green', 'COOLDOWN'); Cancel('phase_green', 'PRE_WARNING')\n    Cancel('flash_freeze', 'ALL')\n    Cancel('engulfing_darkness', 'ALL')\n    Cancel('scorching_blast', 'ALL')\n    \n    if IsDifficulty('10_HEROIC', '25_HEROIC') then\n        Cooldown('phase_dark', 49); PreWarning('phase_dark', 44)\n    else\n        Cooldown('phase_blue_or_red', 49); PreWarning('phase_blue_or_red', 44)\n    end\n    Cooldown('release_abberation', 15)\n    Cooldown('arcane_storm', 12)\nend\n\nENTRY['RAID_BOSS_EMOTE'] = function(text, playerName)\n    if not IsEntryInitialized() then return end\n    if text == L.yell_dark or text:find(L.yell_dark) then\n        PhaseDark()\n    elseif text == L.yell_blue or text:find(L.yell_blue) then\n        PhaseBlue()\n    elseif text == L.yell_red or text:find(L.yell_red) then\n        PhaseRed()\n    elseif text == L.yell_green or text:find(L.yell_green) then\n        PhaseGreen()\n    end\nend\n\nlocal PhaseTwo = function()\n    SetStage(2)\n    Warning('phase_2')\n    \n    Cooldown('magma_jets', 10)\n    Cooldown('absolute_zero', 13)\n    \n    Cancel('arcane_storm', 'ALL')\n    Cancel('flash_freeze', 'ALL')\n    Cancel('scorching_blast', 'ALL')\n    Cancel('release_abberation', 'ALL')\n    Cancel('engulfing_darkness', 'ALL')\n    Cancel('phase_dark', 'ALL')\n    Cancel('phase_blue', 'ALL')\n    Cancel('phase_red', 'ALL')\n    Cancel('phase_green', 'ALL')\n    Cancel('phase_blue_or_red', 'ALL')\nend\n\nENTRY['SPELL_CAST_START'] = function(args)\n    if args.spellId == 77569 then\n        Timer('release_abberation', 1.5)\n        Cooldown('release_abberation', 15)\n        Warning('release_abberation')\n        \n    elseif args.spellId == 77991 then\n        PhaseTwo()\n    elseif args.spellId == 92754 then\n        Cooldown('engulfing_darkness', 12)\n        if CORE.IsTanking('player', nil, args.sourceGUID) then\n            SpecialWarning('engulfing_darkness')\n        else\n            Warning('engulfing_darkness')\n        end\n        CORE.Schedule(ENTRY, 'free_to_heal', 11, FreeToHeal) \n        CORE.Schedule(ENTRY, 'engulfing_darkness', 3, ScheduleDarkness) \n        \n    elseif args.spellId == 77896 then\n        Cooldown('arcane_storm', 14)\n        Warning('arcane_storm')\n        \n    elseif args.spellId == 78194 then\n        if IsDifficulty('10_HEROIC', '25_HEROIC') then\n            Cooldown('magma_jets', 5)\n        else\n            Cooldown('magma_jets', 10)\n        end\n        if CORE.IsTanking('player', nil, UnitGUID('target')) then\n            Timer('magma_jets', 2)\n            SpecialWarning('magma_jets')\n        end\n    end\nend\n\nENTRY['SPELL_CAST_SUCCESS'] = function(args)\n    if args.spellId == 77679 then\n        Warning('scorching_blast')\n        Cooldown('scorching_blast', 10)\n    elseif args.spellId == 77569 then\n        -- Release Abberations\n        if ENTRY.CASTS.adds > 0 then\n            ENTRY.CASTS.adds = ENTRY.CASTS.adds - 3\n            Warning('abberations_left', nil, ENTRY.CASTS.adds or 0)\n        end\n    elseif args.spellId == 78223 then\n        -- Absolute Zero\n        Cooldown('absolute_zero', 8)\n        Warning('absolute_zero', 8)\n    end\nend\n\nENTRY['SPELL_INTERRUPT'] = function(args)\n    if args.interruptId == 77896 then\n        --WeakAuras.ScanEvents('ARCANE_STORM', args.destGUID)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED'] = function(args)\n    if args.spellId == 77699 then\n        Warning('flash_freeze', args.destName)\n    elseif args.spellId == 77760 then\n        if args.destGUID == CORE.PlayerGUID then\n            SpecialWarning('biting_chill')\n        end\n        \n    elseif args.spellId == 77912 and not CORE.IsDestTypePlayer(args.destFlags) then\n        Warning('remedy', args.destName)\n        SpecialWarning('remedy')\n        \n    elseif args.spellId == 77786 then\n        Warning('consuming_flames', args.destName)\n        Timer('consuming_flames', 10, args.destName)\n        \n    elseif args.spellId == 77615 and AntiSpam('dark_sludge', 1) then\n        GTFO('debilitating_slime')\n        Timer('debilitating_slime', 15)\n    elseif args.spellId == 92930 and args.destGUID == CORE.PlayerGUID and AntiSpam('dark_sludge', 2) then\n        GTFO('dark_sludge')\n    elseif args.spellId == 77987 then\n        if CORE.GetGuidCreatureId(args.destGUID) == 41378 then\n            Warning('growth_catalyst', args.destName)\n        end\n    elseif args.spellId == 77896 then\n        Timer('arcane_storm', 6)\n    end\nend\n\nENTRY['SPELL_AURA_APPLIED_DOSE'] = function(args)\n    if args.spellId == 77987 then\n        if CORE.GetGuidCreatureId(args.destGUID) == 41378 then\n            Warning('growth_catalyst', args.destName, args.stacks)\n        end\n    end\nend\n\nENTRY['SPELL_AURA_REMOVED'] = function(args)\n    if args.spellId == 77987 then\n        if CORE.GetGuidCreatureId(args.destGUID) == 41378 then\n            Cancel('growth_catalyst', 'ALL')\n        end\n    elseif args.spellId == 77896 then\n        Cancel('arcane_storm', 'TIMER')\n        WeakAuras.ScanEvents('ARCANE_STORM', args.sourceGUID)\n    end\nend",
