},
["init"] = {
["custom"] = "local encounterID = '1500'\nlocal IDs = {\n    [1] = { 'Phase1', Merfin:L('Phase 1')},\n    [2] = { 'Phase2', Merfin:L('Phase 2')},\n    [3] = { 'Phase3', Merfin:L('Phase 3')},\n}\n\nlocal options = {\n    ['Phase1'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", IDs[1][2]:upper()),\n    },\n    ['Phase2'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", IDs[2][2]:upper()),\n    },\n    ['Phase3'] = {\n        warningText = string.format(\"@cffe3e3e3» %s «@r\", IDs[3][2]:upper()),\n    },\n}\n\naura_env.SendWarning = function()\n    local n = aura_env.phase\n    local ID = IDs[n][1]\n    \n    local data = {\n        ID    = ID,\n        name  = IDs[n][2],\n        count = aura_env.phase,\n    }\n    \n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options[ID])\nend\n\naura_env.MRT = function(phase)\n    if not WeakAuras.IsAuraLoaded(aura_env.id) then return end\n    local event = phase\n    GMRT.F.Note_Timer(event)\nend\n\naura_env.SendPhase = function(n)\n    aura_env.MRT('PHASE_' .. n)\n    WeakAuras.ScanEvents('ELEGON_PHASE', aura_env.phase)\n    if n ~= '1_INITIAL' then\n        aura_env.SendWarning()\n    end\nend",
["do_custom"] = true,
},
},
