["custom"] = "function(e, ...)\n    if e == 'COMBAT_LOG_EVENT_UNFILTERED' then\n        local _, subEvent,_,_,_,_,_,_,_,_,_, spellID = ...\n        \n        if subEvent == 'SPELL_AURA_APPLIED' then\n            if spellID == 124967 then\n                aura_env.phase = 2\n                aura_env.SendPhase(2)\n            elseif spellID == 116994 then\n                aura_env.phase = 3\n                aura_env.SendPhase(3)\n            end\n        elseif subEvent == 'SPELL_AURA_REMOVED' then\n            if spellID == 116994 then\n                aura_env.phase = 1\n                aura_env.SendPhase(1)\n            end\n        end\n        \n    elseif e == 'ENCOUNTER_START' then\n        aura_env.phase = 1\n        aura_env.SendPhase('1_INITIAL')\n    end\nend",
