["custom"] = "local encounterID = '1507'\nlocal ID          = 'Inhale'\n\nlocal name, icon = C_Spell.GetSpellName(122852), C_Spell.GetSpellTexture(122852)\n\nlocal options = {\n    warningText = \"%icon @cffffff80%name@r (%amount) %icon\",\n}\n\naura_env.SendWarning = function(amount)\n    local data = {\n        ID     = ID,\n        count  = aura_env.count,\n        amount = amount,\n        name   = name,\n        icon   = icon,\n    }\n    WeakAuras.ScanEvents('MERFIN_WARNING', encounterID, data, options)\nend",
