["[DP] [Emperor] Emotes Handler"] = {
["outline"] = "OUTLINE",
["wagoID"] = "H5gs0vTam",
["xOffset"] = 0,
["displayText_format_p_time_dynamic_threshold"] = 60,
["shadowYOffset"] = -1,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "event",
["url"] = "https://space.bilibili.com/455259",
["actions"] = {
["start"] = {
},
["finish"] = {
["custom"] = "\n    ",
["do_custom"] = false,
},
["init"] = {
["custom"] = "aura_env.AnnounceAdd = function(add)\n    WeakAuras.ScanEvents('ADD_ACTIVATION', add)\nend\n\nlocal L = GetLocale()\naura_env.IsEmote = function(initialEmote, compareWith)\n    if not initialEmote then return false end\n    if not aura_env.replicas[L] then return false end\n    local replica = aura_env.replicas[L][compareWith]\n    if not replica then return false end\n    return initialEmote == replica or initialEmote:find(replica)\nend\n\naura_env.replicas = {\n    ['enUS'] = {\n        Rage     = \"The Emperor's Rage echoes through the hills.\",\n        Courage  = \"The Emperor's Courage appears in the alcoves!\",\n        Strength = \"The Emperor's Strength appears in the alcoves!\",\n        Bosses   = \"Two titanic constructs appear in the large alcoves!\",\n    },\n    ['deDE'] = {\n        Rage     = \"Der Zorn des Kaisers schallt durch die Berge.\",\n        Courage  = \"Der Mut des Kaisers erscheint in den Erkern!\",\n        Strength = \"Die Stärke des Kaisers erscheint in den Erkern!\",\n        Bosses   = \"In den riesigen Erkern erscheinen zwei Titanenkonstrukte!\",\n    },\n    ['frFR'] = {\n        Rage     = \"La rage de l'empereur se répercute dans les collines.\",\n        Courage  = \"Le Courage de l'empereur apparaît dans les alcôves !\",\n        Strength = \"La Force de l'empereur apparaît dans les alcôves !\",\n        Bosses   = \"Deux assemblages titanesques apparaissent dans les grandes alcôves !\",\n    },\n    ['itIT'] = {\n        Rage     = \"La Rabbia dell'Imperatore risuona tra le colline.\",\n        Courage  = \"Il Coraggio dell'Imperatore appare nelle volte!\",\n        Strength = \"La Forza dell'Imperatore appare nelle volte!\",\n        Bosses   = \"Due Costrutti Titanici appaiono nelle alcove più grandi!\",\n    },\n    ['koKR'] = {\n        Rage     = \"황제의 분노가 문 언덕에 울려퍼진다.\",\n        Courage  = \"황제의 용기가 벽감에 나타납니다!\",\n        Strength = \"황제의 힘이 벽감에 나타납니다!\",\n        Bosses   = \"거대한 모구 조형체 둘이 큰 벽감에 나타납니다!\",\n    },\n    ['ruRU'] = {\n        Rage     = \"Ярость императора эхом звучит среди холмов.\",\n        Courage  = \"В нишах появляется Смелость императора!\",\n        Strength = \"В нишах появляется Сила императора!\",\n        Bosses   = \"В больших нишах появляются два голема!\",\n    },\n    ['zhTW'] = {\n        Rage     = \"大帝之怒響徹群山。\",\n        Courage  = \"大帝之勇永久不滅。\",\n        Strength = \"大帝之力以鐵拳掌握大地。\",\n        Bosses   = \"無盡的大軍會碾碎大帝的敵人。\",\n    },\n}",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["custom_type"] = "status",
["debuffType"] = "HELPFUL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "function(e, ...)\n    if e == 'CHAT_MSG_MONSTER_YELL' then\n        local msg = ...\n        \n        if aura_env.IsEmote(msg, 'Rage') then \n            aura_env.AnnounceAdd('RAGE')\n        end\n        \n    elseif e == 'CHAT_MSG_RAID_BOSS_EMOTE' then\n        local msg = ...\n        \n        if aura_env.IsEmote(msg, 'Strength') then\n            aura_env.AnnounceAdd('STRENGTH')\n            \n        elseif aura_env.IsEmote(msg, 'Courage') then\n            aura_env.AnnounceAdd('COURAGE')\n            \n        elseif aura_env.IsEmote(msg, 'Bosses') then\n            aura_env.AnnounceAdd('BOSSES')\n            \n        elseif msg:find(\"spell:116779\") then\n            WeakAuras.ScanEvents('TITAN_GAS')\n        end\n    end\nend\n\n\n",
